local config = {
  ui_story_5031_50310101_1_dialog_content = "여러분, 안녕하세요!\n<color=#FFB400>‘매직 핸드’ 빌 서커스단</color>에 오신 것을 환영합니다.\n저는 이번 공연의 사회자인 <color=#FFB400>레인보우</color>라고 해요~",
  ui_story_5031_50310101_2_dialog_content = "이 아름다운 밤, 에메랄드호에 오신 손님은 모두 저희 서커스단의\n가장 존귀한 손님이랍니다.",
  ui_story_5031_50310101_3_dialog_content = "모든 걱정과 근심을 내려놓고, 이 멋진 공연을 마음껏 즐겨 주세요.",
  ui_story_5031_50310101_4_dialog_content = "저희 ‘매직 핸드’ 빌 서커스단이 지금까지 상상조차 해본 적 없을\n멋진 공연을 보여드릴 테니까요!",
  ui_story_5031_50310101_5_dialog_content = "이 아름다운 순간은 오직 우리... 오직 이 세상을 위한 시간이랍니다──!",
  ui_story_5031_50310101_6_dialog_content = "그럼 이제... 천상의 멜로디... 공중그네의 대가... 멜트──",
  ui_story_5031_50310101_7_dialog_content = "사블리──",
  ui_story_5031_50310101_8_dialog_content = "팜므──",
  ui_story_5031_50310101_9_dialog_content = "세 자매를 큰 박수로 맞이해 주세요──!",
  ui_story_5031_50310101_10_dialog_content = "저... 저기... 레인보우 언니... 우리 공중그네 설비는 점검 중인 거 아니었나요?",
  ui_story_5031_50310101_11_dialog_content = "그러니까 말이야. 아무리 우리라고 해도 아무 장치도 없이 공중에서 공연할 순 없다구~",
  ui_story_5031_50310101_12_dialog_content = "히히, 사실 팜므는 요즘 서커스단의 차력사랑 같이 힘을 기르는 중이었어.",
  ui_story_5031_50310101_13_dialog_content = "어쩌면 멜 언니랑 사브 언니를 공중으로 던져줄 수 있을지도 몰라.",
  ui_story_5031_50310101_14_dialog_content = "그...그건... 너무 위험해. 누군가 다칠지도 몰라요...",
  ui_story_5031_50310101_15_dialog_content = "그러니까 대장. 뭐라고 말이라도 좀 해봐.",
  ui_story_5031_50310101_16_dialog_content = "장치가 준비되지도 않았는데 리허설은 어떻게 하라는 거야?",
  ui_story_5031_50310101_17_dialog_content = "게다가 우리 셋의 실력이라면 리허설 같은 건 애초에 필요 없잖아!",
  ui_story_5031_50310101_18_dialog_content = "사블리... 제노 단장한테 너무 말을 심하게 하면 안 돼요...",
  ui_story_5031_50310101_19_dialog_content = "네? 전 지금 바쁩니다.",
  ui_story_5031_50310101_20_dialog_content = "엘비스의 보급은 이미 받았습니다. 공연 설비도 마지막으로 다시 점검해 보는 중입니다.",
  ui_story_5031_50310101_21_dialog_content = "리허설이 싫으면 대충 쉬고 있으면 됩니다.",
  ui_story_5031_50310101_22_dialog_content = "레인보우, 동물과 소통할 수 있다는 그 임시 단원을 불러오세요.",
  ui_story_5031_50310101_23_dialog_content = "빙수 때문에 배탈 난 조련사의 빈자리를 채워보도록 하죠.",
  ui_story_5031_50310101_24_dialog_content = "오케이~",
  ui_story_5031_50310101_25_dialog_content = "피아, 준비됐어?",
  ui_story_5031_50310101_26_dialog_content = "조, 조금만 더 기다려!",
  ui_story_5031_50310101_27_dialog_content = "자, 비카. 이쪽이야.",
  ui_story_5031_50310101_28_dialog_content = "하이.",
  ui_story_5031_50310101_29_dialog_content = "내 말대로 하는 거야. 점프하는 동시에 텀블링이야. 알겠지?",
  ui_story_5031_50310101_30_dialog_content = "하이!",
  ui_story_5031_50310101_31_dialog_content = "부탁이야. 한 번만 들어 줘. 저 무서운 단장님이 밑에서 보고 있다구!",
  ui_story_5031_50310101_32_dialog_content = "하이!",
  ui_story_5031_50310101_33_dialog_content = "윽! 진정해. 내가 미안해... 물지 마!",
  ui_story_5031_50310101_34_dialog_content = "잠깐, 잠깐!",
  ui_story_5031_50310101_35_dialog_content = "대체 어떻게 된 겁니까? 우선 무대에서 내려간 뒤에 해결하세요!\n리허설을 방해하지 말란 말입니다!",
  ui_story_5031_50310101_36_dialog_content = "제노 단장!",
  ui_story_5031_50310101_37_dialog_content = "뭐죠? 동물과 얘기는 끝났습니까?",
  ui_story_5031_50310101_38_dialog_content = "저 녀석 말을 전혀 안 들어! 평소에 오냐오냐해서 버릇이 나빠졌잖아!",
  ui_story_5031_50310101_39_dialog_content = "뭐라고요? 말을 안 듣는다고요?",
  ui_story_5031_50310101_40_dialog_content = "그래! 게다가 엄청 사나워! 날 계속 물려고 했다니까!",
  ui_story_5031_50310101_41_dialog_content = "음, 정상이군요.",
  ui_story_5031_50310101_42_dialog_content = "정상?",
  ui_story_5031_50310101_43_dialog_content = "그 녀석들은 원래 일하고 싶으면 일하고, 하기 싫으면 멋대로 굴었으니까요.",
  ui_story_5031_50310101_44_dialog_content = "뭐야?",
  ui_story_5031_50310101_45_dialog_content = "너네 서커스단은 왜 내가 책에서 본 거랑 전혀 다른 건데?",
  ui_story_5031_50310101_46_dialog_content = "책에서 본 서커스단은 동물들한테 엄청 무섭게 굴어서,\n겁에 질린 동물들이 얌전히 공연하게 만든다고 적혀 있었단 말이야.",
  ui_story_5031_50310101_47_dialog_content = "그건 대체 무슨 편견입니까?",
  ui_story_5031_50310101_48_dialog_content = "그런 얘기는 처음 들어보는군요. 어째서 동물들에게 무섭게 굴어야 하죠?\n그들 또한 우리의 소중한 동료입니다만.",
  ui_story_5031_50310101_49_dialog_content = "비카의 부드러운 털을 보세요. 얼마나 마음이 따뜻해집니까.",
  ui_story_5031_50310101_50_dialog_content = "하이~",
  ui_story_5031_50310101_51_dialog_content = "제 서커스단에서는 그런 식으로 동물을 대하지 않습니다.",
  ui_story_5031_50310101_52_dialog_content = "원래 있던 조련사들은 모두 동물을 데리고 공연을 진행했었습니다.\n그러니 그 이유는 당신 자신에게서 찾아보시죠.",
  ui_story_5031_50310101_53_dialog_content = "뭐, 뭐라고?!",
  ui_story_5031_50310101_54_dialog_content = "윽, 나, 난 환상동물 마스터라고...\n환상동물과의 친화력이 하늘을 뚫은 피아 님이란 말이야!",
  ui_story_5031_50310101_55_dialog_content = "내가 평범한 조련사들보다 못할 리가... 못할 리가 없는데...",
  ui_story_5031_50310101_56_dialog_content = "걱정 마, PlayerName. 나한테 발레 공연 같은 건 그리 어려운 일도 아니니까.",
  ui_story_5031_50310101_57_dialog_content = "발레를 하는 카렌을 보게 될 줄은 정말 몰랐어.",
  ui_story_5031_50310101_58_dialog_content = "콜로서스의 다른 백야성 오로리안들한테도 들었거든.\n카렌은 발레 선생님도 감탄한 천재라고 말이야.",
  ui_story_5031_50310101_59_dialog_content = "정말? 바이스가 그러니까 더 기대되는데?",
  ui_story_5031_50310101_60_dialog_content = "PlayerName──!",
  ui_story_5031_50310101_61_dialog_content = "피아? 동물 공연 연습해야 되지 않아? 왜 여기 있는 거야?",
  ui_story_5031_50310101_62_dialog_content = "흐... 흐잉... 그 짜증 나는 환상동물들 진짜 미워 죽겠어...\n걔들은 일하기 싫으면 안 해도 된대...",
  ui_story_5031_50310101_63_dialog_content = "그러니까 사부가... 사부가 날 부려 먹던 게 생각나서... 흐아아아앙!",
  ui_story_5031_50310101_64_dialog_content = "피, 피아, 울지 마!",
  ui_story_5031_50310101_65_dialog_content = "잊지 마. 넌 위대한 환상동물 마스터야.",
  ui_story_5031_50310101_66_dialog_content = "흑... 환상동물 마스터도 됐는데... 왜 아직도 사부 심부름이나 하고 다녀야 하는 건데!",
  ui_story_5031_50310101_67_dialog_content = "자꾸 그런 생각하지 말고, 날 괴롭힐 때처럼 박력 있게 해 봐!",
  ui_story_5031_50310101_68_dialog_content = "뭐야?!",
  ui_story_5031_50310101_69_dialog_content = "아, 아니... 그러니까 우리가 함께 여러 난관을 헤치고...\n위대한 목표를 향해 나아가던 그날을 떠올려보라는 거야!",
  ui_story_5031_50310101_70_dialog_content = "흑... 함께했던... 위대한 목표...",
  ui_story_5031_50310101_71_dialog_content = "<color=#e8d9bb>막 하버 시티에 도착했을 때</color>",
  ui_story_5031_50310101_72_dialog_content = "카렌, 나랑 바이스를 하버 시티에 초대해 줘서 고마워.",
  ui_story_5031_50310101_73_dialog_content = "정말 좋은 곳이네. 조용하고 한적한 분위기 덕분에 무척 편안한 느낌이야.",
  ui_story_5031_50310101_74_dialog_content = "모두 함께 할 수 있어서 정말 좋아.",
  ui_story_5031_50310101_75_dialog_content = "천만에. 다들 요즘 고생한 것 같아서 한번 푹 쉬는 편이 좋을 것 같았거든.",
  ui_story_5031_50310101_76_dialog_content = "하버 시티는 아주 어릴 때 와 봤어. 그때 깊은 인상을 받았었지.",
  ui_story_5031_50310101_77_dialog_content = "하지만 몇 년 뒤부터 도시가 점점 발전하기 시작한 걸 보면\n아마 지금 영주도 꽤 현명한 사람 같아.",
  ui_story_5031_50310101_78_dialog_content = "<size=33>찾았다...</size>",
  ui_story_5031_50310101_79_dialog_content = "아마 솔라드 님처럼 현명한 군주겠지?",
  ui_story_5031_50310101_80_dialog_content = "주민들의 행복한 표정을 보니 나도 이곳의 통치자가 어떤 사람인지 궁금해지기 시작했어.",
  ui_story_5031_50310101_81_dialog_content = "음... 이곳의 영주와 그 사람은... 아마 조금 다를 거야.",
  ui_story_5031_50310101_82_dialog_content = "그래도 예의상 영주를 한번 만나보긴 해야겠지. 같이 가자.",
  ui_story_5031_50310101_83_dialog_content = "방금 거리에 붙어있던 포스터를 봤는데, 거대한 함선에 무슨 카니발이 열린 것 같아.\n서커스 공연도 있다는 것 같던데.",
  ui_story_5031_50310101_84_dialog_content = "그 영주님한테 자세히 물어보는 것도 좋겠지.",
  ui_story_5031_50310101_85_dialog_content = "기왕 쉬는 거, 여름 느낌이 가득한 행사에 참가하는 것도 좋을 것 같아!",
  ui_story_5031_50310101_86_dialog_content = "좋아! 나도 하버 시티의 재미있는 놀거리랑 맛있는 음식이 궁금하던 참이거든~",
  ui_story_5031_50310101_87_dialog_content = "바이스도 오랜만에 놀러 나와서 그런지 되게 신난 모양이네.",
  ui_story_5031_50310101_88_dialog_content = "<size=33>타깃 록 온── PlayerName!</size>",
  ui_story_5031_50310101_89_dialog_content = "그럼 얼른 출발을──<size=50>으악!</size>",
  ui_story_5031_50310101_90_dialog_content = "아야야! 허리 아파!",
  ui_story_5031_50310101_91_dialog_content = "(왠지 어디서 봤던 장면 같은데...)",
  ui_story_5031_50310101_92_dialog_content = "다가오지 마! 안 그러면 정말로 사람 부를 거야!",
  ui_story_5031_50310101_93_dialog_content = "잡아──",
  ui_story_5031_50310101_94_option_content = "강제... 으악!",
  ui_story_5031_50310101_95_dialog_content = "내 허리!",
  ui_story_5031_50310101_96_dialog_content = "루우우!",
  ui_story_5031_50310101_97_dialog_content = "잘했어, 키아로. 그럼 계획대로 숲까지 후퇴하자!",
  ui_story_5031_50310101_98_dialog_content = "난 그저... 친구를 원했을 뿐이야...",
  ui_story_5031_50310101_99_dialog_content = "루...",
  ui_story_5031_50310101_100_dialog_content = "사람들은 날 좋아해 주는 건 고작해야 환상동물들밖에 없을 거라고 했어...\n그래서 나도 오로리안이나 아이테르랑 친구가 될 수 있다는 걸 증명하고 싶었어...",
  ui_story_5031_50310101_101_dialog_content = "헤헤... 그럼 PlayerName 네가 내 첫 번째 친구네!",
  ui_story_5031_50310101_102_dialog_content = "피아의 친구가 돼 줘서 정말 기뻐!",
  ui_story_5031_50310101_103_dialog_content = "사부! 보고 있지? 피아가 친구를 만들었어!",
  ui_story_5031_50310101_104_dialog_content = "여, 역시 너였구나! 피아!",
  ui_story_5031_50310101_105_dialog_content = "왜 쓰레기통에 숨어서 날 공격한 거야?!",
  ui_story_5031_50310101_106_dialog_content = "헤헤, 잡았다! PlayerName!",
  ui_story_5031_50310101_107_dialog_content = "피아?",
  ui_story_5031_50310101_108_dialog_content = "... 아무튼 그렇게 됐어. 얘가 바로 피아야.",
  ui_story_5031_50310101_109_dialog_content = "네가 예전에 만났다던 꼬마 환상동물 마스터가 이 아이였구나.",
  ui_story_5031_50310101_110_dialog_content = "환상동물 마스터라는 사람들에 대해 들어는 봤지만,\n그중에 이렇게 어린 사람도 있을 줄은 몰랐어.",
  ui_story_5031_50310101_111_dialog_content = "오랜만이야, 피아.",
  ui_story_5031_50310101_112_dialog_content = "응! 오랜만이야~ 바이스 언니.",
  ui_story_5031_50310101_113_dialog_content = "카렌 언니, 난 환상동물 마스터인 피아라고 해.",
  ui_story_5031_50310101_114_dialog_content = "이제 막 졸업해서 아직은 미숙한 부분이 많겠지만... 그래도 잘 부탁해!",
  ui_story_5031_50310101_115_dialog_content = "난 백야성에서 온 카렌이야.\n피아 넌 내가 아는 라파엘이란 아이와 느낌이 많이 닮았구나.",
  ui_story_5031_50310101_116_dialog_content = "기회가 된다면 소개해 줄게. 어쩌면 말이 잘 통할지도 몰라.",
  ui_story_5031_50310101_117_dialog_content = "잠깐만.",
  ui_story_5031_50310101_118_dialog_content = "야, 너 왜 갑자기 그렇게 얌전한 척하는 거야?",
  ui_story_5031_50310101_119_dialog_content = "아, 아니야. 피아는 원래 항상 얌전하고 상냥했어!\nPlayerName, 다른 사람한테 피아 흉보면 안 돼!",
  ui_story_5031_50310101_120_dialog_content = "네~ 네. 그럼 우리 피아 아가씨가 언제까지 「상냥」할 수 있는지 지켜봐야겠네.",
  ui_story_5031_50310101_121_dialog_content = "그나저나 넌 왜 여기 있던 거야? 키아로는?",
  ui_story_5031_50310101_122_dialog_content = "쉿. 피아는 지금 키아로랑 같이 사부의 「<color=#FFB400>비밀 임무</color>」를 수행하는 중이라고.",
  ui_story_5031_50310101_123_dialog_content = "키아로는 근처에 있는 물가에서 조사 중이야.",
  ui_story_5031_50310101_124_dialog_content = "비밀 임무? 예전처럼 그 엉망진창이다 못해 괴로울 정도의 임무는 아니겠지?",
  ui_story_5031_50310101_125_dialog_content = "게다가 키아로는 저번 일로 엄청나게 커졌잖아.\n그렇게 큰 몸으로 이리저리 돌아다니면 너무 눈에 띄지 않아?",
  ui_story_5031_50310101_126_dialog_content = "으흥, 키아로를 너무 얕보고 있네.\n키아로는 이제 두 가지 형태를 자유롭게 오갈 수 있다구.",
  ui_story_5031_50310101_127_dialog_content = "사부 말로는... 계속 노력하면 인간형 변신도 할 수 있다던데?",
  ui_story_5031_50310101_128_dialog_content = "그건 조금 무서운데...",
  ui_story_5031_50310101_129_dialog_content = "무서워할 거 없어. 키아로를 화나게 하지만 않는다면 말이야~",
  ui_story_5031_50310101_130_dialog_content = "아무튼 그건 됐고! 이번 일은 엄청 중요해.\n「<color=#FFB400>희귀종</color>」 환상동물이랑 관련이 있거든.",
  ui_story_5031_50310101_131_dialog_content = "저기, 일부러 들으려던 건 아니었는데.",
  ui_story_5031_50310101_132_dialog_content = "피아의 목소리가 너무 커서 들어 버렸거든.",
  ui_story_5031_50310101_133_dialog_content = "PlayerName에게 찾아온 건 그 「비밀 임무」에 도움이 필요해서 그런 거니?",
  ui_story_5031_50310101_134_dialog_content = "아, 나도 모르게 목소리가 커졌네...",
  ui_story_5031_50310101_135_dialog_content = "그래도 PlayerName의 친구니까.\n카렌 언니랑 바이스 언니도 분명히 믿을 수 있겠지!",
  ui_story_5031_50310101_136_dialog_content = "그러니까 두 사람한테도 상황을 자세히 알려줄게.",
  ui_story_5031_50310101_137_dialog_content = "사실 며칠 전에──",
  ui_story_5031_50310101_138_dialog_content = "뭐라고? 정말 하버 시티에 갈 수 있는 거야?",
  ui_story_5031_50310101_139_dialog_content = "헤헤... 거긴 경치도 멋있고 맛있는 것도 많다고 하던데.",
  ui_story_5031_50310101_140_dialog_content = "내가 고생하는 걸 알고 이렇게 쉬게 해 주다니...\n사부가 이 정도로 날 아낄 줄은 몰랐어.",
  ui_story_5031_50310101_141_dialog_content = "참, 하버 시티는 해변도 엄청 유명한데, 아직 수영복도 준비 못했잖아?",
  ui_story_5031_50310101_142_dialog_content = "아니... 너무 좋을 대로 생각하고 있네...",
  ui_story_5031_50310101_143_dialog_content = "그렇게 좋은 일이었으면 당연히 내가 갔겠지.",
  ui_story_5031_50310101_144_dialog_content = "임무라고 했으니 놀러 가는 건 아닌 게 당연하잖아.",
  ui_story_5031_50310101_145_dialog_content = "자, 경비 줄 테니까 얼른 출발해.",
  ui_story_5031_50310101_146_dialog_content = "뭐야! 왜 이렇게 적은데?!",
  ui_story_5031_50310101_147_dialog_content = "자, 잠깐만, 사부! 왜 바로 가 버리는 거야?!",
  ui_story_5031_50310101_148_dialog_content = "휴, 역시 허접 사부가 나한테 그렇게 잘해줄 리가 없잖아.",
  ui_story_5031_50310101_149_dialog_content = "근데 너, 사부에 대한 불만만 잔뜩 털어놓고, 정작 중요한 건 아직 하나도 말 안 했어.",
  ui_story_5031_50310101_150_dialog_content = "이제 얘기하려던 참이었어!",
  ui_story_5031_50310101_151_dialog_content = "이번 목표는 「<color=#FFB400>구름고래</color>」라는 환상동물이야.",
  ui_story_5031_50310101_152_dialog_content = "사부는 구름고래가 가진 특별한 루미나를 계속 쫓고 있었는데,\n이번에 마침 그 녀석이 이 근처의 물가로 온 것 같아.",
  ui_story_5031_50310101_153_dialog_content = "그런데 얼마 전에 그 루미나가 갑자기 사라져 버렸어.",
  ui_story_5031_50310101_154_dialog_content = "너무 갑작스럽게 흔적도 없이 사라졌거든.\n그래서 떠난 게 아니라 무슨 일이 생긴 게 아닐까 싶어!",
  ui_story_5031_50310101_155_dialog_content = "확실히 심상치 않은 상황이네.",
  ui_story_5031_50310101_156_dialog_content = "맞아. 사부 말로는 그 「희귀종」의 힘은 드라코리온보다 강하다고 했어.",
  ui_story_5031_50310101_157_dialog_content = "전설 속 구름고래는 암귀를 두려움에 떨게 하고,\n다크매터를 쫓을 수 있는 강력한 루미나를 가지고 있다고 해.",
  ui_story_5031_50310101_158_dialog_content = "게다가 수명도 엄청나게 기니까 자연사했을 확률은 거의 없을 거야.",
  ui_story_5031_50310101_159_dialog_content = "그래서 사부는 녀석이 나쁜 마음을 먹은 사람한테 잡힌 게 아닌지 걱정하고 있어.",
  ui_story_5031_50310101_160_dialog_content = "녀석의 본성은 착하지만, 나쁜 사람이 그 힘을 이용한다면 무서운 일이 벌어질지도 몰라.",
  ui_story_5031_50310101_161_dialog_content = "만약 그런 상황이 벌어질 수도 있는 거라면... 가만히 있을 수만은 없겠지.",
  ui_story_5031_50310101_162_dialog_content = "뭔가 단서는 있어?",
  ui_story_5031_50310101_163_dialog_content = "윽... 아무것도 없어! 사부도 일만 맡기고 급하게 나가버렸거든.",
  ui_story_5031_50310101_164_dialog_content = "그래서 하버 시티를 허둥지둥 돌아다니다가 날 발견하곤 여기 숨어 있다가 습격한 거야?",
  ui_story_5031_50310101_165_dialog_content = "PlayerName, 너 참 똑똑하네!\n사실... 사부가 나한테 준 여행비도 이제 거의 바닥났거든.",
  ui_story_5031_50310101_166_dialog_content = "PlayerName 네가 안 나타났으면 정말 큰일 날 뻔했다니까.",
  ui_story_5031_50310101_167_dialog_content = "내가 그럴 줄 알았어.",
  ui_story_5031_50310101_168_dialog_content = "그럼 일단 정보부터 수집해 보자. 마침 이곳의 영주를 만나러 가려던 참이거든.",
  ui_story_5031_50310101_169_dialog_content = "어쩌면 그 사람을 통해 뭔가 파악할 수 있을지도 몰라.",
  ui_story_5031_50310101_170_dialog_content = "좋아! 카렌 언니 말대로 할게. 그럼 출발!",
  ui_story_5031_50310101_171_dialog_content = "야! 길은 알고 가는 거야?",
  ui_story_5031_50310101_172_dialog_content = "정말 기운이 넘치네.",
  ui_story_5031_50310201_1_dialog_content = "영주님, 충성스러운 병사들이 준비를 마쳤습니다.",
  ui_story_5031_50310201_2_dialog_content = "계획하신 대로 에메랄드호로 운반하는 보급품과 불꽃을 엄폐물로 삼을 겁니다.",
  ui_story_5031_50310201_3_dialog_content = "네, 알겠습니다.",
  ui_story_5031_50310201_4_dialog_content = "파토 대장, 고생했어요. 어쩌면 이번에는...\n당신밖에 믿을 사람이 없을지도 모르겠군요...",
  ui_story_5031_50310201_5_dialog_content = "네. 맡겨만 주십시오. 영주님을 위해 일하는 것은 제 영광입니다.",
  ui_story_5031_50310201_6_dialog_content = "휴, 만약 기회가 이토록 빠르게 지나가지 않았더라면,\n당신들을 위험하게 만들 일도 없었을 텐데 말이지요.",
  ui_story_5031_50310201_7_dialog_content = "영주님, 파토 님! 보, 보고드릴 일이 있습니다!",
  ui_story_5031_50310201_8_dialog_content = "내가 아무도 들어오지 말라고 했을 텐데!",
  ui_story_5031_50310201_9_dialog_content = "죄, 죄송합니다. 하지만 귀한 손님께서 찾아오셔서...",
  ui_story_5031_50310201_10_dialog_content = "그 귀한 손님이 누구길래 그렇게 허둥대는 거지?\n우리 모드리 가문 친위대의 체면이 말이 아니군.",
  ui_story_5031_50310201_11_dialog_content = "그, 그게... 카렌 전하께서 찾아오셨습니다!",
  ui_story_5031_50310201_12_dialog_content = "뭐라고요? 백야성의 카렌 전하 말입니까?",
  ui_story_5031_50310201_13_dialog_content = "카렌 말대로라면 하버 시티는 어둠의 위기 전에 정식으로 백야성의 속령이 돼서\n백야성의 보호를 받았던 거구나.",
  ui_story_5031_50310201_14_dialog_content = "그럼 그전까진 자신들의 힘으로 터전을 지켰던 거야?",
  ui_story_5031_50310201_15_dialog_content = "기록에 따르면 과거의 하버 시티에는 수많은 암귀가 나타났었다고 해.\n이곳에 사는 사람들과 암귀들은 계속해서 이 땅을 두고 싸워왔고.",
  ui_story_5031_50310201_16_dialog_content = "계속되는 전쟁 속에서 이 땅의 통치자이자 강력한 루미나를 지닌\n「<color=#FFB400>모드리</color>」 가문은 다른 가문들과 협력했어.",
  ui_story_5031_50310201_17_dialog_content = "그리고 무수히 많은 험난한 전투 끝에 모든 암귀를 쫓아낼 수 있었지.",
  ui_story_5031_50310201_18_dialog_content = "그 뒤로...",
  ui_story_5031_50310201_19_dialog_content = "이 땅은 마치 「<color=#FFB400>빛의 신</color>」에게 보호받는 것처럼\n암귀의 소란도 매우 적어졌습니다.",
  ui_story_5031_50310201_20_dialog_content = "사람들이 평온하게 살아가면서 열심히 일하니 도시는 날로 발전할 수 있었지요.",
  ui_story_5031_50310201_21_dialog_content = "카렌 전하. 하버 시티의 과거에 대해 그토록 잘 알고 계시니 실로 영광입니다.",
  ui_story_5031_50310201_22_dialog_content = "또한, 카렌 전하와 백야성의 도움에 감사드립니다.\n그저 「<color=#FFB400>신의 비호</color>」만으로는 어둠의 위기 속에서 살아남을 수 없었을 것입니다.",
  ui_story_5031_50310201_23_dialog_content = "저는 모드리 일가의 후예이자 하버 시티의 현임 영주, 엘비스 모드리라고 합니다.",
  ui_story_5031_50310201_24_dialog_content = "(이상해... 저 사람... 루미나가 왜 저렇게 약하지?)",
  ui_story_5031_50310201_25_dialog_content = "평안하기를, 엘비스 영주. 제 갑작스러운 방문에 곤란하지 않으셨으면 좋겠군요.",
  ui_story_5031_50310201_26_dialog_content = "그럴 리가 있겠습니까.\n물론 미리 언질을 주셨다면 제가 맞이할 채비를 미리 했을 텐데 말이지요.",
  ui_story_5031_50310201_27_dialog_content = "그럴 필요는 없습니다. 괜한 번거로움을 만들고 싶지 않아 연락을 드리지 않았습니다.\n영주께서도 그리 예를 차리지 않았으면 좋겠군요.",
  ui_story_5031_50310201_28_dialog_content = "저희는 단순히 기분 전환을 위해 찾아온 평범한 여행객일 뿐이니까요.",
  ui_story_5031_50310201_29_dialog_content = "카렌 전하의 뜻은 잘 알겠습니다. 그럼 이쪽이 소문의 그 아이테르와 바이스 양이겠군요.",
  ui_story_5031_50310201_30_dialog_content = "안녕하세요. PlayerName입니다.",
  ui_story_5031_50310201_31_dialog_content = "안녕하세요. 영주님께서 PlayerName뿐만 아니라\n저에 대해서도 알고 계실 줄은 몰랐네요.",
  ui_story_5031_50310201_32_dialog_content = "저, 저기!",
  ui_story_5031_50310201_33_dialog_content = "음? 이쪽 분은?",
  ui_story_5031_50310201_34_dialog_content = "저는 환상동물 마스터인 피아라고 해요!\nPlayerName, 카렌 언니, 바이스 언니의 친구기도 하죠!",
  ui_story_5031_50310201_35_dialog_content = "하하, 그렇군요. 환상동물 마스터 피아 양.",
  ui_story_5031_50310201_36_dialog_content = "자, 여러분을 위해 연회를 준비해 두었습니다. 함께 식사하시죠.",
  ui_story_5031_50310201_37_dialog_content = "음... 바이스 양은 「<color=#FFB400>에메랄드호</color>」에서 열리는 행사에 관심이 있으십니까?",
  ui_story_5031_50310201_38_dialog_content = "사실 저 「에메랄드호」를 보유하고 있는 「<color=#FFB400>'매직 핸드' 빌 서커스단</color>」을\n초대한 사람이 바로 접니다.",
  ui_story_5031_50310201_39_dialog_content = "이번 여름 동안 하버 시티의 사람들을 위해 성대한 행사를 열어서\n새로운 추억을 만들어 주고 싶었거든요.",
  ui_story_5031_50310201_40_dialog_content = "배 전체가 서커스단인 건가요? 확실히 뭔가 낭만적인 느낌이 드네요...",
  ui_story_5031_50310201_41_dialog_content = "그렇습니다. 여러분도 관심이 있다면 참가해 보시지요.",
  ui_story_5031_50310201_42_dialog_content = "지금의 단장은 제 어린 시절 친구입니다.\n비록 오랫동안 못 만났지만, 그 능력만큼은 믿을 만한 친구입니다.",
  ui_story_5031_50310201_43_dialog_content = "분명 카니발도 무척 화려하게 준비했을 겁니다.",
  ui_story_5031_50310201_44_dialog_content = "아... 함선!",
  ui_story_5031_50310201_45_dialog_content = "저기...! 혹시 영주님의 친구한테 배를 구경시켜 달라고 부탁해줄 수 있을까요?",
  ui_story_5031_50310201_46_dialog_content = "으음?",
  ui_story_5031_50310201_47_dialog_content = "<size=33>피아! 왜 갑자기 그런 이상한 질문을 하는 거야?!</size>",
  ui_story_5031_50310201_48_dialog_content = "갑자기 생각났는데, 키아로가 하버 시티 항구에 거대하고 이상한 배가 서 있다고 했었어.",
  ui_story_5031_50310201_49_dialog_content = "만약 「구름고래」가 사라진 거라면 그런 커다란 배에 갇혀 있을 가능성도 있잖아!",
  ui_story_5031_50310201_50_dialog_content = "죄송하지만 그건 힘들 것 같습니다.",
  ui_story_5031_50310201_51_dialog_content = "하아? 왜요?",
  ui_story_5031_50310201_52_dialog_content = "자세한 이유는 저도 잘 모르겠습니다만, 아마 서커스단의 규칙일 겁니다.",
  ui_story_5031_50310201_53_dialog_content = "전 어제 단장인 「<color=#FFB400>제노</color>」와 보수로 지급할 보급품에 대해 논의하러 갔습니다.",
  ui_story_5031_50310201_54_dialog_content = "그 친구가 배의 내부를 조금은 보여줄 거라 생각했는데,\n굳이 선실 복도에서만 얘기하려 하더군요.",
  ui_story_5031_50310201_55_dialog_content = "그때 저도 궁금한 마음에 함선을 좀 둘러보게 해 달라고 얘기했지만...",
  ui_story_5031_50310201_56_dialog_content = "「서커스단의 규칙 때문에 외부인을 함선 내부로 들일 수 없다」\n...라면서 거절당했습니다.",
  ui_story_5031_50310201_57_dialog_content = "친구이자 후원자인 제게도 그랬으니... 아마 여러분은 더 힘들 겁니다.",
  ui_story_5031_50310201_58_dialog_content = "함선 내부에 들어가 보고 싶은 이유라도 있습니까?\n제가 다시 제노 단장에게 얘기해 보겠습니다.",
  ui_story_5031_50310201_59_dialog_content = "사실 피아가...",
  ui_story_5031_50310201_60_dialog_content = "아하하! 그냥 궁금해서 그래요! 피아는 아주 작은 마을에서 왔거든요.\n그래서 배 안쪽은 어떻게 생겼을지 좀 궁금해요.",
  ui_story_5031_50310201_61_dialog_content = "<size=33>내가 비밀 임무라고 했잖아! 희귀종에 대한 정보를 다른 사람들한테 말하면 안 돼!</size>",
  ui_story_5031_50310201_62_dialog_content = "피아 양의 마음은 충분히 이해합니다. 저렇게 거대한 함선은 확실히 흔치 않지요.",
  ui_story_5031_50310201_63_dialog_content = "카니발 참가자들 중에도 호기심을 이유로 온 사람들이 많을 겁니다.",
  ui_story_5031_50310201_64_dialog_content = "음, 제가 제노와 한번 얘기해 보도록 하죠.",
  ui_story_5031_50310201_65_dialog_content = "정말요? 고마워요!",
  ui_story_5031_50310201_66_dialog_content = "아닙니다. 하지만 너무 기대하진 마세요.\n제노는 후원자인 제 부탁도 바로 거절했었으니까요.",
  ui_story_5031_50310201_67_dialog_content = "하지만 갑판에서도 카니발과 미식 대회,\n그리고 서커스 공연과 같은 행사가 진행될 예정이니...",
  ui_story_5031_50310201_68_dialog_content = "내부가 아니더라도 피아 양의 호기심을 충분히 채울 수 있을 겁니다.",
  ui_story_5031_50310201_69_dialog_content = "콜록... 콜록, 콜록!",
  ui_story_5031_50310201_70_dialog_content = "영주님!",
  ui_story_5031_50310201_71_dialog_content = "괜찮아요, 파토.",
  ui_story_5031_50310201_72_dialog_content = "카렌 님과 여러분이 방문해 주셔서 즐겁게 대화하다 보니,\n약 먹는 것도 잊어버리고 있었군요.",
  ui_story_5031_50310201_73_dialog_content = "엘비스...",
  ui_story_5031_50310201_74_dialog_content = "환대해 주셔서 고마워요.",
  ui_story_5031_50310201_75_dialog_content = "아닙니다. 방금 제 기침 때문에 흥이 깨지지 않았으면 좋겠군요.",
  ui_story_5031_50310201_76_dialog_content = "그럴 리가요. 그래도 부디 건강에 유의하시길.",
  ui_story_5031_50310201_77_dialog_content = "저희는 에메랄드호에 가서 카니발에 대해 조금 알아보고 싶군요.\n영주께선 멀리 나오지 마세요.",
  ui_story_5031_50310201_78_dialog_content = "...알겠습니다. 그럼 저는 카렌 님에게 드릴 선물을 준비해서 에메랄드호로 가겠습니다.",
  ui_story_5031_50310201_79_dialog_content = "신하 된 자의 예로써 드리는 것이니 모쪼록 받아 주셨으면 합니다.",
  ui_story_5031_50310201_80_dialog_content = "영주의 뜻이 그렇다면 거절하지 않겠습니다.",
  ui_story_5031_50310201_81_dialog_content = "자, 우린 이만 가자.",
  ui_story_5031_50310201_82_dialog_content = "......",
  ui_story_5031_50310201_83_dialog_content = "영주님.",
  ui_story_5031_50310201_84_dialog_content = "파토, 수하들에게 바로 움직일 준비를 하라고 전하세요.",
  ui_story_5031_50310201_85_dialog_content = "...설마 백야성에서 뭔가 알아차린 걸까요?",
  ui_story_5031_50310201_86_dialog_content = "아뇨. 아직 판단하기엔 이릅니다. 하지만 지켜봐야겠죠.",
  ui_story_5031_50310201_87_dialog_content = "아무튼 오늘 반드시 움직여야 합니다.",
  ui_story_5031_50310201_88_dialog_content = "영주님, 제노 단장에게 도움을 청해 보면 어떻겠습니까?",
  ui_story_5031_50310201_89_dialog_content = "오래전부터 영주님의 친구분이셨지 않습니까.",
  ui_story_5031_50310201_90_dialog_content = "그리 간단한 일이 아닙니다. 옛 감정만 가지고 그를 믿을 수는 없습니다.",
  ui_story_5031_50310201_91_dialog_content = "어제 에메랄드호 안쪽을 보고 싶다고 했지만 거절당한 것도 있고 말이지요.",
  ui_story_5031_50310201_92_dialog_content = "제 조사에 의하면 그는 지금 「<color=#FFB400>진리의 결사</color>」라는 조직에 충성하고 있습니다.",
  ui_story_5031_50310201_93_dialog_content = "함부로 우리의 목표를 드러냈다간... 모든 계획이 무산될 수도 있습니다.",
  ui_story_5031_50310201_94_dialog_content = "지금은 더는... 그 친구를 믿을 수 있을지 모르겠군요...",
  ui_story_5031_50310201_95_dialog_content = "알겠습니다. 제게 맡겨 주십시오.",
  ui_story_5031_50310201_96_dialog_content = "네. 저도 그가 과연 제가 알던 제노가 맞는지 조금 더 알아볼 겁니다...",
  ui_story_5031_50310201_97_dialog_content = "엘비스 영주님은 좋은 사람 같아. 그렇게 극진하게 대접해 줄 줄이야...\n나랑 바이스한테도 친절했고 말이야.",
  ui_story_5031_50310201_98_dialog_content = "그러게. 다른 귀족들보다 훨씬 우호적인 것 같아.\n귀족이라고 으스대는 것도 없었고.",
  ui_story_5031_50310201_99_dialog_content = "맞아. 모드리 가문은 다른 많은 귀족과는 달라.\n저들은 자기 백성들을 아끼고, 사람들에게도 많은 사랑을 받고 있어.",
  ui_story_5031_50310201_100_dialog_content = "통치자로서 매우 우수한 사람들이지. 다만...",
  ui_story_5031_50310201_101_dialog_content = "아, 혹시 루미나의 힘이 너무 약한 것 때문에 그래?",
  ui_story_5031_50310201_102_dialog_content = "너도 알아차렸구나. 방금 엘비스 영주가 갑자기 기침을 한 건 단순히 감기 같은 게 아니야.",
  ui_story_5031_50310201_103_dialog_content = "그 기침은 그의 얼굴에 남은 흉터와 마찬가지로...\n「<color=#FFB400>모드리 증후군</color>」이라는 질병 때문이야.",
  ui_story_5031_50310201_104_dialog_content = "얼굴의 흉터가 그래서 생긴 건 줄은 몰랐네.",
  ui_story_5031_50310201_105_dialog_content = "심각한 병이야?",
  ui_story_5031_50310201_106_dialog_content = "사실 나도 그 병에 대해서는 잘 몰라.\n그저 예전에 역사 연구를 하다가 관련 자료를 본 적이 있었어.",
  ui_story_5031_50310201_107_dialog_content = "호기심에 더 많은 자료를 찾아봤지만, 모드리 증후군과 모드리 가문에 대한 기록은 너무 적었어.",
  ui_story_5031_50310201_108_dialog_content = "저 병은 환자의 루미나 에너지를 급속도로 줄어들게 만들고,\n장기간 매우 낮은 수준을 유지하게 만든다는 것만 알 수 있었어.",
  ui_story_5031_50310201_109_dialog_content = "원래부터 강력한 루미나를 가지고 있었다면 그나마 다행이지만,\n보통 사람 정도의 루미나만 가지고 있었다면 발병 후에는 정상적으로 살기 어려워.",
  ui_story_5031_50310201_110_dialog_content = "게다가 병이 심해지면 목숨까지도 위험해져.",
  ui_story_5031_50310201_111_dialog_content = "그럴 정도야?!",
  ui_story_5031_50310201_112_dialog_content = "그래. 하지만 매우 특수한 병이고, 지금까지 하버 시티에서만 발견됐어.\n그래서 일부 학자들은 풍토병으로 추정하고 있어.",
  ui_story_5031_50310201_113_dialog_content = "그런데 하버 시티 사람들은 저 병을 「<color=#FFB400>영웅의 혈통</color>」을 가진 자라는 증거로 굳게 믿고 있어.",
  ui_story_5031_50310201_114_dialog_content = "암귀를 쫓아내는 데에 일조했던 선조들이 엄청난 용기로 암귀의 저주를\n떠안으면서 저런 병에 걸리게 됐다고 믿는 거지.",
  ui_story_5031_50310201_115_dialog_content = "그리고 그 혈통을 계승하는 후손들도 확률적으로 저 병에 걸리게 되는 거야.",
  ui_story_5031_50310201_116_dialog_content = "다행히 최근 환자는 점차 감소하는 추세라고 해.",
  ui_story_5031_50310201_117_dialog_content = "으음, 그렇구나.",
  ui_story_5031_50310201_118_dialog_content = "뭘 다 알아듣는 척하고 있어?",
  ui_story_5031_50310201_119_dialog_content = "다, 당연히 무슨 소린지 다 알아들었거든? 피아가 어리다고 바보인 줄 알아?",
  ui_story_5031_50310201_120_dialog_content = "아무튼 그 영주는 자기 운명을 누구보다 잘 알고 있을 거야.",
  ui_story_5031_50310201_121_dialog_content = "피아가 환상동물 마스터가 될 운명이었던 것처럼...",
  ui_story_5031_50310201_122_dialog_content = "기나긴 영광과 전승 너머엔 분명히 복잡하고 무거운 무언가가 숨어 있을 거야.",
  ui_story_5031_50310201_123_dialog_content = "단순히 외부인의 눈으로 봐서는 판단하기 어려울 거라구.",
  ui_story_5031_50310201_124_dialog_content = "피아 말도 일리가 있어.",
  ui_story_5031_50310201_125_dialog_content = "꽤 그럴듯한 말이었어. 실상은 말하나 마나 한 말이었지만 말이야.",
  ui_story_5031_50310201_126_dialog_content = "후후, 아무튼 그 문제는 일단 신경 쓰지 마.\n지금은 에메랄드호부터 가 봐야 하니까... 얼른 가자!",
  ui_story_5031_50310201_127_dialog_content = "어서 가서 「희귀종」을 구하는 거야!\n임무를 완수하면 피아도 모두랑 같이 놀 수 있어!",
  ui_story_5031_50310201_128_dialog_content = "밀지 마... 네가 에메랄드호 안쪽까지 들어갈 수 있다고 어떻게 확신하는데?",
  ui_story_5031_50310201_129_dialog_content = "피아의 엄청난 매력이라면 가능하지 않을까?",
  ui_story_5031_50310201_130_dialog_content = "매력은 무슨... 동물인 척 들어가서 공연이라도 하는 게 더 가능성 있겠어.",
  ui_story_5031_50310201_131_dialog_content = "우읏──!",
  ui_story_5031_50310201_132_dialog_content = "또 피아가 작다고 놀리는 거지?!",
  ui_story_5031_50310201_133_dialog_content = "이리 와! 당장 이리 오라구!",
  ui_story_5031_50310201_134_dialog_content = "뭐, 뭐야, 피아! 잡아당기지 마!",
  ui_story_5031_50310201_135_dialog_content = "바다에 던져버릴 거야! 키아로한테 공처럼 머리에 이고 있으라고 할 거야!",
  ui_story_5031_50310201_136_dialog_content = "뭐라고? 키아로가 무슨 바다표범이야? 그렇게 하면 키아로도 싫어할걸?",
  ui_story_5031_50310201_137_dialog_content = "상관없거든!",
  ui_story_5031_50310201_138_dialog_content = "휴... 둘이 소란 피우는 걸 보니 뭔가 긴장이 풀리는 것 같아.",
  ui_story_5031_50310201_139_dialog_content = "그러게. 이렇게 마음이 편한 것도 정말 오랜만이야.",
  ui_story_5031_50310201_140_dialog_content = "잠깐만!",
  ui_story_5031_50310201_141_dialog_content = "그, 그만 좀 해... 왜 그래, 카렌?",
  ui_story_5031_50310201_142_dialog_content = "바닷가에... 어째서 암귀가...",
  ui_story_5031_50310201_143_dialog_content = "다들 조심해. 저 암귀 녀석들... 뭔가 이상해. 얼른 전투를 준비해!",
  ui_story_5031_50310202_1_dialog_content = "크에엑...",
  ui_story_5031_50310202_2_dialog_content = "이 암귀들... 왜 이렇게 약한 거지?",
  ui_story_5031_50310202_3_dialog_content = "여러분, 다친 곳은 없으십니까?",
  ui_story_5031_50310202_4_dialog_content = "...아, 아니?! 카렌 전하 아니십니까!\n카렌 전하를 위험에 빠트리다니 저희의 불찰입니다!",
  ui_story_5031_50310202_5_dialog_content = "놀랄 필요 없어. 연약한 시민도 아니고, 우리 몸은 우리가 지킬 수 있어.",
  ui_story_5031_50310202_6_dialog_content = "다만 경계를 늦춰선 안 돼. 위험은 항상 어둠 속에 도사리고 있으니까.",
  ui_story_5031_50310202_7_dialog_content = "예! 카렌 전하의 가르침을 받들어 순찰을 한층 더 강화하겠습니다!\n또한 최근 바닷가에 암귀가 나타나는 이유를 찾아내겠습니다!",
  ui_story_5031_50310202_8_dialog_content = "좋아. 이제 가서 임무를 수행하도록.",
  ui_story_5031_50310202_9_dialog_content = "예!",
  ui_story_5031_50310202_10_dialog_content = "우와! 카렌 언니, 정말 멋져! 말도 행동도 여왕 같은 기품이 느껴져!",
  ui_story_5031_50310202_11_dialog_content = "당연하지. 카렌은 백야성 성주의 딸이니까. 분명히 나중에 훌륭한 통치자가 될 거야.",
  ui_story_5031_50310202_12_dialog_content = "고마워... 하지만 아직은 많이 부족한걸.",
  ui_story_5031_50310202_13_dialog_content = "이 얘기는 나중에 하자. 바로 앞에 있는 게 「에메랄드호」야. 어서 가자.",
  ui_story_5031_50310202_14_dialog_content = "미식 대회에 참가하려는 분은 이쪽으로 오세요~",
  ui_story_5031_50310202_15_dialog_content = "여기가 배 위인가? 사람이 엄청 많네.",
  ui_story_5031_50310202_16_dialog_content = "PlayerName, 우선 정보를 수집해 보자.",
  ui_story_5031_50310202_17_dialog_content = "좋아.",
  ui_story_5031_50310202_18_dialog_content = "안녕하세요. 카니발에 대해 여쭤보고 싶은 게...",
  ui_story_5031_50310202_19_dialog_content = "유후! 「‘매직 핸드’ 빌 서커스단」에 오신 것을 환영합니다!",
  ui_story_5031_50310202_20_dialog_content = "저희 서커스단은 처음이신 모양이네요. 그럼 이쪽으로 오세요.",
  ui_story_5031_50310202_21_dialog_content = "하지만 배에서 이상한 짓을 하는 건 안 돼요.\n멋대로 굴면 저도 가만히 있지 않을 거예요!",
  ui_story_5031_50310202_22_dialog_content = "멜트 언니. 제노 단장이 손님을 맞이하라고 했잖아. 게으름 피우면 안 돼~",
  ui_story_5031_50310202_23_dialog_content = "자~ 자~ 저기 저 사람 언니 스타일이네. 가서 인사해 봐.",
  ui_story_5031_50310202_24_dialog_content = "으앗! 사, 사블리! 밀지 마세요...",
  ui_story_5031_50310202_25_dialog_content = "헤헤, 근데 진짜 비슷하게 생겼잖아? 좀 더 가까이 가서 보라구.",
  ui_story_5031_50310202_26_dialog_content = "응? 뭐가 비슷한데? 무슨 얘기 하는 거야?",
  ui_story_5031_50310202_27_dialog_content = "멜 언니가 수집한 움브라톤의 사진에 있는 사람 말이야!",
  ui_story_5031_50310202_28_dialog_content = "그게 무슨 소리야?",
  ui_story_5031_50310202_29_dialog_content = "잠깐만, 진짜 닮았는데? 설마 네가 그 아이테르인 건 아니겠지?",
  ui_story_5031_50310202_30_dialog_content = "아, 맞아. 난 아이테르야... 근데 날 어떻게 아는 건데?",
  ui_story_5031_50310202_31_dialog_content = "──!",
  ui_story_5031_50310202_32_dialog_content = "사브 언니, 멜 언니는 왜 도망간 거야?",
  ui_story_5031_50310202_33_dialog_content = "그럼 이 사람부터 붙잡을까?",
  ui_story_5031_50310202_34_dialog_content = "뭐라고?!",
  ui_story_5031_50310202_35_dialog_content = "아하하, 그거 재밌겠네. 근데 팜므, 함부로 굴면 안 돼.\n우린 일단 멜 언니부터 쫓아가고 여긴 레인보우 언니한테 맡기자.",
  ui_story_5031_50310202_36_dialog_content = "거기! 너네 왜 또 농땡이 피우고 있는 거야?",
  ui_story_5031_50310202_37_dialog_content = "아, 미안 미안. 저 세 사람은 임시로 도와주러 온 거거든.",
  ui_story_5031_50310202_38_dialog_content = "다들 카니발에 참가하러 온 거지~?",
  ui_story_5031_50310202_39_dialog_content = "난 서커스단의 사회자 겸 안내인 겸 보안요원 겸 본직은 견습 기관사인 레인보우라고 해~",
  ui_story_5031_50310202_40_dialog_content = "지, 직함이 엄청 기네...",
  ui_story_5031_50310202_41_dialog_content = "헤헤, 그래서 다들 날 대단하다고 한다니까~",
  ui_story_5031_50310202_42_dialog_content = "안녕, 언니~ 어떻게 하면 배에 들어갈 수 있는지 물... 으앗!",
  ui_story_5031_50310202_43_dialog_content = "그렇게 대놓고 물어보면 순순히 들어가게 해줄 리가 없잖아.",
  ui_story_5031_50310202_44_dialog_content = "그, 그럼 어떡해?",
  ui_story_5031_50310202_45_dialog_content = "안녕. 카니발엔 어떻게 참가해?",
  ui_story_5031_50310202_46_dialog_content = "카니발이라면 아직 준비 중이야. 손님들은 배에서 개최 신호만 기다리면 돼.",
  ui_story_5031_50310202_47_dialog_content = "자, 다들 일단 미식 대회부터 구경하러 가 봐~",
  ui_story_5031_50310202_48_dialog_content = "곧 뜨거운 대결이 펼쳐질 예정이거든. 그리고 재미있는 가게도 잔뜩 있다구.",
  ui_story_5031_50310202_49_dialog_content = "저쪽으로 가면 돼~",
  ui_story_5031_50310202_50_dialog_content = "고마워. 그럼 우선 둘러보고 올게.",
  ui_story_5031_50310202_51_dialog_content = "방금 그 서커스단 단원들, 뭔가 기묘한 느낌인걸.",
  ui_story_5031_50310202_52_dialog_content = "특히 그 세 자매는 왠지 PlayerName한테 관심이 많아 보였어.",
  ui_story_5031_50310202_53_dialog_content = "그래...? 이상한 사람들이랑 엮이진 않았으면 좋겠는데.",
  ui_story_5031_50310202_54_dialog_content = "매번 성가신 일에 말려드는 경우가 많으니까... 지금은 모두와 함께 좀 쉬고 싶어.",
  ui_story_5031_50310202_55_dialog_content = "으음... 대체 어떻게 해야 배에 들어갈 수 있을까?",
  ui_story_5031_50310202_56_dialog_content = "방금 그 말이 잘 통할 것 같은 언니를 설득할 수도 있었는데 말이야.",
  ui_story_5031_50310202_57_dialog_content = "대놓고 그렇게 말했다간 바다에 던져질걸?",
  ui_story_5031_50310202_58_dialog_content = "영주님이 그랬잖아. 내부엔 서커스단 멤버만 들어갈 수 있다고.",
  ui_story_5031_50310202_59_dialog_content = "아무튼 우선 조사부터 해보자. 뭔가 발견할 수 있을지도 모르잖아.",
  ui_story_5031_50310202_60_dialog_content = "잠깐만, 저기 저쪽에 있는 노점에... 왠지 낯익은 얼굴이 있어.",
  ui_story_5031_50310202_61_dialog_content = "이 뜨거운 여름에 여러분의 더위를 식혀줄 단 하나의 음식을 경험해 보세요.",
  ui_story_5031_50310202_62_dialog_content = "최근에 새로 출시한 「<color=#FFB400>시원한 하버 시티 한정판</color>」 맛도 있답니다.",
  ui_story_5031_50310202_63_dialog_content = "한 번에 빙수 10개를 주문하시면 아이테르 이미지가 인쇄된 보냉백을 선물로 드립니다.",
  ui_story_5031_50310202_64_dialog_content = "자, 아리따운 아가씨. 여기 빙수 10개랑 보냉백 받으세요.",
  ui_story_5031_50310202_65_dialog_content = "저건 내가 발명한 빙수잖아! 클레이튼 씨가 너까지 홍보에 이용하고 있어!",
  ui_story_5031_50310202_66_dialog_content = "바이스... 작년에 클레이튼이랑 「<color=#FFB400>기술 양도 계약</color>」 썼던 거 기억나지?",
  ui_story_5031_50310202_67_dialog_content = "아무래도 저게 그 계약의 결과인 것 같네.",
  ui_story_5031_50310202_68_dialog_content = "으, 으음... 너무 달아.",
  ui_story_5031_50310202_69_dialog_content = "하지만 바이스가 만든 빙수처럼 맛이 풍부하진 않네.",
  ui_story_5031_50310202_70_dialog_content = "나, 나도 하나 먹을래!",
  ui_story_5031_50310202_71_dialog_content = "너희 그걸 바로 사 오면 어떡해?!",
  ui_story_5031_50310202_72_dialog_content = "바이스는 아직도 빙수 사업을 빼앗긴 슬픔에 빠져 있단 말이야.",
  ui_story_5031_50310202_73_dialog_content = "나, 난 괜찮아... 모두가 맛있는 빙수를 먹을 수 있다면... 난... 난...",
  ui_story_5031_50310202_74_dialog_content = "클레이튼 씨한테서 기술을 되찾아 와야겠어!",
  ui_story_5031_50310202_75_dialog_content = "<color=#e8d9bb>잠시 후</color>",
  ui_story_5031_50310202_76_dialog_content = "으! 차가워.",
  ui_story_5031_50310202_77_dialog_content = "한 번에 너무 많이 먹으면 머리가 아플지도 몰라.",
  ui_story_5031_50310202_78_dialog_content = "바이스는 아직도 클레이튼이랑 얘기 중인 건가. 괜찮겠지?",
  ui_story_5031_50310202_79_dialog_content = "PlayerName!",
  ui_story_5031_50310202_80_dialog_content = "응? 이 익숙한 목소리...",
  ui_story_5031_50310202_81_dialog_content = "PlayerName, 정말 너였구나.",
  ui_story_5031_50310202_82_dialog_content = "플뢰르? 네가 왜 여기 있어?",
  ui_story_5031_50310202_83_dialog_content = "응? 너도 「이상한 냄비 쟁탈전」에 참가하러 온 거 아니었어?\n곧 시작될 미식 대회 말이야.",
  ui_story_5031_50310202_84_dialog_content = "참, 저번에 빵 구워줘서 고마워.",
  ui_story_5031_50310202_85_dialog_content = "그 뒤로 한참 생각했거든. 그리고 결심했어.\n그 빵의 맛을 대륙에 전파하고, 내 실력도 기를 수 있게 이 대회에 참가하자고.",
  ui_story_5031_50310202_86_dialog_content = "아, 고맙긴 뭘. 미식 대회 얘기는 나도 방금 들은 거라...\n잠깐만, 「<color=#FFB400>이상한 냄비</color>」라고?!",
  ui_story_5031_50310202_87_dialog_content = "...설마! 레디젤 사막의 철인 요리사...",
  ui_story_5031_50310202_88_dialog_content = "「암귀 육질 평론가」 조니 아저씨!\n맞아. 바로 그 사람이 썼다는 「이상한 냄비」야!",
  ui_story_5031_50310202_89_dialog_content = "카렌 언니, 조니 아저씨가 누구야?",
  ui_story_5031_50310202_90_dialog_content = "레디젤 사막에서 무척 유행하는 레시피를 만든 사람이라는 것 같아.\n자세한 건 나도 잘 모르겠어.",
  ui_story_5031_50310202_91_dialog_content = "으, 너 왜 그런 걸 좋아하는 건데...",
  ui_story_5031_50310202_92_dialog_content = "조니 아저씨는 보통 사람이 아냐!\n그 냄비로 온 대륙을 휩쓴 음식을 만들어냈던 사람이라고!",
  ui_story_5031_50310202_93_dialog_content = "서, 서, 서, 설마 조니 아저씨도 이상한 냄비 쟁탈전에 참가하는 건 아니겠지?",
  ui_story_5031_50310202_94_dialog_content = "아, 아니지. 아저씨는 아직도 이곳저곳을 떠돌고 있겠지.\n그럼 설마 「이상한 냄비 쟁탈전」이라는 건...!",
  ui_story_5031_50310202_95_dialog_content = "맞아! 1등 상품이 바로 그 「이상한 냄비」야!",
  ui_story_5031_50310202_96_dialog_content = "비록 그 사람이 직접 올지는 모르겠지만,\n그 사람이 쓰던 전설의 조리도구가 상품인 이상, 각지의 고수들이 몰려올 거야!",
  ui_story_5031_50310202_97_dialog_content = "나도! 나도 참가할래!",
  ui_story_5031_50310202_98_dialog_content = "그 냄비를 바이스한테 선물한다면 콜로서스의 모두가 행복해질 수 있어!",
  ui_story_5031_50310202_99_dialog_content = "으앗! PlayerName, 갑자기 뭘 그렇게 소리를 질러?! 너무 흥분한 거 아냐?",
  ui_story_5031_50310202_100_dialog_content = "미안, 플뢰르. 우린 잠깐 PlayerName하고 얘기 좀 할게.",
  ui_story_5031_50310202_101_dialog_content = "아, 알았으니까 그만 잡아당겨. 카렌, 피아...",
  ui_story_5031_50310202_102_dialog_content = "플뢰르, 기다려 줘! 반드시 돌아올게!",
  ui_story_5031_50310202_103_dialog_content = "좋아. 기다릴게!",
  ui_story_5031_50310202_104_dialog_content = "여기서 네가 돌아올 때까지 기다릴 테니까!",
  ui_story_5031_50310202_105_dialog_content = "PlayerName, 좀 진정됐어?",
  ui_story_5031_50310202_106_dialog_content = "미안. 방금 전엔 너무 들떴었나 봐.",
  ui_story_5031_50310202_107_dialog_content = "휴, 욕망에 빠져 이성을 잃은 PlayerName 오빠라니.",
  ui_story_5031_50310202_108_dialog_content = "다들 왜 여기까지 온 거야? 한참 찾았잖아!",
  ui_story_5031_50310202_109_dialog_content = "바이스! 클레이튼이랑 얘기는 잘 됐어?",
  ui_story_5031_50310202_110_dialog_content = "시, 실패했어... 대신 무료 빙수를 잔뜩 가져왔어!",
  ui_story_5031_50310202_111_dialog_content = "다 같이 힘껏 먹어 치우고 이 굴욕을 씻어내자! 냠냠냠.",
  ui_story_5031_50310202_112_dialog_content = "바이스가 잔뜩 화난 것 같네... 냠냠.",
  ui_story_5031_50310202_113_dialog_content = "으윽! 머리 시려!",
  ui_story_5031_50310202_114_dialog_content = "한 번에 너무 많이 먹은 거 아냐? 으윽... 나도 아프기 시작했어.",
  ui_story_5031_50310202_115_dialog_content = "어? 저기 저쪽에 있는 계단... 혹시 아래쪽 선실로 가는 입구 아닐까?",
  ui_story_5031_50310202_116_dialog_content = "응? 피아도 볼래.",
  ui_story_5031_50310202_117_dialog_content = "맞는 것 같은데... 한 번 가 볼까?",
  ui_story_5031_50310202_118_dialog_content = "멋대로 들어가는 건 좋지 않아.",
  ui_story_5031_50310202_119_dialog_content = "만약 여기 구름고래를 잡은 악당이 있다면, 우리가 들어가서 조사하게 두진 않을 거야.",
  ui_story_5031_50310202_120_dialog_content = "우선 노크라도 해 보자.",
  ui_story_5031_50310202_121_dialog_content = "똑똑~ 저기요, 실례합니다. 들어갈게요.",
  ui_story_5031_50310202_122_dialog_content = "지금 입으로 「노크」한 거야?",
  ui_story_5031_50310202_123_dialog_content = "<color=#e8d9bb>끼익──</color>",
  ui_story_5031_50310202_124_dialog_content = "꺄앗!",
  ui_story_5031_50310202_125_dialog_content = "누구십니까?",
  ui_story_5031_50310202_126_dialog_content = "저, 저희는 그냥 지나가던 평범한 관광객이에요!",
  ui_story_5031_50310202_127_dialog_content = "설마 모든 희망을 버릴 각오를 하고 이 문에 들어오려고 한 것은 아니겠지요.",
  ui_story_5031_50310202_128_dialog_content = "그게 아니라면, 어서 이곳을 떠나세요.",
  ui_story_5031_50310202_129_dialog_content = "...하아?",
  ui_story_5031_50310202_130_dialog_content = "이 아래는 관광객에게 개방하지 않는다는 말입니다.",
  ui_story_5031_50310202_131_dialog_content = "돌아가세요.",
  ui_story_5031_50310202_132_dialog_content = "아, 미안해요! 갈게요!",
  ui_story_5031_50310202_133_dialog_content = "으으, 역시 쉽게 잠입할 순 없네.",
  ui_story_5031_50310202_134_dialog_content = "그럼 어떡하지?",
  ui_story_5031_50310202_135_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5031_50310202_136_dialog_content = "「배에 방문해 주신 내빈 여러분, 카니발 대회가 곧 시작될 예정입니다.」",
  ui_story_5031_50310202_137_dialog_content = "「참가를 원하시는 분께서는 지정된 장소에서 설명을 듣고 참가 신청을 해 주시기 바랍니다.」",
  ui_story_5031_50310202_138_dialog_content = "「참가자는 서커스단의 일원이 되어 행사에 참가할 수 있을 뿐만 아니라,\n고액의 나이티움 상금을 얻으실 수 있습니다.」",
  ui_story_5031_50310202_139_dialog_content = "「수많은 시험을 통과한 1위 참가자에게는 단장님이 직접 호화 상품을 지급합니다.」",
  ui_story_5031_50310202_140_dialog_content = "잠깐만, 그럼 우리가 서커스단의 일원이 된다면... 선실 안으로 들어갈 수 있지 않을까?",
  ui_story_5031_50310202_141_dialog_content = "좋은 생각이야.",
  ui_story_5031_50310202_142_dialog_content = "자, 그럼 가 보자.",
  ui_story_5031_50310202_143_dialog_content = "사람이 왜 이렇게 많은 거냐!",
  ui_story_5031_50310202_144_dialog_content = "쳇, 평민들이 개미처럼 몰려왔군.",
  ui_story_5031_50310202_145_dialog_content = "이 몸은 귀족이신 심판관 마티외다. 평민들은 저 멀리 떨어져라.",
  ui_story_5031_50310202_146_dialog_content = "......",
  ui_story_5031_50310202_147_dialog_content = "시끄럽다! 썩 비켜라!",
  ui_story_5031_50310202_148_dialog_content = "쳇, 입도 뻥긋 않는 뢰베 네 녀석도 정말 짜증 난단 말이다.",
  ui_story_5031_50310202_149_dialog_content = "카렌, 저기 두 사람, 왠지 백야성 사람 같은데?",
  ui_story_5031_50310202_150_dialog_content = "심판소 사람처럼 보이는데... 신경 쓰지 말자.",
  ui_story_5031_50310202_151_dialog_content = "바이스~ 카렌이랑 PlayerName도 있었네. 여기 꼬마 친구는?",
  ui_story_5031_50310202_152_dialog_content = "그로누 선배! 아, 이쪽은...",
  ui_story_5031_50310202_153_dialog_content = "난 환상동물 마스터 피아라고 해! 잘 부탁해!",
  ui_story_5031_50310202_154_dialog_content = "그래, 그래. 착하네~ 아이테르, 꼬마 친구한테 나쁜 거 가르치면 안 돼.",
  ui_story_5031_50310202_155_dialog_content = "거기서 내가 왜 나와?!",
  ui_story_5031_50310202_156_dialog_content = "그로누 선배, 여긴 어쩐 일이에요?",
  ui_story_5031_50310202_157_dialog_content = "나만 온 거 아니야. 네 귀여운 후배도 있다구~",
  ui_story_5031_50310202_158_dialog_content = "저기..., 저, 저기, 다들 안녕하세요. 전 시엘이에요... 전에 학교에서 바이스랑 같이 공부했어요.",
  ui_story_5031_50310202_159_dialog_content = "저기?",
  ui_story_5031_50310202_160_dialog_content = "아, 시엘, 오랜만이야!\n내가 PlayerName하고 같이 다니기 시작한 뒤로는 거의 못 본 것 같네.",
  ui_story_5031_50310202_161_dialog_content = "시엘은 수줍음이 조금 많은 편이거든.",
  ui_story_5031_50310202_162_dialog_content = "그래도 학교에서는 「공학 천재」라고 불렸다니까!",
  ui_story_5031_50310202_163_dialog_content = "그렇구나. 역시 대단한 사람들은 다들 뭔가 하나씩은 특징이 있는 것 같네.",
  ui_story_5031_50310202_164_dialog_content = "그럼 그로누랑 시엘도 놀러 온 거야?",
  ui_story_5031_50310202_165_dialog_content = "땡! 틀렸어. 놀러 왔다면 더 귀여운 옷을 입었겠지~",
  ui_story_5031_50310202_166_dialog_content = "아이테르는 정말 둔하네. 바이스 너도 모르겠어?",
  ui_story_5031_50310202_167_dialog_content = "이 함선을 봐... 엄청나게 크잖아.\n분명히 엄청나게 복잡한 첨단 기계 구조로 되어 있을 거야.",
  ui_story_5031_50310202_168_dialog_content = "그래서 정보를 확인하자마자 바로 시엘을 데리고 조사하러 달려온 거라구.",
  ui_story_5031_50310202_169_dialog_content = "음~ 근데 선실 내부로는 갈 수 없는 것 같았어.\n밖에서는 딱히 쓸만한 정보를 얻기도 힘들고 말이야.",
  ui_story_5031_50310202_170_dialog_content = "그래서 우린 시합에 참가하기로 했어!",
  ui_story_5031_50310202_171_dialog_content = "그럼 바이스 넌 그로누를 도와주러 갈 거야?",
  ui_story_5031_50310202_172_dialog_content = "그럴 필요는 없어~ 콜로서스 파티를 해체시키고 싶지도 않고,\n주최 측에서도 파티 인원이 다른 경우까지 고려해 뒀다고 들었어.",
  ui_story_5031_50310202_173_dialog_content = "게다가 시엘 실력도 바이스 못지않고 말이야~",
  ui_story_5031_50310202_174_dialog_content = "노, 노력할게요...",
  ui_story_5031_50310202_175_dialog_content = "그럼~ 우린 먼저 준비하러 가 볼게. 조금 이따 봐.",
  ui_story_5031_50310202_176_dialog_content = "으으... 강력한 상대가 계속 늘어나고 있어.",
  ui_story_5031_50310202_177_dialog_content = "시합 해설은 언제 시작하는 거야?!",
  ui_story_5031_50310202_178_dialog_content = "응? 무대 위로 사람 두 명이 올라간 것 같은데?",
  ui_story_5031_50310202_179_dialog_content = "엘비스와 방금 전의 그 검은 옷 남자잖아?",
  ui_story_5031_50310202_180_dialog_content = "크흠, 흠흠.",
  ui_story_5031_50310202_181_dialog_content = "친애하는 하버 시티의 주민 여러분, 멀리서 이곳까지 찾아와 주신 여러분. 모두 환영합니다.",
  ui_story_5031_50310202_182_dialog_content = "저는 하버 시티의 영주, 엘비스 모드리입니다.",
  ui_story_5031_50310202_183_dialog_content = "영주님!",
  ui_story_5031_50310202_184_dialog_content = "엘비스 모드리! 엘비스 모드리!",
  ui_story_5031_50310202_185_dialog_content = "모두 감사합니다. 이 아름다운 여름을 맞아 바다의 전설을 모실 수 있어 정말 영광입니다──",
  ui_story_5031_50310202_186_dialog_content = "오늘 이 자리에서, 이름 높은 ‘매직 핸드’ 빌 서커스단이 여러분을 위해\n새로운 카니발 대회와 공연을 준비했습니다.",
  ui_story_5031_50310202_187_dialog_content = "저는 ‘매직 핸드’ 빌 서커스단의 단장인 제노 갤러거입니다.\n저희 서커스단을 찾아 주셔서 감사합니다.",
  ui_story_5031_50310202_188_dialog_content = "본 대회에서는 부정행위를 방지하는 차원에서,\n각 도전의 시작 직전에 규칙을 공개합니다.",
  ui_story_5031_50310202_189_dialog_content = "모든 도전에 통과한 참가자는 서커스단 공연에 참가할 수 있고, 일일 멤버가 될 수 있습니다.",
  ui_story_5031_50310202_190_dialog_content = "또한, 제가 준비한 진귀한 선물도 손에 넣을 수 있습니다.",
  ui_story_5031_50310202_191_dialog_content = "사람들은 종종 서커스단에는 진귀하고 기이한 물건이 많이 있다고 생각하죠.",
  ui_story_5031_50310202_192_dialog_content = "사실 ‘매직 핸드’ 빌 서커스단도 그렇습니다.",
  ui_story_5031_50310202_193_dialog_content = "저희는 바다를 항해하며 혹독한 훈련을 통해 서커스의 오의를 탐구합니다.\n그와 함께 바다에서 깨우침을 얻기도 하죠.",
  ui_story_5031_50310202_194_dialog_content = "그리고 바다는 우리에게 무수한 보물을 안겨 줍니다.\n바로 그 보물들이 이번 카니발의 보상이기도 합니다.",
  ui_story_5031_50310202_195_dialog_content = "진귀한 보물들을 마음껏 상상하고 기대하십시오. 결코 실망하지 않을 것입니다.",
  ui_story_5031_50310202_196_dialog_content = "오오오! 엄청 비싼 건가 봐!",
  ui_story_5031_50310202_197_dialog_content = "부자가 될 수 있겠어!",
  ui_story_5031_50310202_197X1_dialog_content = "바다가 선물한... 진귀한 보물... 알 것 같아!",
  ui_story_5031_50310202_197X2_dialog_content = "분명히 구름고──우웁!",
  ui_story_5031_50310202_197X3_dialog_content = "쉿! 목소리 낮춰. 녀석의 정체를 사람들한테 알려서 적을 잔뜩 늘릴 셈이야?",
  ui_story_5031_50310202_197X4_dialog_content = "아, 알겠어. 그럼 시합에서 우승해서 구름고래를 구하자!",
  ui_story_5031_50310202_198_dialog_content = "심사위원이 저 혼자라면 모두의 납득을 보장하기 어려울지도 모릅니다.",
  ui_story_5031_50310202_199_dialog_content = "그래서 하버 시티 사람들에게 존경받는 영주 엘비스 님께서\n심판을 맡아주실 것을 부탁드리고자 합니다.",
  ui_story_5031_50310202_200_dialog_content = "영주님! 영주님!",
  ui_story_5031_50310202_201_dialog_content = "저기... 제노? 우리가 이 일에 대해 미리 얘기했던가?",
  ui_story_5031_50310202_202_dialog_content = "문제라도 있습니까? 가끔은 골치 아픈 정무를 내려놓으시지요.\n당신께도 즐거움을 누릴 권리가 있습니다.",
  ui_story_5031_50310202_203_dialog_content = "영주님! 영주님!",
  ui_story_5031_50310202_204_dialog_content = "...좋아. 알겠어.",
  ui_story_5031_50310202_205_dialog_content = "여러분, 그럼 마음껏 즐겨 주십시오!",
  ui_story_5031_50310301_0_dialog_content = "음, 이 끈은 이쪽으로 끼우는 거겠지...?",
  ui_story_5031_50310301_0X1_dialog_content = "어라? 여, 여기 왜 또 끈이 하나 더 있지?!",
  ui_story_5031_50310301_0X2_dialog_content = "이건... 음... 반대편에서 끼우면 되는 건가?",
  ui_story_5031_50310301_0X3_dialog_content = "바이스, 고생이 많아.",
  ui_story_5031_50310301_0X4_dialog_content = "아니야, 카렌. 조금만 기다려. 내가 좀 더 살펴보면 금방 해줄 수 있을 거야.",
  ui_story_5031_50310301_0X5_dialog_content = "응, 난 괜찮아. 천천히 해도 돼.",
  ui_story_5031_50310301_0X6_dialog_content = "음, 여기... 맞겠지!",
  ui_story_5031_50310301_0X7_dialog_content = "으... 안 맞는 것 같은데?",
  ui_story_5031_50310301_0X8_dialog_content = "...바이스.",
  ui_story_5031_50310301_0X9_dialog_content = "응? 왜 그래? 내가 아프게 했어?",
  ui_story_5031_50310301_0X10_dialog_content = "아니야, 그냥... 조금 주제넘은 질문을 하나 하고 싶어.",
  ui_story_5031_50310301_0X11_dialog_content = "어? 주제넘은 질문?",
  ui_story_5031_50310301_0X12_dialog_content = "음... 궁금한 게 있어. 네가 각성한 새로운 힘은... 어떤 느낌이야?",
  ui_story_5031_50310301_0X13_dialog_content = "에이, 그게 무슨 주제넘은 질문인데~",
  ui_story_5031_50310301_0X14_dialog_content = "자, 오른팔 좀 들어줘.",
  ui_story_5031_50310301_0X15_dialog_content = "아, 그래.",
  ui_story_5031_50310301_0X16_dialog_content = "음, 근데 그건 사실 답하기가 조금 어려워.",
  ui_story_5031_50310301_0X17_dialog_content = "내가 답하기 싫은 게 아니라, 그 느낌을 뭐라고 설명해야 할지 잘 모르겠거든.",
  ui_story_5031_50310301_0X18_dialog_content = "이해해.",
  ui_story_5031_50310301_0X19_dialog_content = "내가 느낀 기분대로 말하자면, 마치 잠재력이 자극을 받는 것 같았어.",
  ui_story_5031_50310301_0X20_dialog_content = "루미나에 대한 인식이 전과는 크게 달라지지만, 그만큼 위험도 동반해.",
  ui_story_5031_50310301_0X21_dialog_content = "위험?",
  ui_story_5031_50310301_0X22_dialog_content = "응, 왜냐면 난 그 과정에서 마치 심연 같은 잠에 빠졌거든.\n처음엔 내가 영원히 깨어나지 못하는 건 아닐까 싶었어.",
  ui_story_5031_50310301_0X23_dialog_content = "내 자아를 잃어버릴까 너무 무서웠고, 그래서 계속 과거의 날 떠올리려고 노력했어.",
  ui_story_5031_50310301_0X24_dialog_content = "그리고 신기한 장면들도 많이 봤어. 꼭 내가 진짜로 그 장소에 있는 것처럼 말이야.",
  ui_story_5031_50310301_0X25_dialog_content = "그 환각은 마치 진짜 같았고, 나한테 주어진 시험 같았어.",
  ui_story_5031_50310301_0X26_dialog_content = "그러다 다행히 의식의 바다에서 한 줄기 빛을 붙잡았고, 끝까지 버틸 수 있었어.",
  ui_story_5031_50310301_0X27_dialog_content = "그랬구나. 일종의 잠재력의 자극인 건가...",
  ui_story_5031_50310301_0X28_dialog_content = "응, 나도 그렇게 생각해.",
  ui_story_5031_50310301_0X29_dialog_content = "사실 많은 오로리안이 위기의 순간에 힘을 각성하곤 해.",
  ui_story_5031_50310301_0X30_dialog_content = "아마 나도 같은 상황이 아니었을까 싶어.",
  ui_story_5031_50310301_0X31_dialog_content = "근데 지금도 아직 그 힘을 완전히 다룰 순 없어.",
  ui_story_5031_50310301_0X32_dialog_content = "네가 새로운 힘을 각성한 게 아직 오래된 일은 아니잖아.\n시간이 지나면 분명히 잘 다룰 수 있을 거야.",
  ui_story_5031_50310301_0X33_dialog_content = "응! 그렇겠지~",
  ui_story_5031_50310301_0X34_dialog_content = "카렌 너도 시도하고 싶다면, 먼저 의식을 가라앉히는 데서부터 시작하는 건 어떨까?",
  ui_story_5031_50310301_0X35_dialog_content = "의식을 가라앉힌다고?",
  ui_story_5031_50310301_0X36_dialog_content = "응, 내가 그 힘을 끌어내고 싶을 때마다 그렇게 하거든.\n하지만 항상 성공하는 건 아냐.",
  ui_story_5031_50310301_0X37_dialog_content = "그렇구나. 이해했어.",
  ui_story_5031_50310301_0X38_dialog_content = "나중에 한번 해 볼게. 고마워, 바이스.",
  ui_story_5031_50310301_0X39_dialog_content = "천만에!",
  ui_story_5031_50310301_0X40_dialog_content = "자, 이제 마지막 끈도 제대로 묶였어!",
  ui_story_5031_50310301_0X41_dialog_content = "휴, 귀족의 옷은 입는 것도 정말 번거로운 거구나.",
  ui_story_5031_50310301_0X42_dialog_content = "그리고 옷의 재질도 정말 특별해 보여.\n이런 건 일루미나에서는 한 번도 본 적이 없는걸.",
  ui_story_5031_50310301_0X43_dialog_content = "나도 이런 재질은 처음 봐. 아마 하버 시티의 특산품 원단일 거야.",
  ui_story_5031_50310301_0X44_dialog_content = "드레스는 하버 시티의 특산품 중 하나니까.",
  ui_story_5031_50310301_0X45_dialog_content = "고생 많았어, 바이스.",
  ui_story_5031_50310301_0X46_dialog_content = "에이, 괜찮아. 근데 카렌 너 정말 예쁘네!",
  ui_story_5031_50310301_0X47_dialog_content = "나가서 피아랑 PlayerName한테 가 봐. 다들 분명히 엄청 놀랄걸!",
  ui_story_5031_50310301_1_dialog_content = "카렌은 왜 아직도 안 오지...?",
  ui_story_5031_50310301_2_dialog_content = "원래 숙녀가 옷을 갈아입을 땐 시간이 많이 필요한 거야.\n게다가 그 드레스가 엄청 복잡할지도 모르잖아.",
  ui_story_5031_50310301_2X1_dialog_content = "아마 바이스 언니가 도와준다 해도 한참 걸릴걸.",
  ui_story_5031_50310301_3_dialog_content = "그것도 그렇네. 귀족들 옷은 대부분 다른 사람이 도와줘야 입을 수 있는 것 같더라고.",
  ui_story_5031_50310301_4_dialog_content = "피아, 그럼 너도 가서 카렌 좀 도와줄래?",
  ui_story_5031_50310301_5_dialog_content = "하아? 너 지금 피아를 자기 하인인 줄 아는 거야? 나한테 이것저것 시키고!",
  ui_story_5031_50310301_6_dialog_content = "지금 좀 착하게 굴어야 카렌이랑 바이스가\n「구름고래」찾는 걸 더 열심히 도와주지 않겠어?",
  ui_story_5031_50310301_7_dialog_content = "조, 좋아. 옷 입는 걸 도와줘 본 적은 없지만... 한번 해 볼게.",
  ui_story_5031_50310301_8_dialog_content = "PlayerName, 피아 좀 그만 놀려.",
  ui_story_5031_50310301_9_dialog_content = "미안. 오래 기다리게 했네...",
  ui_story_5031_50310301_10_dialog_content = "우와아! 카렌 언니! 진짜 진짜 진짜 엄청 예뻐!",
  ui_story_5031_50310301_11_dialog_content = "그렇지? 편안함과 활동성을 전부 고려한 드레스인 것 같아.\n카렌한테 진짜 잘 어울리더라고!",
  ui_story_5031_50310301_12_dialog_content = "다들 고마워. 하버 시티는 드레스 디자인과 재봉 장인이 많은 걸로 유명한 곳이거든.",
  ui_story_5031_50310301_13_dialog_content = "이 옷 확실히 엄청 편하네.",
  ui_story_5031_50310301_14_dialog_content = "PlayerName, 어떻게 생각해?",
  ui_story_5031_50310301_15_dialog_content = "아, 미안. 방금 완전히 넋을 잃어서... 내가 보기엔...",
  ui_story_5031_50310301_16_dialog_content = "정말 아름답고, 우아하고, 굉장합니다!",
  ui_story_5031_50310301_17_dialog_content = "역시 솔라드 님의 영애다우십니다.\n카렌 전하의 우아한 자태는 정말 눈물이 흐를 정도로 감동적이로군요!",
  ui_story_5031_50310301_18_dialog_content = "아뇨... 너무 과한 찬사로군요. 그래도 고마워요, 엘비스 영주.",
  ui_story_5031_50310301_19_dialog_content = "천만의 말씀이십니다. 카렌 님의 자태를 보는 순간...\n솔라드 가문의 정의로움과 굴하지 않는 고귀한 품격이 떠올랐습니다.",
  ui_story_5031_50310301_20_dialog_content = "부디 그 드레스가 카렌 님께 행운을 선사해 시합에서 우승을 차지하시길 바라겠습니다.",
  ui_story_5031_50310301_21_dialog_content = "그럼 저는 대회 진행을 준비하러 가겠습니다. 나중에 다시 뵙도록 하죠!",
  ui_story_5031_50310301_22_dialog_content = "아, 미안... 아직 카렌의 새 드레스를 제대로 평가하지도 못했는데...",
  ui_story_5031_50310301_23_dialog_content = "이런... 엘비스 영주님이 내가 할 말을 다 해버렸잖아.",
  ui_story_5031_50310301_24_dialog_content = "응. 하지만 아무 말 안 해도 괜찮아.",
  ui_story_5031_50310301_25_dialog_content = "이미 조금 전 네 눈빛으로 모두 읽었으니까.",
  ui_story_5031_50310301_26_dialog_content = "뭐?!",
  ui_story_5031_50310301_27_dialog_content = "여러분~ 안녕하세요! 다시 레인보우의 해설 시간이 찾아왔습니다~",
  ui_story_5031_50310301_28_dialog_content = "저는 서커스단의 사회자 겸 안내인 겸 보안요원 겸 본직은 견습 기관사인 레인보우라고 해요~",
  ui_story_5031_50310301_29_dialog_content = "그리고 이번엔 카니발의 사회자랍니다~",
  ui_story_5031_50310301_30_dialog_content = "첫 번째 시합은 먼저 이곳에서 레인보우의 특제 물총을 받아 가셔야 해요.",
  ui_story_5031_50310301_31_dialog_content = "이 물총은 루미나를 물총의 탄약으로 전환할 수 있답니다.",
  ui_story_5031_50310301_32_dialog_content = "규칙은 간단해요. 물총으로 제노 단장님이 지정한 목표를 공격하면 점수를 딸 수 있어요.",
  ui_story_5031_50310301_33_dialog_content = "하지만 시합 중에는 선수끼리, 또는 팀끼리의 공격도 가능하답니다~",
  ui_story_5031_50310301_34_dialog_content = "최종 점수가 가장 높은 다섯 팀은 다음 시합에 진출할 수 있어요.\n그리고 탈락한 팀은 즉시 바다로 떨어지게 되죠.",
  ui_story_5031_50310301_35_dialog_content = "그러니 수영을 할 줄 모르는 손님은 참가하지 않는 걸 추천할게요~\n최소한 튜브라도 끼고 참가하는 게 좋겠죠.",
  ui_story_5031_50310301_36_dialog_content = "이번 시합은 참가 팀의 인원 제한이 없답니다.\n대신 마지막에 팀원 개인 점수의 평균으로 최종 점수가 결정될 거예요.",
  ui_story_5031_50310301_37_dialog_content = "누님, 저 규칙 저희한테 아주 유리한 것 같은데요?",
  ui_story_5031_50310301_38_dialog_content = "요나 누님과 아주르 누님의 실력이라면 1등은 무조건 저희 겁니다!",
  ui_story_5031_50310301_39_dialog_content = "물총? 조금 어린애 장난 같긴 해도, 상품을 봐서라도 어울려 줘야겠네.",
  ui_story_5031_50310301_40_dialog_content = "어차피 한가하던 참이었는데 좀 놀아보는 것도 좋잖아~",
  ui_story_5031_50310301_41_dialog_content = "흐흐, 이번엔 짭짤하게 벌 수 있겠네요!",
  ui_story_5031_50310301_42_dialog_content = "아직 기뻐하긴 일러. 너희 둘... 우리 레디젤 렌치에 들어온 지 얼마 안 됐지?",
  ui_story_5031_50310301_43_dialog_content = "우리의 규칙을 잘 기억해. 밖에서 레디젤 렌치의 체면을 깎아 먹지 마.",
  ui_story_5031_50310301_44_dialog_content = "걱정 마십쇼. 단단히 명심하고 있으니까요!",
  ui_story_5031_50310301_45_dialog_content = "그 어쩌고랑 저쩌고, 다 알고 있다고요!",
  ui_story_5031_50310301_46_dialog_content = "다들 규칙은 이해하셨나요~?",
  ui_story_5031_50310301_47_dialog_content = "네~",
  ui_story_5031_50310301_48_dialog_content = "잠깐만! 루미나가 필요한 물총이라면... 난 그냥 걸어 다니는 사냥감 꼴이잖아!",
  ui_story_5031_50310301_49_dialog_content = "으음, 그러고 보니까 아이테르가 있는 걸 생각 못 했네요.",
  ui_story_5031_50310301_50_dialog_content = "멜 언니~ 아이테르네 팀 좀 도와줄래?",
  ui_story_5031_50310301_51_dialog_content = "그, 그럼 안 되잖아요?! 우린 시합에 참가하면 안 돼요...",
  ui_story_5031_50310301_52_dialog_content = "휴~ 정말 알 수가 없다니까. 저런 비실비실한 녀석이 어디가 좋다는 거야?\n최소한 몸이라도 튼튼해야지, 나 원 참.",
  ui_story_5031_50310301_53_dialog_content = "사장님~ 아이테르는 어떡해요?",
  ui_story_5031_50310301_54_dialog_content = "노약자 우대로 처리하죠. 저기 꼬마 아가씨랑 한 사람으로 쳐주세요.",
  ui_story_5031_50310301_55_dialog_content = "에?! 왜 바보 아이테르랑 날 하나로 묶는 건데?!",
  ui_story_5031_50310301_56_dialog_content = "그럼 두 사람으로 치세요.",
  ui_story_5031_50310301_57_dialog_content = "아, 사, 사실 피아는... 나이도 어리고 힘도 약해서...\n반으로 쳐 주는 게 맞을 것 같아!",
  ui_story_5031_50310301_58_dialog_content = "자, 다른 의견이 없다면, 이제 표적이 되어 줄 상대를 불러보도록 하죠.",
  ui_story_5031_50310301_59_dialog_content = "자! 여러분! 열렬한 박수로 맞이해 주십시오!",
  ui_story_5031_50310301_60_dialog_content = "울부짖어라! 지옥의 야수들이여!",
  ui_story_5031_50310301_61_dialog_content = "잠깐만! 대장, 설마 부르려는 게...",
  ui_story_5031_50310301_62_dialog_content = "빠, 빨리 레인보우 언니 눈을 가려줘요! 암귀를 보면 또 폭주하고 말 거예요!",
  ui_story_5031_50310301_63_dialog_content = "캬악──!",
  ui_story_5031_50310301_64_dialog_content = "암귀?!",
  ui_story_5031_50310301_65_dialog_content = "암귀!",
  ui_story_5031_50310301_66_dialog_content = "팜므! 얼른 레인보우 언니 붙잡아! 나 혼자서는 무리야!",
  ui_story_5031_50310301_67_dialog_content = "바보 대장! 왜 암귀를 부른 거야?!",
  ui_story_5031_50310301_68_dialog_content = "하... 오늘의 바람과 무척 잘 어울려서 말입니다.",
  ui_story_5031_50310301_69_dialog_content = "PlayerName, 피아, 너흰 나랑 바이스 뒤로 와.",
  ui_story_5031_50310301_70_dialog_content = "모두 걱정하지 않으셔도 됩니다.\n이 암귀들은 제가 「<color=#FFB400>기원</color>」을 이용해서 만들어 낸 환영에 불과하니까요.",
  ui_story_5031_50310301_71_dialog_content = "저는 제가 가진 능력으로 암귀와의 전투 속에서 그들의 「기원」을 분석했습니다.",
  ui_story_5031_50310301_72_dialog_content = "그리고 「<color=#FFB400>기원의 카드</color>」에 담긴 힘으로 이토록 사실적인 환상을 창조한 것입니다.",
  ui_story_5031_50310301_73_dialog_content = "캬악──",
  ui_story_5031_50310301_74_dialog_content = "캬악──",
  ui_story_5031_50310301_75_dialog_content = "보시다시피 모두 제 제어하에 있습니다. 그러니 사격 대상으로는 이보다 좋을 수 없겠지요.",
  ui_story_5031_50310301_76_dialog_content = "그럼 지금부터 시합을 시작하겠습니다!",
  ui_story_5031_50310401_1_dialog_content = "거기 너희들, 게으름 피우지 말고 흩어져서 암귀를 수색해.\n이번 1위는 반드시 우리 레디젤 렌치에서 가져간다.",
  ui_story_5031_50310401_2_dialog_content = "네! 요나 대장, 만약 오로리안을 만나면 어쩌죠?",
  ui_story_5031_50310401_3_dialog_content = "어쩌긴? 우린 레디젤 렌치야!",
  ui_story_5031_50310401_4_dialog_content = "레디젤 렌치의 이름에 먹칠하는 녀석들은 전부 배 밑으로 가라앉혀 주겠어!",
  ui_story_5031_50310401_5_dialog_content = "알겠습니다!",
  ui_story_5031_50310401_6_dialog_content = "정말 멋대로네, 요나.",
  ui_story_5031_50310401_7_dialog_content = "왜 그래? 도저히 공격할 수 없는 꼬마 멋쟁이라도 있어?",
  ui_story_5031_50310401_8_dialog_content = "으음~ 아주 귀엽긴 하지만... 그 매력적인 보상에 비한다면야...",
  ui_story_5031_50310401_9_dialog_content = "이런... 총기에 능숙한 요나에 아주르 씨까지 있잖아.",
  ui_story_5031_50310401_10_dialog_content = "분명히 암귀를 쏴서 점수만 따면 되는 건데...\n저 레디젤 렌치 녀석들은 다른 사람들을 노리고 있어!",
  ui_story_5031_50310401_11_dialog_content = "만약 제노가 만든 환영들이 가려주지 않았다면...\n우리도 벌써 배에서 떨어지고 남았을 거야.",
  ui_story_5031_50310401_12_dialog_content = "계속 이대로 밀리다간 결국 포위되고 말 거야...\n내가 모두와 함께 길을 뚫겠어!",
  ui_story_5031_50310401_13_dialog_content = "잠깐만! 카렌!",
  ui_story_5031_50310401_14_dialog_content = "규칙도 지키지 않는 녀석들, 피어나라... 아니, 받아라! 「얼음의 총」!",
  ui_story_5031_50310401_15_dialog_content = "으윽!",
  ui_story_5031_50310401_16_dialog_content = "대, 대장!",
  ui_story_5031_50310401_17_dialog_content = "자, 두 녀석은 처리했어... 다들 이쪽으로 와.",
  ui_story_5031_50310401_18_dialog_content = "엄청 강하잖아... 카렌의 「얼음의 총」에 바로 바다로 떨어져 버렸어.\n앗! 카렌! 얼른 엄폐물 뒤에 숨어!",
  ui_story_5031_50310401_19_dialog_content = "PlayerName, 지금은 돌격에 가장 좋은 타이밍이야!",
  ui_story_5031_50310401_20_dialog_content = "카렌! 혼자 너무 깊이 들어갔어! 그러다간──",
  ui_story_5031_50310401_21_dialog_content = "잡았다. 백야성의 꼬마 공주님.",
  ui_story_5031_50310401_22_dialog_content = "<color=#e8d9bb>퍼어엉──</color>",
  ui_story_5031_50310401_23_dialog_content = "──!",
  ui_story_5031_50310401_24_dialog_content = "카렌!",
  ui_story_5031_50310401_25_dialog_content = "미, 미안, PlayerName.",
  ui_story_5031_50310401_26_dialog_content = "카렌 네가 무사하면 됐어.\n루미나 물총을 든 요나가 이렇게나 성가실 줄은 몰랐어.",
  ui_story_5031_50310401_27_dialog_content = "으읏! 이 짜증 나는 레디젤 악당들! 성가시게 굴지 말란 말이야!",
  ui_story_5031_50310401_28_dialog_content = "안 되겠어. 이 상황을 돌파할 방법을 떠올려야 해.",
  ui_story_5031_50310401_29_dialog_content = "시합이 점점 뜨거워지고 있군요.",
  ui_story_5031_50310401_30_dialog_content = "그래. 하지만 네가 그런 힘을 사용할 줄은 몰랐어.",
  ui_story_5031_50310401_31_dialog_content = "이건 제가 진리의 결사에서 얻은 힘입니다...",
  ui_story_5031_50310401_32_dialog_content = "아, 당신은 백야성의 귀족이니, 그들에 대한 나쁜 소문을 많이 들었겠군요.",
  ui_story_5031_50310401_33_dialog_content = "「기원」은 원활한 공연의 진행을 위해 호기심을 일으키려 만든 단어에 불과합니다.",
  ui_story_5031_50310401_34_dialog_content = "그것은 제가 가지고 있는 에너지를 전환하는 힘...\n시간이 지나고 보니 그렇게 부르는 게 익숙해졌을 뿐입니다.",
  ui_story_5031_50310401_35_dialog_content = "난 그들에 대해 별다른 생각은 없어. 그러니 그건 안심해도 좋아.",
  ui_story_5031_50310401_36_dialog_content = "하지만 어째서 암귀인 거지?",
  ui_story_5031_50310401_37_dialog_content = "사람들은 짜릿함을 느끼기 위해 카니발에 참가하고 서커스를 구경하죠.",
  ui_story_5031_50310401_38_dialog_content = "그러니 암귀를 불러내는 것은 당연한 일이 아니겠습니까.",
  ui_story_5031_50310401_39_dialog_content = "아주 상업화된 생각이네. 생각이 많아졌구나.",
  ui_story_5031_50310401_40_dialog_content = "그럴 리가요. 전 그저 서커스단을 이끄는 사람일 뿐입니다.",
  ui_story_5031_50310401_41_dialog_content = "실례합니다, 엘비스 님.",
  ui_story_5031_50310401_42_dialog_content = "파토... 그럼 먼저 실례할게, 제노.",
  ui_story_5031_50310401_43_dialog_content = "뭔가 발견했습니까?",
  ui_story_5031_50310401_44_dialog_content = "영주님께서 말씀하셨던 방과 일치하는 곳을 찾았습니다.",
  ui_story_5031_50310401_45_dialog_content = "그게 사실입니까?! 정말 잘됐군요...",
  ui_story_5031_50310401_46_dialog_content = "하지만 그 방은 처음 보는 형태의 자물쇠로 잠겨 있었습니다.\n강제로 열었다간 경보가 울릴지도 모릅니다.",
  ui_story_5031_50310401_47_dialog_content = "알겠습니다. 그럼 문을 열 수 있는 열쇠부터 찾는 게 좋겠군요.",
  ui_story_5031_50310401_48_dialog_content = "열쇠는 아마 제노의 방에 있거나, 그가 항상 가지고 다닐 겁니다.\n우린 각자 행동하도록 하죠.",
  ui_story_5031_50310401_49_dialog_content = "엘비스!",
  ui_story_5031_50310401_50_dialog_content = "제가 방해한 건 아니겠죠? 하지만 한 팀이 또 점수를 획득해서 말입니다.\n점수를 줘야 한다고 관객들이 외치고 있습니다.",
  ui_story_5031_50310401_51_dialog_content = "영주님! 영주님──!",
  ui_story_5031_50310401_52_dialog_content = "미안해, 제노.\n파토와 조금 더 얘기할 일이 있어서.",
  ui_story_5031_50310401_53_dialog_content = "어떻게 하면 좋겠습니까, 엘비스 님.",
  ui_story_5031_50310401_54_dialog_content = "선실 쪽 방을 찾는 건 당신의 수하에게 맡기죠.",
  ui_story_5031_50310401_55_dialog_content = "이 상황에서 제가 오랫동안 자리를 비운다면 분명히 제노의 의심을 살 겁니다.",
  ui_story_5031_50310401_56_dialog_content = "게다가 시합에 참가한 일부 오로리안들의 목적도 그리 간단하지 않은 듯합니다.\n어쩌면 우리가 노리는 걸 그들도 노리고 있을지도 모르지요.",
  ui_story_5031_50310401_57_dialog_content = "그러니 지금은 그들을 감시할 사람도 필요합니다.\n움직이더라도 깊은 밤에 모두 배에서 내린 뒤를 노려야 합니다.",
  ui_story_5031_50310401_58_dialog_content = "영주님 말씀이 맞습니다. 그럼 수하들에게 계속 은밀히 수색하면서,\n엘비스 님의 명령을 기다리라고 하겠습니다.",
  ui_story_5031_50310401_59_dialog_content = "영주님! 영주님!",
  ui_story_5031_50310401_60_dialog_content = "여러분, 오래 기다리셨습니다! 레디젤 렌치 팀에게 1점 더하겠습니다!",
  ui_story_5031_50310401_61_dialog_content = "드디어 돌아오셨군요. 저도 관객들도 한참 기다렸습니다.",
  ui_story_5031_50310401_62_dialog_content = "미안해, 제노. 오래 기다리게 해서.",
  ui_story_5031_50310402_1_dialog_content = "(열쇠라... 어떻게 해야 찾을 수 있는 거지...)",
  ui_story_5031_50310402_2_dialog_content = "엘비스? 괜찮습니까?",
  ui_story_5031_50310402_3_dialog_content = "호위를 만나고 온 뒤로 계속 표정이 좋지 않군요.",
  ui_story_5031_50310402_4_dialog_content = "몸이 불편한 겁니까?",
  ui_story_5031_50310402_5_dialog_content = "아, 괜찮아.",
  ui_story_5031_50310402_6_dialog_content = "그냥 해야 할 일이 좀 생각났거든. 걱정하게 만들어 버렸네.",
  ui_story_5031_50310402_7_dialog_content = "...갑자기 함께 심판을 봐달라고 해서 일에 방해가 된 겁니까?",
  ui_story_5031_50310402_8_dialog_content = "미안합니다. 이렇게 하면 당신과 모두가 함께 기념일을 즐길 수 있으리라 생각했습니다.",
  ui_story_5031_50310402_9_dialog_content = "어? 대장이 사과하는 건 처음 봤어!",
  ui_story_5031_50310402_10_dialog_content = "그러게. 대장도 다른 사람을 화나게 하지 않고 얘기할 수 있었구나~",
  ui_story_5031_50310402_11_dialog_content = "거기 셋, 한가하면 가서 레인보우나 도와주세요.",
  ui_story_5031_50310402_12_dialog_content = "에베베~",
  ui_story_5031_50310402_13_dialog_content = "정말 하루 종일 까부는 녀석들이란 말이죠.",
  ui_story_5031_50310402_14_dialog_content = "하, 내 걱정은 안 해도 돼. 난 그저...",
  ui_story_5031_50310402_15_dialog_content = "조금 신경 쓰이는 일이 있어서 말이야. 아직 고민만 하고 결정을 못 했거든.",
  ui_story_5031_50310402_16_dialog_content = "이번 기회에 푹 쉬어 둔다면, 일이든 사람이든 제대로 헤아리는 데 도움이 될 거야.",
  ui_story_5031_50310402_17_dialog_content = "좋습니다. 만약 몸이 불편하면 꼭 말해 주세요.",
  ui_story_5031_50310402_18_dialog_content = "그래, 알겠어.",
  ui_story_5031_50310402_19_dialog_content = "「시합에 참가해 주신 여러분,\n더욱 뜨거운 시합을 위해 암귀를 더 추가하도록 하겠습니다.」",
  ui_story_5031_50310402_20_dialog_content = "좋았어! 드디어 보너스 타임이야~",
  ui_story_5031_50310402_21_dialog_content = "시엘, 날 엄호해 줘.\n보너스 타임에 전력으로 공격하는 건 높은 점수를 위한 최고의 전략이니까!",
  ui_story_5031_50310402_22_dialog_content = "네, 네! 그로누 선배님!",
  ui_story_5031_50310402_23_dialog_content = "아, 선배님, 너무 빨라요──",
  ui_story_5031_50310402_24_dialog_content = "오호, 이게 누구신가?",
  ui_story_5031_50310402_25_dialog_content = "혼자 떨어진 일루미나 아가씨 아냐?",
  ui_story_5031_50310402_26_dialog_content = "무, 무슨 짓을 할 생각이야?!",
  ui_story_5031_50310402_27_dialog_content = "당연히 모든 보상을 싹쓸이할 생각이지. 그리고 싹 팔아서 실컷 즐길 거라고.",
  ui_story_5031_50310402_28_dialog_content = "꼬마 아가씨, 미안하지만 그 물총은 내가 가져가야겠어.\n그러니 얌전히 바다에 들어가는 게 좋을 거야.",
  ui_story_5031_50310402_29_dialog_content = "잠깐만, 저 꼬마 아가씨... 장비가 꽤 괜찮아 보이잖아?\n다 팔아버리면 움브라톤에서 돈을 꽤 받을 수 있겠어.",
  ui_story_5031_50310402_30_dialog_content = "그래. 그래! 우리 레디젤 렌치는 빈손으로 가는 법이 없지.\n그러니 얌전히 말을 듣는 게 좋을 거야.",
  ui_story_5031_50310402_31_dialog_content = "값나가는 것들을 전부 내놔!",
  ui_story_5031_50310402_32_dialog_content = "거, 건드리지 마!",
  ui_story_5031_50310402_33_dialog_content = "거기, 멈춰──!",
  ui_story_5031_50310402_34_dialog_content = "누구야? 넌 방금 그 사회자잖아?",
  ui_story_5031_50310402_35_dialog_content = "맞아! 약탈과 반칙 행위는 금지야. 계속 그러면 나도 가만히 있지 않겠어!",
  ui_story_5031_50310402_36_dialog_content = "어디서 큰소리야? 사회자라고 해서 우리가 무서워할 줄 알았냐?!",
  ui_story_5031_50310402_37_dialog_content = "힘만 믿고 남을 괴롭히는 건 절대 금지야!",
  ui_story_5031_50310402_38_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5031_50310402_39_dialog_content = "혀, 형님!",
  ui_story_5031_50310402_40_dialog_content = "너도!",
  ui_story_5031_50310402_41_dialog_content = "<color=#e8d9bb>퍼엉──!</color>",
  ui_story_5031_50310402_42_dialog_content = "크아악──!",
  ui_story_5031_50310402_43_dialog_content = "대, 대단해... 그대로 날려버렸어...",
  ui_story_5031_50310402_44_dialog_content = "다치진 않았지? 저 녀석들도 정말 너무하네. 시합 중에 강도짓이라니!",
  ui_story_5031_50310402_45_dialog_content = "아, 나, 난... 그로누 선배님을 도와드리러 가야 돼... 고마워!",
  ui_story_5031_50310402_46_dialog_content = "어라... 물총... 물총이 없어졌어.",
  ui_story_5031_50310402_47_dialog_content = "휴, 정말 어쩔 수 없네. 자, 여기 물총.",
  ui_story_5031_50310402_48_dialog_content = "「물총을 잃어버린 사람은 사회자에게 새로운 물총을 받을 수 있다」\n규칙에 이렇게 적혀 있었으니까 걱정 말고 가져가.",
  ui_story_5031_50310402_49_dialog_content = "으...응! 고마워.",
  ui_story_5031_50310402_50_dialog_content = "저기...",
  ui_story_5031_50310402_51_dialog_content = "응?",
  ui_story_5031_50310402_52_dialog_content = "난 시엘이라고 해. 고마워, 레인보우 씨.",
  ui_story_5031_50310402_53_dialog_content = "시엘? 기억해 둘게.",
  ui_story_5031_50310402_54_dialog_content = "쳇, 정말이지... 카렌 전하께선 왜 이런 평민들이나 하는 놀이에\n참가하시려는 건지 모르겠군.",
  ui_story_5031_50310402_55_dialog_content = "이건 귀족으로써 정말... 몹시 불쾌하단 말이지!",
  ui_story_5031_50310402_56_dialog_content = "......",
  ui_story_5031_50310402_57_dialog_content = "어이, 너도 뭐라고 말 좀 해 보라고!",
  ui_story_5031_50310402_58_dialog_content = "카렌 님을 감시하고, 지켜.",
  ui_story_5031_50310402_59_dialog_content = "쯧, 안 하느니만 못하군.",
  ui_story_5031_50310402_60_dialog_content = "어서! 이쪽으로! 여기 암귀가 잔뜩 있어!",
  ui_story_5031_50310402_61_dialog_content = "앗!",
  ui_story_5031_50310402_62_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5031_50310402_63_dialog_content = "죄, 죄송합니다. 저 때문에 물총을 떨어트리셨군요...",
  ui_story_5031_50310402_64_dialog_content = "제가 주워드리겠습니다.",
  ui_story_5031_50310402_65_dialog_content = "아니, 신경 쓸 거 없다.\n네 친구가 저쪽에서 기다리고 있으니 어서 가서 즐겁게 놀라고.",
  ui_story_5031_50310402_66_dialog_content = "감사합니다. 정말 마음씨 좋은 귀족이시군요.",
  ui_story_5031_50310402_67_dialog_content = "......",
  ui_story_5031_50310402_68_dialog_content = "......기분 나빠.",
  ui_story_5031_50310402_69_dialog_content = "물! 물을 가져와! 손을 씻어야겠어!",
  ui_story_5031_50310402_70_dialog_content = "...성가셔.",
  ui_story_5031_50310402_71_dialog_content = "캬악──!",
  ui_story_5031_50310402_72_dialog_content = "PlayerName, 암귀가 엄청 많아졌어.",
  ui_story_5031_50310402_73_dialog_content = "하지만 저 레디젤 렌치 녀석들은 여전히 우릴 노리고 있어.",
  ui_story_5031_50310402_74_dialog_content = "점수가 밀리는 건 걱정도 안 하는 건가?!",
  ui_story_5031_50310402_75_dialog_content = "아마 저들에겐 우리야말로 가장 강력한 장애물일 테니까.",
  ui_story_5031_50310402_76_dialog_content = "그러니 이번 시합에서 우릴 탈락시켜 버리려는 거겠지.",
  ui_story_5031_50310402_77_dialog_content = "좋은 생각이 떠올랐어... 차라리 제대로 싸워보는 편이 좋을 것 같아.\n루미나의 힘이 없는 내가 미끼가 될게.",
  ui_story_5031_50310402_78_dialog_content = "일단 최대한 많은 암귀를 유인한 다음에,\n기회를 봐서 요나랑 아주르 씨가 펼친 포위망을 벗어나는 거야.",
  ui_story_5031_50310402_79_dialog_content = "PlayerName, 그건 너무 위험해! 내가 다시 돌파해 볼게. 이번엔 조심할 테니까!",
  ui_story_5031_50310402_80_dialog_content = "카렌, 요나랑 아주르 씨는 둘 다 총을 아주 잘 써.\n엄청 멀리서도 충분히 우릴 맞힐 수 있을 거야.",
  ui_story_5031_50310402_81_dialog_content = "그렇게 쉽게 당해 주지는 않을 거야. 내 힘을 믿어줘.",
  ui_story_5031_50310402_82_dialog_content = "네 힘은 당연히 믿지. 하지만 지금은 너도 날 믿어줄 때야.",
  ui_story_5031_50310402_83_dialog_content = "카렌, PlayerName 의견대로 해보는 것도 좋을 것 같아.",
  ui_story_5031_50310402_84_dialog_content = "어쩌면 지금 같은 상황에선 그게 가장 좋은 전략일지도 몰라.",
  ui_story_5031_50310402_85_dialog_content = "알겠어. 그럼 조심해.",
  ui_story_5031_50310402_86_dialog_content = "걱정 마. 피아, 넌 카렌이랑 바이스를 따라가.",
  ui_story_5031_50310402_87_dialog_content = "어, 응? 알겠어.",
  ui_story_5031_50310402_88_dialog_content = "암귀들아! 한번 잡아 보시지!",
  ui_story_5031_50310402_89_dialog_content = "약 올라 죽겠지? 얼른 쫓아오라고오오오오──",
  ui_story_5031_50310402_90_dialog_content = "캬악──!",
  ui_story_5031_50310402_91_dialog_content = "캬아악──!",
  ui_story_5031_50310402_92_dialog_content = "응? PlayerName 저 녀석, 갑자기 뛰쳐나오다니 무슨 속셈이지?",
  ui_story_5031_50310402_93_dialog_content = "역시 아이테르 꼬마라니까~\n자기가 미끼가 돼서 암귀로 우리 시선을 막을 생각인 거겠지.",
  ui_story_5031_50310402_94_dialog_content = "하지만 그 정도로는 부족해. 날 얕본 벌로 엉덩이에 한 발 쏴 줘야겠어.",
  ui_story_5031_50310402_95_dialog_content = "거기 두 아가씨.",
  ui_story_5031_50310402_96_dialog_content = "응?",
  ui_story_5031_50310402_97_dialog_content = "함부로 카렌 전하를 공격하는 건 내가 허락할 수 없거든.",
  ui_story_5031_50310402_98_dialog_content = "그럼 방금 내 손이 더러워진 분노를...\n너희같이 하늘 높은 줄 모르고 귀족을 해치려는 녀석들에게 풀어줘야겠어!",
  ui_story_5031_50310402_99_dialog_content = "바이스, 피아! 날 따라와!",
  ui_story_5031_50310402_100_dialog_content = "암귀 따위는 나 혼자서도 처리할 수 있어!",
  ui_story_5031_50310402_101_dialog_content = "<color=#e8d9bb>펑펑──!</color>",
  ui_story_5031_50310402_102_dialog_content = "캬악──",
  ui_story_5031_50310402_103_dialog_content = "키익──!",
  ui_story_5031_50310402_104_dialog_content = "캬악──!",
  ui_story_5031_50310402_105_dialog_content = "캬악──!",
  ui_story_5031_50310402_106_dialog_content = "분명히 약해 빠진 암귀들인데... 수가 너무 많아서 포위당했어.",
  ui_story_5031_50310402_107_dialog_content = "카렌, 억지로 싸우지 말고 우선 PlayerName 쪽에 합류하자.",
  ui_story_5031_50310402_108_dialog_content = "만약 달의 고치만 가지고 올 수 있었어도... 암귀 따위는!",
  ui_story_5031_50310402_108X1_dialog_content = "내게도 바이스 같은 새로운 힘이 있었다면...!",
  ui_story_5031_50310402_108X2_dialog_content = "...침착하자, 카렌.",
  ui_story_5031_50310402_108X3_dialog_content = "바이스가 말한 것처럼 의식을 가라앉혀.",
  ui_story_5031_50310402_108X4_dialog_content = "호흡을... 느끼는 거야.",
  ui_story_5031_50310402_108X5_dialog_content = "카렌.",
  ui_story_5031_50310402_108X6_dialog_content = "아버님...",
  ui_story_5031_50310402_108X7_dialog_content = "암귀는 아무리 죽여도 절대 사라지지 않는다.",
  ui_story_5031_50310402_108X8_dialog_content = "무모한 행동은 너를 신뢰하는 병사들을 해칠 뿐이다.",
  ui_story_5031_50310402_108X9_dialog_content = "그리고 충분하지 못한 힘은 그 어떤 소중한 이도 지켜낼 수 없다.",
  ui_story_5031_50310402_108X10_dialog_content = "넌 아직 부족하다... 더 찾고... 더 강해져야 한다.",
  ui_story_5031_50310402_108X11_dialog_content = "실망스럽구나...",
  ui_story_5031_50310402_108X12_dialog_content = "그...그런 게 아니에요, 아버님!",
  ui_story_5031_50310402_108X13_dialog_content = "카렌!",
  ui_story_5031_50310402_108X14_dialog_content = "캬악──!",
  ui_story_5031_50310402_108X15_dialog_content = "저리 비켜!",
  ui_story_5031_50310402_109_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5031_50310402_110_dialog_content = "가, 갑자기 왜 주먹으로 암귀를 때리고 그래? 그렇게 하면 점수도 안 준다구.",
  ui_story_5031_50310402_111_dialog_content = "카렌, 진정해! 우선 PlayerName한테 가야 해!",
  ui_story_5031_50310402_112_dialog_content = "...미안. 네 말이 맞아.",
  ui_story_5031_50310402_113_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310402_114_dialog_content = "「시합 종료. 아직 필드에 남아 있는 참가자들은 심사대에서 성적을 확인하세요.」",
  ui_story_5031_50310402_115_dialog_content = "다행이야! 카렌, 우리도 통과했어!",
  ui_story_5031_50310402_116_dialog_content = "응. 레디젤 렌치한테서 도망치게 해 준 PlayerName 덕분이야.",
  ui_story_5031_50310402_117_dialog_content = "하지만 정말 위험했어. 실전에서는 절대로 이런 위험한 전술을 사용해선 안 돼.",
  ui_story_5031_50310402_118_dialog_content = "흐응... 아이테르 꼬맹이, 넌 네가 모두를 구했다고 생각하는 거니?",
  ui_story_5031_50310402_119_dialog_content = "네? 아주르 씨, 그게 무슨...",
  ui_story_5031_50310402_120_dialog_content = "아까 갑자기 백야성 녀석이 나타나서 싸움을 걸지 뭐야.\n우린 그 녀석을 상대하느라 발이 묶였을 뿐이야.",
  ui_story_5031_50310402_121_dialog_content = "아니었으면 네 엉덩이는 진작에 아주르한테 맞아서 터졌을걸.",
  ui_story_5031_50310402_122_dialog_content = "역시 물총 같은 장난감보다는 백야성 녀석이랑 실전으로 싸우는 게 더 재미있다니까.",
  ui_story_5031_50310402_123_dialog_content = "소리치면서 달려오는 꼴이 전혀 귀족처럼 안 보이던데...\n아무튼 싸우다 보니 시합은 전혀 잊고 있었지 뭐야.",
  ui_story_5031_50310402_124_dialog_content = "아쉽게도 그 녀석이 다른 조용한 녀석한테 끌려가 버려서...\n그것만 아니었으면 아직도 신나게 싸우고 있었을걸.",
  ui_story_5031_50310402_125_dialog_content = "누, 누님...",
  ui_story_5031_50310402_126_dialog_content = "응? 무슨 낯짝으로 돌아왔어?",
  ui_story_5031_50310402_127_dialog_content = "우리 레디젤 렌치는 여자와 아이에겐 손을 대지 않아. 잊었어?",
  ui_story_5031_50310402_128_dialog_content = "죄, 죄송합니다, 누님. 저희가 잠깐 정신이 나갔습니다...",
  ui_story_5031_50310402_129_dialog_content = "배 밑에서 엎드려 뻗치고 있어. 내가 술 다 마시고 혼내주러 갈 때까지.",
  ui_story_5031_50310402_130_dialog_content = "예, 예! 요나 누님!",
  ui_story_5031_50310402_131_dialog_content = "김빠지게...",
  ui_story_5031_50310402_132_dialog_content = "너희 레디젤 렌치에 그런 면도 있는지는 몰랐는데.",
  ui_story_5031_50310402_133_dialog_content = "칭찬으로 들을게. 자, 그럼 난 아주르랑 한잔하러 가야 해서. 나중에 또 보자고.",
  ui_story_5031_50310402_134_dialog_content = "바이바이~ 우린 저기 공짜 술이나 좀 마시려고. 아이테르 꼬마도 놀러 와~",
  ui_story_5031_50310402_135_dialog_content = "하... 어쨌든 우릴 노리는 상대가 하나 줄어들어서 다행이야.",
  ui_story_5031_50310402_136_dialog_content = "그로누 선배 쪽도 순조롭게 통과한 것 같고... 점수도 높았던 것 같아.",
  ui_story_5031_50310402_137_dialog_content = "시합이 이렇게나 치열할 줄은 몰랐어.\n요나랑 아주르 씨 같은 강적들이 첫 라운드에서 탈락할 줄이야...",
  ui_story_5031_50310402_138_dialog_content = "앞으로의 시합은... 아마 더 격렬하고, 잔혹하고, 치열하겠지...",
  ui_story_5031_50310402_139_dialog_content = "꿀꺽.",
  ui_story_5031_50310402_140_dialog_content = "침 넘기는 소리가 너무 큰 거 아니야?",
  ui_story_5031_50310402_141_dialog_content = "으읏... 난 그냥 네가 만든 긴장된 분위기에 맞춰주려던 것뿐이라고!",
  ui_story_5031_50310402_142_dialog_content = "영주님~ 안녕?",
  ui_story_5031_50310402_143_dialog_content = "안녕하십니까. 당신은 방금 그...",
  ui_story_5031_50310402_144_dialog_content = "맞아. 난 사블리라고 해.",
  ui_story_5031_50310402_145_dialog_content = "제노 대장이 이걸 갖다 주라고 했어~",
  ui_story_5031_50310402_146_dialog_content = "이건...",
  ui_story_5031_50310402_147_dialog_content = "담요야. 영주님이 바닷바람을 너무 오래 맞다가 감기라도 걸릴까 걱정하더라고.",
  ui_story_5031_50310402_148_dialog_content = "...알겠습니다. 고맙다고 전해 주시죠.",
  ui_story_5031_50310402_149_dialog_content = "그리고 사블리, 당신도 고마워요.",
  ui_story_5031_50310402_150_dialog_content = "히히, 천만에~",
  ui_story_5031_50310402_151_dialog_content = "......",
  ui_story_5031_50310501_1_dialog_content = "1라운드를 통과한 용사 여러분, 축하드립니다.",
  ui_story_5031_50310501_2_dialog_content = "여러분께서는 자신의 용기와 힘을 충분히 증명하고, 보물의 문 앞에 도달했습니다.",
  ui_story_5031_50310501_3_dialog_content = "두 번째 시합의 게임 규칙도 무척 간단합니다.",
  ui_story_5031_50310501_4_dialog_content = "다들 어릴 적에 이런 놀이를 해보셨을 겁니다.",
  ui_story_5031_50310501_5_dialog_content = "자, 나오시죠. 끝없는 황혼 속에서 춤추는 추악한 괴물, 비밀과 보물의 수호자여──",
  ui_story_5031_50310501_6_dialog_content = "<color=#e8d9bb>쾅──</color>",
  ui_story_5031_50310501_7_dialog_content = "자, 이쪽이 바로 이번 시합의 수호자입니다.",
  ui_story_5031_50310501_8_dialog_content = "흠흠~ 그럼 저 레인보우가 여러분께 규칙을 설명해 드릴게요~",
  ui_story_5031_50310501_9_dialog_content = "이 특수한 암귀가 초록색이 됐을 때...",
  ui_story_5031_50310501_10_dialog_content = "최대한 빠른 속도로 방해하는 암귀를 돌파하고 이 녀석의 앞까지 오면 된답니다~",
  ui_story_5031_50310501_11_dialog_content = "여기 옆에 있는 선을 넘기만 하면 다음 라운드 진출!",
  ui_story_5031_50310501_12_dialog_content = "그리고 녀석이 빨간색으로 변하면 조심하세요~",
  ui_story_5031_50310501_13_dialog_content = "그땐 오로리안도 암귀도 움직여선 안 돼요.\n움직이면 가장 가까운 암귀가 바다로 밀어버리고, 실격 처리될 거예요.",
  ui_story_5031_50310501_14_dialog_content = "물론 제한 시간 내에 도착하지 못한 사람도 탈락이랍니다.",
  ui_story_5031_50310501_15_dialog_content = "이번 시합에서는 루미나틱스에 대해 어떠한 제한도 없어요.",
  ui_story_5031_50310501_16_dialog_content = "그렇습니다! 자, 이제 여러분의 전력을 다해, 보물을 향한 도전을 시작하십시오!",
  ui_story_5031_50310501_17_dialog_content = "PlayerName.",
  ui_story_5031_50310501_18_dialog_content = "음, 드디어 실력을 발휘할 때가 온 것 같네.",
  ui_story_5031_50310501_19_dialog_content = "걱정 마. 가장 빠르게 결승점에 도착할 수 있게 해줄 테니까!",
  ui_story_5031_50310502_1_dialog_content = "하하! 이 정도 암귀는 나도 가볍게 처리할 수 있겠어!",
  ui_story_5031_50310502_2_dialog_content = "받아라! 이 멍청한 암귀들!",
  ui_story_5031_50310502_3_dialog_content = "어이! 저 커다란 암귀의 색이 곧 바뀔 것 같아! 그만 싸워!",
  ui_story_5031_50310502_4_dialog_content = "아직 시간 있어! 조금만 더 가면 우리가 선두라고!",
  ui_story_5031_50310502_5_dialog_content = "멍청이들. 이제 곧 탈락하게 생겼는데도 모르고 있다니.",
  ui_story_5031_50310502_6_dialog_content = "저번 라운드는 네 덕이 컸어.\n내가 두 강도 녀석들을 혼내주는 동안 네가 점수를 쌓아뒀을 줄이야.",
  ui_story_5031_50310502_7_dialog_content = "고작 강도들 주제에 그렇게 성가실 줄은 몰랐지 뭐냐.\n덕분에 몸도 제대로 풀었고 말이야.",
  ui_story_5031_50310502_8_dialog_content = "마지막에 네가 날 끌고 가지 않았어도 모조리 처리할 수 있었을 거라고...",
  ui_story_5031_50310502_9_dialog_content = "......",
  ui_story_5031_50310502_10_dialog_content = "쳇, 기껏 칭찬해 줬는데 대꾸도 없는 거냐...\n네 루미나틱스는 그 주둥이도 잠가 버리는 거냐?",
  ui_story_5031_50310502_11_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310502_12_dialog_content = "색이 변했어!",
  ui_story_5031_50310502_13_dialog_content = "캬악──!",
  ui_story_5031_50310502_14_dialog_content = "오, 오지 마!",
  ui_story_5031_50310502_15_dialog_content = "<color=#e8d9bb>풍덩!</color>",
  ui_story_5031_50310502_16_dialog_content = "<color=#e8d9bb>풍덩!</color>",
  ui_story_5031_50310502_17_dialog_content = "역시 떨어졌군. 멍청한 평민들이란...",
  ui_story_5031_50310502_18_dialog_content = "공주 전하와 너무 떨어지면 안 돼. 조금 더 가까이 가서 지켜드려야 한다고.",
  ui_story_5031_50310502_19_dialog_content = "절대 방금 그 가련한 평민들처럼 떨어지시게 둬선 안 돼.",
  ui_story_5031_50310502_20_dialog_content = "담요 고마웠어, 제노.",
  ui_story_5031_50310502_21_dialog_content = "아닙니다. 바람이 많이 불어서 감기라도 걸릴까 걱정했습니다.",
  ui_story_5031_50310502_22_dialog_content = "하하, 네가 아직도 이런 놀이를 좋아할 줄은 몰랐어.",
  ui_story_5031_50310502_23_dialog_content = "뭐죠? 유치해 보인다는 겁니까?",
  ui_story_5031_50310502_24_dialog_content = "아니, 그냥 조금 놀랐거든.",
  ui_story_5031_50310502_25_dialog_content = "시간이 이렇게나 흘렀는데... 아직도 저런 놀이에 흥미를 느끼다니...\n심지어 그걸 시합으로 만들기까지 하고 말이야.",
  ui_story_5031_50310502_26_dialog_content = "과거가 그리웠기 때문입니다.",
  ui_story_5031_50310502_27_dialog_content = "저는 어떤 일이든 오래 기억합니다. 예를 들면 아주 오래전,\n누군가가 약속을 어긴 탓에 하루 종일 기다려야 했던 일 같은 것 말이지요.",
  ui_story_5031_50310502_28_dialog_content = "...그때 인사도 하지 않고 떠나서... 정말 미안해.",
  ui_story_5031_50310502_29_dialog_content = "네. 용서해드리지요.",
  ui_story_5031_50310502_30_dialog_content = "......?",
  ui_story_5031_50310502_31_dialog_content = "전 그저 그 미안하다는 말을 듣고 싶었을 뿐입니다.",
  ui_story_5031_50310502_32_dialog_content = "사실 조금만 생각해 봐도 알 수 있었습니다.",
  ui_story_5031_50310502_33_dialog_content = "일개 식당 사장의 아들에서 하버 시티의 영주가 되기까지,\n얼마나 많은 고난을 겪었을지 말입니다.",
  ui_story_5031_50310502_34_dialog_content = "하지만 당신이 간직했던 소중한 것들은 아직 변하지 않았음을 느낄 수 있습니다.\n부디 그게 제 착각이 아니었으면 좋겠습니다만.",
  ui_story_5031_50310502_35_dialog_content = "소중한 것들?",
  ui_story_5031_50310502_36_dialog_content = "예를 들면 하버 시티에서 시행하고 있는 건강 체조 같은 것 말이지요.\n정말 멍청해 보이지만, 무척이나 당신답습니다.",
  ui_story_5031_50310502_37_dialog_content = "하하하하! 다들 건강하게 지낼 수 있다면 얼마든지 멍청해도 좋아.",
  ui_story_5031_50310502_38_dialog_content = "그럼 넌? 백야성에 돌아온 뒤로 널 한참 찾았어.\n하지만 어디 갔는지 전혀 알 수 없었지.",
  ui_story_5031_50310502_39_dialog_content = "저 말입니까?",
  ui_story_5031_50310502_40_dialog_content = "하버 시티에 돌아온 뒤로 널 한참 찾았어. 하지만 어디 갔는지 전혀 알 수 없었지.",
  ui_story_5031_50310502_41_dialog_content = "심지어 너희 일가가 죽었다고 말한 사람도 있었어...",
  ui_story_5031_50310502_42_dialog_content = "비슷합니다.",
  ui_story_5031_50310502_43_dialog_content = "어둠의 위기 때 살아남으려 노력하던 불쌍한 자들처럼 말이지요.\n저희 가족은 그저 우연히 「에메랄드호」로 도망칠 수 있었습니다.",
  ui_story_5031_50310502_44_dialog_content = "이후 운명의 인도인지, 진리의 결사의 빅토리아 님께서 절 구해 주셨습니다.",
  ui_story_5031_50310502_45_dialog_content = "게다가 제게 기원을 조종하는 힘도 주셨지요.",
  ui_story_5031_50310502_46_dialog_content = "하지만 저는 「에메랄드호」로 돌아온 뒤에야,\n부모님이 오래전에 이미 세상을 떠났다는 사실을 알게 되었습니다.",
  ui_story_5031_50310502_47_dialog_content = "그때의 저는 고지식하게도 부모님의 죽음이 전임 단장의 탓이라 생각했고,\n부모님의 복수를 위해 그에게 도전했습니다.",
  ui_story_5031_50310502_48_dialog_content = "제가 진실을 알게 됐을 땐 이미 오랜 시간이 흐른 뒤였습니다.\n다행히 단장님은 절 탓하지 않으셨지요.",
  ui_story_5031_50310502_49_dialog_content = "이후 전 「에메랄드호」... 그리고 서커스단 사람들과 함께\n바다 위를 떠돌기 시작했습니다.",
  ui_story_5031_50310502_50_dialog_content = "미안해... 네 가족들은 모두 좋은 사람들이었는데.",
  ui_story_5031_50310502_51_dialog_content = "사과할 필요는 없습니다. 애초에 당신의 잘못이 아니니까요.",
  ui_story_5031_50310502_52_dialog_content = "비록 진리의 결사의 힘으로 마술사의 삶을 이어가고 있지만...",
  ui_story_5031_50310502_53_dialog_content = "솔직히 저는 진리의 결사나 그들의 교의에는 별 관심 없습니다.",
  ui_story_5031_50310502_54_dialog_content = "그들 중에도 다양한 파벌이 있으니 말입니다.\n아마 전 그중에서도 가장 변두리에 속한 「무위도식」하는 유형이겠지요.",
  ui_story_5031_50310502_55_dialog_content = "하지만 빅토리아 님께서 제게 은혜를 베푸셨으니,\n그분과의 약속은 반드시 지켜야만 합니다.",
  ui_story_5031_50310502_56_dialog_content = "지켜지지 않는 약속은... 더는 싫으니 말이지요...",
  ui_story_5031_50310502_57_dialog_content = "약속이라... 크윽, 콜록! 콜록!",
  ui_story_5031_50310502_58_dialog_content = "...피? 지금 피를 토한 겁니까?!",
  ui_story_5031_50310502_59_dialog_content = "괘, 괜찮아. 그저 요즘 처리할 정무가 많아서 쉬질 못했거든.\n게다가 감기까지 걸려서...",
  ui_story_5031_50310502_60_dialog_content = "제가 바보로 보입니까?!",
  ui_story_5031_50310502_61_dialog_content = "하하하... 그럴 리가 없잖아. 정말이야, 난 건강해.",
  ui_story_5031_50310502_62_dialog_content = "못 믿겠으면 네 점술로 내 수명을 계산해보는 건 어때?\n아직 200년은 더 살 수 있을 것 같은데 말이야.",
  ui_story_5031_50310502_63_dialog_content = "계산은 무슨! 대체 어떻게 된 겁니까? 솔직하게 말하세요!",
  ui_story_5031_50310502_64_dialog_content = "하... 하하... 너도 한때 하버 시티의 주민이었으니, 「영웅의 전설」에 대해 알고 있겠지.",
  ui_story_5031_50310502_65_dialog_content = "물론입니다. 어린애를 속이기 위한 유치한 이야기 아닙니까.",
  ui_story_5031_50310502_66_dialog_content = "그 전설은... 사실이야.",
  ui_story_5031_50310502_67_dialog_content = "......",
  ui_story_5031_50310502_68_dialog_content = "쉽게 말하자면, 그들은 피로 계약하는 방식으로 어떤 봉인을 가동했고,\n그걸로 암귀를 봉인했어.",
  ui_story_5031_50310502_69_dialog_content = "계약에 따라 암귀는 깊은 잠에 빠졌고...\n하버 시티는 암귀가 접근할 수 없는 평화로운 땅이 되었지.",
  ui_story_5031_50310502_70_dialog_content = "그리고 그들의 후대들은 상응하는 대가를 치러야 했고 말이야.",
  ui_story_5031_50310502_71_dialog_content = "그게 바로 「모드리 증후군」의 진실이야.",
  ui_story_5031_50310502_72_dialog_content = "뭐라고요?! 당신도 모드리 증후군에 걸렸던 겁니까? 설마 얼굴의 그 흉터도...",
  ui_story_5031_50310502_73_dialog_content = "그래. 하지만 걱정 마. 아직은... 콜록, 콜록... 아직은 괜찮으니까.",
  ui_story_5031_50310502_74_dialog_content = "대체 어떤 계약입니까? 계약을 해제할 방법도 있습니까?",
  ui_story_5031_50310502_75_dialog_content = "사실 난 최근 몇 년간 계속... 해결 방법을 찾고 있었어.",
  ui_story_5031_50310502_76_dialog_content = "어떤 방법입니까?",
  ui_story_5031_50310502_77_dialog_content = "미안해. 아직은 충분한 확신이 없거든.\n너무 많은 게 얽혀 있어서 간단히 설명하기가 힘들어.",
  ui_story_5031_50310502_78_dialog_content = "......",
  ui_story_5031_50310502_79_dialog_content = "저기 좀 봐! 저기 제일 앞에 있는 여자애, 엄청나게 강하다고!",
  ui_story_5031_50310502_80_dialog_content = "루미나틱스를 전혀 못 쓰는 사람이랑 같이 있는 것 같은데...\n어떻게 저렇게 강한 거지?",
  ui_story_5031_50310502_81_dialog_content = "저 사람... 혹시 아이테르 아냐?",
  ui_story_5031_50310502_82_dialog_content = "뭐? 아이테르?! 나도 볼래!",
  ui_story_5031_50310502_83_dialog_content = "사장님~ 2분만 시간 좀 내줘요.\n보급 물자가 또 잔뜩 왔거든요. 와서 좀 확인해 주세요~",
  ui_story_5031_50310502_84_dialog_content = "알겠습니다. 바로 가도록 하죠.",
  ui_story_5031_50310502_85_dialog_content = "그럼 심판 일을 부탁드리죠. 금방 돌아오겠습니다.",
  ui_story_5031_50310502_86_dialog_content = "그래. 갔다 와, 제노.",
  ui_story_5031_50310602_1_dialog_content = "「2라운드 달리기──시작!」",
  ui_story_5031_50310602_2_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310602_3_dialog_content = "PlayerName! 바짝 붙어!",
  ui_story_5031_50310602_4_dialog_content = "바이스랑 피아, PlayerName 쪽을 잘 지켜줘.\n암귀들이 너무 가까이 다가오게 두면 안 돼.",
  ui_story_5031_50310602_5_dialog_content = "알겠어!",
  ui_story_5031_50310602_6_dialog_content = "미안, 매번 움직일 수 있는 시간이 이렇게 짧을 줄은 몰랐어.\n이래서는 지휘도 별 쓸모가 없잖아.",
  ui_story_5031_50310602_7_dialog_content = "오로리안 중에는 루미나틱스로 벌써 수호자 근처에 도착한 사람도 있는 것 같아.",
  ui_story_5031_50310602_8_dialog_content = "그런 건 신경 쓰지 마. 우린 우리 속도대로 가면 되는 거야.",
  ui_story_5031_50310602_9_dialog_content = "PlayerName, 이동 노선을 알려줘.",
  ui_story_5031_50310602_10_dialog_content = "알았어!",
  ui_story_5031_50310602_11_dialog_content = "휴──",
  ui_story_5031_50310602_12_dialog_content = "임무 중에는 최대한 거리를 유지해야 하지만, 도저히 보고만 있을 수가 없더군요.",
  ui_story_5031_50310602_13_dialog_content = "당신... 기억났어. 심판관 마티외.",
  ui_story_5031_50310602_14_dialog_content = "그렇습니다. 심판관 마티외입니다.\n여기 말도 못하는 「깡통」 녀석은 제 동료인 심판원 뢰베라고 합니다.",
  ui_story_5031_50310602_15_dialog_content = "비록 일전에는 피트만 그 멍청한 녀석이 전하의 도움을 받았다지만...\n이번엔 꼭 말해야겠습니다.",
  ui_story_5031_50310602_16_dialog_content = "카렌 전하, 그게 대체 무슨 추태입니까.",
  ui_story_5031_50310602_17_dialog_content = "그토록 용맹하신 전하께서 루미나틱스조차 쓸 수 없는\n녀석 하나 때문에 손발이 묶이시다니요.",
  ui_story_5031_50310602_18_dialog_content = "혼자 움직이신다면... 아니, 애초에 그 아이테르가 없더라도\n충분히 이 시합을 통과할 수 있으시지 않습니까.",
  ui_story_5031_50310602_19_dialog_content = "그 아이테르는 여기 있는 다른 평민들처럼 거추장스러운 짐 덩어리일 뿐입니다.",
  ui_story_5031_50310602_20_dialog_content = "너... 지금 뭐라고──!",
  ui_story_5031_50310602_21_dialog_content = "이 녀석 신경 쓰지 마.",
  ui_story_5031_50310602_22_dialog_content = "으음?",
  ui_story_5031_50310602_23_dialog_content = "이 녀석은 마음에 문제가 있거든.",
  ui_story_5031_50310602_24_dialog_content = "너... 이 자식, 뭐라고 했냐?!",
  ui_story_5031_50310602_25_dialog_content = "계속 말해 봐. 피아는 궁금하거든.",
  ui_story_5031_50310602_26_dialog_content = "평소엔 상냥한 척하지만.",
  ui_story_5031_50310602_27_dialog_content = "평민을 매우 혐오해.",
  ui_story_5031_50310602_28_dialog_content = "하지만 「평민」을 그렇게 싫어하고 무시하면서.",
  ui_story_5031_50310602_29_dialog_content = "정작 자기 출신도...",
  ui_story_5031_50310602_30_dialog_content = "어이, 거기까지. 멈춰. 평소대로 입 다물고 있으란 말이야!",
  ui_story_5031_50310602_31_dialog_content = "내 말 못 들었어? 멈춰!",
  ui_story_5031_50310602_32_dialog_content = "...닥쳐!",
  ui_story_5031_50310602_33_dialog_content = "쳇...",
  ui_story_5031_50310602_34_dialog_content = "하지만 백야성의 귀족들은 대부분 평민을 무시하잖아.",
  ui_story_5031_50310602_35_dialog_content = "달라.",
  ui_story_5031_50310602_X35_dialog_content = "손만 닿아도 열 번은 넘게 씻어.",
  ui_story_5031_50310602_X36_dialog_content = "몸에 먼지라도 묻으면 비명을 질러.",
  ui_story_5031_50310602_36_dialog_content = "아하── 그럼 저 오빠는 상자에라도 들어가서 격리해야 되겠는데?",
  ui_story_5031_50310602_37_dialog_content = "맞아, 변태적인 결벽증이야.",
  ui_story_5031_50310602_38_dialog_content = "오빠, 불쌍한 사람이었구나...",
  ui_story_5031_50310602_39_dialog_content = "너 같은 평민 꼬맹이한테 동정받을 정도는 아니야!",
  ui_story_5031_50310602_40_dialog_content = "게다가 일도 게을리하고.",
  ui_story_5031_50310602_41_dialog_content = "뭐라고? 일도 게을리한다고? 어른인데?",
  ui_story_5031_50310602_42_dialog_content = "오랜 동창이라는 이유로.",
  ui_story_5031_50310602_X42_dialog_content = "일을 피트만한테 떠넘기고...",
  ui_story_5031_50310602_43_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310602_44_dialog_content = "색이 변했어! 다들 움직이지 마!",
  ui_story_5031_50310602_45_dialog_content = "마, 망했다!",
  ui_story_5031_50310602_46_dialog_content = "나 좀 잡아줘! 속도가 너무 빨라!",
  ui_story_5031_50310602_47_dialog_content = "펴, 평민 나부랭이가! 이쪽으로 오지 마──!",
  ui_story_5031_50310602_48_dialog_content = "<color=#e8d9bb>쿵!</color>",
  ui_story_5031_50310602_49_dialog_content = "죄, 죄송합니다! 죄송합니다!",
  ui_story_5031_50310602_50_dialog_content = "비켜... 비키라고!",
  ui_story_5031_50310602_51_dialog_content = "옷! 옷을 갈아입어야겠어!",
  ui_story_5031_50310602_52_dialog_content = "뢰베, 난 씻으러 간다!",
  ui_story_5031_50310602_53_dialog_content = "편식도 해.",
  ui_story_5031_50310602_54_dialog_content = "혓바닥이 델까 봐 무섭대.",
  ui_story_5031_50310602_55_dialog_content = "항상 큰 소리로 「아── 뜨거워──」라고 말하면서.",
  ui_story_5031_50310602_56_dialog_content = "보여주기까지 해.",
  ui_story_5031_50310602_57_dialog_content = "정말 보고 싶지 않은데.",
  ui_story_5031_50310602_58_dialog_content = "세 명 탈락──",
  ui_story_5031_50310602_59_dialog_content = "나중에 다시 얘기하자──",
  ui_story_5031_50310602_60_dialog_content = "겉모습과는 전혀 다르네. 짧고 힘 있는 화법이 참 인상적인걸.",
  ui_story_5031_50310602_X60_dialog_content = "그러게. 재미있는 사람 같아.",
  ui_story_5031_50310602_61_dialog_content = "카렌, 미안해.",
  ui_story_5031_50310602_62_dialog_content = "갑자기 왜? 설마 마티외의 말을 진짜로 신경 쓰는 건 아니지?",
  ui_story_5031_50310602_63_dialog_content = "네가 이렇게 노력하는데, 난 싸울 수도 없고... 가끔은 내가 정말 짐처럼 느껴져.",
  ui_story_5031_50310602_64_dialog_content = "내가 너무 애써서 그런 생각이 든 거야?",
  ui_story_5031_50310602_65_dialog_content = "그래. 이번 카니발 대회에서 넌 무척이나 열심이라서...\n마치 모든 걸 혼자 감당하려는 것처럼 보여...",
  ui_story_5031_50310602_66_dialog_content = "그런가...",
  ui_story_5031_50310602_67_dialog_content = "우린 한 번도 네가 짐이라고 생각해 본 적 없어.\n넌 항상 네 위치에서 중요한 역할을 하고 있었어.",
  ui_story_5031_50310602_68_dialog_content = "당연하지, PlayerName 넌 언제나 우리의 소중한 동료였어.",
  ui_story_5031_50310602_69_dialog_content = "에이, PlayerName 오빠가 저런 사람 말 때문에 혼자 멋대로 풀죽을 줄은 몰랐네.",
  ui_story_5031_50310602_70_dialog_content = "너희들...",
  ui_story_5031_50310602_71_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310602_72_dialog_content = "또 초록색으로 변했어. 이제 움직여도 돼.",
  ui_story_5031_50310602_73_dialog_content = "알겠어. 다들 앞으로 가자!",
  ui_story_5031_50310701_1_dialog_content = "PlayerName, 곧 결승점이야.",
  ui_story_5031_50310701_2_dialog_content = "이 속도라면 다음번엔 도착할 수 있을 거야.",
  ui_story_5031_50310701_3_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310701_4_dialog_content = "다들 움직여!",
  ui_story_5031_50310701_5_dialog_content = "잠깐만! 뭔가 이상해!",
  ui_story_5031_50310701_6_dialog_content = "녀석이 다시 변했어!",
  ui_story_5031_50310701_7_dialog_content = "<color=#e8d9bb>띠링──</color>",
  ui_story_5031_50310701_8_dialog_content = "어떻게 된 거야? 시간 간격이 왜 이렇게 갑자기 짧아진 거지?",
  ui_story_5031_50310701_9_dialog_content = "으앗!",
  ui_story_5031_50310701_10_dialog_content = "이런! 왜 갑자기 간격이 짧아진 거냐고!",
  ui_story_5031_50310701_11_dialog_content = "이번 시합은 아마 반응 능력을 테스트하는 목적이었을 거야.\n그렇게 생각하면 시간 간격이 바뀌는 것도 이해할 수 있어.",
  ui_story_5031_50310701_12_dialog_content = "이제부터는 신중하게 움직여야 해.",
  ui_story_5031_50310701_13_dialog_content = "또 네 명이 탈락했네요!",
  ui_story_5031_50310701_14_dialog_content = "카렌, 봤어? 저기 저 여자애... 뭔가 이상해.",
  ui_story_5031_50310701_15_dialog_content = "표정이 뭔가 이상하지 않아? 느껴지는 루미나도 계속 약해지고 있어.",
  ui_story_5031_50310701_16_dialog_content = "으윽...",
  ui_story_5031_50310701_17_dialog_content = "이런, 쓰러졌잖아!",
  ui_story_5031_50310701_18_dialog_content = "규칙대로라면 이제 바다에 던져지는 거 아냐?",
  ui_story_5031_50310701_19_dialog_content = "눈도 질끈 감고 있어. 엄청 고통스러워 보여!",
  ui_story_5031_50310701_20_dialog_content = "이대로 바다에 던져진다면 위험할 수도 있겠어.",
  ui_story_5031_50310701_21_dialog_content = "PlayerName, PlayerName, 뭐 좋은 방법 없어?",
  ui_story_5031_50310701_22_dialog_content = "캬악──",
  ui_story_5031_50310701_23_dialog_content = "더 기다릴 순 없어.",
  ui_story_5031_50310701_24_dialog_content = "카렌!",
  ui_story_5031_50310702_1_dialog_content = "시합 중지!",
  ui_story_5031_50310702_2_dialog_content = "카렌 전하. 무슨 일이십니까?",
  ui_story_5031_50310702_3_dialog_content = "이 소녀... 상태가 뭔가 이상해요.",
  ui_story_5031_50310702_4_dialog_content = "제게 맡겨 주시죠. 저도 의료 지식이 조금 있습니다.",
  ui_story_5031_50310702_5_dialog_content = "꼬마 아가씨, 무슨 일이죠? 제 목소리가 들립니까?",
  ui_story_5031_50310702_6_dialog_content = "으윽...",
  ui_story_5031_50310702_7_dialog_content = "이 증상은... 「모드리 증후군」이군요.",
  ui_story_5031_50310702_8_dialog_content = "어서 이 약을 먹으세요.",
  ui_story_5031_50310702_9_dialog_content = "제노, 방금 그 담요 좀 가져다줘.",
  ui_story_5031_50310702_10_dialog_content = "알겠습니다.",
  ui_story_5031_50310702_11_dialog_content = "후... 후우...",
  ui_story_5031_50310702_12_dialog_content = "영주님... 감사해요... 이제 좋아졌어요...",
  ui_story_5031_50310702_13_dialog_content = "무리하지 마세요. 지금 체온이 많이 낮군요. 담요를 덮고 있으면 훨씬 좋아질 겁니다.",
  ui_story_5031_50310702_14_dialog_content = "네... 란카는 영주님이 가르쳐주신 건강 체조도 열심히 하고...\n따뜻한 물도 많이 마실 거예요.",
  ui_story_5031_50310702_15_dialog_content = "그래요, 란카처럼 착한 아이가 제 백성인 것이 정말 기쁘군요.",
  ui_story_5031_50310702_16_dialog_content = "엘비스, 담요를 가져왔습니다.",
  ui_story_5031_50310702_17_dialog_content = "응. 고마워.",
  ui_story_5031_50310702_18_dialog_content = "파토!",
  ui_story_5031_50310702_19_dialog_content = "예, 영주님.",
  ui_story_5031_50310702_20_dialog_content = "경비병에게 이 아이를 가족에게 데려다주라고 하세요.\n그리고 꼭 병원에 가서 진찰을 받으라고 말을 전해 두세요.",
  ui_story_5031_50310702_21_dialog_content = "예. 걱정 마십시오!",
  ui_story_5031_50310702_22_dialog_content = "제노, 봤어? 아직 어린아이야.",
  ui_story_5031_50310702_23_dialog_content = "......",
  ui_story_5031_50310702_24_dialog_content = "엘비스 영주는 하버 시티 사람들의 사랑을 한 몸에 받고 있군요.",
  ui_story_5031_50310702_25_dialog_content = "백성들을 아낀다고 저마다 자부하는 수많은 귀족들도\n영주의 이런 모습을 본다면 분명히 부끄러워하겠지요.",
  ui_story_5031_50310702_26_dialog_content = "당신처럼 백성들을 사랑하는 영주가 있는 것은 하버 시티의 큰 행운이에요.",
  ui_story_5031_50310702_27_dialog_content = "쳇, 일개 평민일 뿐이지 않습니까.\n카렌 전하께서는 사소한 일에도 너무 마음을 쓰시는군요.",
  ui_story_5031_50310702_28_dialog_content = "방금 부딪혀서 저까지 탈락시킨 녀석만 생각하면... 괴로워서 견딜 수 없단 말입니다.",
  ui_story_5031_50310702_29_dialog_content = "심지어 바다에 던져질 뻔했지 뭡니까. 다행히 떨어지기 전에 기어 올라왔지만 말이죠.",
  ui_story_5031_50310702_30_dialog_content = "대체 언제 돌아가서 씻고 옷을 갈아입을 수 있는 겁니까?",
  ui_story_5031_50310702_31_dialog_content = "조용히 해.",
  ui_story_5031_50310702_32_dialog_content = "전하의 인정에 감사드립니다.",
  ui_story_5031_50310702_33_dialog_content = "하지만 전 그 아이를 도와줄 방법이 많지 않습니다.",
  ui_story_5031_50310702_34_dialog_content = "죄송합니다. 처리할 일이 있어서 먼저 실례해야 할 것 같군요.",
  ui_story_5031_50310702_35_dialog_content = "편히 가시죠.",
  ui_story_5031_50310702_36_dialog_content = "......",
  ui_story_5031_50310702_37_dialog_content = "영주님, 찾으셨습니까.",
  ui_story_5031_50310702_38_dialog_content = "파토, 시간이 얼마 없습니다.",
  ui_story_5031_50310702_39_dialog_content = "방금 「<color=#FFB400>신풍석</color>」의 힘이 한층 더 약해진 게 느껴졌습니다.",
  ui_story_5031_50310702_40_dialog_content = "그래서 저도... 그 소녀도... 연달아 병세가 나타난 것입니다.",
  ui_story_5031_50310702_41_dialog_content = "아무래도 봉인이 더는 버티지 못할 것 같군요.",
  ui_story_5031_50310702_42_dialog_content = "영주님. 정말 백야성에 도움을 청할 순 없는 겁니까?\n카렌 전하께선 다른 귀족들과는 다른 분 같았습니다.",
  ui_story_5031_50310702_43_dialog_content = "어쩌면 솔라드 님에게 말씀드려 도움을 주실지도 모르지 않습니까.",
  ui_story_5031_50310702_44_dialog_content = "저도 한편으로는 현명하신 솔라드 님께서 모두 해결해 주리라 믿고 싶지만...",
  ui_story_5031_50310702_45_dialog_content = "원로원의 무리들은 전혀 믿을 수 없습니다.",
  ui_story_5031_50310702_46_dialog_content = "병사를 보내 하버 시티를 보호하느니, 우릴 전부 몰아내자고 해서\n우리가 대대로 살아온 고향을 떠나게 만들 자들입니다.",
  ui_story_5031_50310702_47_dialog_content = "게다가 선조들이 각고의 노력으로 지켜낸 「신풍석」의 비밀도...\n이제는 아는 사람이 거의 없습니다.",
  ui_story_5031_50310702_48_dialog_content = "신풍석에 대한 소문이 퍼진다면, 분명히 나쁜 뜻을 품은 자들이 빼앗으려 할 겁니다.",
  ui_story_5031_50310702_49_dialog_content = "신풍석을 잃으면 하버 시티는 끝장입니다.",
  ui_story_5031_50310702_50_dialog_content = "선조와 그들의 후대가 목숨으로 지키고, 사람들이 대대로 가꿔온 우리의 고향이...\n연기처럼 사라지고 말겠지요.",
  ui_story_5031_50310702_51_dialog_content = "이 모든 것은 백성들의 목숨과 이 땅의 미래를 위한 겁니다.\n우린 반드시 우리의 힘으로... 우리만을 믿고 이 역경을 헤쳐 나가야 합니다.",
  ui_story_5031_50310702_52_dialog_content = "예... 영주님, 잘 알겠습니다.",
  ui_story_5031_50310702_53_dialog_content = "하버 시티와 모드리 가문을 위해서라면 목숨 바쳐 최선을 다하겠습니다.",
  ui_story_5031_50310702_54_dialog_content = "이제 더는... 돌이킬 수 없습니다.",
  ui_story_5031_50310702_55_dialog_content = "실패한다면 이 땅의 백성들을 구할 자는 없습니다.",
  ui_story_5031_50310702_56_dialog_content = "우리만이... 우릴 구할 수 있는 겁니다, 파토.",
  ui_story_5031_50310702_57_dialog_content = "카렌 전하, 정말 신분을 숨기실 겁니까?",
  ui_story_5031_50310702_58_dialog_content = "네. 뜻밖의 상황 때문에 편안한 여행을 방해받고 싶진 않군요. 그러니 부탁하죠.",
  ui_story_5031_50310702_59_dialog_content = "잘 알겠습니다.",
  ui_story_5031_50310702_60_dialog_content = "여러분, 드릴 말씀이 있습니다.",
  ui_story_5031_50310702_61_dialog_content = "방금 시합에 참가한 한 소녀가 몸이 불편해서 쓰러졌습니다.\n규칙대로라면 암귀가 그녀를 바다에 던져버렸을 겁니다.",
  ui_story_5031_50310702_62_dialog_content = "그러한 위기의 순간에 이 용감한 아가씨와 그녀의 동료들이\n규칙 위반의 위험을 무릅쓰고 나섰습니다!",
  ui_story_5031_50310702_63_dialog_content = "그리고 위험에 처한 소녀를 구해냈습니다.",
  ui_story_5031_50310702_64_dialog_content = "비록 규칙을 위반하긴 했지만, 하버 시티에서는 선량한 이를\n이렇게 대해서는 안 되는 법입니다!",
  ui_story_5031_50310702_65_dialog_content = "우리 하버 시티는 선한 이들을 존중합니다.\n그러니 이분들이 다시 경기에 참가할 수 있게 하는 것이 어떻겠습니까!",
  ui_story_5031_50310702_66_dialog_content = "동의합니다!",
  ui_story_5031_50310702_67_dialog_content = "영주님 뜻에 찬성합니다!",
  ui_story_5031_50310702_68_dialog_content = "감사합니다! 여러분의 영주라는 점이 정말 자랑스럽습니다.",
  ui_story_5031_50310702_69_dialog_content = "고마워요, 엘비스 영주.",
  ui_story_5031_50310702_70_dialog_content = "천만에요. 이는 이곳에 있는 모든 사람의 마음이 모인 결과입니다.",
  ui_story_5031_50310702_71_dialog_content = "이제 동료들과 함께 시합장으로 돌아가시면 됩니다.",
  ui_story_5031_50310702_X71_dialog_content = "그럼 시합을 재개하겠습니다!",
  ui_story_5031_50310702_X72_dialog_content = "하... 하아! 다들 너무 빠른 거 아니야? 언제 다 결승점까지 갔어?",
  ui_story_5031_50310702_X73_dialog_content = "PlayerName, 서둘러! 또 녀석의 색이 변하려고 해!",
  ui_story_5031_50310702_X74_dialog_content = "어? 아, 안 돼. 이미 한계야!",
  ui_story_5031_50310702_72_dialog_content = "PlayerName, 그냥 그대로 뛰어. 우리가 받아줄게!",
  ui_story_5031_50310702_73_dialog_content = "알겠어!",
  ui_story_5031_50310702_74_dialog_content = "<color=#e8d9bb>퉁──</color>",
  ui_story_5031_50310702_75_dialog_content = "진짜 위험했네.",
  ui_story_5031_50310702_76_dialog_content = "무거워, PlayerName!",
  ui_story_5031_50310702_77_dialog_content = "해냈어!",
  ui_story_5031_50310702_78_dialog_content = "그럼 이제 무사히 다음 단계로 진출할 수 있겠네...",
  ui_story_5031_50310702_79_dialog_content = "벌써 여러 강한 선수들이 결승선을 넘었었어.",
  ui_story_5031_50310702_80_dialog_content = "저기 손 흔들면서 계속 소리치는 사람... 그로누 선배인가?",
  ui_story_5031_50310702_81_dialog_content = "아── 시엘! 빨리 좀!",
  ui_story_5031_50310702_82_dialog_content = "네 그 최강의 기술을 쓰란 말이야!",
  ui_story_5031_50310702_83_dialog_content = "이대로 가다간 우리 둘 다 탈락이야!",
  ui_story_5031_50310702_84_dialog_content = "저, 저기... 그치만 「<color=#FFB400>스틱스</color>」는 아직...",
  ui_story_5031_50310702_85_dialog_content = "으으... 아, 알겠어요. 「다리 강화복 상태 조정, Type-Ⅱ」.",
  ui_story_5031_50310702_86_dialog_content = "「에너지 출력률 50%」.",
  ui_story_5031_50310702_87_dialog_content = "출발!",
  ui_story_5031_50310702_88_dialog_content = "우와! 시엘이 날아서 들어왔어!",
  ui_story_5031_50310702_89_dialog_content = "으아아아── 다들 비켜! 「스틱스」가 제어가 안 돼!",
  ui_story_5031_50310702_90_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5031_50310702_91_dialog_content = "어, 엄청나네... 배 위의 건물에 구멍을 내버렸어.",
  ui_story_5031_50310702_92_dialog_content = "갑판에도 긴 자국이 남았고...",
  ui_story_5031_50310702_93_dialog_content = "우와, 진짜 대단하네! 어디로 갔는지도 안 보이잖아.",
  ui_story_5031_50310702_94_dialog_content = "시엘, 괜찮아?",
  ui_story_5031_50310702_95_dialog_content = "아야야... 그래도 다치진 않았어.",
  ui_story_5031_50310702_96_dialog_content = "대신 내가 사랑하는 에메랄드호에 제대로 부딪히긴 했네.",
  ui_story_5031_50310702_97_dialog_content = "아, 미...미안해!",
  ui_story_5031_50310702_98_dialog_content = "일부러 그런 건 아냐... 아직 「스틱스」의 점검을 다 못 끝내서...\n아니, 전부 내 노력이 부족한 탓이겠지...",
  ui_story_5031_50310702_99_dialog_content = "휴... 지금 잘잘못을 따져 봤자 의미 없어. 어떻게 처리할지나 생각하자~",
  ui_story_5031_50310702_100_dialog_content = "사실 제일 좋은 건 돈으로 사람을 고용해서 배가 파손된 부분을 수리해 주는 거야.",
  ui_story_5031_50310702_101_dialog_content = "하지만 시엘은 그런 부잣집 애는 아닌 것 같네.",
  ui_story_5031_50310702_102_dialog_content = "맞아. 미안해...",
  ui_story_5031_50310702_103_dialog_content = "그만 사과해도 된다니까~ 기운 내.",
  ui_story_5031_50310702_104_dialog_content = "참! 아니면 다음 서핑 대회에 참가해 보는 건 어때?",
  ui_story_5031_50310702_105_dialog_content = "서핑 대회는 엘비스 영주님이 후원한 거라서, 1등한테는 추가 상금도 받을 거야.",
  ui_story_5031_50310702_106_dialog_content = "지, 진짜?!",
  ui_story_5031_50310702_107_dialog_content = "그래! 어디 보자... 1등 상금이 아마 오백만 나이티움이었을걸?",
  ui_story_5031_50310702_108_dialog_content = "대충 수리비랑 비슷할 것 같아.",
  ui_story_5031_50310702_109_dialog_content = "잘됐네! 참가할래!",
  ui_story_5031_50310702_110_dialog_content = "헤헤, 벌써 기뻐하긴 일러.",
  ui_story_5031_50310702_111_dialog_content = "나랑 멜트 세 자매도 참가할 거니까~",
  ui_story_5031_50310702_112_dialog_content = "시엘이라고 봐주진 않을 거야~",
  ui_story_5031_50310702_113_dialog_content = "만약 네가 진다면 말이지~ 음~ 이 아이, 「스틱스」라고 했지?",
  ui_story_5031_50310702_114_dialog_content = "그럼 얜 내 거야~",
  ui_story_5031_50310702_115_dialog_content = "...안 돼.",
  ui_story_5031_50310702_116_dialog_content = "에이~ 그냥 조금 연구해보고 싶은 것뿐이야. 빼앗거나 그걸로 뭘 할 생각은 없어.",
  ui_story_5031_50310702_117_dialog_content = "연구가 끝나면 잘 돌려줄게~",
  ui_story_5031_50310702_118_dialog_content = "미안해.",
  ui_story_5031_50310702_119_dialog_content = "이것만큼은... 안 돼...",
  ui_story_5031_50310801_1_dialog_content = "여러분~ 여름의 바닷바람과 공짜 과일을 즐기면서 푹 쉬셨나요?",
  ui_story_5031_50310801_2_dialog_content = "푹 쉬셨다면 다음 시합을 진행하겠습니다!",
  ui_story_5031_50310801_3_dialog_content = "네──!",
  ui_story_5031_50310801_4_dialog_content = "정말 뜨거운 열기네요~ 다들 각오를 잔뜩 하고 온 모양인데요?",
  ui_story_5031_50310801_5_dialog_content = "그럼 이번에는 뜨거운 전투로 흘린 땀부터 씻어내 볼까요?",
  ui_story_5031_50310801_6_dialog_content = "불꽃처럼 열정적인 햇살 아래에서 시원한 해수욕을 즐겨 보자구요!",
  ui_story_5031_50310801_7_dialog_content = "다음은 모두가 기대하던── <size=45>서핑 대회</size>랍니다!",
  ui_story_5031_50310801_8_dialog_content = "와아아!",
  ui_story_5031_50310801_9_dialog_content = "서핑 대회는 하버 시티의 전통이죠. 그리고 이번 대회에서 1위를 차지하는 팀은...",
  ui_story_5031_50310801_10_dialog_content = "추가로 엘비스 영주님이 제공해 주신 <color=#FFB400>오백만 나이티움</color>의 상금을 받으실 수 있답니다!",
  ui_story_5031_50310801_11_dialog_content = "오, 오백만?!",
  ui_story_5031_50310801_12_dialog_content = "오백마아안?!",
  ui_story_5031_50310801_13_dialog_content = "PlayerName, 바이스. 일단 진정해.",
  ui_story_5031_50310801_14_dialog_content = "우리의 진짜 목적을 잊지 마.",
  ui_story_5031_50310801_15_dialog_content = "알고 있어. 하지만 피아를 도와서 환상동물을 찾는 거랑...\n상금을 차지하는 건 별개잖아?",
  ui_story_5031_50310801_16_dialog_content = "하버 시티는 정말 돈이 많구나.",
  ui_story_5031_50310801_17_dialog_content = "확실히 하버 시티는 최근 들어서 빠르게 발전했어.",
  ui_story_5031_50310801_18_dialog_content = "귀족인 영주가 백성들을 위해 저런 거금을 기꺼이 내놓다니, 확실히 보기 드문 일이야.",
  ui_story_5031_50310801_19_dialog_content = "저런 현명한 군주가 있다면, 하버 시티를 잘 다스리는 것도 당연한 일이겠지.",
  ui_story_5031_50310801_20_dialog_content = "카렌 넌 요즘 정말 많이 노력하고 있는 것 같아.",
  ui_story_5031_50310801_21_dialog_content = "휴가 중에도 국가의 발전에 대해 생각하고 있잖아.",
  ui_story_5031_50310801_22_dialog_content = "아, 미안해. 나 때문에 재미없었지...?",
  ui_story_5031_50310801_23_dialog_content = "아냐 아냐, 전혀 아니야. 그런 뜻이 아니었어.",
  ui_story_5031_50310801_24_dialog_content = "그냥 네가 너무 힘들까 봐 걱정돼서 그래.",
  ui_story_5031_50310801_25_dialog_content = "맞아. 기왕 쉬러 왔으니까 카렌 너도 푹 쉬어야지!",
  ui_story_5031_50310801_26_dialog_content = "그 점은 피아한테 좀 배워도 좋을 것 같아.\n쟤 좀 봐. 파인애플 하나 먹으면서도 저렇게 행복해하잖아.",
  ui_story_5031_50310801_27_dialog_content = "이곳에 온 목적이 뭐였는지는 까맣게 잊어버리고 말이야.",
  ui_story_5031_50310801_28_dialog_content = "냠냠~ 달콤해!",
  ui_story_5031_50310801_29_dialog_content = "과일도 공짜고... 축제는 정말 최고야! 너무 맛있어!",
  ui_story_5031_50310801_30_dialog_content = "훗, 확실히 그렇네.",
  ui_story_5031_50310801_31_dialog_content = "피아에겐 배울 점이 많아.",
  ui_story_5031_50310801_32_dialog_content = "<size=33>피아뿐만 아니라 바이스와 PlayerName 너도 마찬가지야...</size>",
  ui_story_5031_50310801_33_dialog_content = "암귀는 아무리 죽여도 절대 사라지지 않는다.",
  ui_story_5031_50310801_34_dialog_content = "군주라면 그저 최전선에 나서서 홀로 모든 걸 막아내려 해서는 안 된다.",
  ui_story_5031_50310801_35_dialog_content = "그렇게 한다면 너 자신을 다치게 할 뿐만 아니라,\n널 믿고 따르는 이들을 해치게 될 것이다.",
  ui_story_5031_50310801_36_dialog_content = "......",
  ui_story_5031_50310801_37_dialog_content = "카렌, 내가 왜 PlayerName 그자와 함께 많은 곳을\n돌아보라고 했는지 잘 생각해 보아라.",
  ui_story_5031_50310801_38_dialog_content = "전...",
  ui_story_5031_50310801_39_dialog_content = "너의 왕도는 아직 더 성장이 필요하다.",
  ui_story_5031_50310801_40_dialog_content = "...예.",
  ui_story_5031_50310801_41_dialog_content = "카렌? 카렌!",
  ui_story_5031_50310801_42_dialog_content = "응? 미안해. 방금 뭐라고 했어?",
  ui_story_5031_50310801_43_dialog_content = "우리 슬슬 옷 갈아입으러 가야 하지 않을까? 서핑 대회는 무조건 물에 빠질 거잖아.",
  ui_story_5031_50310801_44_dialog_content = "새 옷을 더럽히면 안 되지!",
  ui_story_5031_50310801_45_dialog_content = "아, 그래.",
  ui_story_5031_50310801_46_dialog_content = "잠깐. 무슨 옷으로 갈아입지?",
  ui_story_5031_50310801_47_dialog_content = "헤헤, 그거야 당연히──",
  ui_story_5031_50310801_48_dialog_content = "수영복이지!",
  ui_story_5031_50310801_49_dialog_content = "우와! 카렌 언니! 바이스 언니! 진짜 예뻐!",
  ui_story_5031_50310801_50_dialog_content = "헤헷~ 고마워, 피아~",
  ui_story_5031_50310801_51_dialog_content = "어, 어째서 내 수영복까지 가지고 온 거야?",
  ui_story_5031_50310801_52_dialog_content = "바닷가에 오는데 어떻게 수영복을 안 챙길 수가 있겠어!",
  ui_story_5031_50310801_53_dialog_content = "지금까진 수상 활동이 아니라서 생각이 안 났을 뿐이야.",
  ui_story_5031_50310801_54_dialog_content = "너무 부러워. 피아도 수영복 가지고 싶어!",
  ui_story_5031_50310801_55_dialog_content = "그럼 축제가 끝난 다음에 하버 시티 옷가게에서 한 벌 만들어 달라고 할게~",
  ui_story_5031_50310801_56_dialog_content = "진짜?! 바이스 언니! 고마워!",
  ui_story_5031_50310801_57_dialog_content = "아, 피아는 옷 주문 제작은 처음이야! 신나~",
  ui_story_5031_50310801_58_dialog_content = "그리고 저번에 봤던 귀여운 식기 세트까지 살 수 있을지도 몰라!",
  ui_story_5031_50310801_59_dialog_content = "좋아, 좋아!",
  ui_story_5031_50310801_60_dialog_content = "그리고...",
  ui_story_5031_50310801_61_dialog_content = "크흠, 저, 저기...",
  ui_story_5031_50310801_62_dialog_content = "응? PlayerName, 왜 그래?",
  ui_story_5031_50310801_63_dialog_content = "열심히 얘기하는 도중에 끊어서 미안한데...",
  ui_story_5031_50310801_64_dialog_content = "난 서핑할 줄 몰라.",
  ui_story_5031_50310801_65_dialog_content = "<size=45>뭐라고?!</size>",
  ui_story_5031_50310801_66_dialog_content = "그럼 피아의 커스텀 수영복도 물 건너간 거 아냐?",
  ui_story_5031_50310801_67_dialog_content = "지금 수영복이 더 걱정이야?\n우리 진짜 목표가 환상동물인 것도 잊어버린 거 아냐?",
  ui_story_5031_50310801_68_dialog_content = "흐... 흐앙... 피아 수영복... 그리고 「구름고래」도...",
  ui_story_5031_50310801_69_dialog_content = "전부 망했어. 흐아아아아아앙!",
  ui_story_5031_50310801_70_dialog_content = "아... 미안, 미안. 피아, 울지 마...",
  ui_story_5031_50310801_71_dialog_content = "내가 방법을 생각해 볼게... 1등을 못 하더라도...",
  ui_story_5031_50310801_72_dialog_content = "적어도 수영복은 내가 돈을 내더라도 만들어 줄 테니까!",
  ui_story_5031_50310801_73_dialog_content = "훌쩍... 진짜?",
  ui_story_5031_50310801_74_dialog_content = "진짜야. 카렌이랑 바이스가 증인이 돼 줄 거야!",
  ui_story_5031_50310801_75_dialog_content = "그, 그럼 좋아.",
  ui_story_5031_50310801_76_dialog_content = "미안, 내가 상황도 제대로 파악하기 전에 상부터 받은 것처럼 얘기해 버려서...",
  ui_story_5031_50310801_77_dialog_content = "바이스 탓이 아니야. 내가 둔해서 서핑도 못하는 게 잘못이지.",
  ui_story_5031_50310801_78_dialog_content = "아, 아니야. PlayerName, 그건 오해야.",
  ui_story_5031_50310801_79_dialog_content = "서핑은 누구나 다 할 줄 아는 게 아닌걸.",
  ui_story_5031_50310801_80_dialog_content = "마침 내가 예전에 배웠던 적이 있었을 뿐이야.",
  ui_story_5031_50310801_X80_dialog_content = "맞아. 나도 어릴 때 하버 시티에 왔을 때 마침 그해 열렸던 서핑 대회를 봤었거든.",
  ui_story_5031_50310801_X81_dialog_content = "그때 흥미가 생겨서 배웠던 거야.",
  ui_story_5031_50310801_81_dialog_content = "그랬구나. 그럼 피아는 어디서 배웠어?",
  ui_story_5031_50310801_82_dialog_content = "응? 피아는 배운 적 없어.",
  ui_story_5031_50310801_83_dialog_content = "뭐?!",
  ui_story_5031_50310801_84_dialog_content = "그럼 방금 뭘 그렇게 울었던 건데?! 어차피 너도 못 하면서!",
  ui_story_5031_50310801_85_dialog_content = "칫. 뭘 소리를 지르고 그래? 그렇게 성깔 부리면 나중에 여자친구도 못 사귈걸.",
  ui_story_5031_50310801_86_dialog_content = "여, 여자친구?!",
  ui_story_5031_50310801_87_dialog_content = "너 이 꼬맹이가 대체 무슨 소리를 하는 거야?! 이리 와!",
  ui_story_5031_50310801_88_dialog_content = "우와! 다들 해변으로 갔어! 우리도 얼른 가자!",
  ui_story_5031_50310801_89_dialog_content = "빨리도 가네!",
  ui_story_5031_50310801_90_dialog_content = "......",
  ui_story_5031_50310801_91_dialog_content = "......",
  ui_story_5031_50310801_92_dialog_content = "(뭐야, 왜 갑자기 분위기가 이상해진 건데?)",
  ui_story_5031_50310801_93_dialog_content = "크흠. 그, 그럼 우리도 갈까?",
  ui_story_5031_50310801_94_dialog_content = "아, 그래.",
  ui_story_5031_50310801_95_dialog_content = "응, 가자.",
  ui_story_5031_50310801_96_dialog_content = "(저 둘은 또 왜 저렇게 빨리 가는 거야?)",
  ui_story_5031_50310801_97_dialog_content = "맞아. 양손을 가슴 밑쪽에 나란히 두고 발을 모아 봐.",
  ui_story_5031_50310801_98_dialog_content = "그리고 팔 힘으로 몸을 받치는 거야.",
  ui_story_5031_50310801_99_dialog_content = "이, 이렇게?",
  ui_story_5031_50310801_100_dialog_content = "맞아. 시선은 앞쪽으로. 잘하고 있어.",
  ui_story_5031_50310801_101_dialog_content = "그리고 파도가 밀려오면 몸을 일으키면서 양발을 어깨너비로 벌리고 등을 곧게 세워.",
  ui_story_5031_50310801_102_dialog_content = "파도가 오고 있어!",
  ui_story_5031_50310801_103_dialog_content = "서프보드가 밀리면서 속도가 붙는 게 느껴져? 지금이야!",
  ui_story_5031_50310801_104_dialog_content = "아, 알겠어!",
  ui_story_5031_50310801_105_dialog_content = "일어나서... 우와아악!",
  ui_story_5031_50310801_106_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5031_50310801_107_dialog_content = "PlayerName!",
  ui_story_5031_50310801_108_dialog_content = "어푸푸!",
  ui_story_5031_50310801_109_dialog_content = "나, 난 괜찮아. 아직 살아있어...",
  ui_story_5031_50310801_110_dialog_content = "칫, PlayerName 진짜 허접하네.",
  ui_story_5031_50310801_111_dialog_content = "피아도 벌써 배워서 보드에 잘 서는데 말이야.",
  ui_story_5031_50310801_112_dialog_content = "그게 어딜 봐서 서 있는 거야?! 쪼그려 앉아 있으면서!",
  ui_story_5031_50310801_113_dialog_content = "그래도 너보단 잘하거든!",
  ui_story_5031_50310801_114_dialog_content = "그리고 카렌 언니가 말해 준 방법만 있으면...\n피아는 그냥 보드 위에 웅크리고 있어도 충분하거든!",
  ui_story_5031_50310801_115_dialog_content = "물고기들한테 보드를 밀어달라고 하는 건 나만 할 수 있는 일이니까!",
  ui_story_5031_50310801_116_dialog_content = "너...",
  ui_story_5031_50310801_117_dialog_content = "시간이! 다! 됐어요!",
  ui_story_5031_50310801_118_dialog_content = "와아! 여러 선수들이 벌써 바다에서 연습하는 중이었네요~ 다들 의욕이 넘치네요!",
  ui_story_5031_50310801_119_dialog_content = "역시 오백만 나이티움의 매력이 대단한 모양이네요~",
  ui_story_5031_50310801_120_dialog_content = "하하하하하!",
  ui_story_5031_50310801_121_dialog_content = "헤헷, 농담이에요!",
  ui_story_5031_50310801_122_dialog_content = "그럼 지금부터 규칙을 설명할게요!",
  ui_story_5031_50310801_123_dialog_content = "예전 대회랑 똑같이 최대 4인 1조로 진행하고, 순서대로 서핑을 할 거예요.",
  ui_story_5031_50310801_124_dialog_content = "인원이 부족한 팀은 자유롭게 팀을 맺어도 돼요.",
  ui_story_5031_50310801_125_dialog_content = "이번에는 팀에서 점수가 가장 높은 두 사람의 점수로 평균점을 낼 거니까,\n두 사람만 있어도 참가할 수 있어요!",
  ui_story_5031_50310801_126_dialog_content = "마찬가지로 암귀의 환영을 처치하면 점수를 획득하지만,\n이번엔 바다에 빠져도 탈락이 아니니까 계속해서 진행하면 된답니다~",
  ui_story_5031_50310801_127_dialog_content = "암귀 처치로 획득하는 점수 외에도, 서핑 동작 점수가 개인 점수의 50% 배점이에요.",
  ui_story_5031_50310801_128_dialog_content = "그러니 팀원의 출전 순서를 신중하게 결정하세요.\n그게 바로 승리의 핵심이니까요!",
  ui_story_5031_50310801_129_dialog_content = "...앗, 저희 팀 노하우를 말해버렸네요! 이제 경쟁이 더 치열해지겠네요.",
  ui_story_5031_50310801_130_dialog_content = "하하하하하하!",
  ui_story_5031_50310801_131_dialog_content = "뭐, 상관없어요~ 다들 즐겁게 놀 수 있으면 됐죠!",
  ui_story_5031_50310801_132_dialog_content = "그럼 곧 첫 번째 라운드가 시작될 거예요.",
  ui_story_5031_50310801_133_dialog_content = "다들 팀을 잘 짠 다음에, 첫 번째 참가자는 시작점으로 와서 대기해 주세요!",
  ui_story_5031_50310801_134_dialog_content = "마지막으로 작은 비밀 하나 알려 드릴게요.",
  ui_story_5031_50310801_135_dialog_content = "저희 팀의 첫 번째 주자는... 바로 저랍니다!",
  ui_story_5031_50310801_136_dialog_content = "우오오오──!",
  ui_story_5031_50310801_137_dialog_content = "레인보우! 파이팅!",
  ui_story_5031_50310801_138_dialog_content = "레인보우는 인기가 갈수록 많아지는 것 같네.",
  ui_story_5031_50310801_139_dialog_content = "어떡하지? 저렇게 자신만만한 걸 보니 서핑을 잘하는가 본데?",
  ui_story_5031_50310801_140_dialog_content = "어쩔 수 없어. 하지만 두 명의 성적으로 평균을 낸다면...\n그래도 우리에게 유리한 상황인 것 같아.",
  ui_story_5031_50310801_141_dialog_content = "그럼 출전 순서가 중요하겠네.",
  ui_story_5031_50310801_142_dialog_content = "만약 레인보우 씨가 처음으로 나온다면... 우리 쪽은...",
  ui_story_5031_50310801_143_dialog_content = "후후, 그럼 당연히 최강인 내가 나가야겠지!",
  ui_story_5031_50310801_144_dialog_content = "...네가? 최강?",
  ui_story_5031_50310801_145_dialog_content = "그건 무슨 말투야!",
  ui_story_5031_50310801_146_dialog_content = "잊지 마. 방금 카렌 언니가 말해 준 방법은 나만 할 수 있다구!",
  ui_story_5031_50310801_147_dialog_content = "분명히 쉽게 1등이 될 수 있을 거야!",
  ui_story_5031_50310801_148_dialog_content = "PlayerName, 넌 그냥 내 승리를 축하할 준비나 하고 있어!",
  ui_story_5031_50310801_149_dialog_content = "...정말 괜찮을까?",
  ui_story_5031_50310801_150_dialog_content = "저러는 걸 보니까 갑자기 걱정되는데...",
  ui_story_5031_50310801_151_dialog_content = "크흠, 사회자까지 시합에 참가하러 가 버렸으니,\n이번 시합은 제가 사회를 보겠습니다.",
  ui_story_5031_50310801_152_dialog_content = "여기서 보고 있으니 바다에 떠 있는 여러분이 정말 작아 보이는군요.",
  ui_story_5031_50310801_153_dialog_content = "하지만 이토록 작은 존재들이 자연의 리듬에 순응하며\n서핑 같은 스포츠를 만들어 낸 것입니다.",
  ui_story_5031_50310801_154_dialog_content = "실로 아름답고 지혜로운 예술이라고 할 수 있겠지요.",
  ui_story_5031_50310801_155_dialog_content = "그럼 최선을 다해 파도의 리듬을 제어해서, 휘몰아치는 파도를 정복하고...",
  ui_story_5031_50310801_156_dialog_content = "...쓸데없는 말 그만하고 빨리 시작이나 하세요!",
  ui_story_5031_50310801_157_dialog_content = "다들 시합만 기다리고 있다구요!",
  ui_story_5031_50310801_158_dialog_content = "쳇, 어리석은 자들은 역시 이해할 수 없겠지요.",
  ui_story_5031_50310801_159_dialog_content = "그렇게나 인내심이 없으시다면, 지금 바로 시합을 시작하세요.",
  ui_story_5031_50310801_160_dialog_content = "......",
  ui_story_5031_50310801_161_dialog_content = "뭐야? 그렇게 대충 시작하는 거야?!",
  ui_story_5031_50310801_162_dialog_content = "대체 사회자를 뭐라고 생각하는 거야!",
  ui_story_5031_50310801_163_dialog_content = "아하하, 역시 제노 단장답네.",
  ui_story_5031_50310801_164_dialog_content = "그럼 먼저 갈게!",
  ui_story_5031_50310801_165_dialog_content = "아앗, 시엘! 시합 시작했어! 얼른 출발해!",
  ui_story_5031_50310801_166_dialog_content = "벌써 시작했다고요? 예전처럼 신호 같은 건 안 주는 건가요?",
  ui_story_5031_50310801_167_dialog_content = "이, 이런... 「다리 강화복 상태 조정──분사 모드」!",
  ui_story_5031_50310801_168_dialog_content = "저건 전부 강화복의 동력으로 움직이는 건가?",
  ui_story_5031_50310801_169_dialog_content = "파도가 갑자기 쳐서 옆에 있던 참가자들이 전부 바다에 빠져버렸어!",
  ui_story_5031_50310801_170_dialog_content = "이래가지고 시합이 되겠어?",
  ui_story_5031_50310801_171_dialog_content = "다행히 피아는 조금 떨어져 있어서 아직은 안정적으로 버티고 있어.",
  ui_story_5031_50310801_172_dialog_content = "오오오오──! 레인보우 씨가 선두다!",
  ui_story_5031_50310801_173_dialog_content = "우와! 멋진 급회전 점프!",
  ui_story_5031_50310801_174_dialog_content = "저기 로봇 소녀도 꽤 하잖아! 반응 속도가 엄청 빨라!",
  ui_story_5031_50310801_175_dialog_content = "그래도 레인보우 씨만큼 동작이 아름답진 않아.",
  ui_story_5031_50310801_176_dialog_content = "흥, 이 시합은 그리 간단하지 않습니다.",
  ui_story_5031_50310801_177_dialog_content = "울부짖어라. 심해의 저주들이여.",
  ui_story_5031_50310801_178_dialog_content = "캬아아!",
  ui_story_5031_50310801_179_dialog_content = "나타났다!",
  ui_story_5031_50310801_180_dialog_content = "아하하! 이제 레인보우 언니가 또 눈이 확 돌아가겠네.",
  ui_story_5031_50310801_181_dialog_content = "으, 레인보우 언니, 조심해요...",
  ui_story_5031_50310801_182_dialog_content = "응? 바다에서 암귀가 튀어나왔어!",
  ui_story_5031_50310801_183_dialog_content = "이러면 난이도가 조금... 으앗!",
  ui_story_5031_50310801_184_dialog_content = "레, 레인보우?",
  ui_story_5031_50310801_185_dialog_content = "우오오오!",
  ui_story_5031_50310801_186_dialog_content = "드디어 이 순간이 왔어! 이 벌레 놈들!",
  ui_story_5031_50310801_187_dialog_content = "<size=45>전부 죽어버려!</size>",
  ui_story_5031_50310801_188_dialog_content = "안색이 나빠졌군요. 란카를 떠올린 겁니까?",
  ui_story_5031_50310802_X1_dialog_content = "안색이 나빠졌군요. 란카를 떠올린 겁니까?",
  ui_story_5031_50310802_1_dialog_content = "아... 그래, 맞아.",
  ui_story_5031_50310802_2_dialog_content = "과일을 좀 가져왔습니다. 수분을 보충해야 할 것 같군요.",
  ui_story_5031_50310802_3_dialog_content = "고마워, 제노.",
  ui_story_5031_50310802_4_dialog_content = "방금 그 아이에게 준 약이 당신이 말한 해결 방법입니까?",
  ui_story_5031_50310802_5_dialog_content = "아니, 그건 내가 고서에서 본 기록을 바탕으로 만들어낸 약이야.\n잠깐의 고통만 해결해 줄 뿐이야.",
  ui_story_5031_50310802_6_dialog_content = "당신이 만든 거라고요?",
  ui_story_5031_50310802_7_dialog_content = "전에는 요리사가 되고 싶다고 하지 않았습니까? 어쩌다가 약사가 된 겁니까?",
  ui_story_5031_50310802_8_dialog_content = "후훗, 하버 시티엔 요리사는 많지만, 「모드리 증후군」을 해결할 사람은 부족하거든.",
  ui_story_5031_50310802_9_dialog_content = "그래서 당신의 꿈을 희생해서, 그런 위대한 사람이 되기로 한 겁니까?",
  ui_story_5031_50310802_10_dialog_content = "위대하고 말고는 생각한 적 없어.\n하지만 누군가가 증후군 때문에 고통받는 모습을 더는 보고 싶지 않아.",
  ui_story_5031_50310802_11_dialog_content = "게다가 약사라고 할 만한 것도 아니야.\n그저 서적 더미에 파묻혀서 연구하고 조사하는 걸 좋아할 뿐이니까.",
  ui_story_5031_50310802_12_dialog_content = "「모드리 증후군」을 완벽하게 해결하는 날이 오면,\n그땐 나도 내가 하고 싶은 일을 할 수 있겠지.",
  ui_story_5031_50310802_13_dialog_content = "그때가 오면 뭘 하고 싶습니까?",
  ui_story_5031_50310802_14_dialog_content = "어쩌면... 대륙 각지에 식사도 제공하는 고급 미술관을 열지도 모르겠네.",
  ui_story_5031_50310802_15_dialog_content = "그 약속을 아직도 기억하고 있는 겁니까?",
  ui_story_5031_50310802_16_dialog_content = "시간이 많이 흘러서 잊었을 줄 알았습니다.",
  ui_story_5031_50310802_17_dialog_content = "전부 기억하고 있어... 네가 그림을 그려주겠다고 약속했던 것도 포함해서 말이야.",
  ui_story_5031_50310802_18_dialog_content = "영주의 초상화가 걸리는 하버 시티 미술관의 벽엔 아직 빈 자리가 하나 남아 있어.",
  ui_story_5031_50310802_19_dialog_content = "......",
  ui_story_5031_50310802_20_dialog_content = "그럼 제가 도울 건 없습니까?",
  ui_story_5031_50310802_21_dialog_content = "뭐?",
  ui_story_5031_50310802_22_dialog_content = "「모드리 증후군」 말입니다. 제가 도울 일은 없겠습니까.",
  ui_story_5031_50310802_23_dialog_content = "......",
  ui_story_5031_50310802_24_dialog_content = "사실...",
  ui_story_5031_50310802_25_dialog_content = "우와! 레인보우 씨 정말 강하잖아!",
  ui_story_5031_50310802_26_dialog_content = "동작에 아름다움과 힘이 더해져서 완벽 그 자체야!",
  ui_story_5031_50310802_27_dialog_content = "...방금 뭐라고 했죠?",
  ui_story_5031_50310802_28_dialog_content = "아무것도 아니야. 우선 시합이나 보자.",
  ui_story_5031_50310802_29_dialog_content = "심판 직책을 성실히 수행해야, 열심히 노력 중인 선수들을 볼 면목이 서지 않겠어?",
  ui_story_5031_50310802_30_dialog_content = "레, 레인보우는 정말 강하네... 근데 좀 무서워...",
  ui_story_5031_50310802_31_dialog_content = "지, 진짜 그렇네.",
  ui_story_5031_50310802_32_dialog_content = "비실이, 레인보우 언니를 그렇게 말하면 못 써.",
  ui_story_5031_50310802_33_dialog_content = "맞아, 맞아. 아무리 멜 언니가 좋아하는 사람이라도 그건 안 된다구~",
  ui_story_5031_50310802_34_dialog_content = "아, 미안... 나쁜 뜻은 아니었어!",
  ui_story_5031_50310802_35_dialog_content = "그냥 투지를 불태우는 모습에 감탄하고 놀랐을 뿐이야...",
  ui_story_5031_50310802_36_dialog_content = "사블리, 이상한 얘기하지 마세요...",
  ui_story_5031_50310802_37_dialog_content = "사실 레인보우 언니는 암귀를 너무 증오해서 저러는 거예요...",
  ui_story_5031_50310802_38_dialog_content = "암귀를 증오한다고?",
  ui_story_5031_50310802_39_dialog_content = "네...",
  ui_story_5031_50310802_40_dialog_content = "레인보우 언니의 고향이 암귀 때문에 파괴됐거든.",
  ui_story_5031_50310802_41_dialog_content = "맞아. 친구랑 가족들까지 전부 잃었어.",
  ui_story_5031_50310802_42_dialog_content = "그래서 레인보우 언니는 암귀만 보면 저렇게 변해 버리는 거야.",
  ui_story_5031_50310802_43_dialog_content = "하지만 평소엔 엄청 좋은 언니야. 암귀한테만 저래.",
  ui_story_5031_50310802_44_dialog_content = "응. 팜므는 레인보우 언니가 제일 좋아!",
  ui_story_5031_50310802_45_dialog_content = "나도! 무서운 단장보다 레인보우 언니가 훨씬 좋아~",
  ui_story_5031_50310802_46_dialog_content = "다, 단장님도 좋은 분이에요...",
  ui_story_5031_50310802_47_dialog_content = "멜 언니만 그렇게 생각할걸?",
  ui_story_5031_50310802_48_dialog_content = "그런 이유 때문인가...",
  ui_story_5031_50310802_49_dialog_content = "평소의 레인보우는 밝고 명랑해서, 그런 과거가 있을 줄은 생각도 못 했어...",
  ui_story_5031_50310802_50_dialog_content = "슬픔과 분노를 밑거름으로 해바라기처럼 눈부시게 성장한 아가씨였구나.",
  ui_story_5031_50310802_51_dialog_content = "존경할 만하다고 생각해.",
  ui_story_5031_50310802_52_dialog_content = "맞는 말이야. 그래도 역시 제일 처음 나간 게 내가 아니라서 정말 다행이야...",
  ui_story_5031_50310802_53_dialog_content = "아, 그러고 보니까 피아는?",
  ui_story_5031_50310802_54_dialog_content = "너, 너네 그렇게 이곳저곳에서 보드를 밀면 안 된다구!",
  ui_story_5031_50310802_55_dialog_content = "한 방향으로 밀란 말이야!",
  ui_story_5031_50310802_56_dialog_content = "으악! 반대야, 반대! 그쪽이 아니야... 와악!",
  ui_story_5031_50310802_57_dialog_content = "<color=#e8d9bb>풍덩──</color>",
  ui_story_5031_50310802_58_dialog_content = "하하하하! 저기 저 꼬마 아가씨는 왜 제자리에서 뱅글뱅글 돌고만 있는 거야?",
  ui_story_5031_50310802_59_dialog_content = "게다가 혼자 돌다가 물에 떨어지고 말이야... 동작 점수는 어림도 없겠어.",
  ui_story_5031_50310802_60_dialog_content = "푸웁! 어푸푸...",
  ui_story_5031_50310802_61_dialog_content = "이, 이 바보 물고기들아!",
  ui_story_5031_50310802_62_dialog_content = "PlayerName 녀석... 이따가 분명히 또 날 비웃을 게 뻔해... 힝...",
  ui_story_5031_50310802_63_dialog_content = "벌써 예상이 되네. 지금 분명히 이따가 내가 자기를 놀릴 거라 생각하고 있겠지.",
  ui_story_5031_50310802_64_dialog_content = "근데... 푸훕!",
  ui_story_5031_50310802_65_dialog_content = "진짜 웃긴 걸 어떡하냐고! 아하하하하!",
  ui_story_5031_50310802_66_dialog_content = "PlayerName, 웃음소리가 너무 커.",
  ui_story_5031_50310802_67_dialog_content = "내 탓이야. 피아와 물고기들의 팀워크에 문제가 있을 줄은 전혀 예상 못 했어.",
  ui_story_5031_50310802_68_dialog_content = "동물과 소통하는 능력으로 물고기들을 조종해서\n서프보드를 움직이는 건 확실히 비현실적이긴 해.",
  ui_story_5031_50310802_69_dialog_content = "아, 아니야. 피아 자기가 문제없을 거라고 장담했었잖아.",
  ui_story_5031_50310802_70_dialog_content = "카렌, 모든 책임을 네 탓으로 돌리지 마.\n그냥 놀이일 뿐이니까 그렇게까지 진지할 필요도 없어.",
  ui_story_5031_50310802_71_dialog_content = "...응.",
  ui_story_5031_50310802_72_dialog_content = "그럼 시합 상황을 한번 정리해 도록 하겠습니다.\n소중한 두 눈을 잘 가지고 계신다면 분명 충분히 파악하실 수 있겠지만 말이죠.",
  ui_story_5031_50310802_73_dialog_content = "현재 시합에서 가장 멋진 모습을 보여주고 있는 건\n저희 서커스단의 레인보우와, 일루미나에서 온 시엘 양입니다.",
  ui_story_5031_50310802_74_dialog_content = "두 사람의 암귀 처치량은 막상막하로군요.\n동작 평점은 다른 누구보다도 앞서고 있습니다.",
  ui_story_5031_50310802_75_dialog_content = "하지만 현장 관객 평가단의 모습으로 봤을 땐,\n레인보우의 동작이 약간 우세한 것 같군요.",
  ui_story_5031_50310802_76_dialog_content = "그럼 별 볼 일 없는 나머지 사람들도 힘내시길 바랍니다.",
  ui_story_5031_50310802_77_dialog_content = "계속해서 파도가 넘실대는 이 세계에서 발버둥 쳐 보십시오.",
  ui_story_5031_50310802_78_dialog_content = "......",
  ui_story_5031_50310802_79_dialog_content = "너...너, 너! 거기서 딱 기다리고 있어!",
  ui_story_5031_50310802_80_dialog_content = "바다 밑으로 사라져!",
  ui_story_5031_50310802_81_dialog_content = "캬아악!",
  ui_story_5031_50310802_82_dialog_content = "휴~ 환상이라는 건 알고 있지만, 그래도 도저히 참을 수가 없다니까.",
  ui_story_5031_50310802_83_dialog_content = "싹 정리하고 나니까 기분이 훨씬 좋아졌어!",
  ui_story_5031_50310802_84_dialog_content = "저, 정말 강하구나...",
  ui_story_5031_50310802_85_dialog_content = "응? 너도 꽤 하잖아!",
  ui_story_5031_50310802_86_dialog_content = "어릴 때부터 지금까지 물과 가까이 지냈던 나랑 막상막하라니...\n다시 보게 되는걸!",
  ui_story_5031_50310802_87_dialog_content = "아냐. 난 그냥 계속 암귀를 공격해서 점수를 얻었던 거야.",
  ui_story_5031_50310802_88_dialog_content = "서핑 기술 쪽에서는 점수를 얼마 못 받았어.",
  ui_story_5031_50310802_89_dialog_content = "그냥 규칙을 교묘하게 이용했을 뿐이야...",
  ui_story_5031_50310802_90_dialog_content = "음, 시엘 너도 참 이상하구나.",
  ui_story_5031_50310802_91_dialog_content = "이, 이상해?",
  ui_story_5031_50310802_92_dialog_content = "봐. 난 분명히 널 칭찬하고 있었어.\n근데 넌 계속 자길 깎아내리잖아? 표정도 안 좋고 말이야.",
  ui_story_5031_50310802_93_dialog_content = "암귀를 공격해서 점수를 받는 건 정상적인 룰이야.\n어째서 규칙을 교묘하게 이용했다고 말하는 거야?",
  ui_story_5031_50310802_94_dialog_content = "......",
  ui_story_5031_50310802_95_dialog_content = "시엘, 넌 충분히 잘하고 있잖아. 근데 왜 자길 믿어주지 않는 거니?",
  ui_story_5031_50310802_96_dialog_content = "항상 그렇게 긴장하고 있다간 잘할 수 있는 일도 실패할 거라구~",
  ui_story_5031_50310802_97_dialog_content = "난...",
  ui_story_5031_50310802_98_dialog_content = "캬아악!",
  ui_story_5031_50310802_99_dialog_content = "또 암귀냐! 어딜 도망가려고!",
  ui_story_5031_50310802_100_dialog_content = "내가... 잘한다고?",
  ui_story_5031_50310802_101_dialog_content = "헤헤... 헤헤헤...",
  ui_story_5031_50310802_102_dialog_content = "그럼 절대 레인보우 씨를 실망하게 만들 수 없어!",
  ui_story_5031_50310802_103_dialog_content = "「팔 강화복 상태 조정, Type-Ⅱ」!",
  ui_story_5031_50310802_104_dialog_content = "「에너지 출력률 60%」!",
  ui_story_5031_50310802_105_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5031_50310802_106_dialog_content = "시, 시엘?!",
  ui_story_5031_50310802_107_dialog_content = "에너지 출력률을 더 높인 건가?",
  ui_story_5031_50310802_108_dialog_content = "하지만 「스틱스」는 지금...",
  ui_story_5031_50310802_109_dialog_content = "우와! 저 로봇 소녀 좀 봐! 갑자기 바다에 엄청난 에너지를 내뿜고 있잖아?",
  ui_story_5031_50310802_110_dialog_content = "으앗, 배까지 흔들리고 있어! 뒤집히진 않겠지...?",
  ui_story_5031_50310802_111_dialog_content = "공중으로 날아올랐어! 점프 회전으로 동작 점수를 따려는 건가?",
  ui_story_5031_50310802_112_dialog_content = "아, 아니야... 저건...",
  ui_story_5031_50310802_113_dialog_content = "암귀다! 바닷속 암귀가 전부 딸려 나오고 있어!",
  ui_story_5031_50310802_114_dialog_content = "우와!",
  ui_story_5031_50310802_115_dialog_content = "그 힘... 너무 멋져!",
  ui_story_5031_50310802_116_dialog_content = "난 고난도의 동작은 못 하니까... 나머지 50%에 걸어볼 거야!",
  ui_story_5031_50310802_117_dialog_content = "「스틱스」, 발사!",
  ui_story_5031_50310802_118_dialog_content = "하지만 저 강화복의 에너지 출력은 매우 높습니다.\n효과적으로 대규모 범위의 공격을 전개할 수 있겠지요.",
  ui_story_5031_50310802_119_dialog_content = "음. 메카는 비교적 무겁고 투박하니 가벼운 동작은 힘들죠.",
  ui_story_5031_50310802_120_dialog_content = "시엘은 그 우세를 이용해서 순식간에 대량의 암귀를 처치했군요.\n획득 점수가 역전되었습니다.",
  ui_story_5031_50310802_121_dialog_content = "역경 속에서도 돌파구를 찾아내다니, 매우 훌륭합니다.",
  ui_story_5031_50310802_122_dialog_content = "그럼 영주님, 점수를 계산해 주시죠.",
  ui_story_5031_50310802_123_dialog_content = "그러죠, 단장님.",
  ui_story_5031_50310802_124_dialog_content = "이, 이러면...",
  ui_story_5031_50310802_125_dialog_content = "<color=#e8d9bb>파직, 파지직!</color>",
  ui_story_5031_50310802_126_dialog_content = "어라?",
  ui_story_5031_50310802_127_dialog_content = "큰일이야! 역시 「스틱스」는 저렇게 거대한 에너지를 버틸 수 없었어...",
  ui_story_5031_50310802_128_dialog_content = "으아앗! 떠, 떨어진다!",
  ui_story_5031_50310802_129_dialog_content = "시엘!",
  ui_story_5031_50310802_130_dialog_content = "이얍~",
  ui_story_5031_50310802_131_dialog_content = "어? 레인보우?",
  ui_story_5031_50310802_132_dialog_content = "으으...",
  ui_story_5031_50310802_133_dialog_content = "이제 눈 떠도 돼. 내가 받아줬으니까~",
  ui_story_5031_50310802_134_dialog_content = "어라?",
  ui_story_5031_50310802_135_dialog_content = "레, 레인보우 씨?",
  ui_story_5031_50310802_136_dialog_content = "방금 너무 제멋대로 군 거 아냐?\n강화복을 제대로 점검하지도 않고 그렇게 출력을 높이면 어떡해?",
  ui_story_5031_50310802_137_dialog_content = "미, 미안해.",
  ui_story_5031_50310802_138_dialog_content = "사실 「스틱스」는 전에 한번 폭발한 적이 있거든...\n아직 완벽하게 수리하진 못했어.",
  ui_story_5031_50310802_139_dialog_content = "레인보우 씨한테 폐를 끼쳤네...",
  ui_story_5031_50310802_140_dialog_content = "그렇구나. 그거 정말 아쉬운걸!",
  ui_story_5031_50310802_141_dialog_content = "그래도 제대로 수리하면 분명히 더 대단하겠지? 그거 정말 기대되네~",
  ui_story_5031_50310802_142_dialog_content = "......",
  ui_story_5031_50310802_143_dialog_content = "저기, 레인보우 씨.",
  ui_story_5031_50310802_144_dialog_content = "응? 왜?",
  ui_story_5031_50310802_145_dialog_content = "왜 날 구한 거야? 만약 내가 그대로 바다에 빠졌으면...\n동작 점수가 엄청 깎였을 거잖아.",
  ui_story_5031_50310802_146_dialog_content = "어? 아, 그건 말이지...",
  ui_story_5031_50310802_147_dialog_content = "왜냐하면 난 저 오백만 나이티움보다는...",
  ui_story_5031_50310802_148_dialog_content = "너한테 더 관심이 있거든~",
  ui_story_5031_50310901_1_dialog_content = "첫 번째 시합이 종료되었습니다.\n두 번째 시합의 참가 선수 여러분께서는 지정된 위치로 이동하세요.",
  ui_story_5031_50310901_2_dialog_content = "대기하는 시간 동안 이전 시합의 점수를 결산하겠습니다.",
  ui_story_5031_50310901_3_dialog_content = "피아, 너무 속상해하지 마. 괜찮아. 아직 기회는 있어.",
  ui_story_5031_50310901_4_dialog_content = "맞아, 맞아. 너무 스트레스받을 거 없어.\n애초에 네가 높은 점수를 얻을 거라곤 기대 안 했으니까.",
  ui_story_5031_50310901_5_dialog_content = "으아아아앙!",
  ui_story_5031_50310901_6_dialog_content = "PlayerName, 이 바보!",
  ui_story_5031_50310901_7_dialog_content = "아? 내가 또 뭐 어쨌다고?",
  ui_story_5031_50310901_8_dialog_content = "나, 난 그냥 위로한 건데...",
  ui_story_5031_50310901_9_dialog_content = "자, 자. PlayerName, 넌 일단 말하지 마.",
  ui_story_5031_50310901_10_dialog_content = "...억울해.",
  ui_story_5031_50310901_11_dialog_content = "자, 다음 경기를 준비하자.",
  ui_story_5031_50310901_12_dialog_content = "방금 레인보우 쪽에서 들었는데, 다음 경기는 멜트가 출전할 거야.",
  ui_story_5031_50310901_13_dialog_content = "응? 피아, 왜 그래?",
  ui_story_5031_50310901_14_dialog_content = "훌쩍... 카렌 언니... PlayerName, 저 녀석이...",
  ui_story_5031_50310901_15_dialog_content = "자, 잠깐만... 난 아무것도 안 했다고!",
  ui_story_5031_50310901_16_dialog_content = "피아, 일단 다음 시합부터 준비하는 게 어떨까?",
  ui_story_5031_50310901_17_dialog_content = "피아도 상을... 아니, 수영복을 꼭 가지고 싶잖아.\n「구름고래」도 구해야 하고. 그렇지?",
  ui_story_5031_50310901_18_dialog_content = "훌쩍... 응...",
  ui_story_5031_50310901_19_dialog_content = "그럼 피아, 얼른 눈물 닦고 같이 출전 순서부터 생각해 보자~",
  ui_story_5031_50310901_20_dialog_content = "그럼... 다음 판은 PlayerName 오빠가 나가는 게 좋을 것 같아!",
  ui_story_5031_50310901_21_dialog_content = "뭐?!",
  ui_story_5031_50310901_22_dialog_content = "흥! 아까 내가 물에 빠졌을 때 엄청나게 비웃었지!",
  ui_story_5031_50310901_23_dialog_content = "이번엔 내가 비웃을 차례야!",
  ui_story_5031_50310901_24_dialog_content = "내가 아까 웃은 건 어떻게... 아니, 그것보다 그게 무슨 논리야?!",
  ui_story_5031_50310901_25_dialog_content = "중요한 건 시합에서 이기는 거 아냐?",
  ui_story_5031_50310901_26_dialog_content = "어차피 두 개의 성적만 가지고 계산할 건데, 난 아예 안 나가도 되는 거잖아? 그렇지?",
  ui_story_5031_50310901_27_dialog_content = "잊었어? PlayerName, 너랑 피아는 한 사람으로 계산해.",
  ui_story_5031_50310901_28_dialog_content = "그러니까 너희 둘 성적은 총합으로 계산될 거야.",
  ui_story_5031_50310901_29_dialog_content = "...그, 그런 일이 있었던 것 같기도 하네.",
  ui_story_5031_50310901_30_dialog_content = "지금은 나와 바이스가 출전했을 때 어떤 강적이 나타날지 아직 알 수 없어.",
  ui_story_5031_50310901_31_dialog_content = "그러니까 너도 출전하는 편이 비교적 안전할 거야.",
  ui_story_5031_50310901_32_dialog_content = "그렇게 생각하면 다음 시합에 PlayerName 네가 나가는 것도 괜찮은 것 같은데?",
  ui_story_5031_50310901_33_dialog_content = "확실히 그래. 저 세쌍둥이 중에서는 멜트가 가장 순한 것 같으니까.",
  ui_story_5031_50310901_34_dialog_content = "게다가 그로누 선배도 서핑은 그렇게 잘하지 못할 것 같고 말이야.",
  ui_story_5031_50310901_35_dialog_content = "그럼...",
  ui_story_5031_50310901_36_dialog_content = "그렇다면...",
  ui_story_5031_50310901_37_dialog_content = "...알겠어. 나가면 되잖아. 다들 그렇게 쳐다보지 마.",
  ui_story_5031_50310901_38_dialog_content = "후후, PlayerName 파이팅~",
  ui_story_5031_50310901_39_dialog_content = "너무 긴장하지 마. 우리가 가르쳐 줬던 요령만 기억하면 돼.",
  ui_story_5031_50310901_40_dialog_content = "못해도 괜찮아.",
  ui_story_5031_50310901_41_dialog_content = "응, 알았어.",
  ui_story_5031_50310901_42_dialog_content = "후후, PlayerName! 피아한테 짐이나 되지 말라고!",
  ui_story_5031_50310901_43_dialog_content = "네 점수도 얼마 안 되면서!",
  ui_story_5031_50310901_44_dialog_content = "아직 출발점에 오지 못한 선수는 성적을 발표하는 동안 서둘러 주십시오.",
  ui_story_5031_50310901_45_dialog_content = "저번 시합에서 가장 높은 성적을 기록한 선수는... 레인보우입니다.",
  ui_story_5031_50310901_46_dialog_content = "훗, 역시 우리 서커스단의 유능한 인재답군요. 예상대로입니다.",
  ui_story_5031_50310901_47_dialog_content = "레인보우──!",
  ui_story_5031_50310901_48_dialog_content = "하지만 다음 소식은 아마 모두의 예상을 뒤엎는 결과가 될 것 같군요.",
  ui_story_5031_50310901_49_dialog_content = "레인보우와 함께 1위를 기록한 사람이 있습니다. 바로 시엘 양입니다.",
  ui_story_5031_50310901_50_dialog_content = "우와! 그 로봇 소녀 맞지?",
  ui_story_5031_50310901_51_dialog_content = "엄청나네, 레인보우 씨 점수를 따라잡았단 말이야?",
  ui_story_5031_50310901_52_dialog_content = "우와! 시엘! 완전 대단해!",
  ui_story_5031_50310901_53_dialog_content = "고마워요, 그로누 선배님.",
  ui_story_5031_50310901_54_dialog_content = "그로누 선배? 왜 여기 있어요?!",
  ui_story_5031_50310901_55_dialog_content = "출전 준비 안 해요?",
  ui_story_5031_50310901_56_dialog_content = "헤헤, 그건 말이지...",
  ui_story_5031_50310901_57_dialog_content = "너흰 분명히 PlayerName, 멜트, 그리고 내가 시합을 벌이길.\n원했을 거란 말이지.",
  ui_story_5031_50310901_58_dialog_content = "그렇게 되면 너희 둘의 시합을 견제할 사람이 하나 줄 테니까. 맞지?",
  ui_story_5031_50310901_59_dialog_content = "......",
  ui_story_5031_50310901_60_dialog_content = "아, 그건...",
  ui_story_5031_50310901_61_dialog_content = "그렇다면 뜻대로 만들어 줄 순 없잖아~",
  ui_story_5031_50310901_62_dialog_content = "후, 긴장하지 말자.",
  ui_story_5031_50310901_63_dialog_content = "이번 시합은 확실히 사람이 적네. 침착하게만 하면 충분히 할 수 있을 거야.",
  ui_story_5031_50310901_64_dialog_content = "PlayerName, 저기...",
  ui_story_5031_50310901_65_dialog_content = "응? 멜트, 왜?",
  ui_story_5031_50310901_66_dialog_content = "그... 다, 당신 서프보드의 밧줄... 몸에 제대로 안 묶은 것 같아요.",
  ui_story_5031_50310901_67_dialog_content = "그럼 위험할 거예요...",
  ui_story_5031_50310901_68_dialog_content = "아! 까먹고 있었어...",
  ui_story_5031_50310901_69_dialog_content = "고마워! 멜트, 큰 도움이 됐어.",
  ui_story_5031_50310901_70_dialog_content = "...으읏!",
  ui_story_5031_50310901_71_dialog_content = "어? 물에 뛰어들어서 사라져 버렸잖아?",
  ui_story_5031_50310901_72_dialog_content = "내가 또 뭐 잘못 말했나?",
  ui_story_5031_50310901_73_dialog_content = "음, 시간이 거의 다 됐군요.",
  ui_story_5031_50310901_74_dialog_content = "그럼 다음 시합을 시작하세요.",
  ui_story_5031_50310901_75_dialog_content = "하하하하, 또 저렇게 대충 시작하네.",
  ui_story_5031_50310901_76_dialog_content = "저게 서커스단 단장의 스타일인가?",
  ui_story_5031_50310901_77_dialog_content = "음, 이번엔 로봇도 없으니까 저번 시합처럼 볼거리는 없겠네.",
  ui_story_5031_50310901_78_dialog_content = "어? 저기 좀 봐! 서커스단 세쌍둥이 중 하나가...",
  ui_story_5031_50310901_79_dialog_content = "레인보우보다 멋진 동작을 선보이고 있어!",
  ui_story_5031_50310901_80_dialog_content = "당연하죠. 멜트는 서커스단에서 신체 균형과 장악력이\n가장 뛰어난 사람 중 하나니까요.",
  ui_story_5031_50310901_81_dialog_content = "공중그네와 링 체조도 완벽하게 해내는 멜트라면 서핑 정도는 식은 죽 먹기입니다.",
  ui_story_5031_50310901_82_dialog_content = "넌 서커스단의 모두에 대해 잘 알고 있구나.",
  ui_story_5031_50310901_83_dialog_content = "네. 저들은 서커스단의 연기자일 뿐만 아니라...",
  ui_story_5031_50310901_84_dialog_content = "서커스단이라는 대가족의 일원이니 말이지요.",
  ui_story_5031_50310901_85_dialog_content = "......",
  ui_story_5031_50310901_86_dialog_content = "그 말... 예전의 네가 생각나는 말이네.",
  ui_story_5031_50310901_87_dialog_content = "그렇습니까. 가족과 「엘비스 형」에게만 의지하던 그 쓸모없는 녀석 말입니까?",
  ui_story_5031_50310901_88_dialog_content = "아니, 둥지에서 떨어진 아기새를 위해 울던 착한 꼬마가 생각났어.",
  ui_story_5031_50310901_89_dialog_content = "결국 나무를 타고 올라가서 아기새를 둥지에 올려줬지만,\n그러다 떨어져서 반년 동안 팔에 깁스를 했던 아이 말이야.",
  ui_story_5031_50310901_90_dialog_content = "넌 여전하구나. 모든 사람을 신경 쓰고, 그 누구도 못 본 척할 수 없는 거겠지.",
  ui_story_5031_50310901_91_dialog_content = "그런 흑역사는 얘기하지 마시죠.",
  ui_story_5031_50310901_92_dialog_content = "시합이나 잘 보세요.",
  ui_story_5031_50310901_93_dialog_content = "하하, 알겠어.",
  ui_story_5031_50310902_1_dialog_content = "그럼 두 번째 시합에서 가장 높은 성적을 가져갈 사람도\n의심의 여지 없이 우리 서커스단의 일원인...",
  ui_story_5031_50310902_2_dialog_content = "멜트가 되겠군요.",
  ui_story_5031_50310902_3_dialog_content = "오오오오!",
  ui_story_5031_50310902_4_dialog_content = "저것이 바로 그녀가 밤낮없이 별빛 아래에서도 땀 흘린 결과겠지요.",
  ui_story_5031_50310902_5_dialog_content = "부디 그녀의 성공이 부패하고 게으른 여러분의 영혼에 자극이 되었으면 좋겠습니다.",
  ui_story_5031_50310902_X5_dialog_content = "......",
  ui_story_5031_50310902_X6_dialog_content = "흥, 부끄러워서 말도 할 수 없을 지경입니까?\n그것도 그렇겠죠. 모든 사람이 인생의 목표가 있는 건 아니니까요.",
  ui_story_5031_50310902_X7_dialog_content = "그럼 세 번째 참가 선수들은 출발지로 가서 준비해 주시죠.",
  ui_story_5031_50310902_X8_dialog_content = "세 번째 그룹 선수 여러분, 경기를 준비해 주시기 바랍니다.",
  ui_story_5031_50310902_6_dialog_content = "세 번째 참가 선수들은 출발지로 가서 준비해 주시죠.",
  ui_story_5031_50310902_7_dialog_content = "에~ 아니지? PlayerName, 너 빵점 맞은 거야?",
  ui_story_5031_50310902_8_dialog_content = "뭐라고 해야 할까, 이것도 어떻게 보면 보통 사람은 해낼 수 없는 수준이겠네.",
  ui_story_5031_50310902_9_dialog_content = "만약 바이스 언니랑 카렌 언니가 「구름고래」 일에 대해 몰랐으면 어쩔 뻔했어?",
  ui_story_5031_50310902_10_dialog_content = "으으... 그만해...",
  ui_story_5031_50310902_11_dialog_content = "아이테르로 태어나서 정말 미안해...",
  ui_story_5031_50310902_12_dialog_content = "피아, 너무 질책하진 마.",
  ui_story_5031_50310902_13_dialog_content = "초심자가 하루아침에 서핑을 배우는 건 애초에 그리 쉬운 일이 아니니까.",
  ui_story_5031_50310902_14_dialog_content = "점수는 우리가 따올 테니까 걱정 마.",
  ui_story_5031_50310902_15_dialog_content = "역시 바이스 언니랑 카렌 언니는 정말 든든해!",
  ui_story_5031_50310902_16_dialog_content = "휴~ PlayerName 오빠도 좀 더 노력하라구.",
  ui_story_5031_50310902_17_dialog_content = "이제 그만 놀릴 테니까 기운 내~\n피아가 서핑을 배우고 나면 카렌 언니랑 같이 차근차근 가르쳐 줄 테니까!",
  ui_story_5031_50310902_18_dialog_content = "아하하... 그것참 고맙다.",
  ui_story_5031_50310902_19_dialog_content = "으흥~ 마음껏 감사하라구.",
  ui_story_5031_50310902_20_dialog_content = "저, 저기... PlayerName...",
  ui_story_5031_50310902_21_dialog_content = "응? 멜트구나. 무슨 일이야?",
  ui_story_5031_50310902_22_dialog_content = "으읏...",
  ui_story_5031_50310902_23_dialog_content = "사블리가 말할게!",
  ui_story_5031_50310902_24_dialog_content = "멜 언니는 PlayerName한테 사과하고 싶대.\n방금 잘못하면 다칠 뻔하게 만들었으니까!",
  ui_story_5031_50310902_25_dialog_content = "아, 그거 말이야? 괜찮아, 멜트! 하나도 안 다쳤어.",
  ui_story_5031_50310902_26_dialog_content = "그냥 좀 놀라서 바닷물만 두 모금 정도 마셨을 뿐이야.",
  ui_story_5031_50310902_27_dialog_content = "으음... 네...",
  ui_story_5031_50310902_28_dialog_content = "PlayerName 넌 정말 상냥하구나. 대장이랑 전혀 달라!",
  ui_story_5031_50310902_29_dialog_content = "저렇게 상냥한 비실이라면 아예 못 받아들일 정도는 아니네.\n어쩐지 멜 언니가 널 좋... 우웁!",
  ui_story_5031_50310902_30_dialog_content = "파, 팜므!",
  ui_story_5031_50310902_31_dialog_content = "이제 출발점으로 가야 할 시간이에요. 어, 얼른 가세요!",
  ui_story_5031_50310902_32_dialog_content = "우우읍!",
  ui_story_5031_50310902_33_dialog_content = "아, 기다려! 사블리도 같이 가!",
  ui_story_5031_50310902_34_dialog_content = "호오?",
  ui_story_5031_50310902_35_dialog_content = "역시 PlayerName 넌 정말 인기가 많구나.",
  ui_story_5031_50310902_36_dialog_content = "......",
  ui_story_5031_50310902_37_dialog_content = "응? 뭐라고?",
  ui_story_5031_50310902_38_dialog_content = "아무것도 아니야~",
  ui_story_5031_50310902_39_dialog_content = "나도 얼른 준비하러 가야겠어. 곧 시작할 것 같아!",
  ui_story_5031_50310902_40_dialog_content = "그래, 가자.",
  ui_story_5031_50310902_41_dialog_content = "...뭐야. 제대로 말도 안 하고...",
  ui_story_5031_50310902_42_dialog_content = "우리도 해변 쪽으로 가자. 피...",
  ui_story_5031_50310902_43_dialog_content = "응? 피아?",
  ui_story_5031_50310902_44_dialog_content = "...정말... 다들 왜 저래?",
  ui_story_5031_50310902_45_dialog_content = "세 번째 경기입니다. 규칙은 다들 알고 있겠죠. 그럼 시작하세요.",
  ui_story_5031_50310902_46_dialog_content = "받아라!",
  ui_story_5031_50310902_47_dialog_content = "오~ 엄청 맹렬한걸?",
  ui_story_5031_50310902_48_dialog_content = "그럼 팜므도 진심으로 해야 될 것 같네.\n남몰래 특훈까지 한 나를 얕보면 안 된다구.",
  ui_story_5031_50310902_49_dialog_content = "콜록... 콜록, 콜록!",
  ui_story_5031_50310902_50_dialog_content = "엘비스?! 약은 어디 있습니까!",
  ui_story_5031_50310902_51_dialog_content = "내... 내 외투 안쪽 주머니에...",
  ui_story_5031_50310902_52_dialog_content = "...마이크부터... 꺼야 해... 콜록, 콜록!",
  ui_story_5031_50310902_53_dialog_content = "네, 알고 있습니다. 이미 껐습니다.",
  ui_story_5031_50310902_54_dialog_content = "외투 주머니에 있는 게 맞습니까? 안 보입니다만.",
  ui_story_5031_50310902_55_dialog_content = "윽... 콜록, 콜록!",
  ui_story_5031_50310902_56_dialog_content = "미안. 혹시 손수건 있어?",
  ui_story_5031_50310902_57_dialog_content = "있습니다. 잠시만요.",
  ui_story_5031_50310902_58_dialog_content = "<color=#e8d9bb>딸그락──</color>",
  ui_story_5031_50310902_59_dialog_content = "...온갖 잡동사니가 다 들어 있군요...",
  ui_story_5031_50310902_60_dialog_content = "이럴 때는 좀 얌전히 안에 있을 순 없는 겁니까.",
  ui_story_5031_50310902_61_dialog_content = "......",
  ui_story_5031_50310902_62_dialog_content = "자, 받으세요.",
  ui_story_5031_50310902_63_dialog_content = "고마워... 콜록, 콜록!",
  ui_story_5031_50310902_64_dialog_content = "와! 이번 시합은 장난 아닌데? 실력이 뛰어난 선수가 엄청 많아!",
  ui_story_5031_50310902_65_dialog_content = "오! 또 암귀를 해치웠어!",
  ui_story_5031_50310902_66_dialog_content = "저기 저 활 쏘는 아가씨 대단하네!",
  ui_story_5031_50310902_67_dialog_content = "......",
  ui_story_5031_50310902_68_dialog_content = "사람이 없는 곳에서 좀 쉬어야겠어. 미안한데 부축 좀 해 줄 수 있을까?",
  ui_story_5031_50310902_69_dialog_content = "네. 잠시만요.",
  ui_story_5031_50310902_70_dialog_content = "거기 피에로, 이리 오세요!",
  ui_story_5031_50310902_71_dialog_content = "그래요. 당신 말입니다.",
  ui_story_5031_50310902_72_dialog_content = "단장님, 무슨 일이세요?",
  ui_story_5031_50310902_73_dialog_content = "전 영주님과 가서 할 이야기가 있으니 점수 통계는 당신이 좀 맡으세요.",
  ui_story_5031_50310902_74_dialog_content = "알겠어요.",
  ui_story_5031_50310902_75_dialog_content = "그런 표정 하지 마. 난 괜찮으니까.",
  ui_story_5031_50310902_76_dialog_content = "괜찮다고요? 방금 절 잡고 피를 잔뜩 토해놓고 말입니까?",
  ui_story_5031_50310902_77_dialog_content = "미안. 옷을 더럽혔네.",
  ui_story_5031_50310902_78_dialog_content = "제가 지금 그걸 신경 쓰는 게 아니라는 건 아실 텐데요.",
  ui_story_5031_50310902_79_dialog_content = "걱정 마. 이건 내 몸에 피가 많다는 거잖아. 건강하다는 뜻이야.",
  ui_story_5031_50310902_80_dialog_content = "...헛소리하지 마세요.",
  ui_story_5031_50310902_81_dialog_content = "예전에 말했던 해결 방법... 정말 알려줄 수 없는 겁니까?",
  ui_story_5031_50310902_82_dialog_content = "당신이 절 믿어주기만 한다면 제가 돕겠습니다.",
  ui_story_5031_50310902_83_dialog_content = "......",
  ui_story_5031_50310902_84_dialog_content = "왜 그런 표정을 하는 겁니까?",
  ui_story_5031_50310902_85_dialog_content = "아무것도 아니야. 그냥 방금 네가 한 말을 들었더니... 갑자기 어릴 때가 생각났거든.",
  ui_story_5031_50310902_86_dialog_content = "또 제 흑역사는 아니겠지요.",
  ui_story_5031_50310902_87_dialog_content = "음, 어릴 때 넌 나보다 작고 마르긴 했지만...\n항상 최선을 다해 다른 사람을... 그리고 날 도와줬었지.",
  ui_story_5031_50310902_88_dialog_content = "그때 네 눈빛은 방금 전과 똑같았어. 전혀 달라진 게 없어.",
  ui_story_5031_50310902_89_dialog_content = "세월은 얼굴과 몸에 그 흔적을 남기지만, 영혼을 바꿀 수는 없지요.",
  ui_story_5031_50310902_90_dialog_content = "맞아. 어떤 것들은 절대 변하지 않아.",
  ui_story_5031_50310902_91_dialog_content = "네가 여전히 나보다 키가 작은 것도 말이야.",
  ui_story_5031_50310902_92_dialog_content = "쳇. 하지만 지금 당신 정도의 체력이라면 저 혼자서도 열 명은 상대할 수 있을 겁니다.",
  ui_story_5031_50310902_93_dialog_content = "맞아. 이제 더는 내가 지켜줘야 하는 제노가 아니게 됐으니까.",
  ui_story_5031_50310902_94_dialog_content = "이제 내 꼴로는 널 지킬 수 없게 됐어.",
  ui_story_5031_50310902_95_dialog_content = "...그럼 이제 제가 당신을 지켜야겠군요.",
  ui_story_5031_50310902_96_dialog_content = "하하, 그런 말은 함부로 하는 게 아니야.",
  ui_story_5031_50310902_97_dialog_content = "진심입니다, 엘비스.",
  ui_story_5031_50310902_98_dialog_content = "만약 당신이 방법을 알려주기만 한다면,\n제가 할 수 있는 일이라면 반드시 해내겠습니다.",
  ui_story_5031_50310902_99_dialog_content = "그럼 만약 그 방법이 네가 속한 조직에까지 영향을 주게 된다면?",
  ui_story_5031_50310902_100_dialog_content = "......?",
  ui_story_5031_50310902_101_dialog_content = "만약... 그러니까 만약, 그 방법을 위해서는 네 배가 필요하고...\n네 배의 가장 깊은 곳에 있는 어떤 물건이 필요하다면?",
  ui_story_5031_50310902_102_dialog_content = "날 도와주겠어?",
  ui_story_5031_50310902_103_dialog_content = "...어떻게 아신 겁니까.",
  ui_story_5031_50310902_104_dialog_content = "그건 중요하지 않아, 제노.",
  ui_story_5031_50310902_105_dialog_content = "중요한 건 우리가 더는 어린애가 아니라는 거야.\n이제 더는 순진하고 걱정 없던 그 시절로 돌아갈 순 없어.",
  ui_story_5031_50310902_106_dialog_content = "지금 내리는 모든 결정... 모든 약속...\n내뱉는 모든 말 한마디가... 너무나도 많은 것을 짊어지고 있어.",
  ui_story_5031_50310902_107_dialog_content = "그러니 다시 물어볼게. 그래도 날 도와주겠어?",
  ui_story_5031_50310902_108_dialog_content = "......",
  ui_story_5031_50310902_109_dialog_content = "저...전 한때 맹세했습니다.",
  ui_story_5031_50310902_110_dialog_content = "이 배를 지키겠다고, 그 물건을 지키겠다고 말이지요.",
  ui_story_5031_50310902_111_dialog_content = "...알겠어. 미안해. 널 곤란하게 만들었네.",
  ui_story_5031_50310902_112_dialog_content = "가자. 시합을 계속 진행해야지. 저기 피에로 씨도 정신없어 보이고 말이야.",
  ui_story_5031_50310902_113_dialog_content = "엘비스, 저는...",
  ui_story_5031_50310902_114_dialog_content = "제노.",
  ui_story_5031_50310902_115_dialog_content = "......",
  ui_story_5031_50310902_116_dialog_content = "더는 아무 말도 하지 마. 다 이해하니까.",
  ui_story_5031_50310902_117_dialog_content = "하지만 어쨌든... 너한테 전하고 싶었어...",
  ui_story_5031_50310902_118_dialog_content = "이 십여 년 동안, 난 항상 널 그리워했어.",
  ui_story_5031_50310902_119_dialog_content = "......!",
  ui_story_5031_50311001_1_dialog_content = "카렌 전하.",
  ui_story_5031_50311001_2_dialog_content = "마티외? 무슨 일이지?",
  ui_story_5031_50311001_3_dialog_content = "이 촌극에 계속 참가하실 생각이십니까?",
  ui_story_5031_50311001_4_dialog_content = "이렇게 많은 평민과 같은 물에 몸을 담그고 있자니... 정말... 구역질이 나는군요.",
  ui_story_5031_50311001_5_dialog_content = "그래. 난 신경 안 써.",
  ui_story_5031_50311001_6_dialog_content = "그게 구역질이 난다면, 가서 모래사장이나 배 위에서 구경하고 있어.\n아니면 백야성으로 돌아가도 괜찮아.",
  ui_story_5031_50311001_7_dialog_content = "쳇, 당신의 그 짜증 나는 모...",
  ui_story_5031_50311001_8_dialog_content = "마티외.",
  ui_story_5031_50311001_9_dialog_content = "...흥, 정말 성가시군.\n내가 왜 이렇게 제멋대로인 공주님을 지켜야 하는 건지 원.",
  ui_story_5031_50311001_10_dialog_content = "......",
  ui_story_5031_50311001_11_dialog_content = "마티외, 난 제멋대로인 공주님 같은 게 아니야.\n네 보호가 필요하지도 않아.",
  ui_story_5031_50311001_12_dialog_content = "혹시 네가 수영을 못해서 초조해진 거라면 걱정 마. 난 아무 일도 없을 테니까.",
  ui_story_5031_50311001_13_dialog_content = "푸훕.",
  ui_story_5031_50311001_14_dialog_content = "뭐, 뭐라고요?!",
  ui_story_5031_50311001_15_dialog_content = "누가 수영을 못 한다는 겁니까? 고작 수영일 뿐이잖습니까!\n평민도 하는 걸 제가 못 할 리가 없지 않습니까?!",
  ui_story_5031_50311001_16_dialog_content = "그, 그리고 뢰베 이 자식! 너 뒤에서 뭘 웃고 있어? 다 들었다고!",
  ui_story_5031_50311001_17_dialog_content = "넌 수영 못 해.",
  ui_story_5031_50311001_18_dialog_content = "...으이익! 이 자식!",
  ui_story_5031_50311001_19_dialog_content = "됐어! 이 정도면 충분히 참았다고!\n성격 나쁜 공주님. 평민들과 어울리던 걸 후회하게 될 겁니다!",
  ui_story_5031_50311001_20_dialog_content = "전 가서 옷이나 몸을 씻어야겠습니다!",
  ui_story_5031_50311001_21_dialog_content = "......",
  ui_story_5031_50311001_22_dialog_content = "...저 사람들은 뭐 하러 온 거야?",
  ui_story_5031_50311001_23_dialog_content = "아마 물에 들어갈 엄두가 안 나서, 내가 이번 시합에 참가하는 걸 막고 싶었겠지.",
  ui_story_5031_50311001_24_dialog_content = "정말... 이리돈 대심판관은 대체 왜 저런 녀석을 나한테 보낸 건지...",
  ui_story_5031_50311001_25_dialog_content = "바이스 언니! 왔구나!",
  ui_story_5031_50311001_26_dialog_content = "바이스, 어서 와.",
  ui_story_5031_50311001_27_dialog_content = "방금 바이스 언니 정말 멋졌어. 분명히 점수도 엄청 높을 거야!",
  ui_story_5031_50311001_28_dialog_content = "이제 「구름고래」도 분명히 우리 게 될 거야!\n그럼 나도 사부의 잔소리에서 벗어날 수 있어!",
  ui_story_5031_50311001_29_dialog_content = "피아, 너무 기대하진 마.",
  ui_story_5031_50311001_30_dialog_content = "방금 전엔 상대도 대단했거든.",
  ui_story_5031_50311001_31_dialog_content = "그로누 선배가 저렇게 서핑을 잘할 줄은 몰랐지 뭐야... 내가 너무 방심했어!",
  ui_story_5031_50311001_32_dialog_content = "괜찮아. 아직 한 번 더 남았잖아. 하지만 저쪽은 이제 기회가 없어.",
  ui_story_5031_50311001_33_dialog_content = "그래. 그럼 다음은 카렌 차례네!",
  ui_story_5031_50311001_34_dialog_content = "하지만 방금 그 사람들... 마티외랑 뢰베라고 했나?\n대체 왜 온 거야? 시합에 참가한대?",
  ui_story_5031_50311001_35_dialog_content = "그 사람들은 신경 쓸 필요 없어.",
  ui_story_5031_50311001_36_dialog_content = "그것보다 아까부터 사회자 목소리가 안 들리는 것 같은데.",
  ui_story_5031_50311001_37_dialog_content = "응. 확실히 그렇네. 엘비스 영주님, 무슨 일이라도 있나?",
  ui_story_5031_50311001_38_dialog_content = "아무튼 얼른 가서 준비하는 게 좋겠어!",
  ui_story_5031_50311001_39_dialog_content = "힘내, 카렌!",
  ui_story_5031_50311001_40_dialog_content = "카렌 언니 파이팅!",
  ui_story_5031_50311001_41_dialog_content = "그래. 걱정 말고 나한테 맡겨.",
  ui_story_5031_50311001_42_dialog_content = "......",
  ui_story_5031_50311001_43_dialog_content = "제노 대장?",
  ui_story_5031_50311001_44_dialog_content = "뭡니까.",
  ui_story_5031_50311001_45_dialog_content = "<size=33>으악! 무서워라... 갑자기 대장 기분이 엄청 나빠진 것 같은데...</size>",
  ui_story_5031_50311001_46_dialog_content = "저, 저기, 대장... 이전 시합 성적이 나왔는데... 발표하실 건가요?",
  ui_story_5031_50311001_47_dialog_content = "......",
  ui_story_5031_50311001_48_dialog_content = "그... 아니면 대장... 시합 시작 선포는 하실 건가요?",
  ui_story_5031_50311001_49_dialog_content = "선수들도 전부 대기 중인 것 같은데...",
  ui_story_5031_50311001_50_dialog_content = "시작.",
  ui_story_5031_50311001_51_dialog_content = "......",
  ui_story_5031_50311001_52_dialog_content = "휴, 몇 번 보니까 익숙해지는 것 같기도 하고...",
  ui_story_5031_50311001_53_dialog_content = "받아라!",
  ui_story_5031_50311001_54_dialog_content = "우와! 엄청난 반응 속도네!",
  ui_story_5031_50311001_55_dialog_content = "루미나로 앞쪽 파도를 얼려버렸잖아?",
  ui_story_5031_50311001_56_dialog_content = "거리를 엄청나게 벌린 데다가 동작도 완벽하게 해냈어.",
  ui_story_5031_50311001_57_dialog_content = "대단해~ 대단해~ 보고 있으니까 정말 신나는걸!",
  ui_story_5031_50311001_58_dialog_content = "하압!",
  ui_story_5031_50311001_59_dialog_content = "캬악!",
  ui_story_5031_50311001_60_dialog_content = "응? 저 많은 암귀들을 다 얼려버린 거야?!",
  ui_story_5031_50311001_61_dialog_content = "우와!",
  ui_story_5031_50311001_62_dialog_content = "저 사람, 아까 란카를 구해 준 아가씨 맞지?",
  ui_story_5031_50311001_63_dialog_content = "엄청 강하네! 동작도 우아하고 아름다워! 암귀도 혼자 학살하는 수준이잖아!",
  ui_story_5031_50311001_64_dialog_content = "그리고 해수면을 정확하게 얼리면서 자신만의 커브를 만들어내고 있어! 대단해!",
  ui_story_5031_50311001_65_dialog_content = "헤에~ 저 언니, 카렌이라고 했지?",
  ui_story_5031_50311001_66_dialog_content = "기억났어. 그 공주님이잖아!",
  ui_story_5031_50311001_67_dialog_content = "멋있어! 대단해!",
  ui_story_5031_50311001_68_dialog_content = "왠지 피가 끓는 느낌이야! 사블리도 힘내야겠어!",
  ui_story_5031_50311001_69_dialog_content = "휴...",
  ui_story_5031_50311001_70_dialog_content = "이걸로 62마리인가.",
  ui_story_5031_50311001_71_dialog_content = "방금 그로누가 70마리를 잡았고... 시엘은... 93마리를 잡았어.",
  ui_story_5031_50311001_72_dialog_content = "쳇, 이런 쪽으로는 확실히 강화복이 유리해.",
  ui_story_5031_50311001_73_dialog_content = "바이스가 69마리를 잡으니까...",
  ui_story_5031_50311001_74_dialog_content = "남은 격차는 32마리, 그리고 알 수 없는 동작 점수도 있어.",
  ui_story_5031_50311001_75_dialog_content = "서커스단 쪽은...",
  ui_story_5031_50311001_76_dialog_content = "하이~ 카렌 공주 언니, 여기서 쉬고 있는 거야?",
  ui_story_5031_50311001_77_dialog_content = "사블리?",
  ui_story_5031_50311001_78_dialog_content = "카렌 공주 언니가 사블리의 이름을 기억해 주다니! 정말 기뻐!",
  ui_story_5031_50311001_79_dialog_content = "카렌이라고 부르면 돼.",
  ui_story_5031_50311001_80_dialog_content = "좋아, 카렌 언니~",
  ui_story_5031_50311001_81_dialog_content = "사블리는 카렌 언니가 정말 정말 좋지만,\n그래도 안 좋은 소식을 하나 전해줘야 할 것 같아.",
  ui_story_5031_50311001_82_dialog_content = "뭐지?",
  ui_story_5031_50311001_83_dialog_content = "우리 전략은 레인보우 언니랑 멜트 언니가 선두에 나서서 먼저 득점하는 거야.",
  ui_story_5031_50311001_84_dialog_content = "그리고 팜므랑 사블리는...",
  ui_story_5031_50311001_85_dialog_content = "나머지 선수들을 방해하기로 했거든~",
  ui_story_5031_50311001_86_dialog_content = "으윽!",
  ui_story_5031_50311001_87_dialog_content = "어쩐지 바이스도 계속 팜므한테 방해받은 이유가 있었어!",
  ui_story_5031_50311001_88_dialog_content = "맞아. 카렌 언니, 그렇다고 사블리 미워하면 안 돼. 사블리도 어쩔 수 없는걸~",
  ui_story_5031_50311001_89_dialog_content = "쳇, 저 비천한 평민이 감히 카렌 전하를 공격하다니!",
  ui_story_5031_50311001_90_dialog_content = "뢰베, 카렌 전하를 도와서 저 평민을 물에 빠트리도록 해.",
  ui_story_5031_50311001_91_dialog_content = "......",
  ui_story_5031_50311001_92_dialog_content = "정말 민첩하네. 역시 서커스단 출신이야.",
  ui_story_5031_50311001_93_dialog_content = "(이렇게 좁은 서프보드 위에서 싸우는 건 나한테 불리해...)",
  ui_story_5031_50311001_94_dialog_content = "우와! 역시 카렌 언니야!",
  ui_story_5031_50311001_95_dialog_content = "사블리의 공격을 막으면서 중심을 잡은 거야?",
  ui_story_5031_50311001_96_dialog_content = "정말 너무 우아하잖아! 사블리는 언니가 너무 마음에 들어!",
  ui_story_5031_50311001_97_dialog_content = "(음... 그렇다고 진짜로 다치게 만들 순 없어.)",
  ui_story_5031_50311001_98_dialog_content = "(우선 거리부터 벌리자.)",
  ui_story_5031_50311001_99_dialog_content = "아, 카렌 언니, 어딜 가려고?",
  ui_story_5031_50311001_100_dialog_content = "사블리랑 안 놀아 줄 거야? 아직 부족하단 말이야.",
  ui_story_5031_50311001_101_dialog_content = "...지금이다!",
  ui_story_5031_50311001_102_dialog_content = "피어나라── 빙화여!",
  ui_story_5031_50311001_103_dialog_content = "<color=#e8d9bb>콰드득──</color>",
  ui_story_5031_50311001_104_dialog_content = "으앗!",
  ui_story_5031_50311001_105_dialog_content = "미안, 우선 여기 얌전히 있어 줘.",
  ui_story_5031_50311001_106_dialog_content = "으... 어라?",
  ui_story_5031_50311001_107_dialog_content = "까, 깜짝이야. 끝장나는 줄 알았네.",
  ui_story_5031_50311001_108_dialog_content = "그냥 사블리의 몸을 여기 얼려둔 거였구나.",
  ui_story_5031_50311001_109_dialog_content = "으음~ 몸을 완벽하게 묶어 두면서 사블리를 다치게 하지도 않고...\n게다가 머리도 남겨놨어...",
  ui_story_5031_50311001_110_dialog_content = "엄청난 힘이네! 게다가 이 제어력... 카렌 언니가 더 좋아졌어!",
  ui_story_5031_50311001_111_dialog_content = "...뭔가 이상한 아이네.",
  ui_story_5031_50311001_112_dialog_content = "뭐, 이제 위협도 사라졌으니 열심히 점수만 높이면 되겠지.",
  ui_story_5031_50311001_113_dialog_content = "시간을 너무 낭비해 버렸어... 모두의 희망을 위해 더 빨리 움직여야 해.",
  ui_story_5031_50311002_1_dialog_content = "다들 모여주세요!",
  ui_story_5031_50311002_2_dialog_content = "방금 전의 서핑 대회는 즐거웠나요?",
  ui_story_5031_50311002_3_dialog_content = "네──!",
  ui_story_5031_50311002_4_dialog_content = "후후, 레인보우도 신나게 놀았답니다!",
  ui_story_5031_50311002_5_dialog_content = "다들 고생하셨어요. 자신이나 서로에게 모두 잊을 수 없는 체험이었을 거예요.",
  ui_story_5031_50311002_6_dialog_content = "그럼 이제 성적을 발표할 시간이네요!",
  ui_story_5031_50311002_7_dialog_content = "꿀꺽──",
  ui_story_5031_50311002_8_dialog_content = "피아, 침 삼키는 소리가 너무 커.",
  ui_story_5031_50311002_9_dialog_content = "하, 하나도 긴장 안 했거든.",
  ui_story_5031_50311002_10_dialog_content = "걱정 마. 방금 카렌이 그렇게 멋지게 해냈으니까 분명히 문제없을 거야!",
  ui_story_5031_50311002_11_dialog_content = "아냐. 내 점수는 그로누와 시엘의 암귀 처치 점수까지만 따라잡았을 뿐이야.",
  ui_story_5031_50311002_12_dialog_content = "동작 점수는 결과를 봐야 해.",
  ui_story_5031_50311002_13_dialog_content = "게다가 레인보우 쪽이랑도... 어쩌면 여전히 격차가 조금 있을지도 몰라.",
  ui_story_5031_50311002_14_dialog_content = "자, 그럼 괜히 시간 끌진 않을게요~",
  ui_story_5031_50311002_15_dialog_content = "서핑 대회 1위는 바로!",
  ui_story_5031_50311002_16_dialog_content = "짜자잔! 바로 저희 「에메랄드 팀」이랍니다!",
  ui_story_5031_50311002_17_dialog_content = "자세한 점수는 게시판에 붙여둘 테니까 이의가 있다면 한번 확인해 보세요.",
  ui_story_5031_50311002_18_dialog_content = "현장 관객들의 평가를 반영한 데이터니까 조작 가능성은 전혀 없답니다!",
  ui_story_5031_50311002_19_dialog_content = "우와!",
  ui_story_5031_50311002_20_dialog_content = "레인보우! 역시 최고야!",
  ui_story_5031_50311002_21_dialog_content = "저희 「에메랄드 팀」을 사랑해 주셔서 정말 감사해요~",
  ui_story_5031_50311002_22_dialog_content = "그리고 영주님의 오백만 나이티움도 감사드려요~",
  ui_story_5031_50311002_23_dialog_content = "하하하하!",
  ui_story_5031_50311002_24_dialog_content = "아, 너무 아까워!",
  ui_story_5031_50311002_25_dialog_content = "나이티움... 오백만 나이티움이...",
  ui_story_5031_50311002_26_dialog_content = "흐앙... 피아의 수영복이!",
  ui_story_5031_50311002_27_dialog_content = "괜찮아. 「에메랄드 팀」은 카니발 대회에 참가한 팀은 아니니까,\n「구름고래」는 아직 가망이 있어.",
  ui_story_5031_50311002_28_dialog_content = "수영복은 상금이 없어도 충분히 살 수 있잖아.",
  ui_story_5031_50311002_29_dialog_content = "진짜? PlayerName, 진짜로 피아한테 수영복 사 줄 거야?",
  ui_story_5031_50311002_30_dialog_content = "물론이지. 네가 얌전히 말 잘 듣고, 화나게 하거나 말썽을 피우지만 않는다면.",
  ui_story_5031_50311002_31_dialog_content = "우와, 피아에 대한 고정관념을 버려 줘! 피아는 아주 숙녀다운 사람이란 말이야.",
  ui_story_5031_50311002_32_dialog_content = "못하겠다는 거야? 그럼 관두자.",
  ui_story_5031_50311002_33_dialog_content = "아아앗! 이미 말해놓고 취소하는 게 어딨어!",
  ui_story_5031_50311002_34_dialog_content = "......",
  ui_story_5031_50311002_35_dialog_content = "다음 발표는 2위를 차지한 팀이랍니다.",
  ui_story_5031_50311002_36_dialog_content = "쉿! 2위를 발표한대!",
  ui_story_5031_50311002_37_dialog_content = "2위를 차지한 팀은 바로!",
  ui_story_5031_50311002_38_dialog_content = "일루미나에서 온 그로누와 시엘!",
  ui_story_5031_50311002_39_dialog_content = "오오──!",
  ui_story_5031_50311002_40_dialog_content = "뭐?!",
  ui_story_5031_50311002_41_dialog_content = "<size=45>응?!</size>",
  ui_story_5031_50311002_42_dialog_content = "<size=55>으엑?!</size>",
  ui_story_5031_50311002_43_dialog_content = "그로누 선배랑 시엘이라고?",
  ui_story_5031_50311002_44_dialog_content = "그, 그럼... 우린...",
  ui_story_5031_50311002_45_dialog_content = "상품을 못 받게 되는 거잖아?",
  ui_story_5031_50311002_46_dialog_content = "그, 그그그럼 「구름고래」를 다른 사람한테 뺏기는 거잖아!",
  ui_story_5031_50311002_47_dialog_content = "망했어! 사부한테 엄청나게 혼날 거야!",
  ui_story_5031_50311002_48_dialog_content = "......",
  ui_story_5031_50311002_49_dialog_content = "앗, 카렌, 어디 가?",
  ui_story_5031_50311002_50_dialog_content = "카렌!",
  ui_story_5031_50311002_51_dialog_content = "카렌, 잠깐만. 어디 가는 거야?",
  ui_story_5031_50311002_52_dialog_content = "카...",
  ui_story_5031_50311002_53_dialog_content = "미안, PlayerName. 잠깐 혼자 있고 싶어.",
  ui_story_5031_50311002_54_dialog_content = "아, 알았어...",
  ui_story_5031_50311002_55_dialog_content = "근데 우린 네가 걱정돼서 그래. 혹시 괜찮으면...",
  ui_story_5031_50311002_56_dialog_content = "적어도 왜 그러는지는 말해 주면 안 될까?",
  ui_story_5031_50311002_56X1_dialog_content = "맞아. 혹시 우리 때문에 기분이 상한 거야?",
  ui_story_5031_50311002_56X2_dialog_content = "아, 아니야. 너희와는 상관없는 일이야.",
  ui_story_5031_50311002_57_dialog_content = "...그저... 내가 너무 무력한 것 같았거든.",
  ui_story_5031_50311002_58_dialog_content = "최선을 다했지만, 친구를 위해 승리를 차지하지 못했어.\n필요한 걸 얻을 수 있게 도와주지 못했잖아.",
  ui_story_5031_50311002_59_dialog_content = "하지만 그건 카렌 네 잘못이 아니야.",
  ui_story_5031_50311002_60_dialog_content = "제대로 따진다면 나야말로 사과해야 하는 사람인걸...",
  ui_story_5031_50311002_61_dialog_content = "모두가 그렇게 열심히 점수를 따려고 노력할 때,\n난 서핑 하나 못 배워서 전부 망쳐버렸어.",
  ui_story_5031_50311002_62_dialog_content = "그건 달라...",
  ui_story_5031_50311002_63_dialog_content = "뭐가 다른데? 같은 거잖아!",
  ui_story_5031_50311002_64_dialog_content = "네가 그렇게 노력하고 우릴 생각해 줘서 정말 고마워.\n하지만 내 잘못은 내 잘못이지, 네가 자책할 일이 아니야.",
  ui_story_5031_50311002_65_dialog_content = "이런 단체 협력 시합은 애초에 한 사람만 탓할 수 없어.",
  ui_story_5031_50311002_66_dialog_content = "나야말로 너한테 사과하고, 고마워해야 돼.",
  ui_story_5031_50311002_67_dialog_content = "카렌 네가 없었다면 여기까지 오지도 못했을 테니까.",
  ui_story_5031_50311002_68_dialog_content = "......",
  ui_story_5031_50311002_69_dialog_content = "마찬가지로 바이스가 없었다면 우리가 지금처럼 해올 수 있었을까?",
  ui_story_5031_50311002_70_dialog_content = "...아니.",
  ui_story_5031_50311002_71_dialog_content = "그렇지? 우리한테는 카렌도 마찬가지인 거야.",
  ui_story_5031_50311002_72_dialog_content = "1등을 하려고 했던 건 그 무슨 고래 때문이니까, 이제 다른 방법을 생각해보자.",
  ui_story_5031_50311002_73_dialog_content = "1등을 못 했다고 하늘이 무너지는 것도 아니잖아.",
  ui_story_5031_50311002_74_dialog_content = "도저히 안 되면 제노 씨나 그로누 선배, 아니면 레인보우 씨한테 물어보는 방법도 있어.",
  ui_story_5031_50311002_75_dialog_content = "구름고래에 대한 사정을 잘 얘기하면 다른 사람들도 분명히 우릴 도와줄 거야.",
  ui_story_5031_50311002_75X1_dialog_content = "바이스 말이 맞아. 전부 별문제 아니잖아. 어떻게든 해결할 방법이 있을 거라고.",
  ui_story_5031_50311002_76_dialog_content = "그러니까 카렌, 그렇게 속상해하지 마. 알았지?",
  ui_story_5031_50311002_77_dialog_content = "같이 방법을 생각해보자.",
  ui_story_5031_50311002_78_dialog_content = "......",
  ui_story_5031_50311002_79_dialog_content = "그래.",
  ui_story_5031_50311002_80_dialog_content = "너희 말이 맞아. 고마워.",
  ui_story_5031_50311002_81_dialog_content = "확실히 난 너희한테 많이 배워야 해.\n어쩌면 그게 아버님의 목적일지도 모르니까...",
  ui_story_5031_50311002_82_dialog_content = "아버님? 갑자기 솔라드 씨는 왜?",
  ui_story_5031_50311002_83_dialog_content = "사실 이번에 여기 오기 전에 아버님과... 토론을 했었어.",
  ui_story_5031_50311002_83X1_dialog_content = "토론?",
  ui_story_5031_50311002_83X2_dialog_content = "맞아. 아버님은 내가 너희와 함께 여행하는 것에 대한 의미를 생각해보길 원하셨어.",
  ui_story_5031_50311002_83X3_dialog_content = "그리고 왠지 이제 그 의미를 이해하게 된 것 같아.\n너희에겐 배워야 할 점들이 많아.",
  ui_story_5031_50311002_83X4_dialog_content = "어쩐지 너 오늘 계속 왠지 자기만의 세계에 빠져 있는 것 같았어.",
  ui_story_5031_50311002_83X5_dialog_content = "하지만 아무리 생각을 거듭해도, 아직 어렴풋하게 느껴지는 것들이 너무 많아.",
  ui_story_5031_50311002_83X6_dialog_content = "예를 들면 바이스 네가 얘기했던 각성에 대한 것도 그래.\n사실 오늘 한번 시도해 봤어.",
  ui_story_5031_50311002_83X7_dialog_content = "응? 각성을 시도해 봤다고?",
  ui_story_5031_50311002_83X8_dialog_content = "맞아. 네가 얘기해 준 방법대로 의식을 가라앉혔어.",
  ui_story_5031_50311002_83X9_dialog_content = "하지만 아버님과의 대화가 떠오르면서 어떻게 해도 집중할 수가 없었어.",
  ui_story_5031_50311002_83X10_dialog_content = "결국 실패했지.",
  ui_story_5031_50311002_83X11_dialog_content = "그랬구나... 하지만 그건 흔히 있는 일이야.",
  ui_story_5031_50311002_83X12_dialog_content = "잡념을 떨쳐내고 고도의 집중력을 발휘하는 건 원래부터 어려운 일이잖아.",
  ui_story_5031_50311002_83X13_dialog_content = "난 그때 내 마음속의 한 줄기 빛이 모든 집착을 몰아내 줬었어.",
  ui_story_5031_50311002_83X14_dialog_content = "빛? 그때도 말했던 것 같아. 그게 대체 뭐야?",
  ui_story_5031_50311002_83X15_dialog_content = "음... 그러니까 PlayerName, 그리고 너랑 겪었던 즐거운 일들을 생각하니까...",
  ui_story_5031_50311002_83X16_dialog_content = "나도 모르게 마음이 평화로워졌어.",
  ui_story_5031_50311002_83X17_dialog_content = "하지만 좀 오묘한 일이라서 설명하기가 어려워.",
  ui_story_5031_50311002_83X18_dialog_content = "그렇구나. 그럼 난...",
  ui_story_5031_50311002_84_dialog_content = "PlayerName! 카렌 언니! 바이스 언니!",
  ui_story_5031_50311002_85_dialog_content = "왜 피아만 놔두고 여기까지 온 거야? 한참 찾았잖아!",
  ui_story_5031_50311002_85X1_dialog_content = "아, 이런. 방금 너무 급해서 피아만 두고 와버렸네!",
  ui_story_5031_50311002_86_dialog_content = "응? 피아, 왜 그래? 뭘 그렇게 허둥대고 있어?",
  ui_story_5031_50311002_87_dialog_content = "너랑 언니들 찾으러 왔지!",
  ui_story_5031_50311002_88_dialog_content = "내 말 좀 들어봐... 방금 제노 아저씨가 그랬는데...",
  ui_story_5031_50311002_89_dialog_content = "서핑 대회는 출전 순서를 정하기 위한 거였고, 다음 시합이 있대!",
  ui_story_5031_50311002_90_dialog_content = "다음 시합은 단원이 돼서 서커스 공연에 참가하는 거야!",
  ui_story_5031_50311002_91_dialog_content = "아직 기회가 있어!",
  ui_story_5031_50311101_1_dialog_content = "그럼 지금 상황은...",
  ui_story_5031_50311101_2_dialog_content = "흑흑... <size=45>흐아앙!</size>",
  ui_story_5031_50311101_3_dialog_content = "<size=45>우리의... 위대한 목표가...</size>",
  ui_story_5031_50311101_4_dialog_content = "구름고래... 이대로면 구름고래 못 찾아... <size=45>흐아아아앙!</size>",
  ui_story_5031_50311101_5_dialog_content = "(휴... 곧 가장 중요한 마지막 무대에서 결전이 펼쳐질 텐데...)",
  ui_story_5031_50311101_6_dialog_content = "(환상동물들이 피아랑 사이가 틀어져서 말을 듣지를 않잖아...)",
  ui_story_5031_50311101_7_dialog_content = "(이대로라면 탈락할 거야. 우선 피아부터 달래고 최선을 다해 노력해 봐야겠어!)",
  ui_story_5031_50311101_8_option_content = "피아, 벌써부터 실망할 거 없어!",
  ui_story_5031_50311101_9_dialog_content = "훌쩍... 호, 혹시 PlayerName 너 무슨 방법이라도 있어?",
  ui_story_5031_50311101_10_dialog_content = "사실 나도 딱히 좋은 생각은 없어.\n하지만 리허설 시간이 이제 한 시간밖에 안 남았어.",
  ui_story_5031_50311101_11_dialog_content = "한 시간 뒤면 배 위의 관객들이 공연을 보러 올 거야.",
  ui_story_5031_50311101_12_dialog_content = "그럼 망한 거 아냐?! 흐아아앙!",
  ui_story_5031_50311101_13_dialog_content = "자, 잠깐만. 일단 울지 말아 봐!",
  ui_story_5031_50311101_14_dialog_content = "예전 기억을 떠올려 봐. 우린 아스트라 대륙을 떠돌면서...\n오직 환상동물을 지키기 위해 수많은 어려움을 이겨냈잖아.",
  ui_story_5031_50311101_15_dialog_content = "그렇게 위대한 업적도 이룬 우리가 겨우 이 정도 작은 어려움에 쓰러질 순 없잖아?",
  ui_story_5031_50311101_16_dialog_content = "피아가 조금만 더 노력해서 비카랑 사이가 좋아진다면...\n분명히 멋진 공연을 해낼 수 있을 거야!",
  ui_story_5031_50311101_17_dialog_content = "하이?",
  ui_story_5031_50311101_18_dialog_content = "피...피아는 이미 지쳤어.",
  ui_story_5031_50311101_19_dialog_content = "솔직히 마지막 상품이 구름고래인지도 아직 확실하지 않잖아.\n그런데도 일단 시합부터 참가해 버렸으니까...",
  ui_story_5031_50311101_20_dialog_content = "(그걸 이제야 알았어?!)",
  ui_story_5031_50311101_21_dialog_content = "야! 너 그 표정... 지금 속으로 피아 흉보고 있는 거지?!",
  ui_story_5031_50311101_22_dialog_content = "아, 아니야! 내가 그럴 리가 없잖아!",
  ui_story_5031_50311101_23_dialog_content = "아니면 이렇게 하자. 우리 둘이 화장실에 가는 척하고,\n최종 상품이 구름고래가 맞는지 슬쩍 확인하고 오는 거야.",
  ui_story_5031_50311101_24_dialog_content = "만약 진짜로 구름고래라면, 너도 정신 차리고 비카랑 리허설 계속할 수 있겠지?",
  ui_story_5031_50311101_25_dialog_content = "그, 그래도 되나?",
  ui_story_5031_50311101_26_dialog_content = "근데 그 제노라는 아저씨 엄청 무서워 보이던데...\n그러다가 그 사람을 화나게 만들면 큰일이잖아...",
  ui_story_5031_50311101_27_dialog_content = "그냥 잠깐 보는 것뿐이니까 괜찮지 않을까?",
  ui_story_5031_50311101_28_dialog_content = "나도 감응 능력으로 도와줄게. 아무도 우릴 발견할 수 없을 거야.",
  ui_story_5031_50311101_29_dialog_content = "으...응! 그것도 그렇네!",
  ui_story_5031_50311101_30_dialog_content = "그럼 부탁할게. 피아의 환상동물 파트너...\n「초희귀종」 아이테르 PlayerName!",
  ui_story_5031_50311101_31_dialog_content = "몇 번이나 말했잖아. 난 환상동물이 아니라니까!",
  ui_story_5031_50311101_32_dialog_content = "휴, 됐어. 이제 시간이 없으니까 얼른 갔다가 돌아오자.",
  ui_story_5031_50311101_33_dialog_content = "<color=#e8d9bb>함선 내부</color>",
  ui_story_5031_50311101_34_dialog_content = "여기가 그 무서운 단장이 못 들어가게 하던 곳이야.",
  ui_story_5031_50311101_35_dialog_content = "엄청 크네. 복도가 전부 다 엄청나게 길어. 게다가 갈림길도 엄청 많고...",
  ui_story_5031_50311101_36_dialog_content = "구름고래는 대체 어디에 숨겨 둔 걸까?",
  ui_story_5031_50311101_37_dialog_content = "잠깐만, 피아.",
  ui_story_5031_50311101_38_dialog_content = "우선 여기 숨자. 누군가 오는 게 느껴져.",
  ui_story_5031_50311101_39_dialog_content = "후아── 벌써 세 바퀴째 순찰 중이잖아.",
  ui_story_5031_50311101_40_dialog_content = "정말, 단장은 무슨 생각인지 모르겠다니까.\n개미 한 마리 안 보이는 곳에서 순찰을 하라니...",
  ui_story_5031_50311101_41_dialog_content = "서커스단에 왜 순찰하는 경비가 있는 건데?\n설마 그 단장한테 정말 숨겨야 할 비밀이라도 있는 걸까?",
  ui_story_5031_50311101_42_dialog_content = "PlayerName 너 아니었으면 피아는 진작 잡혀서 쫓겨났을 거야.",
  ui_story_5031_50311101_43_dialog_content = "전부 PlayerName 덕분이야.\n구름고래를 찾으면 꼭 PlayerName한테 제대로 보답할게.",
  ui_story_5031_50311101_44_dialog_content = "동물 쿠키 한 봉지 어때? 키아로가 엄청 좋아하는 쿠키야. 좋지?",
  ui_story_5031_50311101_45_dialog_content = "그런 건 나중에 생각해. 우선 최종 상품부터 찾은 뒤에 다시 얘기하자.",
  ui_story_5031_50311101_46_dialog_content = "으음...",
  ui_story_5031_50311101_47_dialog_content = "잠깐만. 다시 멈춰. 앞에 두 명이 있어...\n근데 제자리에 가만히 있는 것 같아.",
  ui_story_5031_50311101_48_dialog_content = "그럼 슬쩍 지나가자. 분명히 안 들킬 거야.",
  ui_story_5031_50311101_49_dialog_content = "잠깐만!",
  ui_story_5031_50311101_50_dialog_content = "또 왜 그래?",
  ui_story_5031_50311101_51_dialog_content = "앞에 있는 두 사람... 뭔가 익숙해.",
  ui_story_5031_50311101_52_dialog_content = "엘비스 영주님이랑 파토?!",
  ui_story_5031_50311101_53_dialog_content = "그 영주님이랑 호위병 아저씨? 왜 여기 있는 건데?",
  ui_story_5031_50311101_54_dialog_content = "그걸 내가 어떻게 알아!\n일단 두 사람은 신경 쓰지 말고 우리 목표에 집중하자.",
  ui_story_5031_50311101_55_dialog_content = "쉿. 절대 들키면 안 돼.",
  ui_story_5031_50311101_56_dialog_content = "죄송합니다. 제노의 방과 수상한 곳을 전부 수색해 봤지만,\n열쇠로 보이는 물건은 찾지 못했습니다.",
  ui_story_5031_50311101_57_dialog_content = "괜찮습니다. 제가 찾았으니까요.",
  ui_story_5031_50311101_58_dialog_content = "제노는 열쇠를 항상 몸에 지니고 다니는 것 같더군요.",
  ui_story_5031_50311101_59_dialog_content = "그럼 골치가 아프겠는데요...",
  ui_story_5031_50311101_60_dialog_content = "괜찮습니다. 계획대로 진행하죠. 오늘 밤엔 반드시 성공해야 합니다.",
  ui_story_5031_50311101_61_dialog_content = "계획? PlayerName, 저 두 사람... 무슨 계획 같은 걸 얘기하는 것 같...우우웁──!",
  ui_story_5031_50311101_62_option_content = "조용히 해!",
  ui_story_5031_50311101_63_dialog_content = "방금 무슨 소리 못 들었습니까?",
  ui_story_5031_50311101_64_dialog_content = "누구냐! 나와라!",
  ui_story_5031_50311101_65_dialog_content = "(이런, 도망치자!)",
  ui_story_5031_50311101_66_dialog_content = "후우... 후우... 단숨에 갑판까지 올라와 버렸네.",
  ui_story_5031_50311101_67_dialog_content = "푸하──! PlayerName 너무 난폭하잖아! 숨 막혀 죽을 뻔했다구!",
  ui_story_5031_50311101_68_dialog_content = "미안, 미안. 방금은 너무 급해서...",
  ui_story_5031_50311101_69_dialog_content = "이쪽으로 도망친 것 같습니다!",
  ui_story_5031_50311101_70_dialog_content = "콜록... 어서 쫓아갑시다.",
  ui_story_5031_50311101_71_dialog_content = "이런, 계속 쫓아오고 있잖아. 일단 숨어야겠어!",
  ui_story_5031_50311101_72_dialog_content = "이게 누구야, PlayerName! 꼬마 피아도 있네?",
  ui_story_5031_50311101_73_dialog_content = "피아는 꼬마가 아니야!",
  ui_story_5031_50311101_74_dialog_content = "리허설은 다 끝낸 거야?",
  ui_story_5031_50311101_75_dialog_content = "응? 아...아직. 미안, 지금은 일이 좀 있어서 먼저...",
  ui_story_5031_50311101_76_dialog_content = "후후, 난 이미 필살기를 준비해 뒀다구!",
  ui_story_5031_50311101_77_dialog_content = "왕좌의 도움이 있다면 이번 승리자는 반드시 내가 될 거야.",
  ui_story_5031_50311101_78_dialog_content = "지금 좀 보여줄까? 어때? 패배자~",
  ui_story_5031_50311101_79_dialog_content = "(이런, 그로누한테 잡혀버렸잖아... 근처에 숨을 만한 곳 없나?)",
  ui_story_5031_50311101_80_dialog_content = "PlayerName, 그 사람들이 쫓아왔어!",
  ui_story_5031_50311101_81_dialog_content = "얼른 네 무적의 감응 능력으로 방법 좀 생각해 봐!",
  ui_story_5031_50311101_82_dialog_content = "감응 능력을 써도 방법이 떠오르진 않는다고!",
  ui_story_5031_50311101_83_dialog_content = "무적──!",
  ui_story_5031_50311101_84_dialog_content = "벽해──!",
  ui_story_5031_50311101_85_dialog_content = "<size=45>왕좌──!</size>",
  ui_story_5031_50311101_86_dialog_content = "뭐야?! 이 엄청난 빛은?",
  ui_story_5031_50311101_87_dialog_content = "윽, 저 빛은 대체?!",
  ui_story_5031_50311101_88_dialog_content = "어때? 대단하지?",
  ui_story_5031_50311101_89_dialog_content = "내가 왕좌에 새로 추가한 조명 기능이야!",
  ui_story_5031_50311101_90_dialog_content = "이것만 있으면 빛 하나 없는 바다에서도 마음껏 서핑할 수 있어!",
  ui_story_5031_50311101_91_dialog_content = "어, 음, 그... 대단하네.",
  ui_story_5031_50311101_92_dialog_content = "저것 좀 봐!",
  ui_story_5031_50311101_93_dialog_content = "사람들이 몰려오고 있는데?!",
  ui_story_5031_50311101_94_dialog_content = "방금 그거 정말 대단하네요! 한 번만 더 보여줄 수 있나요?!",
  ui_story_5031_50311101_95_dialog_content = "한 번 더 해달라고? 좋지!",
  ui_story_5031_50311101_96_dialog_content = "이런, 사람들이 너무 많습니다.\n아무래도 훔쳐 듣던 녀석들은 이미 도망친 것 같군요.",
  ui_story_5031_50311101_97_dialog_content = "괜찮습니다. 그저 엿들은 것 가지고는 계획에 아무런 영향도 없을 겁니다.",
  ui_story_5031_50311101_98_dialog_content = "갑시다. 모든 건 계획대로 진행합니다.",
  ui_story_5031_50311101_99_dialog_content = "네, 알겠습니다.",
  ui_story_5031_50311101_100_dialog_content = "그 사람들, 우릴 못 찾고 간 것 같아.",
  ui_story_5031_50311101_101_dialog_content = "다행이야... 그로누, 고마워!",
  ui_story_5031_50311101_102_dialog_content = "으응? 내가 뭘 했는데? 무슨 소리를 하는 거야?",
  ui_story_5031_50311101_103_dialog_content = "일이 마무리되면 제대로 얘기해줄게.",
  ui_story_5031_50311101_104_dialog_content = "지금은 해야 할 일이 있어서... 먼저 갈게!",
  ui_story_5031_50311101_105_dialog_content = "뭘 저렇게 급하게 하는 거야?",
  ui_story_5031_50311101_106_dialog_content = "근데 아깐 엄청 긴장한 것 같았는데, 지금은 편해 보이네.",
  ui_story_5031_50311101_107_dialog_content = "아마 내 멋진 공연에 푹 빠진 거겠지? 헤헤!",
  ui_story_5031_50311101_108_dialog_content = "한참 돌아다녔는데 결국 최종 상품이 뭔지 확인도 못 하고 시간만 날렸잖아.",
  ui_story_5031_50311101_109_dialog_content = "어쩔 수 없지. 배 안쪽이 너무 큰 데다가 경비도 잔뜩 있었으니까.",
  ui_story_5031_50311101_110_dialog_content = "우리 둘만으로는 그렇게 짧은 시간 내에 전부 살펴볼 수가 없었어.",
  ui_story_5031_50311101_111_dialog_content = "아무래도 그냥 열심히 기술을 연습해서 1위를 차지하는 수밖에 없겠네.",
  ui_story_5031_50311101_112_dialog_content = "하지만... 이미 시간이 없는데...",
  ui_story_5031_50311101_113_dialog_content = "구름고래... 훌쩍... 불쌍한 구름고래... 설마 벌써...",
  ui_story_5031_50311101_114_dialog_content = "왜 또 우는 거야?!",
  ui_story_5031_50311101_115_dialog_content = "PlayerName, 피아? 아직 연습 중이야?",
  ui_story_5031_50311101_116_dialog_content = "너 설마 또 피아에게 무슨 심한 말이라도 해서 울린 건 아니지?",
  ui_story_5031_50311101_117_option_content = "그런 거 아니거든!",
  ui_story_5031_50311101_118_option_content = "나 때문이 아니야!",
  ui_story_5031_50311101_119_dialog_content = "리허설하는 동안 비카가 자꾸 훈련을 거부했거든.\n피아가 그것 때문에 속상해서 그래.",
  ui_story_5031_50311101_120_dialog_content = "하이하이~",
  ui_story_5031_50311101_121_dialog_content = "훌쩍... 너 진짜... 지금 너 칭찬하는 거 아니거든!",
  ui_story_5031_50311101_122_dialog_content = "하이?",
  ui_story_5031_50311101_123_dialog_content = "이상하네. 분명히 전에는 비카랑 사이가 좋았었잖아.",
  ui_story_5031_50311101_124_dialog_content = "어째서 갑자기 거부하는 건데?",
  ui_story_5031_50311101_125_dialog_content = "설마 비카랑 제대로 얘기 안 해 본 거야?",
  ui_story_5031_50311101_126_dialog_content = "피아는 분명히... 분명히 비카 군한테 제대로 설명했는데... 쟤가 안 듣는 걸 어떻게 해!",
  ui_story_5031_50311101_127_dialog_content = "피아, 비카한테 뭐라고 했어?",
  ui_story_5031_50311101_128_dialog_content = "시합에서 상품을 꼭 받고 싶으니까 피아를 도와달라고 했어.",
  ui_story_5031_50311101_129_dialog_content = "그래서 비카는 뭐라는데?",
  ui_story_5031_50311101_130_dialog_content = "아무 말도 안 했던 것 같아...",
  ui_story_5031_50311101_131_dialog_content = "그럼 애초에 동의하지 않았다는 거잖아?",
  ui_story_5031_50311101_132_dialog_content = "하지만... 나랑 임시 파트너가 되기로 약속했단 말이야...\n동의하지 않을 리가 없잖아?",
  ui_story_5031_50311101_133_dialog_content = "흐아아앙!",
  ui_story_5031_50311101_134_dialog_content = "휴, 그러니까 일단 그만 울어.\n이 일을 해결하려면 중요한 건 너 자신이야.",
  ui_story_5031_50311101_135_dialog_content = "피아가?",
  ui_story_5031_50311101_136_dialog_content = "비카가 네 임시 파트너긴 하지만, 파트너가 널 받아준다고 해서\n네가 윗사람처럼 명령을 내려도 된다는 뜻은 아냐.",
  ui_story_5031_50311101_137_dialog_content = "지금 이런 상황은 결국 네가 비카와 제대로 소통하지 않았기 때문이야.",
  ui_story_5031_50311101_138_dialog_content = "히잉... 그럼 피아는 어떻게 해야 돼?",
  ui_story_5031_50311101_139_dialog_content = "우선 비카한테 진심으로 사과하는 건 어떨까?",
  ui_story_5031_50311101_140_dialog_content = "사과뿐만이 아니라, 비카에게 도와달라고 진심으로 부탁해야 해.\n그리고 동의를 얻어야지.",
  ui_story_5031_50311101_141_dialog_content = "비카 군이 날 도와줄까?",
  ui_story_5031_50311101_142_dialog_content = "야생 비카보다 훨씬 사나워 보여...",
  ui_story_5031_50311101_143_dialog_content = "그건 네 성의를 봐야겠지.",
  ui_story_5031_50311101_144_dialog_content = "그래도 피아라면 분명히 할 수 있을 거야.",
  ui_story_5031_50311101_145_dialog_content = "맞아. 포기하지 말고 힘내!",
  ui_story_5031_50311101_146_dialog_content = "조, 좋아. 해볼게.",
  ui_story_5031_50311101_147_dialog_content = "비카 군, 미...",
  ui_story_5031_50311101_148_dialog_content = "미안해.",
  ui_story_5031_50311101_149_dialog_content = "하이하이?",
  ui_story_5031_50311101_150_dialog_content = "(비카가 발을 귓가에 갖다 댔어. 피아 목소리가 너무 작다는 뜻인가?)",
  ui_story_5031_50311101_151_dialog_content = "미...",
  ui_story_5031_50311101_152_dialog_content = "<size=45>미안하다고!</size>",
  ui_story_5031_50311101_153_dialog_content = "내가 잘못했어... 멋대로 너한테 내 공연을 도와달라고 강요하면 안 되는데...",
  ui_story_5031_50311101_154_dialog_content = "내가 미안해. 다음엔... 아니... 다음은 없어!",
  ui_story_5031_50311101_155_dialog_content = "앞으로 네 의견도 잘 들을게. 훌쩍...",
  ui_story_5031_50311101_156_dialog_content = "하이?",
  ui_story_5031_50311101_157_dialog_content = "그리고? 그, 그리고... 맛있는 것도 잔뜩 사 줄게!",
  ui_story_5031_50311101_158_dialog_content = "하이~ 하이하이?",
  ui_story_5031_50311101_159_dialog_content = "응?! 전설 속 펭 아저씨가 기르는 포도를 먹고 싶다고?",
  ui_story_5031_50311101_160_dialog_content = "다른 비카가 말해줬다고?!",
  ui_story_5031_50311101_161_dialog_content = "근데 그거 엄청 비싼데...",
  ui_story_5031_50311101_162_dialog_content = "하이하이?",
  ui_story_5031_50311101_163_dialog_content = "아, 아니야! 불평한 거 아니야!",
  ui_story_5031_50311101_164_dialog_content = "날 용서해 준다면 전부 사 줄게! 히잉...",
  ui_story_5031_50311101_165_dialog_content = "(피아 녀석, 정말 난처해하는 표정이네.)",
  ui_story_5031_50311101_166_dialog_content = "(그래도 이번 기회에 피아도 타인과 더 잘 소통하는 방법을 배웠을 거야.)",
  ui_story_5031_50311101_167_dialog_content = "하이~",
  ui_story_5031_50311101_168_dialog_content = "(비카는 왠지 즐거워 보이네. 피아의 사과를 받아들인 걸까?)",
  ui_story_5031_50311101_169_dialog_content = "피아를 용서해 준다고? 다행이야!",
  ui_story_5031_50311101_170_dialog_content = "그럼 이따가 공연은...",
  ui_story_5031_50311101_171_dialog_content = "하이하이~",
  ui_story_5031_50311101_172_dialog_content = "뭐?",
  ui_story_5031_50311101_173_dialog_content = "피아, 비카가 뭐라는데?",
  ui_story_5031_50311101_174_dialog_content = "그게... 「피아가 하는 거에 달렸다」고 했어.",
  ui_story_5031_50311101_175_dialog_content = "반응이 그렇게 미적지근하다고?!",
  ui_story_5031_50311101_176_dialog_content = "정말 괜찮을까? 다시 부탁해야 하는 거 아니야?",
  ui_story_5031_50311101_177_dialog_content = "이번 공연은 최종 결전이 달린 중대한 문제라고...",
  ui_story_5031_50311101_178_dialog_content = "으, 난...",
  ui_story_5031_50311101_179_dialog_content = "결승전이 곧 시작될 예정입니다. 참가자 여러분, 시간이 되었습니다.",
  ui_story_5031_50311101_180_dialog_content = "벌써?!",
  ui_story_5031_50311101_181_dialog_content = "벌써 한 시간이 지난 건가... 어쩔 수 없네...",
  ui_story_5031_50311101_182_dialog_content = "눈 딱 감고 올라가자!",
  ui_story_5031_50311101_183_dialog_content = "나한테 맡겨!",
  ui_story_5031_50311101_184_dialog_content = "우리가 점수를 최대한 많이 벌어올 테니까.",
  ui_story_5031_50311101_185_dialog_content = "그럼 피아랑 비카 군도 힘낼게!",
  ui_story_5031_50311101_186_dialog_content = "하이하이!",
  ui_story_5031_50311201_1_dialog_content = "밤의 장막과 함께, 이번 대회의 세 번째 시합이 정식으로 시작됩니다~",
  ui_story_5031_50311201_2_dialog_content = "와아아!",
  ui_story_5031_50311201_3_dialog_content = "직전 시합의 성적에 따라, 두 팀이 이 무대에서 순위를 겨루게 될 거예요.",
  ui_story_5031_50311201_4_dialog_content = "먼저, 현재 1위를 차지하고 있는 일루미나 팀!",
  ui_story_5031_50311201_5_dialog_content = "그리고 신입 조련사 피아가 이끄는 피아 팀!",
  ui_story_5031_50311201_6_dialog_content = "오오오오!",
  ui_story_5031_50311201_7_dialog_content = "분위기가 정말 뜨겁네요! 아주 좋아요!",
  ui_story_5031_50311201_8_dialog_content = "그럼 시합이 정식으로 시작되기 전에,\n제노 단장님과 세 자매가 선사하는 오프닝 무대부터 감상해 주세요!",
  ui_story_5031_50311201_9_dialog_content = "먼저, 제노 단장님을 모시겠습니다!",
  ui_story_5031_50311201_10_dialog_content = "「예지 의식」은 예로부터 무수한 오로리안들이 추구했던 능력입니다.",
  ui_story_5031_50311201_11_dialog_content = "초월적인 존재와의 소통을 통해, 과거 그리고 미래의 많은 것들을 해독할 수 있었고...",
  ui_story_5031_50311201_12_dialog_content = "더 나아가 역사의 진실을 밝히고 미래를 예언할 수도 있었습니다.",
  ui_story_5031_50311201_13_dialog_content = "오늘 밤, 제가 이곳에서 그 고대의 능력을 선보여,\n자리에 계신 여러분의 의문을 풀어드리고자 합니다.",
  ui_story_5031_50311201_14_dialog_content = "그리고 제가 사용할 것은 여기 있는 기원의 카드입니다.",
  ui_story_5031_50311201_15_dialog_content = "오! 왔다, 왔어! 전설의 「예지 의식」!",
  ui_story_5031_50311201_16_dialog_content = "암귀를 소환하고 예지까지 할 수 있다니...\n기원의 힘이란 건 대체 어떤 비밀이 있는 거지?",
  ui_story_5031_50311201_17_dialog_content = "자, 그럼 지금부터 제 공연을 도와주실 행운의 관객 한 분을 모시도록 하겠습니다.",
  ui_story_5031_50311201_18_dialog_content = "과연 어떤 분의 운명의 실이 저와 교차할까요?",
  ui_story_5031_50311201_19_dialog_content = "저요!",
  ui_story_5031_50311201_20_dialog_content = "저요, 저요!",
  ui_story_5031_50311201_21_dialog_content = "느껴집니다... 느껴지는군요...",
  ui_story_5031_50311201_22_dialog_content = "기원의 카드가 제 운명을 당신에게 이끌고 있습니다──",
  ui_story_5031_50311201_23_dialog_content = "거기 첫 번째 줄 가장 오른쪽에 계신 부인.",
  ui_story_5031_50311201_24_dialog_content = "저, 저 말인가요?",
  ui_story_5031_50311201_25_dialog_content = "맞습니다. 올라오시죠.",
  ui_story_5031_50311201_26_dialog_content = "아무 질문이나 하셔도 됩니다.\n그럼 제가 이 기원의 카드를 통해 답을 드리겠습니다.",
  ui_story_5031_50311201_27_dialog_content = "아무거나 다 괜찮나요?",
  ui_story_5031_50311201_28_dialog_content = "물론입니다.",
  ui_story_5031_50311201_29_dialog_content = "그럼... 제가 어디서 왔는지 알고 있나요?",
  ui_story_5031_50311201_30_dialog_content = "기원의 카드여. 나의 두 눈이 되어 내게 진실을 보여다오.\n이 부인의 고향은 어디인가.",
  ui_story_5031_50311201_31_dialog_content = "(카드가 제노의 손가락 사이를 날아다니고 있어... 카드 한 장을 뽑았어!)",
  ui_story_5031_50311201_32_dialog_content = "기원의 카드가 답을 알려줬습니다. 페테르부르크에서 오셨군요.",
  ui_story_5031_50311201_33_dialog_content = "어떻게 안 거죠?!",
  ui_story_5031_50311201_34_dialog_content = "기원의 카드가 알려준 것입니다.\n그뿐만 아니라 당신에 대한 다른 사실도 알려주었지요.",
  ui_story_5031_50311201_35_dialog_content = "당신은 한 자작 가문의 사람이고, 행복한 가정을 이루고 계시는군요.",
  ui_story_5031_50311201_36_dialog_content = "이유는 알 수 없지만, 방금 당신은 남편분과 따로 떨어져 앉아 계셨습니다.\n하지만 두 분의 관계는 물론 변함없이 좋습니다.",
  ui_story_5031_50311201_37_dialog_content = "정말 대단하네요... 그런 것까지 알아내다니...",
  ui_story_5031_50311201_38_dialog_content = "티켓 경쟁이 너무 치열해서 붙어있는 자리를 못 구했거든요.\n그래서 따로 떨어져서 앉을 수밖에 없었네요.",
  ui_story_5031_50311201_39_dialog_content = "게다가 남편분께서는 앞자리를 당신에게 양보했겠지요.",
  ui_story_5031_50311201_40_dialog_content = "마, 맞아요...",
  ui_story_5031_50311201_41_dialog_content = "기원의 카드가 두 분의 앞날을 축복했습니다.\n자, 이제 자리로 돌아가셔도 됩니다.",
  ui_story_5031_50311201_42_dialog_content = "오오! 대단해!",
  ui_story_5031_50311201_43_dialog_content = "한 명 더 해 주세요!",
  ui_story_5031_50311201_44_dialog_content = "시간은 소중한 법이랍니다. 기원의 카드라도 시간의 규칙은 따라야만 합니다.",
  ui_story_5031_50311201_45_dialog_content = "부디 다음 공연을 계속 즐겨 주십시오.\n여러분과 운명이 교차하는 다음 순간을 기대하고 있겠습니다.",
  ui_story_5031_50311201_46_dialog_content = "제노 단장님의 정말 멋진 공연이었습니다!",
  ui_story_5031_50311201_47_dialog_content = "다음으로 멜트, 사블리와 팜므가 선사하는 짜릿한 공중 곡예 공연을 감상해 보세요!",
  ui_story_5031_50311201_48_dialog_content = "저기... 이제 올라가야 해요!",
  ui_story_5031_50311201_49_dialog_content = "그럼 입을 못 다물 정도로 깜짝 놀라게 해 주자고!",
  ui_story_5031_50311201_50_dialog_content = "좋아──",
  ui_story_5031_50311201_51_dialog_content = "가요!",
  ui_story_5031_50311201_52_dialog_content = "(멜트가 사다리에 올라갔네... 나머지 두 사람을 향해 손을 뻗고 있어.)",
  ui_story_5031_50311201_53_dialog_content = "에잇──!",
  ui_story_5031_50311201_54_dialog_content = "팜므, 잘 받아줘!",
  ui_story_5031_50311201_55_dialog_content = "사브 언니... 너무 무거워...",
  ui_story_5031_50311201_56_dialog_content = "(위험해! ...다행이야. 팜므가 사블리를 잘 잡았어!)",
  ui_story_5031_50311201_57_dialog_content = "오, 올라가요!",
  ui_story_5031_50311201_58_dialog_content = "(응?! 설마...)",
  ui_story_5031_50311201_59_dialog_content = "이얏!",
  ui_story_5031_50311201_60_dialog_content = "내가 잡을게!",
  ui_story_5031_50311201_61_dialog_content = "더... 무거워졌어!",
  ui_story_5031_50311201_62_dialog_content = "해냈어요!",
  ui_story_5031_50311201_63_option_content = "대단해!",
  ui_story_5031_50311201_64_dialog_content = "오오오! 정말 대단해!",
  ui_story_5031_50311201_65_dialog_content = "가, 감사합니다!",
  ui_story_5031_50311201_66_dialog_content = "우리의 화려한 모습은 잘 기억했겠지?",
  ui_story_5031_50311201_67_dialog_content = "기억했어요!",
  ui_story_5031_50311201_68_dialog_content = "그냥 평범한 공연인데 뭐...",
  ui_story_5031_50311201_69_dialog_content = "아무튼 여러분의 환호는 잘 받았어!",
  ui_story_5031_50311201_70_dialog_content = "그럼 이제 다음 시합을 기대해 줘!",
  ui_story_5031_50311201_71_dialog_content = "세 분의 멋진 공연 감사드려요!",
  ui_story_5031_50311201_72_dialog_content = "자, 이제 마지막 시합이 정식으로 시작되었습니다!",
  ui_story_5031_50311201_73_dialog_content = "1위를 차지하고 있는 일루미나 팀의 시엘과 그로누가\n저마다 자신들의 놀라운 기술을 뽐낸다고 하네요!",
  ui_story_5031_50311201_74_dialog_content = "그로누 선배님의 의견에 따라 강화복을 개조해 봤어요.\n바로 이 순간을 위해서요...",
  ui_story_5031_50311201_75_dialog_content = "「스틱스」, 꼭 성공해 줘. 부탁이야!",
  ui_story_5031_50311201_76_dialog_content = "오! 시엘이 뭔가 엄청난 걸 준비한 것 같아!",
  ui_story_5031_50311201_77_dialog_content = "......",
  ui_story_5031_50311201_78_dialog_content = "응? 피아? 괜찮아? 왜 떨고 있어?",
  ui_story_5031_50311201_79_dialog_content = "긴장돼...",
  ui_story_5031_50311201_80_dialog_content = "긴장하는 거야?",
  ui_story_5031_50311201_81_dialog_content = "그, 그런 적 없거든!",
  ui_story_5031_50311201_82_dialog_content = "난 환상동물 마스터야. 난... 윽!",
  ui_story_5031_50311201_83_dialog_content = "긴장해서 혓바닥까지 깨문 거야...?",
  ui_story_5031_50311201_84_dialog_content = "피아는 긴장한 적 없어!",
  ui_story_5031_50311201_85_dialog_content = "피아, 우선 다른 건 생각하지 말고 깊게 숨을 들이쉬어 봐.",
  ui_story_5031_50311201_86_dialog_content = "후──",
  ui_story_5031_50311201_87_dialog_content = "하──",
  ui_story_5031_50311201_88_dialog_content = "어때? 훨씬 좋아졌지?",
  ui_story_5031_50311201_89_dialog_content = "으... 역시 안 돼. 긴장해서 심장이 튀어나올 것 같아.",
  ui_story_5031_50311201_90_dialog_content = "시엘이랑 그로누는 엄청 강해 보이는데,\n난 아직 비카랑 손발도 제대로 안 맞잖아...",
  ui_story_5031_50311201_91_dialog_content = "아무리 봐도 이길 수 있을 것 같지가 않다구!",
  ui_story_5031_50311201_92_dialog_content = "일단 긴장하지 마. 어차피 이렇게 된 이상 후회해도 소용없어.",
  ui_story_5031_50311201_93_dialog_content = "정신 차리고 최선을 다해서 공연하자.",
  ui_story_5031_50311201_94_dialog_content = "근데... 만약에 비카가 또 말을 안 들어주면 어떡해?",
  ui_story_5031_50311201_95_dialog_content = "그건...",
  ui_story_5031_50311201_96_option_content = "너 그런 말 들어본 적 있어?",
  ui_story_5031_50311201_97_dialog_content = "무슨 말?",
  ui_story_5031_50311201_98_dialog_content = "「칭찬은 고래도 춤추게 한다!」",
  ui_story_5031_50311201_99_dialog_content = "뭐?!",
  ui_story_5031_50311201_100_dialog_content = "아무튼 대충 그런 뜻이야. 비카를 즐겁게 해 주고, 같이 잘 맞춰보자고 해 봐.",
  ui_story_5031_50311201_101_dialog_content = "상품만 손에 넣을 수 있다면 그 상이 구름고래든 아니든 좋으니까!",
  ui_story_5031_50311201_102_dialog_content = "그럼 나, 나도 최선을 다해볼게!",
  ui_story_5031_50311201_103_dialog_content = "파이팅! 나랑 바이스, 카렌도 최선을 다해 점수를 낼게!",
  ui_story_5031_50311201_104_dialog_content = "어차피 마지막은 총점에서 인원을 나눈 평균 점수로 계산하니까.",
  ui_story_5031_50311201_105_dialog_content = "모든 사람이 최선을 다해야만 승리할 확률도 높아질 거야!",
  ui_story_5031_50311201_106_dialog_content = "아, 알겠어...",
  ui_story_5031_50311201_107_dialog_content = "그로누와 시엘이 정말 멋진 공연을 펼치고 있습니다!",
  ui_story_5031_50311201_108_dialog_content = "시엘의 강화복과 그로누의 왕좌가 찬란한 빛 속에서 교차하며 춤을 추고 있네요.",
  ui_story_5031_50311201_109_dialog_content = "시엘의 강철 강화복은 마치 중력의 영향을 받지 않는 것처럼 보여요!\n고난이도의 기술로 전투하듯 춤추고 있군요.",
  ui_story_5031_50311201_110_dialog_content = "중량감과 아름다움이라는 모순된 요소가 완벽하게 결합된 공연이었습니다!",
  ui_story_5031_50311201_111_dialog_content = "그럼 다음은 피아 팀의 공연이 있겠습니다!",
  ui_story_5031_50311201_112_dialog_content = "과연 관객 여러분을 위해 어떤 멋진 공연을 준비했을까요?",
  ui_story_5031_50311201_113_dialog_content = "휴우... 가자, 비카 군!",
  ui_story_5031_50311201_114_dialog_content = "하이!",
  ui_story_5031_50311201_115_dialog_content = "(피아, 비카! 힘내!)",
  ui_story_5031_50311201_116_dialog_content = "(제발... 이번엔 아무 일도 없게 해 줘...)",
  ui_story_5031_50311201_117_dialog_content = "자, 가자. 비카 군, 이쪽으로 와.",
  ui_story_5031_50311201_118_dialog_content = "하이!",
  ui_story_5031_50311201_119_dialog_content = "내 말대로 하는 거야. 점프하는 동시에 텀블링이야. 알겠지?",
  ui_story_5031_50311201_120_dialog_content = "하이하이?",
  ui_story_5031_50311201_121_dialog_content = "(방금 비카가 피아를 보면서 뭔가 알 수 없는 미소를 지은 것 같은데?!)",
  ui_story_5031_50311201_122_dialog_content = "제...제발 내 말 좀 들어 줘!",
  ui_story_5031_50311201_123_dialog_content = "하이?",
  ui_story_5031_50311201_124_dialog_content = "(비카가 모르는 척하고 있잖아?!)",
  ui_story_5031_50311201_125_dialog_content = "뭐야? 대체 어떻게 된 거야!",
  ui_story_5031_50311201_126_dialog_content = "지금 시간 낭비하는 거나 보려고 산 표가 아니라고!",
  ui_story_5031_50311201_127_dialog_content = "으윽...",
  ui_story_5031_50311201_128_dialog_content = "부, 부탁이야!",
  ui_story_5031_50311201_129_dialog_content = "하이~?",
  ui_story_5031_50311201_129X1_dialog_content = "비카 군은 최고야! 이 정도는 너한테는 아주 쉬운 일이잖아!",
  ui_story_5031_50311201_130_dialog_content = "시합이 끝나면 펭 아저씨가 심었다는 그 포도를 사 줄게!",
  ui_story_5031_50311201_131_dialog_content = "하이하이!",
  ui_story_5031_50311201_132_dialog_content = "성공인가?!",
  ui_story_5031_50311201_133_dialog_content = "하이~",
  ui_story_5031_50311201_134_dialog_content = "오오! 한 번 더!",
  ui_story_5031_50311201_135_dialog_content = "이번엔 내가 이 공을 던질 거야. 잘 받아 줘!",
  ui_story_5031_50311201_136_dialog_content = "하이! 하이!",
  ui_story_5031_50311201_137_dialog_content = "하이~",
  ui_story_5031_50311201_138_dialog_content = "대단해!",
  ui_story_5031_50311201_139_dialog_content = "(다행이네... 비카 군이 포도를 봐서라도 내 말을 들어주나 봐!)",
  ui_story_5031_50311201_140_dialog_content = "하이?",
  ui_story_5031_50311201_141_dialog_content = "잠깐만! 그건 먹으라고 준 게 아니야!",
  ui_story_5031_50311201_142_dialog_content = "하하하!",
  ui_story_5031_50311201_143_dialog_content = "(휴, 공연 사고라도 날 줄 알았는데, 관객들이 저걸 공연의 일부인 줄 안 것 같네.)",
  ui_story_5031_50311201_144_dialog_content = "그럼 마지막으로 모두한테 네 필살기를 보여줘!",
  ui_story_5031_50311201_145_dialog_content = "필살기?! 그런 건 말한 적 없었잖아?",
  ui_story_5031_50311201_146_dialog_content = "설마 피아... 저번에 사냥꾼들 상대할 때처럼 비카한테 바위라도 삼키게 할 건가?!",
  ui_story_5031_50311201_147_dialog_content = "그건 너무 위험하잖아!",
  ui_story_5031_50311201_148_dialog_content = "피아는 그런 위험한 짓 안 해!",
  ui_story_5031_50311201_149_dialog_content = "이번엔 이런 걸 준비했어!",
  ui_story_5031_50311201_150_dialog_content = "짜잔──!",
  ui_story_5031_50311201_151_dialog_content = "거품?!",
  ui_story_5031_50311201_152_dialog_content = "오, 예쁜 공기 방울이네.",
  ui_story_5031_50311201_153_dialog_content = "근데 이게 조련이랑 무슨 상관이지?",
  ui_story_5031_50311201_154_dialog_content = "다음은 비카 군의 공연이 있겠습니다!",
  ui_story_5031_50311201_155_dialog_content = "하이하이!",
  ui_story_5031_50311201_156_dialog_content = "하이──!",
  ui_story_5031_50311201_157_dialog_content = "(그래! 거품은 전부 비카가 좋아하는 동그란 모양이잖아!)",
  ui_story_5031_50311201_158_dialog_content = "오! 저 녀석한테 저런 능력이 있었어?",
  ui_story_5031_50311201_159_dialog_content = "하이!",
  ui_story_5031_50311201_160_dialog_content = "하이... 하이...",
  ui_story_5031_50311201_161_dialog_content = "꺼억──!",
  ui_story_5031_50311201_162_dialog_content = "(비카가 거품을 너무 많이 먹어서 몸이 부풀었어!)",
  ui_story_5031_50311201_163_dialog_content = "하하하하하! 귀여워!",
  ui_story_5031_50311201_164_dialog_content = "피아의 공연은 여기까지예요!",
  ui_story_5031_50311201_165_dialog_content = "피아의 팀원들이 준비한 멋진 공연도 많이 많이 기대해 주세요!",
  ui_story_5031_50311201_166_dialog_content = "오오!",
  ui_story_5031_50311201_167_dialog_content = "(피아가 공연을 마친 뒤, 나와 바이스, 카렌도 순서대로 무대에 올랐다.)",
  ui_story_5031_50311201_168_dialog_content = "(나는 감응 능력으로 독심술을 했고...)",
  ui_story_5031_50311201_169_dialog_content = "(바이스는 뛰어난 궁술로 사격 묘기를 선보였다.)",
  ui_story_5031_50311201_170_dialog_content = "(하지만 다음엔 내 머리 위에 사과를 놓고 과녁으로 삼지 않았으면 좋겠다...)",
  ui_story_5031_50311201_171_dialog_content = "(가장 대단했던 건 역시 카렌이었다. 카렌의 발레는 모든 사람을 깜짝 놀라게 만들었다.)",
  ui_story_5031_50311201_172_dialog_content = "(게다가... 제노에게 암귀를 무대에 소환해 달라고 해서 공연의 도구로 삼았다!)",
  ui_story_5031_50311202_1_dialog_content = "피어나라, 빙화여!",
  ui_story_5031_50311202_2_dialog_content = "(발레와 전투를 결합하는 건 아마 카렌만 할 수 있는 공연일 것 같다.)",
  ui_story_5031_50311202_3_dialog_content = "정말... 대단해!",
  ui_story_5031_50311202_4_dialog_content = "카렌 선수의 멋진 발레 공연이었습니다~ 정말 놀랍고 멋진 공연이었네요!",
  ui_story_5031_50311202_5_dialog_content = "이제부터는 모두가 기대하던 시간이겠네요.",
  ui_story_5031_50311202_6_dialog_content = "드디어... 최종 성적을 발표할 시간이야!",
  ui_story_5031_50311202_7_dialog_content = "하이!",
  ui_story_5031_50311202_8_dialog_content = "벌써... 긴장해서... 숨도 잘 안 쉬어져...",
  ui_story_5031_50311202_9_dialog_content = "피아, 조금만 더 버텨!",
  ui_story_5031_50311202_10_dialog_content = "네가 찾던 구름고래를 생각해 봐!",
  ui_story_5031_50311202_11_dialog_content = "구름고래... 맞아! 구름고래! 내 상품!",
  ui_story_5031_50311202_12_dialog_content = "다음으로 시합의 최종 승리자를 발표하겠습니다. 최종 승리자는 바로──",
  ui_story_5031_50311202_13_dialog_content = "피아 팀입니다!",
  ui_story_5031_50311202_14_dialog_content = "피아가... 우승했다고...?",
  ui_story_5031_50311202_15_dialog_content = "예이! 피아가 이겼어!",
  ui_story_5031_50311202_16_dialog_content = "하이!",
  ui_story_5031_50311202_17_dialog_content = "피아의 조련술은 그리 완벽하진 않았지만,\n피아팀이 승리한 이유는 팀원 간의 협력 덕분이었습니다.",
  ui_story_5031_50311202_18_dialog_content = "카렌 양의 발레 공연은 정말 훌륭했습니다.",
  ui_story_5031_50311202_19_dialog_content = "따라서 피아 팀의 평균 성적이 더 높았기 때문에 1위를 차지했습니다!",
  ui_story_5031_50311202_20_dialog_content = "피아, 축하해.",
  ui_story_5031_50311202_21_dialog_content = "쪼끄만 녀석이 꽤 대단하잖아!",
  ui_story_5031_50311202_22_dialog_content = "이번엔 졌지만, 다음엔 절대 안 져!",
  ui_story_5031_50311202_23_dialog_content = "축하해, 피아! 조련사 공연도 잘 마치고 우승까지 했네!",
  ui_story_5031_50311202_24_dialog_content = "하지만 역시 신경 쓰여. 대체 최종 상품이 뭐지?",
  ui_story_5031_50311202_25_dialog_content = "피아가 계속 찾던 그 구름고래가 맞을까?",
  ui_story_5031_50311202_26_dialog_content = "맞아! 내 상품! 바다에서 건졌다는 엄청난 보물!",
  ui_story_5031_50311202_27_dialog_content = "그렇습니다. 이미 당신의 보상을 가지고 왔습니다.",
  ui_story_5031_50311202_28_dialog_content = "바로 여기 있습니다.",
  ui_story_5031_50311202_29_dialog_content = "루! 루우우!",
  ui_story_5031_50311202_30_dialog_content = "우와?! 이, 이, 이건 키아로잖아?!",
  ui_story_5031_50311202_31_dialog_content = "내가 구름고래에 대한 단서를 찾으라고 보냈었잖아!",
  ui_story_5031_50311202_32_dialog_content = "왜 연락 안 하나 했더니, 여기서 게으름 피우고 있었어?!",
  ui_story_5031_50311202_33_dialog_content = "이건 제가 얼마 전 바다에서 건져낸 동물입니다.",
  ui_story_5031_50311202_34_dialog_content = "매우 맛있어 보여서 탕으로 끓여 우승자에게 주려고 했었지요.",
  ui_story_5031_50311202_35_dialog_content = "루우우?! 루!",
  ui_story_5031_50311202_36_dialog_content = "키아로를 먹으면 안 돼!",
  ui_story_5031_50311202_37_dialog_content = "내 친구란 말이야!",
  ui_story_5031_50311202_38_dialog_content = "당신의 친구라고요? 전 엄청나게 맛있는 식재료인 줄 알았는데 말입니다.",
  ui_story_5031_50311202_39_dialog_content = "우승자는 당신이니 이 녀석은 당신의 상품입니다. 원하는 대로 하시지요.",
  ui_story_5031_50311202_40_dialog_content = "루우...",
  ui_story_5031_50311202_41_dialog_content = "휴, 조심 좀 하지 그랬어. 너 죽을 뻔한 거 알아 몰라?",
  ui_story_5031_50311202_42_dialog_content = "루...루우!",
  ui_story_5031_50311202_43_dialog_content = "바닷속에서 구름고래를 찾다가 갑자기 그물에 걸려버렸다고?",
  ui_story_5031_50311202_44_dialog_content = "게다가 배에 며칠 동안 갇혀 있었어?",
  ui_story_5031_50311202_45_dialog_content = "그럼 배에서 혹시 구름고래 못 봤어?!",
  ui_story_5031_50311202_46_dialog_content = "루? 루우!",
  ui_story_5031_50311202_47_dialog_content = "뭐야... 못 봤구나.",
  ui_story_5031_50311202_48_dialog_content = "성적도 발표했고 수상식도 마쳤으니, 다들 갑판으로 이동하시죠.",
  ui_story_5031_50311202_49_dialog_content = "축하 파티와 불꽃놀이가 곧 시작될 예정입니다.",
  ui_story_5031_50311202_50_dialog_content = "불꽃놀이도 있다고? 그럼 얼른 가서 좋은 자리부터 잡자!",
  ui_story_5031_50311202_51_dialog_content = "구름고래가 아니라니... 상품이 어째서 구름고래가 아닌 건데!",
  ui_story_5031_50311202_52_dialog_content = "결국 다 헛수고한 게 되잖아!",
  ui_story_5031_50311202_53_dialog_content = "고래일 리가 있겠습니까?",
  ui_story_5031_50311202_54_dialog_content = "아무리 어린 고래라 해도 에메랄드호에는 실을 수 없습니다.",
  ui_story_5031_50311202_55_dialog_content = "꼬마 숙녀분께서는 진짜 고래의 모습을 본 적이 없으신 겁니까?",
  ui_story_5031_50311202_56_dialog_content = "보, 본 적 없으면 뭐 어쩔 건데!",
  ui_story_5031_50311202_57_dialog_content = "그건 희귀종이니까 그렇게 아무 데서나 보일 리가 없잖아?",
  ui_story_5031_50311202_58_dialog_content = "풉...",
  ui_story_5031_50311202_59_dialog_content = "웃지 마!",
  ui_story_5031_50311202_60_dialog_content = "알겠어, 알겠어. 아무튼 헛수고는 아니었잖아.",
  ui_story_5031_50311202_61_option_content = "적어도 대회에선 우승했으니까.",
  ui_story_5031_50311202_62_dialog_content = "피아도 서커스단의 비카와 친구가 됐고 말이야.",
  ui_story_5031_50311202_63_dialog_content = "하이!",
  ui_story_5031_50311202_64_dialog_content = "아, 알겠어! 포도는 꼭 사 줄 테니까!",
  ui_story_5031_50311202_65_option_content = "적어도 키아로를 구해냈으니까.",
  ui_story_5031_50311202_66_dialog_content = "루우!",
  ui_story_5031_50311202_67_dialog_content = "휴... 근데 최종 상품이 키아로일 줄은 진짜로 몰랐어.",
  ui_story_5031_50311202_68_dialog_content = "그럼 너도 실수로 잡혀 온 거니까...\n다시 돌아가서 계속 구름고래를 찾아봐.",
  ui_story_5031_50311202_69_dialog_content = "루?",
  ui_story_5031_50311202_70_dialog_content = "여긴 네 도움이 없어도 괜찮으니까. 자, 얼른 돌아가!",
  ui_story_5031_50311202_71_dialog_content = "던진다!",
  ui_story_5031_50311202_72_dialog_content = "루──!",
  ui_story_5031_50311202_73_dialog_content = "(키아로는 하늘의 별이 되었다... 피아... 무서워!)",
  ui_story_5031_50311202_74_dialog_content = "휴... 당신 정말 환상동물 마스터가 맞습니까?",
  ui_story_5031_50311202_75_dialog_content = "진짜 맞다구!",
  ui_story_5031_50311202_76_dialog_content = "근데 제노 아저씨, 점술은 어떻게 한 거야?",
  ui_story_5031_50311202_77_dialog_content = "아저씨도 아이테르처럼 신비한 감응 능력이 있는 거야?",
  ui_story_5031_50311202_78_dialog_content = "사실 그건 진정한 점술이 아니었습니다.\n그저 대상을 관찰하고 결과를 도출했을 뿐이지요.",
  ui_story_5031_50311202_79_dialog_content = "예를 들어 아까 그 부인은 대중적인 옷을 입고 있었지만,\n그 옷은 사실 페테르부르크에서만 생산되는 옷감으로 만들어진 것이었죠.",
  ui_story_5031_50311202_80_dialog_content = "가정이 있고 없고는 손에 낀 반지만 봐도 알 수 있습니다.",
  ui_story_5031_50311202_81_dialog_content = "남편과 따로 앉아있다는 것은 그녀가 종종 고개를 돌려\n다른 사람과 눈을 맞췄기 때문에 알 수 있었지요.",
  ui_story_5031_50311202_82_dialog_content = "그래서 결론을 낼 수 있었...",
  ui_story_5031_50311202_83_dialog_content = "제노, 미안하지만 할 말이 좀 있어. 무대 쪽에서 둘이 잠깐 얘기할 수 있을까?",
  ui_story_5031_50311202_84_dialog_content = "알겠습니다.",
  ui_story_5031_50311202_85_dialog_content = "여러분, 죄송합니다. 먼저 실례하겠습니다.",
  ui_story_5031_50311202_86_dialog_content = "잠깐만! 말은 마저 해 주고 가야지!",
  ui_story_5031_50311202_87_dialog_content = "쳇... 혼자 중얼거리다가 가버렸잖아.",
  ui_story_5031_50311202_88_dialog_content = "불꽃놀이가 시작됐어!",
  ui_story_5031_50311202_89_dialog_content = "응, 정말 아름답네.",
  ui_story_5031_50311202_90_dialog_content = "너희도 여기 있었구나!",
  ui_story_5031_50311202_91_dialog_content = "다, 다들 여기 있었네...",
  ui_story_5031_50311202_92_dialog_content = "레인보우, 먹을 걸 왜 그렇게 잔뜩 챙겼어? 돌아가서 먹으려고?",
  ui_story_5031_50311202_93_dialog_content = "같이 불꽃놀이 안 볼 거야?",
  ui_story_5031_50311202_94_dialog_content = "우린 다른 할 일이 있어!",
  ui_story_5031_50311202_95_dialog_content = "불꽃놀이가 예쁘긴 하지만, 방금 나랑 시엘은\n강화복을 개조할 멋진 아이디어가 떠올랐거든!",
  ui_story_5031_50311202_96_dialog_content = "그래서 바로 돌아가서 시험해 볼 거야!",
  ui_story_5031_50311202_97_dialog_content = "맞아...",
  ui_story_5031_50311202_98_dialog_content = "미안, 그래서 같이 얘기는 못 나눌 것 같아.",
  ui_story_5031_50311202_99_dialog_content = "괜찮아, 괜찮아. 기회는 앞으로도 많으니까!",
  ui_story_5031_50311202_100_dialog_content = "그럼 먼저 갈게!",
  ui_story_5031_50311202_101_dialog_content = "저 둘은 사이가 참 좋아 보이네. 조금 부러운걸.",
  ui_story_5031_50311202_102_dialog_content = "카렌, 무슨 소리야?",
  ui_story_5031_50311202_103_dialog_content = "너한테는 PlayerName하고 나라는 좋은 친구가 둘이나 있잖아!",
  ui_story_5031_50311202_104_dialog_content = "맞아. 우린 항상 같이 여행하고 모험을 해왔잖아?",
  ui_story_5031_50311202_105_dialog_content = "그래, 이번에도 마찬가지고!",
  ui_story_5031_50311202_106_dialog_content = "만약 카렌 네가 발레로 그렇게 많은 점수를 따주지 않았으면 우린 분명히 졌을걸!",
  ui_story_5031_50311202_107_dialog_content = "맞아. 전부 네 덕분이야!",
  ui_story_5031_50311202_108_dialog_content = "그러니까 카렌 넌 우리한테 남이 아니야. 그렇게 생각하지 말아줘!",
  ui_story_5031_50311202_109_dialog_content = "그렇구나... 후훗, 알겠어.",
  ui_story_5031_50311202_110_dialog_content = "두 사람 다 고마워.",
  ui_story_5031_50311202_111_dialog_content = "응!",
  ui_story_5031_50311301_1_dialog_content = "낮엔 잘 몰랐는데, 지금 보니까 밤하늘과 불꽃놀이 아래의\n하버 시티는 정말 아름답네.",
  ui_story_5031_50311301_2_dialog_content = "그러게. 흰 건물이 불꽃으로 화려하게 빛나니까 낮보다 훨씬 멋져!",
  ui_story_5031_50311301_3_dialog_content = "PlayerName, 바이스, 피아...\n난 엘비스 영주한테 가서 이야기할 일이 좀 있어.",
  ui_story_5031_50311301_4_dialog_content = "다들 잠깐 기다려 줄래?",
  ui_story_5031_50311301_5_dialog_content = "응! 그럼 여기서 기다리고 있을게.",
  ui_story_5031_50311301_6_dialog_content = "알겠어, 고마워.",
  ui_story_5031_50311301_7_dialog_content = "이번 일은 이걸로 잘 마무리된 것 같네.",
  ui_story_5031_50311301_8_dialog_content = "근데 구름고래는 아직 못 찾았잖아...",
  ui_story_5031_50311301_9_dialog_content = "전설 속 구름고래는 대체 어디 있는 걸까...",
  ui_story_5031_50311301_10_dialog_content = "그렇게 조급해하지 마. 어떤 일은 무리한다고 해결되는 게 아니니까.",
  ui_story_5031_50311301_11_dialog_content = "맞아. 나도 가끔 자다가 깨서 머리핀이 안 보일 때가 있는데,\n급하게 찾을수록 안 보이거든.",
  ui_story_5031_50311301_12_dialog_content = "근데 마지막에 포기하려고 할 때마다 머리핀이 바로 옆에 있는 게 보이지 뭐야!",
  ui_story_5031_50311301_13_dialog_content = "진짜?",
  ui_story_5031_50311301_14_dialog_content = "당연하지.",
  ui_story_5031_50311301_15_dialog_content = "좋아. 그럼 한 번은 믿어줄게.",
  ui_story_5031_50311301_16_dialog_content = "다들...",
  ui_story_5031_50311301_17_dialog_content = "응? 카렌? 벌써 얘기가 끝났어?",
  ui_story_5031_50311301_18_dialog_content = "아니, 아무리 찾아도 엘비스 영주가 안 보여서.",
  ui_story_5031_50311301_19_dialog_content = "제노 아저씨랑 같이 무대 쪽으로 얘기하러 간 거 아니었어?",
  ui_story_5031_50311301_20_dialog_content = "무대 쪽도 가 봤지만 아무도 없었어.",
  ui_story_5031_50311301_21_dialog_content = "엘비스 영주님이랑 제노라면...",
  ui_story_5031_50311301_22_dialog_content = "설마 선실 쪽으로 간 건가?",
  ui_story_5031_50311301_23_dialog_content = "선실? 거긴 제노가 아무도 못 들어가게 한 곳 아니야?",
  ui_story_5031_50311301_24_dialog_content = "하지만 다른 곳에 안 보인다면 그곳일 확률이 높아.",
  ui_story_5031_50311301_25_dialog_content = "가서 한번 살펴보자. 아마 둘의 행방을 아는 사람이 있을 거야.",
  ui_story_5031_50311301_26_dialog_content = "PlayerName, 선실 쪽 길을 어떻게 이렇게 잘 알아?",
  ui_story_5031_50311301_27_dialog_content = "전에 피아랑 여기서 엘비스 영주님이랑 파토한테 쫓긴 적이 있거든...",
  ui_story_5031_50311301_28_dialog_content = "엘비스와 파토한테 쫓겨? 대체 어떻게 된 거야?",
  ui_story_5031_50311301_29_dialog_content = "말하자면 길어. 그러니까...",
  ui_story_5031_50311301_30_dialog_content = "PlayerName, 저기 좀 봐! 누가 쓰러져 있어!",
  ui_story_5031_50311301_31_dialog_content = "저건... 제노?!",
  ui_story_5031_50311301_32_dialog_content = "진짜? 진짜로 초상화 그려줄 거야?",
  ui_story_5031_50311301_33_dialog_content = "응... 근데 난 그림 그리는 속도가 엄청 느려... 그리고 잘 그리지도 못해.",
  ui_story_5031_50311301_34_dialog_content = "괜찮아. 제노가 그려준다면 분명히 최고로 멋질 거야!",
  ui_story_5031_50311301_35_dialog_content = "그럼 내일 아침에 항구의 부두에서 만나는 거지?",
  ui_story_5031_50311301_36_dialog_content = "나 바닷일이 끝나면 넌 그림을 그려 줘.\n그림 다 그리면 내가 해산물 수프 끓여 줄게!",
  ui_story_5031_50311301_37_dialog_content = "와! 엘비스 형의 해산물 수프!",
  ui_story_5031_50311301_38_dialog_content = "좋아, 좋아~ 그럼 약속이야!",
  ui_story_5031_50311301_39_dialog_content = "내일 봐!",
  ui_story_5031_50311301_40_dialog_content = "내, 내일 봐!",
  ui_story_5031_50311301_41_dialog_content = "......",
  ui_story_5031_50311301_42_dialog_content = "............",
  ui_story_5031_50311301_43_dialog_content = "약속했으면서.",
  ui_story_5031_50311301_44_dialog_content = "분명히... 약속했으면서...",
  ui_story_5031_50311301_45_dialog_content = "<size=33>제...</size>",
  ui_story_5031_50311301_46_dialog_content = "<size=33>제노──</size>",
  ui_story_5031_50311301_47_dialog_content = "으음? 누구...?",
  ui_story_5031_50311301_48_dialog_content = "제노!",
  ui_story_5031_50311301_49_dialog_content = "엘비스? 당신입니까? 돌아온 겁니까?",
  ui_story_5031_50311301_50_dialog_content = "<size=45>제노, 정신 차려!</size>",
  ui_story_5031_50311301_51_dialog_content = "엘비스!",
  ui_story_5031_50311301_52_dialog_content = "으악!",
  ui_story_5031_50311301_53_dialog_content = "우와앗!",
  ui_story_5031_50311301_54_dialog_content = "PlayerName, 왜 소리를 꽥 지르고 그래? 깜짝 놀랐잖아!",
  ui_story_5031_50311301_55_dialog_content = "미, 미안. 나도 깜짝 놀라서...",
  ui_story_5031_50311301_56_dialog_content = "제노 씨, 좀 어때요? 다친 데는 없나요?",
  ui_story_5031_50311301_57_dialog_content = "제가... 왜 여기 있는 겁니까?",
  ui_story_5031_50311301_58_dialog_content = "그건 우리가 물어봐야 되는 거 아냐?",
  ui_story_5031_50311301_59_dialog_content = "왜 구석에서 자고 있었던 거야? 한참 찾았잖아.",
  ui_story_5031_50311301_60_dialog_content = "그러니까 피아... 자고 있었던 게 아니라니까...",
  ui_story_5031_50311301_61_dialog_content = "설명해 줄게. 불꽃놀이와 축제가 끝나고 우린 엘비스한테\n인사한 뒤에 돌아가려고 했어.",
  ui_story_5031_50311301_62_dialog_content = "그런데 아무리 찾아도 보이지가 않았어.\n그래서 어쩌면 선실에 들어갔을지도 모른다고 생각했어.",
  ui_story_5031_50311301_63_dialog_content = "그래서 들어와 봤더니 당신이 바닥에 쓰러져 있었고.",
  ui_story_5031_50311301_64_dialog_content = "방금... 으윽.",
  ui_story_5031_50311301_65_dialog_content = "이곳이라면 방해하는 사람이 없겠군요.\n엘비스, 무슨 얘기가 하고 싶은 겁니까?",
  ui_story_5031_50311301_66_dialog_content = "난... 제노 너한테 고맙다는 인사를 하고 싶어.",
  ui_story_5031_50311301_67_dialog_content = "...갑자기요?",
  ui_story_5031_50311301_68_dialog_content = "제게 왜 고마운 거죠?",
  ui_story_5031_50311301_69_dialog_content = "내 초대를 받아줘서...\n하버 시티의 주민들에게 이토록 아름다운 기억을 남겨 줘서 고마워.",
  ui_story_5031_50311301_70_dialog_content = "네가 이곳에 온 건... 내게 정말 큰 의미가 있거든.",
  ui_story_5031_50311301_71_dialog_content = "신경 쓰지 마십시오. 제 서커스단은 사방을 떠돌아다니니,\n어디서 정박하고 공연하든 다를 게 없으니 말입니다.",
  ui_story_5031_50311301_72_dialog_content = "게다가 보급도 풍족하게 제공해 주셨으니, 오히려 이쪽에서 고마워해야겠지요.",
  ui_story_5031_50311301_73_dialog_content = "아니야, 제노.",
  ui_story_5031_50311301_74_dialog_content = "내가 너한테 빚진 건, 아마 어떻게 해도 갚을 수 없을 거야.",
  ui_story_5031_50311301_75_dialog_content = "제게 빚을 졌다고요? 그게 무슨...",
  ui_story_5031_50311301_76_dialog_content = "으윽?!",
  ui_story_5031_50311301_77_dialog_content = "미안해.",
  ui_story_5031_50311301_78_dialog_content = "콜록! 콜록, 콜록... 대...대체 이게...",
  ui_story_5031_50311301_79_dialog_content = "무슨...",
  ui_story_5031_50311301_80_dialog_content = "제노... 정말 미안해.",
  ui_story_5031_50311301_81_dialog_content = "그러니까 엘비스 영주가 뭔가를 사용해서 당신을 기절시켰다고?",
  ui_story_5031_50311301_82_dialog_content = "그렇습니다.",
  ui_story_5031_50311301_83_dialog_content = "뭐? 엘비스 영주님 나쁜 사람이야?",
  ui_story_5031_50311301_84_dialog_content = "피아, 아직 어떻게 된 일인지 모르니까 섣불리 결론을 내리면 안 돼.",
  ui_story_5031_50311301_85_dialog_content = "<size=33>이런... 정말 사라졌군요...</size>",
  ui_story_5031_50311301_86_dialog_content = "왜 그래? 제노, 뭘 찾는...",
  ui_story_5031_50311301_87_dialog_content = "으앗! 뭐야?",
  ui_story_5031_50311301_88_dialog_content = "선체가... 떨리고 있잖아?",
  ui_story_5031_50311301_89_dialog_content = "...정말 이렇게까지 할 줄이야.",
  ui_story_5031_50311301_90_dialog_content = "잠깐만! 제노!",
  ui_story_5031_50311301_91_dialog_content = "제...제노... 휴...",
  ui_story_5031_50311301_92_dialog_content = "일단 어떻게 된 건지부터 설명부터 해 주면 안 될까?",
  ui_story_5031_50311301_93_dialog_content = "......",
  ui_story_5031_50311301_94_dialog_content = "어쩔 수 없군요.",
  ui_story_5031_50311301_95_dialog_content = "만약 그가 정말 「그것」을 깨웠다면, 지금 확실히 여러분의 힘이 필요합니다.",
  ui_story_5031_50311301_96_dialog_content = "그거?",
  ui_story_5031_50311301_97_dialog_content = "방금 제가 깨어났을 때, 항상 가지고 다니던 코어 룸의 열쇠가\n사라진 것을 발견했습니다.",
  ui_story_5031_50311301_98_dialog_content = "그 코어 룸에 뭔가 중요한 물건이 있는 건가?",
  ui_story_5031_50311301_99_dialog_content = "「<color=#FFB400>에너지 코어</color>」가 있습니다.",
  ui_story_5031_50311301_100_dialog_content = "「에너지 코어」?!",
  ui_story_5031_50311301_101_dialog_content = "왜 다들 그게 뭔지 아는 것 같은 표정인데?",
  ui_story_5031_50311301_102_dialog_content = "「에너지 코어」는 구문명의 산물이야. 아주 귀한 자원이라고 이해하면 돼.",
  ui_story_5031_50311301_103_dialog_content = "이 배에도 그런 게 있을 줄은...",
  ui_story_5031_50311301_104_dialog_content = "이 배 자체가 유적이니까요.",
  ui_story_5031_50311301_105_dialog_content = "방금 얘기한 「그것」은 「에너지 코어」를 수호하는 구문명의 병기──",
  ui_story_5031_50311301_106_dialog_content = "「<color=#FFB400>코어 가디언</color>」입니다.",
  ui_story_5031_50311301_107_dialog_content = "「코어 가디언」이 깨어난 이상,\n「에너지 코어」에 접근하는 모든 생명체를 무차별적으로 공격합니다.",
  ui_story_5031_50311301_108_dialog_content = "그렇게 된다면 배 전체가 위험해질 겁니다.",
  ui_story_5031_50311301_109_dialog_content = "그러니까 엘비스 영주가 당신이 기절한 틈에 열쇠를 빼앗아 갔다는 말인가?",
  ui_story_5031_50311301_110_dialog_content = "그리고 코어 룸에 들어가서 그 「에너지 코어」를 빼앗으려고 한다고?",
  ui_story_5031_50311301_111_dialog_content = "아마 그럴 겁니다. 하지만...",
  ui_story_5031_50311301_112_dialog_content = "단장!",
  ui_story_5031_50311301_113_dialog_content = "아! 레인보우 언니, 시엘 언니!",
  ui_story_5031_50311301_114_dialog_content = "큰일이에요, 단장. 방금 시엘이랑 기관실에서 코어 룸의 문이 열린 걸 발견했어요!",
  ui_story_5031_50311301_115_dialog_content = "알고 있습니다. 그래서 지금 가고 있는 겁니다.",
  ui_story_5031_50311301_116_dialog_content = "그리고 오는 길에 우리가 함선 순찰을 위해 고용한\n용병들이 쓰러져 있는 것도 봤어...",
  ui_story_5031_50311301_117_dialog_content = "레인보우! 조심해!",
  ui_story_5031_50311301_118_dialog_content = "으앗! 위험했어... 고마워, 시엘.",
  ui_story_5031_50311301_119_dialog_content = "어라? 이건... 하버 시티의 경비병?",
  ui_story_5031_50311301_120_dialog_content = "우릴 막기 위해 방어선을 구축한 건가.",
  ui_story_5031_50311301_121_dialog_content = "......",
  ui_story_5031_50311301_122_dialog_content = "우매한 시종들이여. 길을 비켜라!",
  ui_story_5031_50311302_1_dialog_content = "엘비스, 이 자식...",
  ui_story_5031_50311302_2_dialog_content = "이 자들은 대체 언제 선실에 들어온 겁니까?",
  ui_story_5031_50311302_3_dialog_content = "또 다른 루미나가 다가오고 있어!",
  ui_story_5031_50311302_4_dialog_content = "...지금보다 훨씬 더 많은 수야.",
  ui_story_5031_50311302_5_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5031_50311302_6_dialog_content = "으앗! 우리 배가!",
  ui_story_5031_50311302_7_dialog_content = "엘비스 이 망할 녀석이 우리 배에다 뭔 짓을 하는 거야?!",
  ui_story_5031_50311302_8_dialog_content = "이대로 가다간 여기서 발이 묶이고 말 거야.",
  ui_story_5031_50311302_9_dialog_content = "다들 곤란해하고 있어...",
  ui_story_5031_50311302_10_dialog_content = "그렇다면...!",
  ui_story_5031_50311302_11_dialog_content = "「손 강화복 상태 조정, Type-Ⅲ」.",
  ui_story_5031_50311302_12_dialog_content = "「다리 강화복 상태 조정, Type-Ⅲ」.",
  ui_story_5031_50311302_13_dialog_content = "「에너지 출력률 70%」.",
  ui_story_5031_50311302_14_dialog_content = "응?",
  ui_story_5031_50311302_15_dialog_content = "시엘! 뭐 하는 거야! 너 그 강화복 아직 성능 점검이 안 끝났잖아!",
  ui_story_5031_50311302_16_dialog_content = "내가 저들을 막을게. 레인보우랑 다른 사람들은 얼른 코어 룸으로 가!",
  ui_story_5031_50311302_17_dialog_content = "하지만...",
  ui_story_5031_50311302_18_dialog_content = "걱정 마.",
  ui_story_5031_50311302_19_dialog_content = "우리가 같이 점검하면서 최적화했으니까 「스틱스」도 분명히 문제없을 거야.",
  ui_story_5031_50311302_20_dialog_content = "시엘 말이 맞아.",
  ui_story_5031_50311302_21_dialog_content = "이대로 여기서 붙잡힐 순 없어. 이미 시간을 너무 많이 지체했어.",
  ui_story_5031_50311302_22_dialog_content = "우린... 반드시 동료를 믿어야 해. 그러니까 여기는 시엘에게 맡기자.",
  ui_story_5031_50311302_23_dialog_content = "카렌...",
  ui_story_5031_50311302_24_dialog_content = "(카렌... 드디어 변했구나.)",
  ui_story_5031_50311302_25_dialog_content = "......",
  ui_story_5031_50311302_26_dialog_content = "시엘, 너무 무리하다가 강화복 망가트리지 마!",
  ui_story_5031_50311302_27_dialog_content = "그렇게 되면 나한테 진 빚은 절대로 편하게 못 갚을 줄 알아!",
  ui_story_5031_50311302_28_dialog_content = "으, 응?",
  ui_story_5031_50311302_29_dialog_content = "알겠어. 걱정하지 마.",
  ui_story_5031_50311302_30_dialog_content = "시엘, 그럼 부탁할게.",
  ui_story_5031_50311302_31_dialog_content = "시엘! 조심해야 돼!",
  ui_story_5031_50311302_32_dialog_content = "꼬마 아가씨, 우리도 여럿이서 그쪽을 괴롭히고 싶진 않으니까 얌전히 비켜.",
  ui_story_5031_50311302_33_dialog_content = "당신들을 막는 것 정도라면 나 혼자서도 충분해.",
  ui_story_5031_50311302_34_dialog_content = "...그럼 미안하게 됐어.",
  ui_story_5031_50311302_35_dialog_content = "(윽... 방금 그 사람들보다 강해... 게다가 수도 많고...)",
  ui_story_5031_50311302_36_dialog_content = "(이대로라면...)",
  ui_story_5031_50311302_37_dialog_content = "「에너지 출력률 80%」.",
  ui_story_5031_50311302_38_dialog_content = "쳇... 화력이 더 강해진 건가?",
  ui_story_5031_50311302_39_dialog_content = "제길... 저 갑옷, 괴물이 따로 없군.",
  ui_story_5031_50311302_40_dialog_content = "하지만 영주님을 위해서라면... 절대 물러설 수 없다!",
  ui_story_5031_50311302_41_dialog_content = "1분대! 대형을 유지하고 루미나 실드 진형으로 접근한다!",
  ui_story_5031_50311302_42_dialog_content = "저 여자애를 로봇에서 떼어낸다면 아무것도 할 수 없겠지!",
  ui_story_5031_50311302_43_dialog_content = "예!",
  ui_story_5031_50311302_44_dialog_content = "(저 방패... 뭉치니까 더 단단해졌잖아?)",
  ui_story_5031_50311302_45_dialog_content = "지금이다! 2분대! 루미나 창을 준비해라!",
  ui_story_5031_50311302_46_dialog_content = "(이런... 저 실드를 파괴하지 못한다면... 저들이 다가오는 순간 끝장이야...)",
  ui_story_5031_50311302_47_dialog_content = "(안 돼. 냉정해져야 해. 휴──)",
  ui_story_5031_50311302_48_dialog_content = "(비록 더 단단해지긴 했지만...\n에너지를 사용하는 거라면 강도도 루미나와 관계가 있을 거야.)",
  ui_story_5031_50311302_49_dialog_content = "(그럼 내가 저 실드보다 더 강한 루미나를 방출하면 돼...)",
  ui_story_5031_50311302_50_dialog_content = "(하지만 「스틱스」는 오늘 이미 한번 손상이 발생했어...)",
  ui_story_5031_50311302_51_dialog_content = "(만약 여기서 에너지 출력을 더 높인다면... 「스틱스」는...)",
  ui_story_5031_50311302_52_dialog_content = "그리고 이미 다 생각해 뒀어요.\n나중에 제가 강화복을 만들면 모두를 도와 좋은 일을 많이 많이 할 거예요!",
  ui_story_5031_50311302_53_dialog_content = "어머? 그럼 강화복을 만들고 나서 시엘이 제일 하고 싶은 일은 뭐니?",
  ui_story_5031_50311302_54_dialog_content = "저요? 전...",
  ui_story_5031_50311302_55_dialog_content = "...저는...",
  ui_story_5031_50311302_56_dialog_content = "친구를 돕고, 동료를 지키는... 의지할 수 있는 사람이 되고 싶어요!",
  ui_story_5031_50311302_57_dialog_content = "레인보우, 미안해...「스틱스」!",
  ui_story_5031_50311302_58_dialog_content = "<size=45>「에너지 출력률 100%」!</size>",
  ui_story_5031_50311302_59_dialog_content = "뭐, 뭐야? 루미나 실드가 깨지다니!",
  ui_story_5031_50311302_60_dialog_content = "이 녀석... 괴물이냐?!",
  ui_story_5031_50311302_61_dialog_content = "하, 하아...",
  ui_story_5031_50311302_62_dialog_content = "아무래도 조금 무리였던 것 같네...",
  ui_story_5031_50311302_63_dialog_content = "다리 부분 연결에도 문제가 발생했고... 루미나도...",
  ui_story_5031_50311302_64_dialog_content = "물러서지 마라!",
  ui_story_5031_50311302_65_dialog_content = "실드가 깨져도 상관없다! 저쪽의 에너지도 곧 바닥날 거다!",
  ui_story_5031_50311302_66_dialog_content = "우린 수가 더 많다! 고작 어린 소녀한테 가로막힐 순 없다!",
  ui_story_5031_50311302_67_dialog_content = "...예!",
  ui_story_5031_50311302_68_dialog_content = "하아... 절대... 지나가게 둘 순 없어...",
  ui_story_5031_50311302_69_dialog_content = "공격이 약해졌다! 지금이다!",
  ui_story_5031_50311302_70_dialog_content = "머릿수로 밀어붙여 놓고 그렇게 두들겨 맞기까지 해놓고,\n너네가 그러고도 하버 시티의 병사들이야?",
  ui_story_5031_50311302_71_dialog_content = "이 목소리...",
  ui_story_5031_50311302_72_dialog_content = "앗!",
  ui_story_5031_50311302_73_dialog_content = "바, 방금 그 녀석이다!",
  ui_story_5031_50311302_74_dialog_content = "우와, 내가 무리하지 말라고 했잖아. 말 참 안 듣네!",
  ui_story_5031_50311302_75_dialog_content = "「스틱스」의 상태가 아까보다 더 나빠진 것 같아.\n정말... 오후 내내 수리해 준 게 허탕이 됐잖아!",
  ui_story_5031_50311302_76_dialog_content = "레인보우! 왜 돌아온 거야?",
  ui_story_5031_50311302_77_dialog_content = "네가 걱정되니까 그렇지.",
  ui_story_5031_50311302_78_dialog_content = "그럼 코어 룸 쪽은 어떡해?",
  ui_story_5031_50311302_79_dialog_content = "제노 단장이랑 다른 사람들한테 맡겼지.",
  ui_story_5031_50311302_80_dialog_content = "흥, 기습까지 해?",
  ui_story_5031_50311302_81_dialog_content = "으윽!",
  ui_story_5031_50311302_82_dialog_content = "......",
  ui_story_5031_50311302_83_dialog_content = "응? 시엘? 표정이 왜 그래?",
  ui_story_5031_50311302_84_dialog_content = "...그래.",
  ui_story_5031_50311302_85_dialog_content = "이렇게 처참한 꼴이라니...\n나 같은 사람은 신뢰할 수도... 의지할 수도 없는 게 당연해...",
  ui_story_5031_50311302_86_dialog_content = "레인보우가 돌아오지 않았다면 어쩌면...",
  ui_story_5031_50311302_87_dialog_content = "......",
  ui_story_5031_50311302_88_dialog_content = "시엘, 넌 가끔 정말 바보 같아.",
  ui_story_5031_50311302_89_dialog_content = "응?",
  ui_story_5031_50311302_90_dialog_content = "하지만 그렇게 바보 같은 시엘도 난 좋아~",
  ui_story_5031_50311302_91_dialog_content = "난 말이야, 널 믿었으니까 온 거야.\n네가 우릴 위해서 100%의 출력으로 병사들을 막을 줄 알았으니까.",
  ui_story_5031_50311302_92_dialog_content = "하지만 「스틱스」의 상태는 너랑 내가 가장 잘 알고 있잖아.\n그러니까 그다음엔 어떻게 될지도 알고 있고 말이야.",
  ui_story_5031_50311302_93_dialog_content = "......",
  ui_story_5031_50311302_94_dialog_content = "그리고 난 제노 단장도 믿고 있어. 그들이라면 반드시 「에메랄드호」를 지켜줄 거야.",
  ui_story_5031_50311302_95_dialog_content = "그러니까 걱정하지 마.",
  ui_story_5031_50311302_96_dialog_content = "이번 일이 마무리되면 너랑 같이 「스틱스」를 개선해야겠어.",
  ui_story_5031_50311302_97_dialog_content = "아주 강하고 튼튼하게 만들어서, 300%의 힘을 써도 망가지지 않게 만들자!",
  ui_story_5031_50311302_98_dialog_content = "...좋아.",
  ui_story_5031_50311302_99_dialog_content = "근데 지금은 일단 저 바글바글한 녀석들부터 처리해야겠지?",
  ui_story_5031_50311302_100_dialog_content = "나 원 참, 너희 하버 시티 병사들은 쪽수로 밀어붙이질 않나, 기습을 하질 않나.",
  ui_story_5031_50311302_101_dialog_content = "품위라고는 하나도 없네.",
  ui_story_5031_50311302_102_dialog_content = "......",
  ui_story_5031_50311401_1_dialog_content = "콜록... 콜록, 콜록.",
  ui_story_5031_50311401_2_dialog_content = "모든 준비가 끝났습니다.",
  ui_story_5031_50311401_3_dialog_content = "이제 모든 체스말이 제자리에 놓이길 기다리면 됩니다.",
  ui_story_5031_50311401_4_dialog_content = "영주님. 발소리가 가까워지고 있습니다.",
  ui_story_5031_50311401_5_dialog_content = "좋습니다. 다들 오게 두세요.\n당신들은 계획대로 어서 이 배를 떠나서 다른 자들의 접근을 막으세요.",
  ui_story_5031_50311401_6_dialog_content = "......",
  ui_story_5031_50311401_7_dialog_content = "왜 그러죠?",
  ui_story_5031_50311401_8_dialog_content = "정말... 괜찮으십니까?",
  ui_story_5031_50311401_9_dialog_content = "영주님 혼자 계시는 건 아무래도 좀...",
  ui_story_5031_50311401_10_dialog_content = "당신은 이미 당신의 임무를 마쳤습니다. 나머지는 반드시 제가 마주해야 할 일입니다.",
  ui_story_5031_50311401_11_dialog_content = "......",
  ui_story_5031_50311401_12_dialog_content = "아니면... 파토, 당신은 절 믿지 못하는 겁니까?",
  ui_story_5031_50311401_13_dialog_content = "전 당연히 영주님을 믿습니다! 그런 뜻이 아니라는 걸 알고 계시잖습니까.",
  ui_story_5031_50311401_14_dialog_content = "절 믿는다면 어서 떠나세요.\n당신들이 이곳에 있으면 오히려 계획에 방해가 될 겁니다.",
  ui_story_5031_50311401_15_dialog_content = "걱정 마세요. 지금 모든 상황은 제 손바닥 안에 있으니까요.",
  ui_story_5031_50311401_16_dialog_content = "제 말을 잊지 마세요. 그 어떤 소리를 듣더라도, 절대 들어와선 안 됩니다.",
  ui_story_5031_50311401_17_dialog_content = "...예.",
  ui_story_5031_50311401_18_dialog_content = "부디 조심하십시오.",
  ui_story_5031_50311401_19_dialog_content = "엘비스!",
  ui_story_5031_50311401_20_dialog_content = "으음? 레인보우와 시엘이 아니라 카렌 전하와 친구분들이 오셨군요.",
  ui_story_5031_50311401_21_dialog_content = "뭐, 괜찮습니다. 제 생각보다 좀 더 늦긴 했지만 말입니다.",
  ui_story_5031_50311401_22_dialog_content = "준비 작업이 벌써 끝났는데도 다들 나타나질 않기에,\n제 병사들이 여러분을 궁지에 몰아넣은 건 아닌지 걱정했습니다.",
  ui_story_5031_50311401_23_dialog_content = "뭔가... 우릴 기다렸다는 것처럼 말하는데?",
  ui_story_5031_50311401_24_dialog_content = "파토도 곁에 없어. 무슨 속셈인지 모르겠네.",
  ui_story_5031_50311401_25_dialog_content = "아무튼 다들 조심해.",
  ui_story_5031_50311401_26_dialog_content = "응.",
  ui_story_5031_50311401_27_dialog_content = "저 옆에 있는 게... 바로 「에너지 코어」인가?",
  ui_story_5031_50311401_28_dialog_content = "그럴 거야. 엄청나게 강하고, 평범하지 않은 힘이 느껴져.",
  ui_story_5031_50311401_29_dialog_content = "하지만 저 「에너지 코어」는 너무 크잖아. 대체 어떻게 가져가려는 거지?",
  ui_story_5031_50311401_30_dialog_content = "엘비스, 제 말부터 들어 보세요.",
  ui_story_5031_50311401_31_dialog_content = "당신이 「에너지 코어」의 힘을 어떻게 이용하려는지는 모릅니다.",
  ui_story_5031_50311401_32_dialog_content = "하지만 하버 시티의 백성들을 「모드리 증후군」에서 구하기 위해\n이 일을 벌였다는 것은 압니다.",
  ui_story_5031_50311401_33_dialog_content = "그러나 당신이 지금 하려는 일은 오히려 하버 시티를 위험에 빠트릴 것입니다.",
  ui_story_5031_50311401_34_dialog_content = "「에너지 코어」가 비정상적인 작동 상태가 되면....",
  ui_story_5031_50311401_35_dialog_content = "「가디언」이 깨어나겠지.",
  ui_story_5031_50311401_36_dialog_content = "......",
  ui_story_5031_50311401_37_dialog_content = "그걸 알고 있단 말입니까?",
  ui_story_5031_50311401_38_dialog_content = "이 대륙의 모든 서적을 다 읽는다면, 필요한 정보쯤은 충분히 찾을 수 있어.",
  ui_story_5031_50311401_39_dialog_content = "기계 병기, 「코어 가디언」.",
  ui_story_5031_50311401_40_dialog_content = "구문명이 만들어낸 산물, 작은 도시를 없앨 수 있을 정도의 힘을 가졌다고 하지.",
  ui_story_5031_50311401_41_dialog_content = "「에너지 코어」에 문제가 생기면 「코어 가디언」이 깨어나겠지.",
  ui_story_5031_50311401_42_dialog_content = "함부로 건드렸다간 「코어 가디언」에게 공격받을 뿐 아니라,\n「에너지 코어」가 자폭할 수도 있어.",
  ui_story_5031_50311401_43_dialog_content = "너희 「진리의 결사」가 이 「에너지 코어」에 지금까지\n손을 대지 못한 것도 이런 이유 때문 아닌가?",
  ui_story_5031_50311401_44_dialog_content = "......",
  ui_story_5031_50311401_45_dialog_content = "지, 진리의 결사?",
  ui_story_5031_50311401_46_dialog_content = "제노, 당신... 「진리의 결사」 사람이었어?!",
  ui_story_5031_50311401_47_dialog_content = "...말하자면 깁니다.\n에너지 코어에 대해 알게 된 건 확실히 진리의 결사를 통해서였지만...\n그건 중요하지 않습니다.",
  ui_story_5031_50311401_48_dialog_content = "제노와 「진리의 결사」에 대한 일은 일단 나중에 생각하자.",
  ui_story_5031_50311401_49_dialog_content = "엘비스, 당신이 그걸 그렇게 잘 알고 있다면,\n어째서 백성들까지 위험하게 만들지도 모르는 일을 하는 거죠?",
  ui_story_5031_50311401_50_dialog_content = "하버 시티의 백성들이 위험해진다고요?",
  ui_story_5031_50311401_51_dialog_content = "카렌 전하, 아닙니다. 저는 백야성에서 호사를 부리는 그 원로 귀족들과는 다릅니다.",
  ui_story_5031_50311401_52_dialog_content = "결코 제 백성들의 목숨을 가지고 장난을 치진 않습니다.",
  ui_story_5031_50311401_53_dialog_content = "제가 이렇게 하는 건 그만한 생각이 있기 때문입니다.",
  ui_story_5031_50311401_54_dialog_content = "하지만 여러분에겐... 제 생각을 알 기회가 없을지도 모르겠군요.",
  ui_story_5031_50311401_55_dialog_content = "<color=#e8d9bb>위이잉──</color>",
  ui_story_5031_50311401_56_dialog_content = "윽... 무슨 소리야? 엄청 시끄럽네!",
  ui_story_5031_50311401_57_dialog_content = "...엘비스, 무슨 짓을 한 거죠?",
  ui_story_5031_50311401_58_dialog_content = "귀빈들이 모두 모였으니, 제 계획도 시작할 수 있겠군요.",
  ui_story_5031_50311401_59_dialog_content = "카렌 전하, 전 당신의 기품을 무척이나 존경합니다.\n하지만 전 하버 시티의 미래를 위해서라면 무슨 일이든 할 수 있죠.",
  ui_story_5031_50311401_60_dialog_content = "원망하려면 얼마든지 원망하세요.",
  ui_story_5031_50311401_61_dialog_content = "하지만 봉인은 더는 버틸 수 없습니다. 그리고 전 반드시 하버 시티를 구해야 합니다.",
  ui_story_5031_50311401_62_dialog_content = "봐! 지팡이의 보석이... 빛나기 시작했어!",
  ui_story_5031_50311401_63_dialog_content = "...저 보석은...",
  ui_story_5031_50311401_64_dialog_content = "저 보석이... 지금 「에너지 코어」의 에너지를 흡수하고 있어!",
  ui_story_5031_50311401_65_dialog_content = "흐음? 역시 아이테르로군요. 그런 것까지도 느낄 수 있을 줄이야.",
  ui_story_5031_50311401_66_dialog_content = "그렇다면 확실히... 살려둘 순 없겠군요.",
  ui_story_5031_50311401_67_dialog_content = "애초부터 그럴 생각이었지만 말이죠.",
  ui_story_5031_50311401_68_dialog_content = "「...코어 상태 오류 감지.」",
  ui_story_5031_50311401_69_dialog_content = "「자동 방어 시스템 실행, 시스템 판별을 진행합니다.」",
  ui_story_5031_50311401_70_dialog_content = "아, 커다란 네모 위에 매달려 있던 로봇이 움직이기 시작했어!",
  ui_story_5031_50311401_71_dialog_content = "큰일이군요. 가장 성가신 상황이 되었습니다.",
  ui_story_5031_50311401_72_dialog_content = "저게 바로 「코어 가디언」입니다. 이제 곧 깨어날 겁니다...",
  ui_story_5031_50311401_73_dialog_content = "모두 조심하십시오.",
  ui_story_5031_50311401_74_dialog_content = "「에너자 유형 식별: ...루미나.」",
  ui_story_5031_50311401_75_dialog_content = "「시스템 판단: ...적대.」",
  ui_story_5031_50311401_76_dialog_content = "「결론: 공격 모드 실행.」",
  ui_story_5031_50311401_77_dialog_content = "녀석의 에너지가 계속해서 강해지고 있어!",
  ui_story_5031_50311401_78_dialog_content = "피아, 얼른 내 뒤로 와!",
  ui_story_5031_50311401_79_dialog_content = "으...응!",
  ui_story_5031_50311402_1_dialog_content = "바이스, 제노. 난 왼쪽 후방에서 공격할게.",
  ui_story_5031_50311402_2_dialog_content = "「코어 가디언」의 공격 노선을 방해해 줘!",
  ui_story_5031_50311402_3_dialog_content = "알았어!",
  ui_story_5031_50311402_4_dialog_content = "바이스, 조심해! 「코어 가디언」의 오른쪽 팔에 에너지가 맺히기 시작했어!",
  ui_story_5031_50311402_5_dialog_content = "녀석이 공격하려고 해!",
  ui_story_5031_50311402_6_dialog_content = "알겠어!",
  ui_story_5031_50311402_7_dialog_content = "받아라!",
  ui_story_5031_50311402_8_dialog_content = "「기체가 공격을 받았습니다.」",
  ui_story_5031_50311402_9_dialog_content = "「손상 정도 검사 시작.」",
  ui_story_5031_50311402_10_dialog_content = "우와! 성공이야! 로봇이 안 움직여!",
  ui_story_5031_50311402_11_dialog_content = "카렌 언니 멋져!",
  ui_story_5031_50311402_12_dialog_content = "아니... 녀석의 몸 속 에너지는 아직 정상적으로 움직이고 있어.",
  ui_story_5031_50311402_13_dialog_content = "여러분 모두 훌륭하군요. 제 예상을 조금 벗어났습니다.",
  ui_story_5031_50311402_14_dialog_content = "PlayerName 님의 능력에 대해서는 일찍이 들어봤지만...\n이렇게 직접 보니 정말 신기하군요.",
  ui_story_5031_50311402_15_dialog_content = "하지만... 아쉽습니다.",
  ui_story_5031_50311402_16_dialog_content = "여러분 모두 노력하고 있지만... 여러분의 능력으로는 승산이 없습니다.",
  ui_story_5031_50311402_17_dialog_content = "「검사 완료, 심각한 손상 없음.」",
  ui_story_5031_50311402_18_dialog_content = "「적 공격력 데이터 업데이트, 공격 강도 조정.」",
  ui_story_5031_50311402_19_dialog_content = "이, 이건...?",
  ui_story_5031_50311402_20_dialog_content = "카렌! 녀석의 가슴 부분에 대량의 에너지가 모이고 있어! 피해!",
  ui_story_5031_50311402_21_dialog_content = "으윽!",
  ui_story_5031_50311402_22_dialog_content = "위험했어.",
  ui_story_5031_50311402_23_dialog_content = "카렌! 괜찮아?!",
  ui_story_5031_50311402_24_dialog_content = "미리 알려준 덕분이야. 그냥 약간 긁힌 것뿐이니까 걱정하지 않아도 돼.",
  ui_story_5031_50311402_25_dialog_content = "다행이야. 방금 그 공격... 정말 무서운 힘이었어...",
  ui_story_5031_50311402_26_dialog_content = "벽의 반이 전부 녹아버렸잖아...",
  ui_story_5031_50311402_27_dialog_content = "구문명 병기의 힘은 역시 무섭네.",
  ui_story_5031_50311402_28_dialog_content = "다들 우선 조심해서 녀석의 주위를 맴돌며 약점을 찾아봐.",
  ui_story_5031_50311402_29_dialog_content = "그래. 너도 조심해.",
  ui_story_5031_50311402_30_dialog_content = "근데 이상한 점이 하나 있지 않아?",
  ui_story_5031_50311402_31_dialog_content = "이상한 점?",
  ui_story_5031_50311402_32_dialog_content = "어째서 「코어 가디언」은 우리만 공격하는 거지?",
  ui_story_5031_50311402_33_dialog_content = "「에너지 코어」 옆에 있는 건 엘비스잖아.\n「에너지 코어」의 힘을 흡수하고 있는 것도 엘비스고.",
  ui_story_5031_50311402_34_dialog_content = "그러고 보니 그렇네.",
  ui_story_5031_50311402_35_dialog_content = "왜냐하면 「코어 가디언」은...",
  ui_story_5031_50311402_36_dialog_content = "......",
  ui_story_5031_50311402_37_dialog_content = "이유를 알고 있는 거야?",
  ui_story_5031_50311402_38_dialog_content = "아무것도 아닙니다.",
  ui_story_5031_50311402_39_dialog_content = "왜 말을 하다가 마는 거야!",
  ui_story_5031_50311402_40_dialog_content = "이런 상황에서까지 아직도 날 걱정하는 거야?",
  ui_story_5031_50311402_41_dialog_content = "제노, 넌 정말 여전하구나.",
  ui_story_5031_50311402_42_dialog_content = "괜찮아. 이미 익숙해졌어. 그러니 얘기해줘도 돼.",
  ui_story_5031_50311402_43_dialog_content = "엘비스...",
  ui_story_5031_50311402_44_dialog_content = "말해줘. 「코어 가디언」은 루미나로 적을 판단하는 거라고.",
  ui_story_5031_50311402_45_dialog_content = "나처럼 루미나를 거의 흡수당한 폐인이라면, 저 녀석의 눈에는...",
  ui_story_5031_50311402_46_dialog_content = "그저 「죽은 사람」일 뿐이라고 말이야.",
  ui_story_5031_50311402_47_dialog_content = "루, 루미나를 흡수당했다고?",
  ui_story_5031_50311402_48_dialog_content = "확실히... 그동안 엘비스한테서 루미나를 거의 느낄 수 없었어.",
  ui_story_5031_50311402_49_dialog_content = "병 때문에 그런 거라 생각했는데...",
  ui_story_5031_50311402_50_dialog_content = "반대입니다. 루미나가 사라지면서 병이 생기는 것이죠.",
  ui_story_5031_50311402_51_dialog_content = "「모드리 증후군」은 체내의 루미나를 오랜 시간 흡수당하면서 생기는\n루미나 결핍증입니다.",
  ui_story_5031_50311402_52_dialog_content = "병에 걸린 오로리안은 루미나가 추출되는 고통을 계속해서 참아야 하고, 더 심해지면...",
  ui_story_5031_50311402_53_dialog_content = "그럼 만약 「에너지 코어」를 손에 넣는다면,\n「모드리 증후군」도 해결할 수 있는 건가?",
  ui_story_5031_50311402_54_dialog_content = "엘비스의 계획이 무엇인지는 저도 모르겠습니다. 아마 그럴지도 모르지요.",
  ui_story_5031_50311402_55_dialog_content = "하지만 엘비스... 제 말 좀 들어 보세요.",
  ui_story_5031_50311402_56_dialog_content = "당신이 「에너지 코어」를 손에 넣는다 해도,\n「코어 가디언」을 제어할 방법은 없습니다.",
  ui_story_5031_50311402_57_dialog_content = "우리가 쓰러지고 나면, 녀석의 목표는 당신과 하버 시티가 될 겁니다.",
  ui_story_5031_50311402_58_dialog_content = "분명히 다른 방법이 있을 겁니다. 우리 함께...",
  ui_story_5031_50311402_59_dialog_content = "제노, 다른 방법은 없어.",
  ui_story_5031_50311402_60_dialog_content = "처음으로 내 백성이 이 병 때문에 세상을 떠나는 모습을 본 순간부터...\n난 줄곧 이 문제를 해결할 방법을 찾아왔어.",
  ui_story_5031_50311402_61_dialog_content = "몇 년간 가능성이 조금이라도 있으면 뭐든 시도해 봤지.\n성공 확률이 아무리 낮아도 포기하지 않았어.",
  ui_story_5031_50311402_62_dialog_content = "하지만 내게 남은 건 끝없는 실망과... 갈수록 쓸모없어지는 내 몸뿐이었지.",
  ui_story_5031_50311402_63_dialog_content = "난 반드시 내 손으로 이 모든 걸 완성해야만 해.\n허나 내게 남은 시간은 많지 않아.",
  ui_story_5031_50311402_64_dialog_content = "하지만...",
  ui_story_5031_50311402_65_dialog_content = "제노 아저씨! 수다는 그만해! 「코어 가디언」이 그쪽으로 가고 있다구!",
  ui_story_5031_50311402_66_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5031_50311402_67_dialog_content = "제노!",
  ui_story_5031_50311402_68_dialog_content = "콜록, 콜록...",
  ui_story_5031_50311402_69_dialog_content = "전 괜찮습니다...",
  ui_story_5031_50311402_70_dialog_content = "다행이야... 깜짝 놀랐잖아...",
  ui_story_5031_50311402_71_dialog_content = "엘비스! 당신 정말 비열하네!",
  ui_story_5031_50311402_72_dialog_content = "제노 아저씨한테 말을 시켜서 한눈팔게 만들어?!",
  ui_story_5031_50311402_73_dialog_content = "훗, 오해입니다, 피아 양.",
  ui_story_5031_50311402_74_dialog_content = "그건 제 뜻이 아니었거든요. 오히려 전 아직 여러분이 필요합니다...",
  ui_story_5031_50311402_75_dialog_content = "당신이 「에너지 코어」를 흡수하는 동안,\n「코어 가디언」을 막아줄 사람이 필요한 거겠지.",
  ui_story_5031_50311402_76_dialog_content = "카렌 전하께선 역시 총명하시군요.",
  ui_story_5031_50311402_77_dialog_content = "참, 여러분이 하버 시티의 백성들을 그리 걱정하신다니,\n「코어 가디언」에 대해 조금 알려드리도록 하죠.",
  ui_story_5031_50311402_78_dialog_content = "저와 「진리의 결사」와 차이는 바로, 제가 그들에게 없는 것을 가지고 있다는 겁니다.",
  ui_story_5031_50311402_79_dialog_content = "저는 제 혈통을 가지고 「에너지 코어」의 힘과 계약을 맺어 사용할 수 있습니다.",
  ui_story_5031_50311402_80_dialog_content = "제가 「에너지 코어」를 모두 흡수하면, 「코어 가디언」도 제 명령을 듣게 되겠죠.",
  ui_story_5031_50311402_81_dialog_content = "그러니 제 백성들은 걱정하지 마시고,\n여러분께서는 이 배와 함께 바닷속에 가라앉으시면 됩니다.",
  ui_story_5031_50311402_82_dialog_content = "아무래도 엘비스 당신은 우리 목숨을 거두기로 결정한 모양이네.",
  ui_story_5031_50311402_83_dialog_content = "정말 죄송합니다.\n하지만 원로원의 귀족들이 알게 될지도 모르는 위험을 감수할 수는 없습니다.",
  ui_story_5031_50311402_84_dialog_content = "그렇다면 더는 얘기할 게 없겠어.",
  ui_story_5031_50311402_85_dialog_content = "하지만 네 선택이 옳고 그르고를 떠나서, 내 친구를 다치게 하는 건 용납할 수 없어.",
  ui_story_5031_50311402_86_dialog_content = "제노, 당신이 소환하는 환영들에는 당신의 루미나가 담겨 있겠지?",
  ui_story_5031_50311402_87_dialog_content = "그렇습니다.",
  ui_story_5031_50311402_88_dialog_content = "그럼 방금 그 병사들 수준의 환상은 얼마나 소환할 수 있지?",
  ui_story_5031_50311402_89_dialog_content = "동시에 조종해야 한다면 열 개 정도가 되겠군요.",
  ui_story_5031_50311402_90_dialog_content = "카렌, 무슨 계획이라도 있는 거야?",
  ui_story_5031_50311402_91_dialog_content = "바이스, 제노. 「코어 가디언」을 저지해 줘.",
  ui_story_5031_50311402_92_dialog_content = "어쨌든 「에너지 코어」를 정상으로 돌려놔야\n「코어 가디언」도 다시 잠들 수 있을 거야.",
  ui_story_5031_50311402_93_dialog_content = "그렇다면 목표는 확실해지지.",
  ui_story_5031_50311402_94_dialog_content = "난 가서 엘비스가 「에너지 코어」를 흡수하는 걸 막겠어.",
  ui_story_5031_50311501_1_dialog_content = "받아라!",
  ui_story_5031_50311501_2_dialog_content = "좋아. 「코어 가디언」의 주의를 끌었어.",
  ui_story_5031_50311501_3_dialog_content = "카렌! 지금이야!",
  ui_story_5031_50311501_4_dialog_content = "서두르십시오! 이렇게 많은 환영은 오래 유지하지 못합니다!",
  ui_story_5031_50311501_5_dialog_content = "좋아. 그럼 부탁할게.",
  ui_story_5031_50311501_6_dialog_content = "콜록, 콜록...",
  ui_story_5031_50311501_7_dialog_content = "역시 카렌 전하다우시군요.",
  ui_story_5031_50311501_8_dialog_content = "제노를 알게 된 지 하루도 채 되지 않았는데,\n그의 능력으로 「코어 가디언」을 포위할 생각을 하시다니...",
  ui_story_5031_50311501_9_dialog_content = "전황에 대한 이해도 명확하고, 거기에 PlayerName 님의 능력까지 더해지니...",
  ui_story_5031_50311501_10_dialog_content = "역시 처음부터 당신을 얕보지 않아서 다행입니다.",
  ui_story_5031_50311501_11_dialog_content = "으윽?!",
  ui_story_5031_50311501_12_dialog_content = "카렌? 왜 그래?!",
  ui_story_5031_50311501_13_dialog_content = "몸에... 힘이... 들어가지 않아...",
  ui_story_5031_50311501_14_dialog_content = "힘이... 흩어지고 있어...",
  ui_story_5031_50311501_15_dialog_content = "피아, 여기 숨어서 움직이지 마!",
  ui_story_5031_50311501_16_dialog_content = "으앗! PlayerName! 그렇게 달려 나가면 로봇한테 당해버릴지도 몰라!",
  ui_story_5031_50311501_17_dialog_content = "...응? 로봇이 아무 반응도 없잖아?",
  ui_story_5031_50311501_18_dialog_content = "카렌!",
  ui_story_5031_50311501_19_dialog_content = "PlayerName... 으윽.",
  ui_story_5031_50311501_20_dialog_content = "(어떻게 된 거지... 카렌의 몸속 루미나가 빠르게 줄어들고 있잖아?)",
  ui_story_5031_50311501_21_dialog_content = "제길...",
  ui_story_5031_50311501_22_dialog_content = "<size=45>엘비스, 무슨 짓을 한 거야?!</size>",
  ui_story_5031_50311501_23_dialog_content = "고통스러우시겠죠. 루미나가 빠르게 사라지는 그 느낌.",
  ui_story_5031_50311501_24_dialog_content = "전 만일을 대비해 카렌 전하의 몸에 미리 「<color=#FFB400>조치</color>」를 취해 뒀습니다.",
  ui_story_5031_50311501_25_dialog_content = "조치? 대체 언제?!",
  ui_story_5031_50311501_26_dialog_content = "잠깐만... 설마 이 옷이?",
  ui_story_5031_50311501_27_dialog_content = "맞습니다.",
  ui_story_5031_50311501_28_dialog_content = "여러분께서 제게 선실 깊은 곳으로 들어갈 방법을 물어봤을 때부터,\n어쩌면 지금 이 순간이 올지도 모른다고 생각했습니다.",
  ui_story_5031_50311501_29_dialog_content = "카렌 전하께서 입고 계신 그 옷은... 특수한 가공을 거친 것입니다.",
  ui_story_5031_50311501_30_dialog_content = "「<color=#FFB400>빛의 실</color>」로 만든 옷감은 발동된 순간 착용자의 몸에 붙어서 빠르게 루미나를 빨아들이죠.",
  ui_story_5031_50311501_31_dialog_content = "그러니 더는 루미나를 사용하지 않는 편이 좋을 겁니다. 그편이 훨씬 견디기 쉬울 테니까요.",
  ui_story_5031_50311501_32_dialog_content = "이 자식!",
  ui_story_5031_50311501_33_dialog_content = "미안해... 전부 내가 방심해서...",
  ui_story_5031_50311501_34_dialog_content = "네 잘못이 아니야. 카렌, 일단...",
  ui_story_5031_50311501_35_dialog_content = "제노 씨! 조심해요!",
  ui_story_5031_50311501_36_dialog_content = "윽!",
  ui_story_5031_50311501_37_dialog_content = "제노 씨, 괜찮아요?",
  ui_story_5031_50311501_38_dialog_content = "큭... 손목을...",
  ui_story_5031_50311501_39_dialog_content = "움직일 수 없을 것 같습니다.",
  ui_story_5031_50311501_40_dialog_content = "피가 나고 있잖아! 일단 움직이지 마!",
  ui_story_5031_50311501_41_dialog_content = "「적 부상. 추격 발동.」",
  ui_story_5031_50311501_42_dialog_content = "앗! 바이스 언니! 「코어 가디언」이 그쪽으로 가고 있어!",
  ui_story_5031_50311501_43_dialog_content = "으악! 어, 어쩌지?! 속도가 너무 빨라!",
  ui_story_5031_50311501_44_dialog_content = "사거리가... 너무 가까워! 늦었어!",
  ui_story_5031_50311501_45_dialog_content = "멈춰라! 윽!",
  ui_story_5031_50311501_46_dialog_content = "제, 제노 씨?!",
  ui_story_5031_50311501_47_dialog_content = "......",
  ui_story_5031_50311501_48_dialog_content = "기, 기절한 건가?",
  ui_story_5031_50311501_49_dialog_content = "으아아! 어떡하지? 어떡하지, 어떡하지?!",
  ui_story_5031_50311501_50_dialog_content = "아, 맞다! 이게 있었구나!",
  ui_story_5031_50311501_51_dialog_content = "<color=#e8d9bb>퍼엉──</color>",
  ui_story_5031_50311501_52_dialog_content = "「?」",
  ui_story_5031_50311501_53_dialog_content = "맞혔어! 다행히 사부가 준 호신용 총이 있었어!",
  ui_story_5031_50311501_54_dialog_content = "어, 어떠냐! 커다란 로봇!",
  ui_story_5031_50311501_55_dialog_content = "「알 수 없는 공격. 손상 정도: 0」",
  ui_story_5031_50311501_56_dialog_content = "「대상의 루미나 소모 없음. 판단: 우선 제거.」",
  ui_story_5031_50311501_57_dialog_content = "으아악! 왜 나한테 달려오는 거야!",
  ui_story_5031_50311501_58_dialog_content = "아악!",
  ui_story_5031_50311501_59_dialog_content = "피아!",
  ui_story_5031_50311501_60_dialog_content = "......",
  ui_story_5031_50311501_61_dialog_content = "(어쩌지... 이대로 가다간 전부 끝장나고 말 거야.)",
  ui_story_5031_50311501_62_dialog_content = "(안 돼. 이제 싸울 수 있는 사람은 나뿐이야. 함부로 움직일 순 없어.)",
  ui_story_5031_50311501_63_dialog_content = "(우선 엘비스부터 막아야 「코어 가디언」을 멈출 수 있을 거야.)",
  ui_story_5031_50311501_64_dialog_content = "......",
  ui_story_5031_50311501_65_dialog_content = "카렌, 우선 여기 누워있어. 더는 루미나를 사용하지 말고.",
  ui_story_5031_50311501_66_dialog_content = "PlayerName... 뭘 하려고?",
  ui_story_5031_50311501_67_dialog_content = "내가 엘비스를 막을게.",
  ui_story_5031_50311501_68_dialog_content = "군단장들과 사메야마가 평소에 나한테 해줬던 특훈이...\n드디어 빛을 볼 순간이 왔어.",
  ui_story_5031_50311501_69_dialog_content = "하지만...",
  ui_story_5031_50311501_70_dialog_content = "걱정 마, 카렌.",
  ui_story_5031_50311501_71_dialog_content = "난 루미나는 없지만, 엘비스 저 약골 정도한테는...",
  ui_story_5031_50311501_72_dialog_content = "지지 않을 거야.",
  ui_story_5031_50311501_73_dialog_content = "...조심해.",
  ui_story_5031_50311501_74_dialog_content = "영웅 같은 발언이었습니다. 무척이나 인상 깊군요.",
  ui_story_5031_50311501_75_dialog_content = "하지만 사람을 「약골」이라고 부르다니... 예의가 없네요.",
  ui_story_5031_50311501_76_dialog_content = "쓸데없는 소리는 집어치워.",
  ui_story_5031_50311501_77_dialog_content = "입 다물고──",
  ui_story_5031_50311501_78_dialog_content = "얌전히 쓰러져!",
  ui_story_5031_50311501_79_dialog_content = "하.",
  ui_story_5031_50311501_80_dialog_content = "<size=45>PlayerName! 조심해!</size>",
  ui_story_5031_50311501_81_dialog_content = "「우선 명령 변경, 목표 업데이트.」",
  ui_story_5031_50311501_82_dialog_content = "으악!",
  ui_story_5031_50311501_83_dialog_content = "PlayerName!",
  ui_story_5031_50311501_84_dialog_content = "아...안 돼...",
  ui_story_5031_50311501_85_dialog_content = "어째서 이런...",
  ui_story_5031_50311501_86_dialog_content = "유감이지만 조금 늦었습니다, PlayerName.",
  ui_story_5031_50311501_87_dialog_content = "아쉽게도 「에너지 코어」의 힘은 이미 모두 흡수했거든요.",
  ui_story_5031_50311501_88_dialog_content = "이제 제가 바로 「코어 가디언」의 주인입니다.",
  ui_story_5031_50311501_89_dialog_content = "아니었으면 당신처럼 루미나가 없는 존재는 정말 제 계산 밖의 대상이 되었겠죠.",
  ui_story_5031_50311501_90_dialog_content = "「최고 지휘권 업데이트, 수동 전투로 변경.」",
  ui_story_5031_50311501_91_dialog_content = "「자동 방어 시스템 종료.」",
  ui_story_5031_50311501_92_dialog_content = "(아파!)",
  ui_story_5031_50311501_93_dialog_content = "(다리에 감각이 없어!)",
  ui_story_5031_50311501_94_dialog_content = "어디 보자, 아직도 움직일 수 있는 건...",
  ui_story_5031_50311501_95_dialog_content = "바이스 양뿐이군요.",
  ui_story_5031_50311501_96_dialog_content = "자, 가서 처리하세요. 그리고 다음 장소로 이동하죠.",
  ui_story_5031_50311501_97_dialog_content = "「새로운 명령 확인. 목표 변경.」",
  ui_story_5031_50311501_98_dialog_content = "(큰일이야! 바이스가!)",
  ui_story_5031_50311501_99_dialog_content = "<size=33>바이스... 도망쳐...</size>",
  ui_story_5031_50311501_100_dialog_content = "호오? 아직도 일어설 수 있는 겁니까?",
  ui_story_5031_50311501_101_dialog_content = "<size=33>뭐?</size>",
  ui_story_5031_50311501_102_dialog_content = "카렌 전하. 아직도 그 정도의 에너지를 발산할 수 있다니... 정말 감탄스럽군요.",
  ui_story_5031_50311501_103_dialog_content = "하지만 그런 행동은 죽음을 조금 더 앞당길 뿐이랍니다.",
  ui_story_5031_50311501_104_dialog_content = "<size=33>카, 카렌?</size>",
  ui_story_5031_50311501_105_dialog_content = "전부 나 때문이야...",
  ui_story_5031_50311501_106_dialog_content = "카렌 전하?",
  ui_story_5031_50311501_107_dialog_content = "전부... 나 때문에...",
  ui_story_5031_50311501_108_dialog_content = "아, 루미나가 사라진 것 때문에 곧 의식을 잃게 될 모양이군요.",
  ui_story_5031_50311501_109_dialog_content = "정말 놀랍습니다. 그 지경이 돼서도 무의식적으로 동료들을 보호하려 하다니...",
  ui_story_5031_50311501_110_dialog_content = "「새로운 활동 목표 발견. 공격하시겠습니까?」",
  ui_story_5031_50311501_111_dialog_content = "아니요, 저쪽은 이제 더는 위협이 아닙니다.",
  ui_story_5031_50311501_112_dialog_content = "<size=45>카렌... 멈춰...!</size>",
  ui_story_5031_50311501_113_dialog_content = "(제길... 목소리가 나오질 않아.)",
  ui_story_5031_50311501_114_dialog_content = "(그렇다면...)",
  ui_story_5031_50311501_115_option_content = "(강제 감응!)",
  ui_story_5031_50311501_116_dialog_content = "네가 다스리는 도시가 암귀의 공격을 받는다면, 너는 무엇을 할 것이냐.",
  ui_story_5031_50311501_117_dialog_content = "(응? 솔라드 씨의 목소리?)",
  ui_story_5031_50311501_118_dialog_content = "(이건... 꿈인가? 카렌이 의식을 잃기 직전이라서?)",
  ui_story_5031_50311501_119_dialog_content = "즉시 부대를 편성해 적을 막겠습니다.",
  ui_story_5031_50311501_120_dialog_content = "다른 암귀들이 방어가 허술한 쪽을 공격한다면?",
  ui_story_5031_50311501_121_dialog_content = "예비 부대를 이끌고 달려갈 겁니다.",
  ui_story_5031_50311501_122_dialog_content = "그때 땅을 뚫고 나타난 암귀가 도시 중앙에서 나타난다면?",
  ui_story_5031_50311501_123_dialog_content = "장교에게 진지를 지키도록 명하고, 저는...",
  ui_story_5031_50311501_124_dialog_content = "암귀가 처음 공격을 시작했던 성벽이 다시 위기에 처한다면?",
  ui_story_5031_50311501_125_dialog_content = "......",
  ui_story_5031_50311501_126_dialog_content = "제, 제가 모든 암귀를 없앨 겁니다.",
  ui_story_5031_50311501_127_dialog_content = "암귀는 아무리 죽여도 절대 사라지지 않는다.",
  ui_story_5031_50311501_128_dialog_content = "......",
  ui_story_5031_50311501_129_dialog_content = "아무래도 네가 훌륭한 군주가 되기까지는 아직도 갈 길이 먼 모양이구나...",
  ui_story_5031_50311501_130_dialog_content = "백야성은 네게만 기댈 수는 없다.",
  ui_story_5031_50311501_131_dialog_content = "아, 아버님?",
  ui_story_5031_50311501_132_dialog_content = "분명 널 북방에 보내서 베들레헴에게 가르침을 받도록 했거늘, 전혀 발전이 없구나.",
  ui_story_5031_50311501_133_dialog_content = "힘도, 지략도 부족하다.",
  ui_story_5031_50311501_134_dialog_content = "그렇기에 당신의 친구들을 잃게 된 것이겠죠.",
  ui_story_5031_50311501_135_dialog_content = "그들이 다치고 목숨을 잃은 것은... 모두 당신 때문입니다, 카렌 전하.",
  ui_story_5031_50311501_136_dialog_content = "나...난...",
  ui_story_5031_50311501_137_dialog_content = "카렌... 난 널 믿어서... 네 작전대로 했어.",
  ui_story_5031_50311501_138_dialog_content = "근데 결과는?",
  ui_story_5031_50311501_139_dialog_content = "나랑 PlayerName... 우린 너 때문에 여기서 죽을 거야.",
  ui_story_5031_50311501_140_dialog_content = "바이스, 미안해... 난...",
  ui_story_5031_50311501_141_dialog_content = "카렌! 똑똑히 봐! 저건 바이스가 아니야!",
  ui_story_5031_50311501_142_dialog_content = "이 목소리...",
  ui_story_5031_50311501_143_dialog_content = "PlayerName?",
  ui_story_5031_50311501_144_dialog_content = "그래! 나야!",
  ui_story_5031_50311501_145_dialog_content = "미안해... 네가 속으로 이렇게 고통스러워하고 있는 줄도 몰랐어.",
  ui_story_5031_50311501_146_dialog_content = "하지만 바이스는 절대 저렇게 말하지 않아!\n네 앞에 있는 건 전부 환영이지 진짜가 아니야!",
  ui_story_5031_50311501_147_dialog_content = "아직도 네 책임으로부터 도망치려고 하는 거야?",
  ui_story_5031_50311501_148_dialog_content = "정말 슬프군요. 입으로는 다른 사람들을 지키겠다고 외치면서 이토록 나약하다니.",
  ui_story_5031_50311501_149_dialog_content = "군주는 지금 네 모습이어서는 안 된다.",
  ui_story_5031_50311501_150_dialog_content = "난...",
  ui_story_5031_50311501_151_dialog_content = "카렌, 내 말 들어.",
  ui_story_5031_50311501_152_dialog_content = "언제나 군주로서의 책임과 부담을 짊어지고 있을 필요는 없어!",
  ui_story_5031_50311501_153_dialog_content = "나랑 바이스 앞에서 넌 그냥 카렌이야! 그저 카렌일 뿐이라고!",
  ui_story_5031_50311501_154_dialog_content = "뭐?",
  ui_story_5031_50311501_154X1_dialog_content = "카렌, 전에 바이스가 했던 말 기억해?!",
  ui_story_5031_50311501_154X2_dialog_content = "절대로 자기 집념에 빠져버려서는 안 돼!",
  ui_story_5031_50311501_154X3_dialog_content = "내... 집념...",
  ui_story_5031_50311501_154X4_dialog_content = "왜냐면 난 그 과정에서 마치 심연 같은 잠에 빠졌거든.\n처음엔 내가 영원히 깨어나지 못하는 건 아닐까 싶었어.",
  ui_story_5031_50311501_154X5_dialog_content = "내 자아를 잃어버릴까 너무 무서웠고, 그래서 계속 과거의 날 떠올리려고 노력했어.",
  ui_story_5031_50311501_154X6_dialog_content = "그리고 신기한 장면들도 많이 봤어. 꼭 내가 진짜로 그 장소에 있는 것처럼 말이야.",
  ui_story_5031_50311501_154X7_dialog_content = "그 환각은 마치 진짜 같았고, 나한테 주어진 시험 같았어.",
  ui_story_5031_50311501_154X8_dialog_content = "그러다 다행히 의식의 바다에서 한 줄기 빛을 붙잡았고, 끝까지 버틸 수 있었어.",
  ui_story_5031_50311501_154X9_dialog_content = "빛? 그때도 말했던 것 같아. 그게 대체 뭐야?",
  ui_story_5031_50311501_154X10_dialog_content = "음... 그러니까 PlayerName, 그리고 너랑 겪었던 즐거운 일들을 생각하니까...",
  ui_story_5031_50311501_154X11_dialog_content = "나도 모르게 마음이 평화로워졌어.",
  ui_story_5031_50311501_154X12_dialog_content = "맞아, 카렌! 포기하지 마. 너 자신을 잃지 마!",
  ui_story_5031_50311501_155_dialog_content = "우린 어깨를 맞대고 함께 싸우고, 함께 나아가는 동료야.",
  ui_story_5031_50311501_156_dialog_content = "서로의 등을 맡기는 전우라고!",
  ui_story_5031_50311501_157_dialog_content = "어떤 어려움 앞에서도, 너 혼자 군주의 책임이니 뭐니 그런 걸 짊어질 필요는 없어!",
  ui_story_5031_50311501_158_dialog_content = "혼자 모든 걸 감당하고 우릴 지키려고 하지 마!",
  ui_story_5031_50311501_159_dialog_content = "우린 함께 나아가고, 함께 방법을 고민하고, 함께 모든 걸 마주해야 되는 거야!",
  ui_story_5031_50311501_160_dialog_content = "PlayerName...",
  ui_story_5031_50311501_161_dialog_content = "무슨 일이 있어도 나랑 바이스는 절대로! 널 원망하지 않아!",
  ui_story_5031_50311501_162_dialog_content = "그러니까 힘내, 카렌! 눈앞의 허상이 네 마음을 속이게 만들지 마!",
  ui_story_5031_50311501_163_dialog_content = "진짜 바이스는 지금도 우릴 지키기 위해 싸우고 있어! 바이스는 아직 포기하지 않았어!",
  ui_story_5031_50311501_164_dialog_content = "바이스한테는 네가 필요해!",
  ui_story_5031_50311501_165_dialog_content = "......",
  ui_story_5031_50311501_166_dialog_content = "네 말이 맞아, PlayerName.",
  ui_story_5031_50311501_167_dialog_content = "동료가 아직 싸우고 있는데, 후회만 하고 있으면 안 되잖아.",
  ui_story_5031_50311501_168_dialog_content = "그럼 네 잘못을 외면하겠다는 것이냐?",
  ui_story_5031_50311501_169_dialog_content = "네 방심과 무능함이──",
  ui_story_5031_50311501_170_dialog_content = "지금의 상황을 만든 거야.",
  ui_story_5031_50311501_171_dialog_content = "그래. 하지만 더는 잘잘못에 집착하지 않겠어.",
  ui_story_5031_50311501_172_dialog_content = "......",
  ui_story_5031_50311501_173_dialog_content = "그건 의미가 없으니까. 잘못한 게 있다면...",
  ui_story_5031_50311501_174_dialog_content = "열심히 바로잡으면 돼.",
  ui_story_5031_50311501_175_dialog_content = "...만약 그게 네가 믿는 「왕도」라면.",
  ui_story_5031_50311501_176_dialog_content = "그 신념을 계속해서 이어갈 수 있기를 바랄게.",
  ui_story_5031_50311501_176X1_dialog_content = "그럴 거야.",
  ui_story_5031_50311501_176X2_dialog_content = "난...",
  ui_story_5031_50311501_176X3_dialog_content = "나만의 빛을 찾았으니까.",
  ui_story_5031_50311501_177_dialog_content = "아, 주변이...",
  ui_story_5031_50311501_178_dialog_content = "바이스, 미안해. 오래 기다렸지.",
  ui_story_5031_50311501_179_dialog_content = "카렌!",
  ui_story_5031_50311501_180_dialog_content = "「경고: 대량의 루미나 감지. 위험도 높음.」",
  ui_story_5031_50311501_181_dialog_content = "「즉시 대상에 대한 제거 작업 실시.」",
  ui_story_5031_50311501_182_dialog_content = "빛이여, 어둠을 비춰라!",
  ui_story_5031_50311501_183_dialog_content = "어, 어떻게?!",
  ui_story_5031_50311501_184_dialog_content = "분명히 「<color=#FFB400>빛의 실</color>」이 아직도 루미나를 빨아들이고 있는데!",
  ui_story_5031_50311501_185_dialog_content = "카렌의 몸에서... 루미나가 끊임없이 뿜어져 나오고 있어!",
  ui_story_5031_50311501_186_dialog_content = "대체 어떻게 된 거지?",
  ui_story_5031_50311501_187_dialog_content = "무의미한 의심과 불안은 고뇌만 늘리고 사고를 방해할 뿐이야.",
  ui_story_5031_50311501_188_dialog_content = "전세는 순간순간마다 계속해서 변화하고 있어.\n그 어떤 신분이든, 마음속 공포가 아니라 지금의 상황을 직시해야 해.",
  ui_story_5031_50311501_189_dialog_content = "바이스, 앞으로의 전투는 내가 함께 맞설게.",
  ui_story_5031_50311501_190_dialog_content = "카렌... 몸은 괜찮아?",
  ui_story_5031_50311501_191_dialog_content = "왜인지는 모르겠지만, 몸에서 계속해서 새로운 힘이 샘솟고 있어.",
  ui_story_5031_50311501_192_dialog_content = "하지만 그 이유가 무엇이든, 지금 우리의 목표는 하나야──",
  ui_story_5031_50311501_193_dialog_content = "바로 너와 함께 눈앞의 적을 쓰러트리는 거지.",
  ui_story_5031_50311501_194_dialog_content = "응!",
  ui_story_5031_50311501_195_dialog_content = "「경고: 대량의 루미나 감지. 위험도 매우 높음.」",
  ui_story_5031_50311501_196_dialog_content = "「결전 모드 가동.」",
  ui_story_5031_50311502_1_dialog_content = "「경고... 기체 손상도 70% 초과.」",
  ui_story_5031_50311502_2_dialog_content = "「오른팔 연결 끊김, 자동 복구 불가.」",
  ui_story_5031_50311502_3_dialog_content = "바이스, 괜찮아?",
  ui_story_5031_50311502_4_dialog_content = "괜찮아. 멀리서 적을 견제하기만 하는 건 힘든 일도 아니니까!",
  ui_story_5031_50311502_5_dialog_content = "좋아. 그럼 녀석의 오른쪽을 집중해서 공격하자.",
  ui_story_5031_50311502_6_dialog_content = "이제 오른팔은 움직일 수 없으니까, 공격이든 방어든 영향을 받을 수밖에 없을 거야.",
  ui_story_5031_50311502_7_dialog_content = "좋아!",
  ui_story_5031_50311502_8_dialog_content = "카렌 전하, 당신은 정말 제 예상을 뛰어넘는군요.",
  ui_story_5031_50311502_9_dialog_content = "비록 서로 다른 입장에 서 있지만, 전 진심으로 당신께 탄복했습니다.",
  ui_story_5031_50311502_10_dialog_content = "하지만 제게도 실패할 수 없는 이유가 있습니다.",
  ui_story_5031_50311502_11_dialog_content = "여러분의 완벽한 앙코르를 감상하지 못하고 먼저 물러나는 것을 부디 용서하시길.",
  ui_story_5031_50311502_12_dialog_content = "엘비스, 거기 서!",
  ui_story_5031_50311502_13_dialog_content = "저들을 막으세요.",
  ui_story_5031_50311502_14_dialog_content = "바이스! 조심해! 「코어 가디언」한테 등을 보이면 안 돼!",
  ui_story_5031_50311502_15_dialog_content = "으아앗!",
  ui_story_5031_50311502_16_dialog_content = "......",
  ui_story_5031_50311502_17_dialog_content = "쳇, 도망쳤잖아.",
  ui_story_5031_50311502_18_dialog_content = "괜찮아. 엘비스에 대한 건 나간 뒤에 방법을 생각하면 돼.",
  ui_story_5031_50311502_19_dialog_content = "그래, 그것도 그렇네.",
  ui_story_5031_50311502_20_dialog_content = "일단 「코어 가디언」부터 해결하자.",
  ui_story_5031_50311502_21_dialog_content = "그럼 우리도... 응?",
  ui_story_5031_50311502_22_dialog_content = "왜 그래? 카렌?",
  ui_story_5031_50311502_23_dialog_content = "(카렌의 루미나가 갑자기 더 강해졌어?)",
  ui_story_5031_50311502_24_dialog_content = "이 옷... 이제 더는 내 루미나를 흡수하지 않는 것 같아.",
  ui_story_5031_50311502_25_dialog_content = "엘비스가 가버려서 그런 건가?",
  ui_story_5031_50311502_26_dialog_content = "그러고 보니까 그동안에는 그 옷을 입고 있어도 괜찮았잖아.",
  ui_story_5031_50311502_27_dialog_content = "아무래도 그 효과는 엘비스가 발동해야 생기는 것 같아.",
  ui_story_5031_50311502_28_dialog_content = "그렇다면 더는 힘을 아낄 필요가 없겠네.",
  ui_story_5031_50311502_29_dialog_content = "적과 아군도 구분하지 못하는 멍청한 기계가\n배를 망가트리기 전에, 최후의 일격을 가하자.",
  ui_story_5031_50311502_30_dialog_content = "응! 제노 씨가 깨어나면 제대로 우리한테 감사해야 될걸.",
  ui_story_5031_50311502_31_dialog_content = "지금 반역이라도 하겠다는 건가?",
  ui_story_5031_50311502_32_dialog_content = "영주님께서는 서커스단의 단장과 오랜만에 이야기를 나누시는 중입니다.\n누구도 배에 들이지 말라고 명하셨습니다.",
  ui_story_5031_50311502_33_dialog_content = "저희도 명령에 따를 뿐이니 부디 이해해 주십시오.",
  ui_story_5031_50311502_34_dialog_content = "그 태도... 단순한 호위는 아닌 모양이군.",
  ui_story_5031_50311502_35_dialog_content = "게다가 방금 배에서 뭔가 폭발하는 소리도 들렸잖아.",
  ui_story_5031_50311502_36_dialog_content = "정말 이야기를 나누는 게 맞나? 원한을 푸는 건 아니고?",
  ui_story_5031_50311502_37_dialog_content = "너희의 주인이 걱정되지는 않는 건가?\n그렇게 허약해서 그 제노의 주먹을 막을 수나 있겠어?",
  ui_story_5031_50311502_38_dialog_content = "... 떠나주시죠.",
  ui_story_5031_50311502_39_dialog_content = "호오? 그건 무슨 뜻이지? 공격이라도 하겠다는 건가?",
  ui_story_5031_50311502_40_dialog_content = "그럼 제대로 준비해두는 편이 좋을 거야.\n나중에 내가 이 모든 걸 사실대로 보고하면...",
  ui_story_5031_50311502_41_dialog_content = "파토, 무례한 행동은 삼가세요.",
  ui_story_5031_50311502_42_dialog_content = "영주님!",
  ui_story_5031_50311502_43_dialog_content = "오, 엘비스 님 아니십니까. 「이야기」는 끝나셨습니까?",
  ui_story_5031_50311502_44_dialog_content = "방금 옛 친구와 중요한 일을 논의하느라 마티외 님을 기다리게 했군요. 죄송합니다.",
  ui_story_5031_50311502_45_dialog_content = "파토는 제 명에 따라 행동했을 뿐입니다. 그러니 너무 탓하지 말아 주시지요.",
  ui_story_5031_50311502_46_dialog_content = "그럼 이제 배에 타도 되는 겁니까?",
  ui_story_5031_50311502_47_dialog_content = "원하신다면.",
  ui_story_5031_50311502_48_dialog_content = "<size=33>영주님, 이대로 들어가게 두시는 겁니까?</size>",
  ui_story_5031_50311502_49_dialog_content = "<size=33>상관없습니다. 이 배는 곧 폭발할 겁니다.</size>",
  ui_story_5031_50311502_50_dialog_content = "<size=33>이곳보다는 어서 그곳으로...</size>",
  ui_story_5031_50311502_51_dialog_content = "참, 엘비스 님.",
  ui_story_5031_50311502_52_dialog_content = "...무슨 일이십니까?",
  ui_story_5031_50311502_53_dialog_content = "이 배에서 혹시 우리 카렌 전하를 못 보셨는지요.",
  ui_story_5031_50311502_54_dialog_content = "못 봤습니다만, 카렌 전하께서도 배에 계셨습니까?",
  ui_story_5031_50311502_55_dialog_content = "이상하군요. 방금 축제가 끝난 뒤로 계속 이곳에서 기다리고 있었는데...\n카렌 전하께선 보이지 않으셨습니다만.",
  ui_story_5031_50311502_56_dialog_content = "배에서 내리지도 않으셨고... 여러분을 찾아간 것도 아니라면...\n대체 배에 남아서 뭘 하고 계시는 걸까요?",
  ui_story_5031_50311502_57_dialog_content = "배에서 만난 새로운 친구분들과 작별 인사라도 나누고 계실지도 모르죠.",
  ui_story_5031_50311502_58_dialog_content = "오늘 행사 동안 꽤 많이 가까워지셨을 테니까요.",
  ui_story_5031_50311502_59_dialog_content = "전 카렌 전하의 호위를 맡고 있습니다만,\n마치 보모라도 된 양 전하께서 다치실까 하루 종일 지켜보고 있었지요.",
  ui_story_5031_50311502_60_dialog_content = "그래서 전하와 서커스단 사람들은 별다른 교류가 없었다는 것도 보았습니다만.",
  ui_story_5031_50311502_61_dialog_content = "하지만 바이스 양과 시엘 양은 예전부터 알고 지내던 사이 같더군요.",
  ui_story_5031_50311502_62_dialog_content = "PlayerName 님도 레인보우 양과 즐겁게 얘기하고 있었고...",
  ui_story_5031_50311502_63_dialog_content = "말씀 중에 실례지만, 엘비스 님.",
  ui_story_5031_50311502_64_dialog_content = "...으음?",
  ui_story_5031_50311502_65_dialog_content = "방금 제가 다른 사람 이야기를 꺼냈던가요?",
  ui_story_5031_50311502_66_dialog_content = "엘비스 님은 카렌 전하를 보지도 못하셨다면서,\n카렌 전하께서 그들과 함께 있다는 걸 어떻게 그리 확신하시죠?",
  ui_story_5031_50311502_67_dialog_content = "......",
  ui_story_5031_50311502_68_dialog_content = "그 네 분은 사이가 좋으시잖습니까. 항상 함께 다니시던데요.",
  ui_story_5031_50311502_69_dialog_content = "엘비스 님께서 그들에 대해 오늘 알게 되시지 않았습니까?\n그런데 사이가 좋은지는 어떻게 아시는 걸까요?",
  ui_story_5031_50311502_70_dialog_content = "저도 꽁꽁 싸매고 있는 제 동료와 사이가 좋습니다.\n그 친구도 지금 여기 없지 않나요?",
  ui_story_5031_50311502_71_dialog_content = "......",
  ui_story_5031_50311502_72_dialog_content = "파토.",
  ui_story_5031_50311502_73_dialog_content = "예.",
  ui_story_5031_50311502_74_dialog_content = "아하, 들켜버린 이상 입을 막아버리시겠다?",
  ui_story_5031_50311502_75_dialog_content = "꽤나 훌륭하게 음험하십니다.",
  ui_story_5031_50311502_76_dialog_content = "그런데 알고 계실지는 모르겠습니다만...\n저희 성주 전하께서는 매우 냉정해 보여도, 실은 딸바보시거든요.",
  ui_story_5031_50311502_77_dialog_content = "그러니 호위를 맡은 저희가... 당신들한테 쉽게 당할 그런 사람들로 보이십니까?",
  ui_story_5031_50311502_78_dialog_content = "뢰베! 지금이다!",
  ui_story_5031_50311502_79_dialog_content = "?!",
  ui_story_5031_50311502_80_dialog_content = "...쓸데없는 말이 너무 많아, 마티외.",
  ui_story_5031_50311502_81_dialog_content = "쳇, 뭔 상관이야?",
  ui_story_5031_50311502_82_dialog_content = "두 사람?",
  ui_story_5031_50311502_83_dialog_content = "지금 겨우 두 사람으로 우리 병사들에게 맞서겠다는 겁니까?",
  ui_story_5031_50311502_84_dialog_content = "틀렸어. 한 사람이다.",
  ui_story_5031_50311502_85_dialog_content = "뢰베, 여기는 네게 맡기지. 난 카렌 전하를 구하러 간다.",
  ui_story_5031_50311502_86_dialog_content = "......",
  ui_story_5031_50311502_87_dialog_content = "그럴 거 없어.",
  ui_story_5031_50311502_88_dialog_content = "으음? 이 목소리는...",
  ui_story_5031_50311502_89_dialog_content = "어...어째서?!",
  ui_story_5031_50311502_90_dialog_content = "두 사람, 엘비스를 붙잡아 둬서 고마워.",
  ui_story_5031_50311502_91_dialog_content = "큰 도움이 됐어.",
  ui_story_5031_50311502_92_dialog_content = "카렌 전하! 아직 살아계신 걸 보니 정말 기쁘군요.",
  ui_story_5031_50311502_93_dialog_content = "마, 말도 안 돼!",
  ui_story_5031_50311502_94_dialog_content = "「코어 가디언」은 어떻게 됐지? 왜 아직도 배가 폭발하지 않은 거지?",
  ui_story_5031_50311502_95_dialog_content = "전력을 다한 카렌의 공격에 고철 더미가 되어 버렸다고.",
  ui_story_5031_50311502_96_dialog_content = "근데 그 「코어 가디언」 말인데... 구조가 정말 엄청나더라고!",
  ui_story_5031_50311502_97_dialog_content = "아쉽게도 우리가 도착했을 땐 이미 더는 움직이지 않는 상태였지만 말이야.",
  ui_story_5031_50311502_98_dialog_content = "괜찮아. 지금 그대로도 충분히 연구할 만한 가치가 있어.",
  ui_story_5031_50311502_99_dialog_content = "그것도 맞지~",
  ui_story_5031_50311502_100_dialog_content = "어째서... 분명히 「빛의 실」이 루미나를 빨아들이고 있었을 텐데... 어떻게 그런 힘을...",
  ui_story_5031_50311502_101_dialog_content = "...아니, 「빛의 실」이 흡수를 멈췄잖아?",
  ui_story_5031_50311502_102_dialog_content = "「빛의 실」은 당신이 조정하는 거잖아?",
  ui_story_5031_50311502_103_dialog_content = "설마... 흡수 한도를 초과한 건가?!",
  ui_story_5031_50311502_104_dialog_content = "불가능해... 그 옷은 오로리안 두세 명의 루미나를 완전히 흡수할 수 있었을 텐데!",
  ui_story_5031_50311502_105_dialog_content = "이유는 중요하지 않아.",
  ui_story_5031_50311502_106_dialog_content = "중요한 건... 엘비스, 당신 계획이 실패했다는 거지.",
  ui_story_5031_50311502_107_dialog_content = "그만 포기해. 이젠 도망칠 수 없으니까.",
  ui_story_5031_50311502_108_dialog_content = "아, 안 돼... 난 실패할 수 없어! 절대 실패할 수 없다고!",
  ui_story_5031_50311502_109_dialog_content = "「<color=#FFB400>봉인</color>」이 곧...",
  ui_story_5031_50311502_110_dialog_content = "...파토!",
  ui_story_5031_50311502_111_dialog_content = "예!",
  ui_story_5031_50311502_112_dialog_content = "무의미한 저항이야.",
  ui_story_5031_50311502_113_dialog_content = "제길...",
  ui_story_5031_50311502_114_dialog_content = "영주님! 지금입니다!",
  ui_story_5031_50311502_115_dialog_content = "사람이 이렇게 많은데도 당신을 놓친다면 웃음거리가 되지 않겠어?",
  ui_story_5031_50311502_116_dialog_content = "으윽!",
  ui_story_5031_50311502_117_dialog_content = "...뭐야? 그냥 「가볍게 건드렸을 뿐」인데 쓰러진다고?",
  ui_story_5031_50311502_118_dialog_content = "이 사람 대체 얼마나 약한 거야?",
  ui_story_5031_50311502_119_dialog_content = "영주님!",
  ui_story_5031_50311502_120_dialog_content = "네 상대는 나야.",
  ui_story_5031_50311502_121_dialog_content = "윽... 빌어먹을!",
  ui_story_5031_50311502_122_dialog_content = "너흰 아무도 이곳에서 도망칠 수 없어.",
  ui_story_5031_50311601_1_dialog_content = "그럼 레인보우! 시엘은 너한테 맡길게!",
  ui_story_5031_50311601_2_dialog_content = "걱정 마~ 시엘은 내가 잘 돌볼 테니까!",
  ui_story_5031_50311601_3_dialog_content = "팜므도 같이 시엘 언니를 돌봐줄 거야!",
  ui_story_5031_50311601_4_dialog_content = "사블리도!",
  ui_story_5031_50311601_5_dialog_content = "메, 멜트도요!",
  ui_story_5031_50311601_6_dialog_content = "오! 아주 든든하네!",
  ui_story_5031_50311601_7_dialog_content = "그, 그로누 선배님... 남게 해 줘서 고마워요.",
  ui_story_5031_50311601_8_dialog_content = "아냐, 아냐. 어차피 요즘 다른 임무도 없는걸.",
  ui_story_5031_50311601_9_dialog_content = "시엘은 여기서 푹 쉬고 와~",
  ui_story_5031_50311601_10_dialog_content = "그럼 저 에너지 코어는... 저대로 둬도 정말 괜찮은 건가요?",
  ui_story_5031_50311601_11_dialog_content = "아~ 저건 그냥 「소형 동력 코어」야. 일루미나에선 그렇게 귀한 물건은 아니야.",
  ui_story_5031_50311601_12_dialog_content = "「에너지 코어」랑 엄청 비슷하긴 해도, 여러 부분에서 한참 부족해.\n출력하는 에너지의 순도도 훨씬 떨어지고 말이야.",
  ui_story_5031_50311601_13_dialog_content = "거기다 저 영주가 엉망으로 다루는 바람에 이미 폐기처분 수준이라구.",
  ui_story_5031_50311601_14_dialog_content = "연구 가치라면... 아마 「스틱스」의 업그레이드에 아이디어를 조금 줄 순 있을 거야.",
  ui_story_5031_50311601_15_dialog_content = "으으... 그것보다 아직 이 함선을 제대로 연구하지도 못했는데...\n왜 하필 이럴 때 날 호출하는 거냐구.",
  ui_story_5031_50311601_15X1_dialog_content = "시엘, 코어를 수리하고 나면 겸사겸사 전동 시스템도 꼭 확인해 봐!",
  ui_story_5031_50311601_15X2_dialog_content = "노트에 잘 정리해 둬. 돌아오면 나도 볼 거니까!",
  ui_story_5031_50311601_15X3_dialog_content = "아, 알겠어요...",
  ui_story_5031_50311601_16_dialog_content = "앗, 너네 귓속말하고 있구나!",
  ui_story_5031_50311601_17_dialog_content = "사블리도 들을래!",
  ui_story_5031_50311601_18_dialog_content = "하, 하지만 저희한테 들려주면... 그건 귓속말이 아니잖아요...",
  ui_story_5031_50311601_19_dialog_content = "아, 그것도 그렇네?",
  ui_story_5031_50311601_20_dialog_content = "그럼 안 들을래~",
  ui_story_5031_50311601_21_dialog_content = "좋아. 그래야 착한 아이지...",
  ui_story_5031_50311601_22_dialog_content = "뭐라고요?!",
  ui_story_5031_50311601_23_dialog_content = "으악! 누가 이렇게 시끄러운 거야?",
  ui_story_5031_50311601_24_dialog_content = "카렌 전하, 진심이십니까?",
  ui_story_5031_50311601_25_dialog_content = "정말 여기 남아서... 섭정을 하시겠다고요?",
  ui_story_5031_50311601_26_dialog_content = "그래.",
  ui_story_5031_50311601_27_dialog_content = "하지만 엘비스는 전하께 무기를 겨눈 자입니다.\n그 사실은 이미 반역이나 다름없습니다!",
  ui_story_5031_50311601_28_dialog_content = "성주 전하께서 허락하지 않으실 겁니다!",
  ui_story_5031_50311601_29_dialog_content = "그래서 두 사람의 도움이 필요해.",
  ui_story_5031_50311601_30_dialog_content = "...뭔가 안 좋은 예감이 드는데 말이죠.",
  ui_story_5031_50311601_31_dialog_content = "당신과 뢰베가 보고할 때, 이 부분에 대한 내용은 숨겨줬으면 좋겠어.",
  ui_story_5031_50311601_32_dialog_content = "그리고 두 사람도 나와 함께 하버 시티에 한동안 머물러 줬으면 좋겠고.",
  ui_story_5031_50311601_33_dialog_content = "안 됩니다.",
  ui_story_5031_50311601_34_dialog_content = "카렌 님, 죄송합니다. 이건 이리돈 님의 명령입니다.",
  ui_story_5031_50311601_35_dialog_content = "저는 그분께 절대적인 충성을 바칠 의무가 있습니다.",
  ui_story_5031_50311601_36_dialog_content = "......",
  ui_story_5031_50311601_37_dialog_content = "잘 알고 있어, 마티외. 당신의 충심에는 그 어떤 의심도 없으니까.",
  ui_story_5031_50311601_38_dialog_content = "하지만 당신과 뢰베를 곤란하게 만들고 싶지도 않아.",
  ui_story_5031_50311601_39_dialog_content = "난 부상 때문에 17바늘을 꿰매고, 루미나를 과도하게 사용한 탓에\n당분간은 루미나를 쓸 수 없는 신세가 됐으니 말이야.",
  ui_story_5031_50311601_40_dialog_content = "만약 이리돈 씨나 성주 전하께서 이걸 알게 된다면... 꽤 곤란해지겠지.",
  ui_story_5031_50311601_41_dialog_content = "윽, 그건...",
  ui_story_5031_50311601_42_dialog_content = "물론 그건 전부 내가 부주의했기 때문에 일어난 일이고, 두 사람과는 관련이 없어.\n지금은 크게 불편한 것도 없고 말이야.",
  ui_story_5031_50311601_43_dialog_content = "의사들도 며칠간 요양하면 완전히 회복할 수 있을 거라고 했어.",
  ui_story_5031_50311601_44_dialog_content = "그러니 두 사람도 불필요한 질책을 피하고 싶다면... 난 충분히 협력해줄 용의가 있어.",
  ui_story_5031_50311601_45_dialog_content = "......",
  ui_story_5031_50311601_46_dialog_content = "왜?",
  ui_story_5031_50311601_47_dialog_content = "뭐라고?",
  ui_story_5031_50311601_48_dialog_content = "카렌 전하는 왜 여기 남으려고 하지?",
  ui_story_5031_50311601_49_dialog_content = "왜 엘비스의 죄를 덮어주려는 거지?",
  ui_story_5031_50311601_50_dialog_content = "첫째, 난 그가 한 모든 일이 하버 시티의 사람들을 위해서라고 판단했어.",
  ui_story_5031_50311601_51_dialog_content = "둘째, 하버 시티는 과거 몇 년간 백야성에 종속되어 있었어.\n영주인 엘비스도 백야성에서 공부한 적이 있었지.",
  ui_story_5031_50311601_52_dialog_content = "하지만 문제가 생겼을 때 그는 백야성에 도움을 청하지 않고 직접 조사했어.\n심지어 백야성을 경계하기까지 했지.",
  ui_story_5031_50311601_53_dialog_content = "두 사람은 이게 뭘 의미한다고 생각해?",
  ui_story_5031_50311601_54_dialog_content = "......",
  ui_story_5031_50311601_55_dialog_content = "그는 백야성이 이 일에 대해 도움을 줄 수 없거나, 돕지 않을 거라 생각한 거야.",
  ui_story_5031_50311601_56_dialog_content = "종속된 도시의 영주 된 자가 우릴 믿지 않는다면,\n그것이야말로 진정한 반역의 씨앗이야.",
  ui_story_5031_50311601_57_dialog_content = "다음 영주가 이런 문제를 마주했을 때, 엘비스와 같은 선택을 하지 않으리란 보장은 없어.",
  ui_story_5031_50311601_58_dialog_content = "만약 이 일의 진상을 제대로 조사하지 않는다면 문제는 해결되지 않을 거야.\n영원히 살에 박힌 가시가 돼버리겠지.",
  ui_story_5031_50311601_59_dialog_content = "그러니 내가 제대로 조사해보려고 해. 엘비스의 진정한 목적이 대체 뭐였는지 말이야.",
  ui_story_5031_50311601_60_dialog_content = "그리고 그 씨앗이 싹트기 전에, 내 손으로 직접 뿌리를 뽑아내겠어.",
  ui_story_5031_50311601_61_dialog_content = "......",
  ui_story_5031_50311601_62_dialog_content = "하하, 제가 보기에 당신은 줄곧 순진하고 보호받기만 하던 공주님일 뿐입니다.",
  ui_story_5031_50311601_63_dialog_content = "......?",
  ui_story_5031_50311601_64_dialog_content = "하지만...",
  ui_story_5031_50311601_65_dialog_content = "방금 그 발언은... 꽤 그럴듯하군요.",
  ui_story_5031_50311601_66_dialog_content = "안 그래, 뢰베?",
  ui_story_5031_50311601_67_dialog_content = "그래.",
  ui_story_5031_50311601_68_dialog_content = "그럼...",
  ui_story_5031_50311601_69_dialog_content = "하지만!",
  ui_story_5031_50311601_70_dialog_content = "......",
  ui_story_5031_50311601_71_dialog_content = "저흰 이리돈 님을 기만하는 일은 결코 하지 않습니다.",
  ui_story_5031_50311601_72_dialog_content = "그러니 오늘 저녁 식사 때, 쿠리어 길드를 통해 이리돈 님께 사실대로 보고드릴 것입니다.",
  ui_story_5031_50311601_73_dialog_content = "참, 그 쿠리어 길드가 어디 있다고?",
  ui_story_5031_50311601_74_dialog_content = "화...화 뭐라고 했지? 뢰베?",
  ui_story_5031_50311601_75_dialog_content = "......",
  ui_story_5031_50311601_76_dialog_content = "「화이트 펄 스트리트」의 「해피 가든 레스토랑」 옆.",
  ui_story_5031_50311601_77_dialog_content = "아, 그래. 바로 거기였지.",
  ui_story_5031_50311601_78_dialog_content = "그럼 오늘 밤에 네가 다녀오는 걸로 하자고.",
  ui_story_5031_50311601_79_dialog_content = "......",
  ui_story_5031_50311601_80_dialog_content = "왜 네가 안 가고?",
  ui_story_5031_50311601_81_dialog_content = "왜냐하면 난 근처를 순찰해야 하니까.",
  ui_story_5031_50311601_82_dialog_content = "이처럼 위험한 상황이라면, 종합적으로 실력이 더 뛰어난 사람이\n카렌 전하의 안전을 책임지는 게 당연하지.",
  ui_story_5031_50311601_83_dialog_content = "......",
  ui_story_5031_50311601_84_dialog_content = "뭔데? 싸우자고?",
  ui_story_5031_50311601_85_dialog_content = "흥, 상대해 줄게.",
  ui_story_5031_50311601_86_dialog_content = "좋아! 가자고! 저기 공터에서 한판 붙자. 오늘이야말로 패배를 인정하게 만들어 주마.",
  ui_story_5031_50311601_87_dialog_content = "꿈도 크네.",
  ui_story_5031_50311601_88_dialog_content = "......",
  ui_story_5031_50311601_89_dialog_content = "카렌, 잘 해결됐어?",
  ui_story_5031_50311601_90_dialog_content = "저 두 사람은 왜 가면서 싸우고 있는 거야?",
  ui_story_5031_50311601_91_dialog_content = "예전부터 저랬어. 저렇게 싸우면서 항상 붙어 있어.",
  ui_story_5031_50311601_92_dialog_content = "보고 일은...",
  ui_story_5031_50311601_93_dialog_content = "아마 잘 해결된 것 같아.",
  ui_story_5031_50311601_94_dialog_content = "다행이네~",
  ui_story_5031_50311601_95_dialog_content = "저 두 사람... 뭔가 이상해 보이지만 의외로 좋은 사람 같아.",
  ui_story_5031_50311601_96_dialog_content = "근데 너희 둘 다 몸은 정말 괜찮은 거 맞아?",
  ui_story_5031_50311601_97_dialog_content = "나랑 같이 여기 머물 필요는 없어.",
  ui_story_5031_50311601_98_dialog_content = "지금 상황에서 너 혼자 여길 조사하게 두면 우리가 마음이 편할 리가 없잖아.",
  ui_story_5031_50311601_98X1_dialog_content = "그때 넌 루미나가 제어되지 않는 것처럼 계속해서 흘러넘쳤어.\n그리고 우리가 탈출한 지 얼마 되지 않아서 넌 기절했어...",
  ui_story_5031_50311601_98X2_dialog_content = "진짜로 깜짝 놀랐다니까!",
  ui_story_5031_50311601_98X3_dialog_content = "걱정 끼쳐서 미안해.",
  ui_story_5031_50311601_98X4_dialog_content = "근데 카렌은 어떻게 갑자기 새로운 힘을 각성한 거야? 너무 신기하잖아.",
  ui_story_5031_50311601_98X5_dialog_content = "그때... 그 느낌은 바이스 네가 말해 준 것과 같았어.",
  ui_story_5031_50311601_98X6_dialog_content = "난 마음속에서 날 오랫동안 괴롭혀온 고민들을 마주했어...",
  ui_story_5031_50311601_98X7_dialog_content = "정말 사실적이고, 괴롭고, 숨이 막혔어.",
  ui_story_5031_50311601_98X8_dialog_content = "카렌...",
  ui_story_5031_50311601_98X9_dialog_content = "다행히 그때 연결된 PlayerName의 의식이 나를 그 심연 속에서 건져내 줬어.",
  ui_story_5031_50311601_98X10_dialog_content = "그리고 날 깨우쳐 줬어. 너희가 바로 나의 빛이라는 사실을 말이야.",
  ui_story_5031_50311601_98X11_dialog_content = "고마워, PlayerName, 그리고 바이스.",
  ui_story_5031_50311601_98X12_dialog_content = "그건 카렌 네가 해낸 거야.\n네가 자기 집념을 이겨내고, 네 모든 마음과 의지를 통제한 거야.",
  ui_story_5031_50311601_98X13_dialog_content = "맞아. 근데 왠지 PlayerName 넌 중요할 때마다 하는 말이\n항상 마음을 치유하는 힘이 있는 것 같단 말이야.",
  ui_story_5031_50311601_98X14_dialog_content = "정말 신기하다니까~",
  ui_story_5031_50311601_98X15_dialog_content = "그, 그래?",
  ui_story_5031_50311601_98X16_dialog_content = "난 그냥 내 마음속 진심을 얘기한 것뿐이야.",
  ui_story_5031_50311601_98X17_dialog_content = "그 점이 대단하다는 거야.",
  ui_story_5031_50311601_98X18_dialog_content = "맞아.",
  ui_story_5031_50311601_98X19_dialog_content = "하지만 카렌 너도 한동안은 푹 쉬어야 돼.\n루미나를 회복하는 일은 너무 초조해하지 마.",
  ui_story_5031_50311601_98X20_dialog_content = "제대로 제어하지 못하면 루미나가 흘러넘쳐서 또 기절할지도 몰라.",
  ui_story_5031_50311601_98X21_dialog_content = "그러니까 회복 기간에는 절대 새로운 힘을 연습하겠다고 무리하면 안 돼!",
  ui_story_5031_50311601_98X22_dialog_content = "그거 확실히 카렌이 할 만한 행동이네.",
  ui_story_5031_50311601_98X23_dialog_content = "그래, 알겠어.",
  ui_story_5031_50311601_98X24_dialog_content = "제대로 쉬고, 걱정 끼치지 않을게.",
  ui_story_5031_50311601_98X25_dialog_content = "각성에 대한 건 내 몸이 완전히 회복되고 나서,\n바이스와 함께 규칙과 방법을 찾아볼 거야.",
  ui_story_5031_50311601_98X26_dialog_content = "얼마든지 좋아~",
  ui_story_5031_50311601_99_dialog_content = "아무튼 너도 걱정할 거 없어.\n나랑 PlayerName, 몸은 아주 튼튼하니까. 그렇지?",
  ui_story_5031_50311601_100_dialog_content = "맞아. 그러니까 카렌 너도 가끔은 우리한테 의지해 줘.",
  ui_story_5031_50311601_101_dialog_content = "우리도 널 도울 수 있게 말이야!",
  ui_story_5031_50311601_102_dialog_content = "후훗, 그럼 앞으로 잘 부탁할게.",
  ui_story_5031_50311601_103_dialog_content = "좋아!",
  ui_story_5031_50311601_104_dialog_content = "그럼 이제 뭐 해야 하지?",
  ui_story_5031_50311601_105_dialog_content = "엄청난 소동이 일어났으니까, 하버 시티에 처리해야 할 일이 잔뜩 있을 것 같은데.",
  ui_story_5031_50311601_106_dialog_content = "섭정을 하려면 카렌도 엄청 바쁘겠지?",
  ui_story_5031_50311601_107_dialog_content = "확실히 그렇겠지.\n하지만 정식으로 영주 자리를 넘겨받기 전에 만나야 할 사람이 있어.",
  ui_story_5031_50311601_108_dialog_content = "누구?",
  ui_story_5031_50311601_109_dialog_content = "엘비스.",
  ui_story_5031_50311601_110_dialog_content = "<color=#e8d9bb>To be continued...</color>"
}
return config
